const fs = require('fs')
const path = require('path')

const root = process.cwd()
const files = [
  'app/broker/page.tsx',
  'app/driver/page.tsx',
  'app/station-manager/page.tsx',
  'app/store-officer/page.tsx',
  'app/truck-admin/page.tsx',
  'app/truck-officer/page.tsx',
  'components/admin/CashOfficers.tsx',
  'components/admin/StationManagers.tsx',
  'components/admin/StoreOfficers.tsx',
  'components/admin/TruckAdmins.tsx',
  'components/admin/TruckOfficers.tsx',
  'components/CashOfficerPanel.tsx',
]

const importStatement = 'import ModernInput from "@/components/ModernInput"\n'

for (const file of files) {
  const filePath = path.join(root, file)
  let text = fs.readFileSync(filePath, 'utf8')
  const original = text

  const hasModernImport = /import\s+ModernInput\s+from\s+"@\/components\/ModernInput"/.test(text)
  const hasTarget = /<input[\s\S]*?style=\{inputStyle\}|<select[\s\S]*?style=\{inputStyle\}|<textarea[\s\S]*?style=\{inputStyle\}/.test(text)

  if (hasTarget && !hasModernImport) {
    if (/^"use client"/.test(text)) {
      const lines = text.split(/\r?\n/)
      const insertAt = lines.findIndex((line, idx) => idx > 0 && line.startsWith('import '))
      if (insertAt >= 0) {
        lines.splice(insertAt, 0, importStatement.trimEnd())
      } else {
        lines.splice(1, 0, importStatement.trimEnd())
      }
      text = lines.join('\n')
    } else {
      const match = text.match(/^(?:import .*\r?\n)+/)
      if (match) {
        const prefix = match[0]
        text = prefix + importStatement + text.slice(prefix.length)
      } else {
        text = importStatement + text
      }
    }
  }

  text = text.replace(/<input([^>]*?)style=\{inputStyle\}([^>]*)\/>/g, '<ModernInput$1style={inputStyle}$2/>')
  text = text.replace(/<input([^>]*?)style=\{inputStyle\}([^>]*)>/g, '<ModernInput$1style={inputStyle}$2>')
  text = text.replace(/<select([^>]*?)style=\{inputStyle\}([^>]*)>/g, '<ModernInput as="select"$1style={inputStyle}$2>')
  text = text.replace(/<textarea([^>]*?)style=\{inputStyle\}([^>]*)>([\s\S]*?)<\/textarea>/g, '<ModernInput as="textarea"$1style={inputStyle}$2>$3</ModernInput>')

  if (text !== original) {
    fs.writeFileSync(filePath, text, 'utf8')
    console.log('updated', file)
  }
}

"use client"

import { useState, useEffect } from "react"
import { useRouter, useSearchParams } from "next/navigation"
import { supabase } from "@/lib/supabase"
import { Icon } from "@iconify/react"
import AdminPanel from "@/components/admin/AdminPanel"
import BrokerPanel from "@/components/broker/BrokerPanel"
import ErrorBoundary from "@/components/ErrorBoundary"
import { Role } from "@/lib/roles"
import { FONT_SIZE } from "@/lib/constants"

type UserProfile = {
  user_id: string
  role: string
  full_name: string
  profile_picture_url?: string
}

export const dynamic = "force-dynamic"

export default function AdminDashboard() {
  const router = useRouter()

  const [mounted, setMounted] = useState(false)
  const [loading, setLoading] = useState(true)
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null)
  const [error, setError] = useState<string | null>(null)
  const searchParams = useSearchParams()
  const urlRole = searchParams.get("role")

  useEffect(() => { setMounted(true) }, [])

  useEffect(() => {
    async function initUser() {
      try {
        const { data: { session } } = await supabase.auth.getSession()
        if (!session) { router.push("/login"); return }

        const { data: profile, error: profileError } = await supabase
          .from("Profiles")
          .select("user_id, role, full_name, profile_picture_url")
          .eq("user_id", session.user.id)
          .single()

        if (profileError || !profile) {
          setError("Failed to load user profile")
          setLoading(false)
          return
        }

        // Check UserRoles for admin dashboard access
        const { data: userRoles } = await supabase
          .from("UserRoles")
          .select("role")
          .eq("user_id", session.user.id)

        let roles = userRoles?.map(r => r.role) || []
        // Fall back to Profiles.role for legacy users without UserRoles entries
        if (roles.length === 0) {
          roles = [profile.role]
        }
        const dashboardRoles = [Role.SuperAdmin, Role.Supervisor, Role.CashAuthorizer, Role.TruckAdmin, Role.DeskOfficer, Role.ATCOfficer, Role.Admin, Role.Broker]
        let dashboardRole: Role | undefined = dashboardRoles.find(r => roles.includes(r))
        const params = new URLSearchParams(window.location.search)
        const requestedRole = params.get("role") as Role | null
        if (requestedRole && roles.includes(requestedRole)) {
          dashboardRole = requestedRole
        }
        const hasAdminAccess = Boolean(dashboardRole)

        if (!hasAdminAccess) {
          setError("You do not have permission to access this dashboard")
          setLoading(false)
          return
        }

        let profilePictureUrl: string | undefined = profile.profile_picture_url
        if (dashboardRole === Role.Broker) {
          const { data: brokerData } = await supabase
            .from("Brokers")
            .select("profile_picture_url")
            .eq("broker_id", session.user.id)
            .single()
          if (brokerData?.profile_picture_url) profilePictureUrl = brokerData.profile_picture_url
        }

        setUserProfile({ ...profile, role: dashboardRole!, profile_picture_url: profilePictureUrl })
        setLoading(false)
      } catch (err) {
        console.error("Init error:", err)
        setError("An error occurred while loading your profile")
        setLoading(false)
      }
    }
    if (mounted) initUser()
  }, [mounted, router])

  useEffect(() => {
    if (urlRole) {
      setUserProfile(prev => prev && prev.role !== urlRole ? { ...prev, role: urlRole } : prev)
    }
  }, [urlRole])

  async function handleLogout() {
    await supabase.auth.signOut()
    router.push("/login")
  }

  if (!mounted) {
    return <div style={{ display: "flex", minHeight: "100vh", background: "#f8fafc" }} />
  }

  if (loading) {
    return (
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", minHeight: "100vh", background: "#f8fafc", fontFamily: "'Inter', sans-serif" }}>
        <div style={{ textAlign: "center" }}>
          <div style={{ width: 40, height: 40, borderRadius: "50%", border: "3px solid #e2e8f0", borderTopColor: "#0070f3", animation: "spin 1s linear infinite", margin: "0 auto 12px" }} />
          <p style={{ color: "#64748b", fontSize: FONT_SIZE.sm }}>LoadingΓÇª</p>
        </div>
        <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
      </div>
    )
  }

  if (error || !userProfile) {
    return (
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", minHeight: "100vh", background: "#f8fafc", fontFamily: "'Inter', sans-serif", padding: 24 }}>
        <div style={{ textAlign: "center", maxWidth: 400 }}>
          <Icon icon="mdi:lock-alert" width={48} color="#ef4444" style={{ marginBottom: 16, display: "block" }} />
          <h1 style={{ margin: "0 0 8px", fontSize: FONT_SIZE.xl, fontWeight: 700, color: "#0f172a" }}>Access Denied</h1>
          <p style={{ margin: "0 0 24px", fontSize: FONT_SIZE.base, color: "#64748b" }}>
            {error || "You do not have permission to access this dashboard."}
          </p>
          <button onClick={handleLogout} style={{ padding: "10px 20px", background: "#0070f3", color: "white", border: "none", borderRadius: 8, cursor: "pointer", fontWeight: 600, fontSize: FONT_SIZE.sm }}>
            Go to Login
          </button>
        </div>
      </div>
    )
  }

  const renderDashboard = () => {
    const role = urlRole || userProfile.role
    switch (role) {
      case Role.Admin:
      case Role.SuperAdmin:
      case Role.Supervisor:
      case Role.CashAuthorizer:
      case Role.DeskOfficer:
      case Role.ATCOfficer:
        return (
          <ErrorBoundary label="Admin Panel">
            <AdminPanel userProfile={userProfile} initialRole={role} />
          </ErrorBoundary>
        )
      case Role.Broker:
        return (
          <ErrorBoundary label="Broker Panel">
            <BrokerPanel userProfile={userProfile} />
          </ErrorBoundary>
        )
      default:
        return <p style={{ color: "#888", fontSize: FONT_SIZE.base }}>Unknown user role: {role}</p>
    }
  }

  return <div style={{ minHeight: "100vh" }}>{renderDashboard()}</div>
}

"use client"

import { useState, useEffect } from "react"
import { Icon } from "@iconify/react"
import { supabase } from "@/lib/supabase"
import { apiMutate } from "@/lib/api-mutation"
import RoleSwitcher from "@/components/RoleSwitcher"
import ReportModal from "@/components/ReportModal"
import { formatAmount, parseAmount } from "@/lib/formatAmount"
import ModernInput from "@/components/ModernInput"
import CustomerSelector from "@/components/CustomerSelector"
import CustomerPayments from "@/components/CustomerPayments"
import ProfilePictureUpload from "@/components/ProfilePictureUpload"
import { useBreakpoint } from "@/app/hooks/useBreakpoint"
import { FONT_SIZE } from "@/lib/constants"
import { requireDashboardRole } from "@/lib/auth-helpers"
import { Role } from "@/lib/roles"
import { formatDate, formatDateTime } from "@/lib/date-utils"
import { useStops } from "@/lib/hooks/useStops"

type Broker = {
  broker_id: string
  full_name: string
  profile_picture_url?: string
}

type Customer = {
  customer_id: string
  full_name: string
  phone_number: string
}

type Stop = {
  stop_id: string
  trip_id: string
  customer_id: string | null
  customer_name: string
  quantity_offloaded: number
  stop_location: string
  stop_time: string
  plate_number: string
  material_centre: string
  atc: string | null
  order_no: string | null
  child_order_no: string | null
  product: string
  confirmed: boolean
  disputed: boolean
}

export default function BrokerDashboard() {
  const bp = useBreakpoint()
  const isMobile = bp === "mobile"
  const isTablet = bp === "tablet"
  const isNarrow = isMobile || isTablet

  const [brokerId, setBrokerId] = useState<string | null>(null)
  const [broker, setBroker] = useState<Broker | null>(null)
  const [selectedStop, setSelectedStop] = useState<Stop | null>(null)
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null)
  const [pricePerBag, setPricePerBag] = useState("")
  const [disputingStop, setDisputingStop] = useState<Stop | null>(null)
  const [disputeReason, setDisputeReason] = useState("")
  const [message, setMessage] = useState("")
  const [submitting, setSubmitting] = useState(false)
  const [loading, setLoading] = useState(true)
  const [companyPriceMap, setCompanyPriceMap] = useState<Record<string, number>>({})
  const [soldAtDifferentPrice, setSoldAtDifferentPrice] = useState(false)
  const [discount, setDiscount] = useState("")
  const [salePrice, setSalePrice] = useState("")
  const [activeFilter, setActiveFilter] = useState<"pending" | "confirmed" | "disputed">("pending")
  const [allStops, setAllStops] = useState<Stop[]>([])
  const [page, setPage] = useState(1)
  const PAGE_SIZE = 50
  const [stopsFilter, setStopsFilter] = useState<{ broker_id: string } | null>(null)
  const { data: stopsFromHook, refetch: refetchStops } = useStops(stopsFilter ?? undefined)
  useEffect(() => { setAllStops(stopsFromHook as Stop[]) }, [stopsFromHook])

  const [showPictureModal, setShowPictureModal] = useState(false)
  const [showReportModal, setShowReportModal] = useState(false)
  const [activeView, setActiveView] = useState<"broker" | "payments">("broker")

  useEffect(() => { initBroker() }, [])

  async function initBroker() {
    const { data: { session } } = await supabase.auth.getSession()
    if (!session) { window.location.href = "/login"; return }
    const user = session.user

    const hasRole = await requireDashboardRole(user.id, Role.Broker)
    if (!hasRole) { window.location.href = "/login"; return }

    setBrokerId(user.id)
    setStopsFilter({ broker_id: user.id })

    const { data: brokerData } = await supabase
      .from("Profiles").select("full_name").eq("user_id", user.id).single()

    if (brokerData) {
      const { data: brokerDetails } = await supabase
        .from("Brokers")
        .select("broker_id, full_name, profile_picture_url")
        .eq("broker_id", user.id)
        .single()

      if (brokerDetails) {
        setBroker(brokerDetails)
      } else {
        setBroker({ broker_id: user.id, full_name: brokerData.full_name })
      }
    }

    const { data: priceData } = await supabase.from("company_prices").select("*")
    const priceMap: Record<string, number> = {}
    for (const p of (priceData || [])) priceMap[p.product] = p.price
    setCompanyPriceMap(priceMap)
    setLoading(false)
  }

  function openConfirmModal(stop: Stop) {
    const cp = companyPriceMap[stop.product]
    setSelectedStop(stop)
    setSelectedCustomer(null)
    setPricePerBag(cp ? formatAmount(cp.toString()) : "")
    setSoldAtDifferentPrice(false)
    setDiscount("")
    setSalePrice("")
    setMessage("")
  }

  function closeModal() {
    setSelectedStop(null); setSelectedCustomer(null); setPricePerBag(""); setMessage(""); setSoldAtDifferentPrice(false); setDiscount(""); setSalePrice("")
  }

  function handleDiscountChange(raw: string) {
    const digits = raw.replace(/[^0-9]/g, "")
    if (digits === "") { setDiscount(""); setSalePrice(""); setPricePerBag(""); return }
    const discountVal = parseInt(digits)
    const cp = selectedStop ? companyPriceMap[selectedStop.product] ?? 0 : 0
    const saleAmount = Math.max(0, cp - discountVal)
    setDiscount(formatAmount(discountVal.toString()))
    setSalePrice(formatAmount(saleAmount.toString()))
    setPricePerBag(formatAmount(saleAmount.toString()))
    setMessage("")
  }

  function handleSalePriceChange(raw: string) {
    const digits = raw.replace(/[^0-9]/g, "")
    if (digits === "") { setSalePrice(""); setDiscount(""); setPricePerBag(""); return }
    const saleVal = parseInt(digits)
    const cp = selectedStop ? companyPriceMap[selectedStop.product] ?? 0 : 0
    const discountAmount = Math.max(0, cp - saleVal)
    setSalePrice(formatAmount(saleVal.toString()))
    setDiscount(formatAmount(discountAmount.toString()))
    setPricePerBag(formatAmount(saleVal.toString()))
    setMessage("")
  }

  function handleToggleDifferentPrice(checked: boolean) {
    setSoldAtDifferentPrice(checked)
    if (!checked) {
      const cp = selectedStop ? companyPriceMap[selectedStop.product] ?? 0 : 0
      setDiscount("")
      setSalePrice("")
      setPricePerBag(cp ? formatAmount(cp.toString()) : "")
    } else {
      const cp = selectedStop ? companyPriceMap[selectedStop.product] ?? 0 : 0
      setDiscount("0")
      setSalePrice(cp ? formatAmount(cp.toString()) : "")
    }
  }

  async function handleDispute() {
    if (!disputingStop) return
    if (!disputeReason.trim()) return setMessage("Please provide a reason for the dispute")
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return

    setSubmitting(true)
    const { error } = await apiMutate("trips", {
      action: "update", table: "Stops",
      data: { disputed: true, dispute_reason: disputeReason, disputed_by: user.id },
      filters: { stop_id: disputingStop.stop_id },
    })
    setSubmitting(false)

    if (error) { setMessage("Failed to dispute stop"); return }
    setDisputingStop(null); setDisputeReason(""); setMessage("")
    refetchStops()
  }

  async function handleConfirm() {
    if (!selectedStop) return
    if (!pricePerBag) return setMessage("Price per bag is required")
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return

    setSubmitting(true)
    const customerIdToSave = selectedCustomer?.customer_id ?? selectedStop.customer_id

    const { error: stopError } = await apiMutate("trips", {
      action: "update", table: "Stops",
      data: { confirmed: true, customer_id: customerIdToSave, updated_by: user.id },
      filters: { stop_id: selectedStop.stop_id },
    })

    if (stopError) { setMessage("Failed to confirm stop"); setSubmitting(false); return }

    const { error: confirmError } = await apiMutate("trips", {
      action: "insert", table: "Stop_Confirmations",
      data: { stop_id: selectedStop.stop_id, broker_id: brokerId, customer_id: customerIdToSave, price_per_bag: parseAmount(pricePerBag) },
    })

    setSubmitting(false)
    if (confirmError) { setMessage("Stop updated but confirmation record failed"); return }
    closeModal()
    refetchStops()
  }

  if (loading) return (
    <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: "white" }}>
      <div style={{ textAlign: "center" }}>
        <Icon icon="mdi:loading" width={32} color="#0070f3" style={{ animation: "spin 1s linear infinite" }} />
        <p style={{ color: "#888", marginTop: 12, fontSize: 14 }}>LoadingΓÇª</p>
      </div>
      <style>{`@keyframes spin { from { transform: rotate(0deg) } to { transform: rotate(360deg) } }`}</style>
    </div>
  )

  const pendingStops = allStops.filter(s => !s.confirmed && !s.disputed)
  const confirmedStops = allStops.filter(s => s.confirmed)
  const disputedStops = allStops.filter(s => s.disputed)

  const visibleStopsUnpaginated =
    activeFilter === "pending" ? pendingStops :
    activeFilter === "confirmed" ? confirmedStops : disputedStops
  const totalPages = Math.ceil(visibleStopsUnpaginated.length / PAGE_SIZE) || 1
  const safePage = Math.min(page, totalPages)
  const visibleStops = visibleStopsUnpaginated.slice(0, safePage * PAGE_SIZE)

  const filterOptions: { key: "pending" | "confirmed" | "disputed"; label: string; count: number; color: string }[] = [
    { key: "pending", label: "Pending", count: pendingStops.length, color: "#0070f3" },
    { key: "confirmed", label: "Confirmed", count: confirmedStops.length, color: "#10b981" },
    { key: "disputed", label: "Disputed", count: disputedStops.length, color: "#ff4444" },
  ]

  const maxW = isNarrow ? "100%" : 520
  const sidePad = isMobile ? "0 16px" : isTablet ? "0 24px" : 0

  const inputStyle: React.CSSProperties = {
    width: "100%", padding: isMobile ? "14px 12px" : "11px 12px",
    boxSizing: "border-box", borderRadius: 8,
    border: "1.5px solid #e5e5e5", fontSize: isMobile ? 16 : 14,
    background: "white", color: "#171717", minHeight: isMobile ? 48 : 42,
    appearance: "none", WebkitAppearance: "none",
  }

  const labelStyle: React.CSSProperties = {
    fontWeight: "600", display: "block", marginBottom: 6,
    fontSize: isMobile ? 14 : 13, color: "#444",
  }

  const modalOverlay: React.CSSProperties = {
    position: "fixed", inset: 0, background: "rgba(0,0,0,0.5)",
    display: "flex", alignItems: isMobile ? "flex-end" : "center",
    justifyContent: "center", zIndex: 100,
  }

  const modalBox: React.CSSProperties = {
    background: "white",
    borderRadius: isMobile ? "20px 20px 0 0" : 14,
    padding: isMobile ? "24px 20px 40px" : 32,
    width: isMobile ? "100%" : 420,
    maxWidth: "100%",
    maxHeight: isMobile ? "92vh" : "88vh",
    overflowY: "auto",
    boxShadow: "0 8px 32px rgba(0,0,0,0.2)",
  }

  const fullBtn = (bg: string, color = "white"): React.CSSProperties => ({
    width: "100%", padding: isMobile ? "15px 0" : "13px 0",
    background: bg, color,
    border: "none", borderRadius: 10,
    fontSize: isMobile ? 16 : 14, cursor: "pointer", fontWeight: "bold",
    minHeight: 52,
    display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
  })

  return (
    <div style={{ fontFamily: "'Inter', sans-serif", background: "#f8fafc", minHeight: "100vh" }}>
      <style>{`
        @keyframes spin { from { transform: rotate(0deg) } to { transform: rotate(360deg) } }
        .avatar-btn:hover { border-color: #0070f3 !important; transform: scale(1.05); }
        .avatar-wrapper:hover .camera-overlay { opacity: 1 !important; }
        .report-btn:hover { background: #fff0e1 !important; border-color: #f8ad5c !important; }
        .logout-btn:hover { background: rgba(239,68,68,0.1) !important; border-color: #fca5a5 !important; }
      `}</style>

      {/* Profile Banner */}
      <div style={{ background: "white", borderBottom: "1px solid #e2e8f0", padding: isMobile ? "16px" : "24px 32px" }}>
        <div style={{ maxWidth: 1200, margin: "0 auto", display: "flex", alignItems: "center", gap: isMobile ? 12 : 16, justifyContent: "space-between" }}>
          <div style={{ display: "flex", alignItems: "center", gap: isMobile ? 12 : 16, flex: 1 }}>
            <div className="avatar-wrapper" style={{ position: "relative" }}>
              <div
                onClick={() => setShowPictureModal(true)}
                className="avatar-btn"
                style={{
                  width: isMobile ? 48 : 56,
                  height: isMobile ? 48 : 56,
                  borderRadius: "50%",
                  background: broker?.profile_picture_url ? "transparent" : "#f0f7ff",
                  border: "2px solid #bfdbfe",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  flexShrink: 0,
                  cursor: "pointer",
                  overflow: "hidden",
                  transition: "all 0.2s",
                }}
              >
                {broker?.profile_picture_url ? (
                  <img
                    src={broker.profile_picture_url}
                    alt={broker.full_name}
                    style={{ width: "100%", height: "100%", objectFit: "cover" }}
                  />
                ) : (
                  <span style={{ fontSize: isMobile ? 20 : 24, fontWeight: 700, color: "#0070f3" }}>
                    {broker?.full_name.charAt(0).toUpperCase()}
                  </span>
                )}
                <div className="camera-overlay" style={{ position: "absolute", inset: 0, background: "rgba(0, 0, 0, 0.4)", display: "flex", alignItems: "center", justifyContent: "center", opacity: 0, transition: "opacity 0.2s" }}>
                  <Icon icon="mdi:camera" width={20} height={20} color="white" />
                </div>
              </div>
            </div>
            <div>
              <h1 style={{ margin: 0, fontSize: isMobile ? FONT_SIZE.lg : FONT_SIZE.xl, fontWeight: 700, color: "#0070f3" }}>
                {broker?.full_name}
              </h1>
              <RoleSwitcher currentRole={Role.Broker} style={{ margin: "2px 0 0", fontSize: FONT_SIZE.sm, color: "#64748b" }} />
            </div>
          </div>
          <div style={{ display: "flex", gap: 8 }}>
            <button
              onClick={() => setShowReportModal(true)}
              className="report-btn"
              style={{ padding: "8px 14px", background: "#fff8e1", color: "#f5a623", border: "1.5px solid #f8ad5c", borderRadius: 8, cursor: "pointer", fontSize: FONT_SIZE.sm, minHeight: 40, fontWeight: 600, display: "flex", alignItems: "center", gap: 6, transition: "all 0.2s", whiteSpace: "nowrap" }}
            >
              <Icon icon="mdi:alert-circle-outline" width={16} />
              {!isMobile && "Report"}
            </button>
            <button
              onClick={async () => { await supabase.auth.signOut(); window.location.href = "/login" }}
              className="logout-btn"
              style={{ padding: "8px 16px", background: "rgba(239, 68, 68, 0.05)", color: "#ef4444", border: "1.5px solid #fecaca", borderRadius: 6, cursor: "pointer", fontSize: FONT_SIZE.sm, fontWeight: 600, transition: "all 0.2s", minHeight: 40, whiteSpace: "nowrap" }}
            >
              Logout
            </button>
          </div>
        </div>
      </div>

      <div style={{ maxWidth: maxW, margin: "0 auto" }}>
        <div style={{ padding: sidePad }}>

          {/* ΓöÇΓöÇ View Switcher ΓöÇΓöÇ */}
          <div style={{
            display: "grid", gridTemplateColumns: "1fr 1fr",
            gap: 10, padding: isMobile ? "16px 16px 0" : "20px 0 0",
            background: isMobile ? "#f8fafc" : "transparent",
          }}>
            {[
              { key: "broker", label: "My Stops", icon: "mdi:truck-delivery", count: allStops.length },
              { key: "payments", label: "Payments", icon: "mdi:cash-register" },
            ].map(tab => {
              const isActive = activeView === tab.key
              return (
                <button
                  key={tab.key}
                  onClick={() => setActiveView(tab.key as "broker" | "payments")}
                  style={{
                    padding: isMobile ? "14px 12px" : "13px 12px",
                    background: isActive ? "rgba(0, 112, 243, 0.1)" : "white",
                    color: isActive ? "#0070f3" : "#555",
                    border: isActive ? "1px solid #0070f3" : "1.5px solid #e5e5e5",
                    borderRadius: 10,
                    cursor: "pointer",
                    fontWeight: isActive ? "bold" : "normal",
                    fontSize: isMobile ? 14 : 13,
                    minHeight: 52,
                    display: "flex", flexDirection: "column",
                    alignItems: "center", justifyContent: "center", gap: 6,
                    transition: "all 0.15s",
                    boxShadow: isActive ? "0 4px 12px rgba(0,112,243,0.25)" : "none",
                  }}
                >
                  <Icon icon={tab.icon} width={20} />
                  <span>{tab.label}</span>
                </button>
              )
            })}
          </div>

          {/* ΓöÇΓöÇ Payments View ΓöÇΓöÇ */}
          {activeView === "payments" && brokerId && (
            <div style={{ padding: isMobile ? "16px 0" : "20px 0" }}>
              <CustomerPayments brokerId={brokerId} />
            </div>
          )}

          {/* ΓöÇΓöÇ Broker Stops View ΓöÇΓöÇ */}
          {activeView === "broker" && (
            <div style={{ padding: isMobile ? "20px 0" : "24px 0" }}>

              <h2 style={{ margin: "0 0 20px", fontSize: isMobile ? 22 : 20, color: "#171717",
                padding: isMobile ? "0 16px" : 0 }}>
                My Stops
              </h2>

              {/* Filter Pills */}
              <div style={{
                display: "flex", gap: 8, marginBottom: 20,
                padding: isMobile ? "0 16px" : 0,
                overflowX: "auto", scrollbarWidth: "none",
              }}>
                {filterOptions.map(({ key, label, count, color }) => {
                  const isActive = activeFilter === key
                  return (
                    <button
                      key={key}
                      onClick={() => setActiveFilter(key)}
                      style={{
                        padding: isMobile ? "9px 16px" : "7px 14px",
                        borderRadius: 20, fontSize: 13, cursor: "pointer",
                        border: isActive ? "none" : "1.5px solid #e5e5e5",
                        background: isActive ? color : "white",
                        color: isActive ? "white" : "#555",
                        fontWeight: isActive ? "bold" : "normal",
                        minHeight: 38, whiteSpace: "nowrap",
                        display: "flex", alignItems: "center", gap: 5, flexShrink: 0,
                        boxShadow: isActive ? `0 2px 8px ${color}44` : "none",
                      }}
                    >
                      {label}
                      {count > 0 && (
                        <span style={{
                          background: isActive ? "rgba(255,255,255,0.25)" : "#f0f0f0",
                          color: isActive ? "white" : "#888",
                          borderRadius: 10, padding: "1px 7px", fontSize: 11, fontWeight: "bold",
                        }}>
                          {count}
                        </span>
                      )}
                    </button>
                  )
                })}
              </div>

              {/* Stop Cards */}
              <div style={{ padding: isMobile ? "0 16px" : 0 }}>
                {visibleStopsUnpaginated.length > PAGE_SIZE && (
                  <div style={{ display: "flex", justifyContent: "center", gap: 8, marginBottom: 16 }}>
                    <button disabled={safePage <= 1} onClick={() => setPage(p => Math.max(1, p - 1))} style={{ padding: "8px 16px", background: safePage <= 1 ? "#f0f0f0" : "white", border: "1px solid #e5e5e5", borderRadius: 8, cursor: safePage <= 1 ? "not-allowed" : "pointer", fontSize: 13, color: safePage <= 1 ? "#ccc" : "#555" }}>
                      ΓåÉ Previous
                    </button>
                    <span style={{ display: "flex", alignItems: "center", fontSize: 13, color: "#888", padding: "0 8px" }}>Page {safePage} of {totalPages}</span>
                    <button disabled={safePage >= totalPages} onClick={() => setPage(p => p + 1)} style={{ padding: "8px 16px", background: safePage >= totalPages ? "#f0f0f0" : "white", border: "1px solid #e5e5e5", borderRadius: 8, cursor: safePage >= totalPages ? "not-allowed" : "pointer", fontSize: 13, color: safePage >= totalPages ? "#ccc" : "#555" }}>
                      Next ΓåÆ
                    </button>
                  </div>
                )}
                {visibleStops.length === 0 ? (
                  <div style={{ textAlign: "center", padding: "60px 0", color: "#bbb" }}>
                    <Icon icon="mdi:map-marker-off" width={40} style={{ marginBottom: 10, display: "block", margin: "0 auto 10px" }} />
                    <p style={{ margin: 0, fontSize: 14 }}>No {activeFilter} stops</p>
                  </div>
                ) : (
                  visibleStops.map((stop) => (
                    <div
                      key={stop.stop_id}
                      style={{
                        background: "white", border: "1px solid #eee", borderRadius: 12,
                        padding: isMobile ? "14px 16px" : "16px 20px",
                        marginBottom: 10,
                        boxShadow: "0 1px 4px rgba(0,0,0,0.05)",
                      }}
                    >
                      {/* Top row */}
                      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 10 }}>
                        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                          <div style={{
                            width: 36, height: 36, borderRadius: 9, background: "#f0f7ff",
                            display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
                          }}>
                            <Icon icon="mdi:truck" width={18} color="#0070f3" />
                          </div>
                          <div>
                            <p style={{ margin: 0, fontWeight: "bold", fontSize: isMobile ? 15 : 14, color: "#171717" }}>{stop.plate_number}</p>
                            <p style={{ margin: "2px 0 0", fontSize: 12, color: "#888" }}>{stop.stop_location}</p>
                          </div>
                        </div>
                        <p style={{ margin: 0, fontSize: 11, color: "#aaa", flexShrink: 0, paddingLeft: 8 }}>
                          {formatDate(stop.stop_time)}
                        </p>
                      </div>

                      {/* Details */}
                      <div style={{
                        display: "grid", gridTemplateColumns: "1fr 1fr",
                        gap: 8, padding: "10px 12px", background: "#f9f9f9",
                        borderRadius: 8, marginBottom: 12,
                      }}>
                        <div>
                          <p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Bags</p>
                          <p style={{ margin: "2px 0 0", fontWeight: "bold", fontSize: 14, color: "#171717" }}>{stop.quantity_offloaded}</p>
                        </div>
                        <div>
                          <p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Customer</p>
                          <p style={{ margin: "2px 0 0", fontSize: 13, color: "#171717", fontWeight: "500" }}>{stop.customer_name}</p>
                        </div>
                        <div>
                          <p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Loading Point</p>
                          <p style={{ margin: "2px 0 0", fontSize: 12, color: "#555" }}>{stop.material_centre}</p>
                        </div>
                        {stop.order_no ? (
                          <>
                            <div>
                              <p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Order No</p>
                              <p style={{ margin: "2px 0 0", fontSize: 12, color: "#555" }}>{stop.order_no}</p>
                            </div>
                            {stop.child_order_no && (
                              <div>
                                <p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Child Order</p>
                                <p style={{ margin: "2px 0 0", fontSize: 12, color: "#555" }}>{stop.child_order_no}</p>
                              </div>
                            )}
                          </>
                        ) : stop.atc ? (
                          <div>
                            <p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>ATC</p>
                            <p style={{ margin: "2px 0 0", fontSize: 12, color: "#555" }}>{stop.atc}</p>
                          </div>
                        ) : null}
                      </div>

                      {/* Status / Actions */}
                      {activeFilter === "pending" && (
                        <div style={{ display: "flex", gap: 8 }}>
                          <button
                            onClick={() => openConfirmModal(stop)}
                            style={{
                              flex: 1, padding: "11px 0", background: "#0070f3", color: "white",
                              border: "none", borderRadius: 8, cursor: "pointer", fontWeight: "bold",
                              fontSize: isMobile ? 14 : 13, minHeight: 44,
                              display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
                            }}
                          >
                            <Icon icon="mdi:check-circle" width={16} />
                            Confirm
                          </button>
                          <button
                            onClick={() => { setDisputingStop(stop); setDisputeReason(""); setMessage("") }}
                            style={{
                              flex: 1, padding: "11px 0", background: "white", color: "#ff4444",
                              border: "1.5px solid #ff4444", borderRadius: 8, cursor: "pointer",
                              fontWeight: "bold", fontSize: isMobile ? 14 : 13, minHeight: 44,
                              display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
                            }}
                          >
                            <Icon icon="mdi:alert-circle" width={16} />
                            Dispute
                          </button>
                        </div>
                      )}

                      {activeFilter === "confirmed" && (
                        <div style={{
                          display: "flex", alignItems: "center", gap: 6,
                          padding: "8px 10px", background: "#ecfdf5", borderRadius: 7,
                        }}>
                          <Icon icon="mdi:check-circle" width={16} color="#10b981" />
                          <span style={{ fontSize: 13, color: "#10b981", fontWeight: "600" }}>Confirmed</span>
                        </div>
                      )}

                      {activeFilter === "disputed" && (
                        <div style={{
                          display: "flex", alignItems: "center", gap: 6,
                          padding: "8px 10px", background: "#fff0f0", borderRadius: 7,
                        }}>
                          <Icon icon="mdi:alert-circle" width={16} color="#ff4444" />
                          <span style={{ fontSize: 13, color: "#ff4444", fontWeight: "600" }}>Disputed</span>
                        </div>
                      )}
                    </div>
                  ))
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* ΓòÉΓòÉ Confirmation Modal ΓòÉΓòÉ */}
      {selectedStop && (
        <div onClick={closeModal} style={modalOverlay}>
          <div onClick={e => e.stopPropagation()} style={modalBox}>
            {isMobile && <div style={{ width: 40, height: 4, background: "#e0e0e0", borderRadius: 2, margin: "0 auto 20px" }} />}
            <h3 style={{ margin: "0 0 4px", color: "#171717", fontSize: isMobile ? 18 : 16 }}>Confirm Stop</h3>
            <p style={{ color: "#888", fontSize: 13, marginBottom: 20 }}>
              {selectedStop.plate_number} ┬╖ {selectedStop.stop_location}
            </p>

            {/* Info card */}
            <div style={{ padding: "12px 14px", background: "#f9f9f9", borderRadius: 10, marginBottom: 20 }}>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                <div>
                  <p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Bags</p>
                  <p style={{ margin: "2px 0 0", fontWeight: "bold", fontSize: 16, color: "#171717" }}>{selectedStop.quantity_offloaded}</p>
                </div>
                <div>
                  <p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Loading Point</p>
                  <p style={{ margin: "2px 0 0", fontSize: 13, color: "#171717" }}>{selectedStop.material_centre}</p>
                </div>
                {selectedStop.order_no ? (
                  <>
                    <div>
                      <p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Order No</p>
                      <p style={{ margin: "2px 0 0", fontSize: 13, color: "#171717" }}>{selectedStop.order_no}</p>
                    </div>
                    {selectedStop.child_order_no && (
                      <div>
                        <p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Child Order</p>
                        <p style={{ margin: "2px 0 0", fontSize: 13, color: "#171717" }}>{selectedStop.child_order_no}</p>
                      </div>
                    )}
                  </>
                ) : selectedStop.atc ? (
                  <div>
                    <p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>ATC</p>
                    <p style={{ margin: "2px 0 0", fontSize: 13, color: "#171717" }}>{selectedStop.atc}</p>
                  </div>
                ) : null}
                <div>
                  <p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Driver's Customer</p>
                  <p style={{ margin: "2px 0 0", fontSize: 13, color: "#171717" }}>{selectedStop.customer_name}</p>
                </div>
              </div>
            </div>

            <div style={{ marginBottom: 16 }}>
              <label style={labelStyle}>Correct Customer (if not provided)</label>
              <CustomerSelector onSelect={(c) => setSelectedCustomer(c)} />
            </div>

            {companyPriceMap[selectedStop.product] !== undefined && (
              <div style={{ marginBottom: 12, padding: "8px 12px", background: "#f0f7ff", borderRadius: 8, border: "1px solid #bfdbfe", display: "flex", alignItems: "center", gap: 8 }}>
                <Icon icon="mdi:information" width={16} color="#0070f3" />
                <span style={{ fontSize: 13, color: "#0c4a6e" }}>Company price: <strong>Γéª{companyPriceMap[selectedStop.product].toLocaleString()}</strong>/bag</span>
              </div>
            )}

            <div style={{ marginBottom: 12 }}>
              <label style={labelStyle}>Price Per Bag (Γéª) *</label>
              <ModernInput
                type="text"
                inputMode="numeric"
                placeholder="e.g. 10,500"
                value={pricePerBag}
                onChange={(e) => { setPricePerBag(formatAmount(e.target.value)); setMessage("") }}
                style={inputStyle}
              />
            </div>

            {companyPriceMap[selectedStop.product] !== undefined && (
              <>
                <div style={{ marginBottom: 16 }}>
                  <label style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer", fontWeight: 500, fontSize: 13, color: "#444" }}>
                    <input type="checkbox" checked={soldAtDifferentPrice} onChange={e => handleToggleDifferentPrice(e.target.checked)} style={{ width: 16, height: 16, cursor: "pointer" }} />
                    Sold at a different price?
                  </label>
                </div>

                {soldAtDifferentPrice && (
                  <div style={{ display: "flex", gap: 10, marginBottom: 16 }}>
                    <div style={{ flex: 1 }}>
                      <label style={labelStyle}>Discount (Γéª)</label>
                      <ModernInput type="text" inputMode="numeric" placeholder="0" value={discount} onChange={e => handleDiscountChange(e.target.value)} style={inputStyle} />
                    </div>
                    <div style={{ flex: 1 }}>
                      <label style={labelStyle}>Sale Price (Γéª)</label>
                      <ModernInput type="text" inputMode="numeric" placeholder="Sale price" value={salePrice} onChange={e => handleSalePriceChange(e.target.value)} style={inputStyle} />
                    </div>
                  </div>
                )}
              </>
            )}

            {message && (
              <div style={{ display: "flex", alignItems: "center", gap: 6, color: "#ff4444", marginBottom: 14, fontSize: 13 }}>
                <Icon icon="mdi:alert-circle" width={15} />{message}
              </div>
            )}

            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={closeModal} style={{ flex: 1, padding: "13px 0", background: "white", border: "1.5px solid #e5e5e5", borderRadius: 10, cursor: "pointer", fontSize: 15, minHeight: 50 }}>
                Cancel
              </button>
              <button onClick={handleConfirm} disabled={submitting} style={{ ...fullBtn(submitting ? "#ccc" : "#0070f3"), flex: 1 }}>
                {submitting
                  ? <><Icon icon="mdi:loading" width={16} style={{ animation: "spin 1s linear infinite" }} /> ConfirmingΓÇª</>
                  : <><Icon icon="mdi:check-circle" width={16} /> Confirm Stop</>
                }
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ΓòÉΓòÉ Dispute Modal ΓòÉΓòÉ */}
      {disputingStop && (
        <div onClick={() => setDisputingStop(null)} style={modalOverlay}>
          <div onClick={e => e.stopPropagation()} style={modalBox}>
            {isMobile && <div style={{ width: 40, height: 4, background: "#e0e0e0", borderRadius: 2, margin: "0 auto 20px" }} />}
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
              <div style={{ width: 38, height: 38, borderRadius: 10, background: "#fff0f0", display: "flex", alignItems: "center", justifyContent: "center" }}>
                <Icon icon="mdi:alert-circle" width={20} color="#ff4444" />
              </div>
              <h3 style={{ margin: 0, color: "#ff4444", fontSize: isMobile ? 18 : 16 }}>Dispute Stop</h3>
            </div>
            <p style={{ color: "#888", fontSize: 13, marginBottom: 20 }}>
              {disputingStop.plate_number} ┬╖ {disputingStop.stop_location}
            </p>

            <div style={{ marginBottom: 24 }}>
              <label style={labelStyle}>Reason for Dispute *</label>
              <ModernInput
                as="textarea"
                placeholder="e.g. This stop does not belong to meΓÇª"
                value={disputeReason}
                onChange={e => { setDisputeReason(e.target.value); setMessage("") }}
                rows={4}
                style={{ ...inputStyle, resize: "none", minHeight: 110 }}
              />
            </div>

            {message && (
              <div style={{ display: "flex", alignItems: "center", gap: 6, color: "#ff4444", marginBottom: 14, fontSize: 13 }}>
                <Icon icon="mdi:alert-circle" width={15} />{message}
              </div>
            )}

            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={() => setDisputingStop(null)} style={{ flex: 1, padding: "13px 0", background: "white", border: "1.5px solid #e5e5e5", borderRadius: 10, cursor: "pointer", fontSize: 15, minHeight: 50 }}>
                Cancel
              </button>
              <button onClick={handleDispute} disabled={submitting} style={{ ...fullBtn(submitting ? "#ccc" : "#ff4444"), flex: 1 }}>
                {submitting
                  ? <><Icon icon="mdi:loading" width={16} style={{ animation: "spin 1s linear infinite" }} /> SubmittingΓÇª</>
                  : <><Icon icon="mdi:alert-circle" width={16} /> Submit Dispute</>
                }
              </button>
            </div>
          </div>
        </div>
      )}

      <ProfilePictureUpload
        isOpen={showPictureModal}
        onClose={() => setShowPictureModal(false)}
        userId={broker?.broker_id || ""}
        table="Brokers"
        idField="broker_id"
        currentUrl={broker?.profile_picture_url}
        onSuccess={(url) => setBroker(prev => prev ? { ...prev, profile_picture_url: url } : prev)}
      />

      <ReportModal
        isOpen={showReportModal}
        onClose={() => setShowReportModal(false)}
        userId={broker?.broker_id || ""}
        userRole={Role.Broker}
      />
    </div>
  )
}

"use client"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { supabase } from "@/lib/supabase"
import { Icon } from "@iconify/react"
import RoleSwitcher from "@/components/RoleSwitcher"
import CashOfficerPanel from "@/components/CashOfficerPanel"
import ReportModal from "@/components/ReportModal"
import ProfilePictureUpload from "@/components/ProfilePictureUpload"
import { FONT_SIZE } from "@/lib/constants"
import { useBreakpoint } from "@/app/hooks/useBreakpoint"
import { requireDashboardRole } from "@/lib/auth-helpers"
import { Role } from "@/lib/roles"

type Clerk = { clerk_id: string; full_name: string; office_name: string; profile_picture_url?: string }

export default function CashOfficerDashboard() {
  const bp = useBreakpoint()
  const isMobile = bp === "mobile"
  const router = useRouter()

  const [clerk, setClerk] = useState<Clerk | null>(null)
  const [loading, setLoading] = useState(true)
  const [showPictureModal, setShowPictureModal] = useState(false)
  const [showReportModal, setShowReportModal] = useState(false)
  const [avatarHover, setAvatarHover] = useState(false)

  useEffect(() => { init() }, [])

  async function init() {
    const { data: { session } } = await supabase.auth.getSession()
    if (!session) { router.push("/login"); return }

    const hasRole = await requireDashboardRole(session.user.id, Role.CashOfficer)
    if (!hasRole) { router.push("/login"); return }

    const { data: profile } = await supabase
      .from("Profiles").select("full_name").eq("user_id", session.user.id).single()

    if (profile) {
      const { data: clerkData } = await supabase
        .from("cash_officers")
        .select("clerk_id, full_name, office_name, profile_picture_url")
        .eq("clerk_id", session.user.id)
        .single()

      if (clerkData) {
        setClerk(clerkData)
      } else {
        setClerk({ clerk_id: session.user.id, full_name: profile.full_name, office_name: "" })
      }
    }

    setLoading(false)
  }

  if (loading) return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", minHeight: "100vh", fontFamily: "'Inter', sans-serif" }}>
      <div style={{ width: 40, height: 40, borderRadius: "50%", border: "3px solid #e2e8f0", borderTopColor: "#0070f3", animation: "spin 1s linear infinite" }} />
      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  )

  return (
    <div style={{ minHeight: "100vh", background: "#f8fafc", fontFamily: "'Inter', sans-serif" }}>

      {/* Profile Banner */}
      <div style={{ background: "white", borderBottom: "1px solid #e2e8f0", padding: isMobile ? "16px" : "24px 32px" }}>
        <div style={{ maxWidth: 1200, margin: "0 auto", display: "flex", alignItems: "center", gap: isMobile ? 12 : 16, justifyContent: "space-between" }}>
          <div style={{ display: "flex", alignItems: "center", gap: isMobile ? 12 : 16, flex: 1 }}>
            <div
              onClick={() => setShowPictureModal(true)}
              onMouseEnter={() => setAvatarHover(true)}
              onMouseLeave={() => setAvatarHover(false)}
              style={{
                width: isMobile ? 48 : 56,
                height: isMobile ? 48 : 56,
                borderRadius: "50%",
                background: clerk?.profile_picture_url ? "transparent" : "#f0f7ff",
                border: "2px solid #bfdbfe",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                flexShrink: 0,
                cursor: "pointer",
                position: "relative",
                overflow: "hidden",
                transition: "all 0.2s",
              }}
            >
              {clerk?.profile_picture_url ? (
                <img
                  src={clerk.profile_picture_url}
                  alt={clerk.full_name}
                  style={{ width: "100%", height: "100%", objectFit: "cover" }}
                />
              ) : (
                <span style={{ fontSize: isMobile ? 20 : 24, fontWeight: 700, color: "#0070f3" }}>
                  {clerk?.full_name?.charAt(0).toUpperCase()}
                </span>
              )}
              <div
                style={{
                  position: "absolute", inset: 0, background: "rgba(0, 0, 0, 0.4)",
                  display: "flex", alignItems: "center", justifyContent: "center",
                  opacity: avatarHover ? 1 : 0, transition: "opacity 0.2s",
                }}
              >
                <Icon icon="mdi:camera" width={20} height={20} color="white" />
              </div>
            </div>
            <div>
              <h1 style={{ margin: 0, fontSize: isMobile ? FONT_SIZE.lg : FONT_SIZE.xl, fontWeight: 700, color: "#0070f3" }}>
                {clerk?.full_name || ""}
              </h1>
              <RoleSwitcher currentRole={Role.CashOfficer} style={{ margin: "2px 0 0", fontSize: FONT_SIZE.sm, color: "#64748b" }} />
            </div>
          </div>
          <div style={{ display: "flex", gap: 8 }}>
            <button
              onClick={() => setShowReportModal(true)}
              style={{ padding: "8px 14px", background: "#fff8e1", color: "#f5a623", border: "1.5px solid #f8ad5c", borderRadius: 8, cursor: "pointer", fontSize: FONT_SIZE.sm, minHeight: 40, fontWeight: 600, display: "flex", alignItems: "center", gap: 6, transition: "all 0.2s", whiteSpace: "nowrap" }}
            >
              <Icon icon="mdi:alert-circle-outline" width={16} />
              {!isMobile && "Report"}
            </button>
            <button
              onClick={async () => { await supabase.auth.signOut(); router.push("/login") }}
              style={{ padding: "8px 16px", background: "rgba(239, 68, 68, 0.05)", color: "#ef4444", border: "1.5px solid #fecaca", borderRadius: 6, cursor: "pointer", fontSize: FONT_SIZE.sm, fontWeight: 600, transition: "all 0.2s", minHeight: 40, whiteSpace: "nowrap" }}
            >
              Logout
            </button>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div style={{ padding: isMobile ? "16px" : "32px", maxWidth: 1200, margin: "0 auto" }}>
        <div style={{ marginBottom: 40 }}>
          <CashOfficerPanel 
            clerkId={clerk?.clerk_id || ""} 
            officeName={clerk?.office_name || ""} 
            fullName={clerk?.full_name || ""} 
          />
        </div>
      </div>

      <ProfilePictureUpload
        isOpen={showPictureModal}
        onClose={() => setShowPictureModal(false)}
        userId={clerk?.clerk_id || ""}
        table="cash_officers"
        idField="clerk_id"
        currentUrl={clerk?.profile_picture_url}
        onSuccess={(url) => setClerk(prev => prev ? { ...prev, profile_picture_url: url } : prev)}
      />

      <ReportModal
        isOpen={showReportModal}
        onClose={() => setShowReportModal(false)}
        userId={clerk?.clerk_id || ""}
        userRole={Role.CashOfficer}
      />
    </div>
  )
}

"use client"

import { useState, useEffect, useRef } from "react"

import { Icon } from "@iconify/react"
import { supabase } from "@/lib/supabase"
import { apiMutate } from "@/lib/api-mutation"
import RoleSwitcher from "@/components/RoleSwitcher"
import StopForm from "@/components/StopForm"
import ModernInput from "@/components/ModernInput"
import TripOfflineIndicator from "@/components/TripOfflineIndicator"
import ProfilePictureUpload from "@/components/ProfilePictureUpload"
import { useBreakpoint } from "@/app/hooks/useBreakpoint"
import { useOfflineTripAction } from "@/app/hooks/useOfflineTripAction"
import { initTripActionAutoSync } from "@/lib/offline/tripActionSync"
import { clearOfflineTripData } from '@/lib/offline/tripsDb'
import { FONT_SIZE } from "@/lib/constants"
import { toISOString, formatDate } from "@/lib/date-utils"
import { requireDashboardRole } from "@/lib/auth-helpers"
import { Role } from "@/lib/roles"
import { useATFs } from "@/lib/hooks/useATFs"

type Driver = { driver_id: string; full_name: string; profile_picture_url?: string }
type Trip = {
  trip_id: string
  plate_number: string
  product: string
  material_centre: string
  loaded_quantity: number
  trip_status: string
  atc: string | null
  order_no: string | null
  child_order_no: string | null
  amount_charged: number | null
  payment_mode: string | null
}
type Stop = {
  stop_id: string
  stop_location: string
  quantity_offloaded: number
  stop_time: string
}
type Truck = { plate_number: string; kbnl_truck_no?: string; truck_size: string | null }
type Complaint = {
  complaint_id: string
  complaint_type: string
  notes: string
  plate_number: string
  reported_at: string
  resolved: boolean
}

type LoadMoreEntry = {
  id: string
  quantity: number
  loading_point_type: string
  loading_point_name: string
  product: string
  created_at: string
}

type ATF = {
  request_id: string
  atf_code: string | null
  plate_number: string
  company_name: string
  litres: number
  rate_per_litre: number | null
  total_amount: number | null
  atf_status: "Authorised" | "Dispensed" | "Confirmed" | "Invalidated" | "Pending"
  requested_at: string
  invalidation_reason: string | null
}

type ViewType = "dashboard" | "start-trip" | "active-trip" | "log-stop" | "fuel" | "side-trips"

const LOADING_POINT_MAP: Record<string, string[]> = {
  Factory: ["HBM Mfamosing", "HBM Uyo Warehouse"],
  Depot: ["Calabar Mini Depot", "Ikom Mini Depot", "Ogoja Depot", "Uyo Depot"],
  Outlet: ["Brooks Outlet", "Urua Ekpa Outlet", "Urua Nyemeiko Outlet", "Reserve Store", "E1 Outlet", "Ogoja Outlet"],
}

const FACTORY_PRODUCTS: Record<string, string[]> = {
  "HBM Mfamosing": ["Classic", "Supaset", "Supafix"],
  "HBM Uyo Warehouse": ["Classic", "Supaset", "Supafix"],
}

const SIDE_TRIP_ITEMS = ["Yam", "Plantain", "Cassava", "Maize", "Rice", "Other foodstuff"]

const COMPLAINT_TYPES = [
  "Breakdown", "Tyre Blowout", "Accident", "Police / Checkpoint Issue",
  "Fuel Problem", "Mechanical Fault", "Road Blockage", "Other",
]

const ATF_STATUS_CONFIG = {
  Authorised: { color: "#f5a623", bg: "#fff8e1", icon: "mdi:clock-outline", label: "Awaiting Dispensing" },
  Dispensed: { color: "#0070f3", bg: "#f0f7ff", icon: "mdi:gas-station-outline", label: "Dispensed ΓÇö Confirm Receipt" },
  Confirmed: { color: "#16a34a", bg: "#f0fff4", icon: "mdi:check-circle", label: "Confirmed" },
  Invalidated: { color: "#ef4444", bg: "#fef2f2", icon: "mdi:close-circle", label: "Invalidated" },
  Pending: { color: "#94a3b8", bg: "#f8fafc", icon: "mdi:clock-outline", label: "Pending Authorisation" },
}


export default function DriverDashboard() {
  const [view, setView] = useState<ViewType>("dashboard")
  
  const bp = useBreakpoint()
  const isMobile = bp === "mobile"

  const { submitAction, isSubmitting: isOfflineSubmitting, isOnline } = useOfflineTripAction()

  const [driver, setDriver] = useState<Driver | null>(null)
  const [activeTrip, setActiveTrip] = useState<Trip | null>(null)
  const [stops, setStops] = useState<Stop[]>([])
  const [remaining, setRemaining] = useState(0)
  const [offloadedSoFar, setOffloadedSoFar] = useState(0)
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [message, setMessage] = useState("")

  // ATF
  const [loadMoreEntries, setLoadMoreEntries] = useState<LoadMoreEntry[]>([])
  const [atfs, setAtfs] = useState<ATF[]>([])
  const [activeATF, setActiveATF] = useState<ATF | null>(null)
  const [confirmingATF, setConfirmingATF] = useState(false)
  const [atfFilter, setAtfFilter] = useState<{ driver_id: string } | null>(null)
  const { data: atfsFromHook, refetch: refetchATFs } = useATFs(atfFilter ?? undefined)
  useEffect(() => {
    setAtfs(atfsFromHook as ATF[])
    const active = atfsFromHook.find(a => a.atf_status === "Authorised" || a.atf_status === "Dispensed")
    setActiveATF((active as ATF) ?? null)
  }, [atfsFromHook])

  // Modals
  const [showEndConfirm, setShowEndConfirm] = useState(false)
  const [showHoldConfirm, setShowHoldConfirm] = useState(false)
  const [showDiscrepancyModal, setShowDiscrepancyModal] = useState(false)
  const [showComplaintModal, setShowComplaintModal] = useState(false)
  const [showLoadMoreModal, setShowLoadMoreModal] = useState(false)
  const [showPictureModal, setShowPictureModal] = useState(false)

  // Discrepancy
  const [discrepancyType, setDiscrepancyType] = useState<'shortage' | 'caked'>('shortage')
  const [discShortage, setDiscShortage] = useState("")
  const [discCaked, setDiscCaked] = useState("")
  const [discNotes, setDiscNotes] = useState("")
  const [discError, setDiscError] = useState("")
  const [discSubmitting, setDiscSubmitting] = useState(false)

  // Complaint
  const [complaintType, setComplaintType] = useState("")
  const [complaintTruck, setComplaintTruck] = useState("")
  const [complaintNotes, setComplaintNotes] = useState("")
  const [complaintError, setComplaintError] = useState("")
  const [complaintSubmitting, setComplaintSubmitting] = useState(false)
  const [complaintPendingEndTrip, setComplaintPendingEndTrip] = useState(false)
  const [showMyComplaints, setShowMyComplaints] = useState(false)
  const [complaintsRefreshKey, setComplaintsRefreshKey] = useState(0)
  const [myComplaints, setMyComplaints] = useState<Complaint[]>([])
  const [fetchingComplaints, setFetchingComplaints] = useState(false)
  const [resolvingComplaintId, setResolvingComplaintId] = useState<string | null>(null)

  // Load more
  const [loadMoreQty, setLoadMoreQty] = useState("")
  const [loadMoreCategory, setLoadMoreCategory] = useState("")
  const [loadMoreLocationName, setLoadMoreLocationName] = useState("")
  const [loadMoreProduct, setLoadMoreProduct] = useState("")
  const [loadMoreProductOptions, setLoadMoreProductOptions] = useState<string[]>([])
  const [loadMoreError, setLoadMoreError] = useState("")
  const [loadMoreSubmitting, setLoadMoreSubmitting] = useState(false)

  // Side trips
  const [sideTripTruck, setSideTripTruck] = useState("")
  const [sideTripItem, setSideTripItem] = useState("")
  const [sideTripCustomItem, setSideTripCustomItem] = useState("")
  const [sideTripSubmitting, setSideTripSubmitting] = useState(false)
  const [sideTripMessage, setSideTripMessage] = useState("")
  const [mySideTrips, setMySideTrips] = useState<{ id: string; plate_number: string; item_description: string; created_at: string }[]>([])

  // Start trip
  const [truckSize, setTruckSize] = useState("")
  const [plateNumber, setPlateNumber] = useState("")
  const [loadingPointCategory, setLoadingPointCategory] = useState("")
  const [loadingPointName, setLoadingPointName] = useState("")
  const [product, setProduct] = useState("")
  const [loadedQuantity, setLoadedQuantity] = useState("")
  const [atc, setAtc] = useState("")
  const [orderNo, setOrderNo] = useState("")
  const [childOrderNo, setChildOrderNo] = useState("")
  const [amountCharged, setAmountCharged] = useState("")
  const [paymentMode, setPaymentMode] = useState("")
  const [trucks, setTrucks] = useState<Truck[]>([])
  const [allTrucks, setAllTrucks] = useState<Truck[]>([])
  const [productOptions, setProductOptions] = useState<string[]>([])
  const [allProducts, setAllProducts] = useState<string[]>([])

  const loadedQtyRef = useRef<HTMLInputElement | null>(null)
  const allStoreLocations = [...LOADING_POINT_MAP.Depot, ...LOADING_POINT_MAP.Outlet]

  const mountedRef = useRef(true)

  useEffect(() => {
    initTripActionAutoSync()
  }, [])

  useEffect(() => {
    mountedRef.current = true
    initDriver()
    return () => { mountedRef.current = false }
  }, [])

  // Sync initial view from URL
  useEffect(() => {
    const params = new URLSearchParams(window.location.search)
    const viewParam = params.get('view') as ViewType | null
    if (viewParam && ["dashboard", "start-trip", "active-trip", "log-stop", "fuel", "side-trips"].includes(viewParam)) {
      setView(viewParam)
    }
  }, [])

  // Handle browser back/forward
  useEffect(() => {
    const handlePopState = () => {
      const params = new URLSearchParams(window.location.search)
      const viewParam = params.get('view') as ViewType | null
      if (viewParam && ["dashboard", "start-trip", "active-trip", "log-stop", "fuel", "side-trips"].includes(viewParam)) {
        setView(viewParam)
      }
    }
    window.addEventListener('popstate', handlePopState)
    return () => window.removeEventListener('popstate', handlePopState)
  }, [])

  function navigateTo(newView: ViewType) {
    setView(newView)
    window.history.pushState(null, '', `/driver?view=${newView}`)
  }

  async function initDriver() {
    const { data: { session } } = await supabase.auth.getSession()
    if (!session) { window.location.href = "/login"; return }
    if (!mountedRef.current) return
    const user = session.user

    const hasRole = await requireDashboardRole(user.id, Role.Driver)
    if (!hasRole) { window.location.href = "/login"; return }
    if (!mountedRef.current) return

    const { data: profile } = await supabase
      .from("Profiles").select("full_name").eq("user_id", user.id).single()
    if (!mountedRef.current) return

    const { data: driverData } = await supabase
      .from("Drivers").select("driver_id, full_name, profile_picture_url").eq("driver_id", user.id).single()

    if (driverData) {
      setDriver(driverData)
    } else if (profile) {
      setDriver({ driver_id: user.id, full_name: profile.full_name })
    }

    const { data: tripData } = await supabase
      .from("Trips").select("*").eq("driver_id", user.id)
      .in("trip_status", ["In transit", "On hold"]).single()

    if (tripData) {
      setActiveTrip(tripData)
      await Promise.all([
        fetchStops(tripData.trip_id, tripData.loaded_quantity),
        fetchLoadMoreEntries(tripData.trip_id),
      ])
    }

    const { data: trucksData } = await supabase
      .from("Trucks").select("plate_number, kbnl_truck_no, truck_size").neq("status", "Decommissioned")
    if (!mountedRef.current) return
    let merged: Truck[] = [...(trucksData || [])]

    const { data: tricyclesData } = await supabase
      .from("tricycles").select("tricycle_number, assigned_to")
    if (!mountedRef.current) return
    const allTricycles: Truck[] = (tricyclesData || [])
      .map(t => ({ plate_number: t.tricycle_number, kbnl_truck_no: t.assigned_to, truck_size: "Tricycle" }))
    merged = [...merged, ...allTricycles]

    setTrucks(merged)
    setAllTrucks(merged)

    const { data: productsData } = await supabase.rpc("get_products")
    if (!mountedRef.current) return
    if (productsData) {
      const list = productsData.map((r: { value: string }) => r.value)
      setAllProducts(list)
      setProductOptions(list)
    }

    setAtfFilter({ driver_id: user.id })
    if (!mountedRef.current) return
    fetchSideTrips(user.id)
    setLoading(false)
  }

  async function fetchStops(tripId: string, loadedQty: number) {
    try {
      const { data: stopsData } = await supabase
        .from("Stops").select("stop_id, stop_location, quantity_offloaded, stop_time")
        .eq("trip_id", tripId).order("stop_time", { ascending: false })

      const { data: discData } = await supabase
        .from("trip_discrepancies").select("shortage, caked_bags").eq("trip_id", tripId)

      const stopList = stopsData || []
      setStops(stopList)

      const totalOffloaded = stopList.reduce((sum, s) => sum + s.quantity_offloaded, 0)
      const totalShortage = (discData || []).reduce((sum, d) => sum + (d.shortage || 0), 0)
      const totalCaked = (discData || []).reduce((sum, d) => sum + (d.caked_bags || 0), 0)
      const total = totalOffloaded + totalShortage + totalCaked
      
      setOffloadedSoFar(total)
      
      const rem = loadedQty - total
      setRemaining(rem)
      if (rem <= 0 && tripId) setShowEndConfirm(true)
    } catch (error) {
      console.warn('[fetchStops] Network error, keeping local state', error)
    }
  }

  async function fetchLoadMoreEntries(tripId: string) {
    const { data } = await supabase
      .from("trip_load_more")
      .select("id, quantity, loading_point_type, loading_point_name, product, created_at")
      .eq("trip_id", tripId)
      .order("created_at", { ascending: false })

    setLoadMoreEntries(data || [])
  }

  async function fetchSideTrips(driverId?: string) {
    const id = driverId || driver?.driver_id
    if (!id) return
    const { data } = await supabase
      .from("side_trips")
      .select("id, plate_number, item_description, created_at")
      .eq("driver_id", id)
      .order("created_at", { ascending: false })

    setMySideTrips(data || [])
  }

  async function handleSubmitSideTrip() {
    if (!sideTripTruck) return setSideTripMessage("Select a truck")
    const item = sideTripItem === "Other foodstuff" ? sideTripCustomItem.trim() : sideTripItem
    if (!item) return setSideTripMessage("Select or enter the item you're carrying")

    setSideTripSubmitting(true)
    const { error } = await apiMutate("admin", {
      action: "insert",
      table: "side_trips",
      data: {
        driver_id: driver?.driver_id,
        plate_number: sideTripTruck,
        item_description: item,
      },
    })
    setSideTripSubmitting(false)

    if (error) { setSideTripMessage("Failed to record side trip"); return }

    setSideTripTruck(""); setSideTripItem(""); setSideTripCustomItem(""); setSideTripMessage("")
    await fetchSideTrips()
  }

  async function handleConfirmReceipt() {
    if (!activeATF || !driver) return
    setConfirmingATF(true)
    await apiMutate("fuel", {
      action: "rpc",
      function: "confirm_fuel_receipt",
      params: {
        p_request_id: activeATF.request_id,
        p_driver_id: driver.driver_id,
      },
    })
    setConfirmingATF(false)
    refetchATFs()
  }


  function handleCategoryChange(cat: string) {
    setLoadingPointCategory(cat); setLoadingPointName(""); setProduct(""); setAtc(""); setOrderNo(""); setChildOrderNo(""); setAmountCharged(""); setPaymentMode(""); setMessage("")
  }

  function handleLoadingPointNameChange(name: string) {
    setLoadingPointName(name); setProduct(""); setAtc(""); setOrderNo(""); setChildOrderNo(""); setMessage("")
    setProductOptions(loadingPointCategory === "Factory" ? (FACTORY_PRODUCTS[name] || []) : allProducts)
  }

  function handleLoadMoreCategoryChange(cat: string) {
    setLoadMoreCategory(cat); setLoadMoreLocationName(""); setLoadMoreProduct(""); setLoadMoreProductOptions([]); setLoadMoreError("")
  }

  function handleLoadMoreLocationChange(name: string) {
    setLoadMoreLocationName(name); setLoadMoreProduct(""); setLoadMoreError("")
    setLoadMoreProductOptions(allProducts)
  }

  const isDinaOrTricycle = truckSize === "Dina" || truckSize === "Tricycle"
  const showHbmOrderFields = loadingPointCategory === "Factory" && loadingPointName === "HBM Mfamosing" && !isDinaOrTricycle
  const showATC = loadingPointCategory === "Factory" && !showHbmOrderFields && !isDinaOrTricycle
  const availableLocations = LOADING_POINT_MAP[loadingPointCategory] || []

  async function handleStartTrip() {
    if (!truckSize) return setMessage("Select a truck size")
    if (!plateNumber) return setMessage("Select a plate number")
    if (!loadingPointCategory) return setMessage("Select a loading point type")
    if (!loadingPointName) return setMessage("Select a loading point")
    if (showATC && !atc.trim()) return setMessage("ATC number is required")
    if (showHbmOrderFields && !orderNo.trim()) return setMessage("Order number is required")
    if (showHbmOrderFields && !childOrderNo.trim()) return setMessage("Child order number is required")
    if (isDinaOrTricycle && !amountCharged) return setMessage("Enter amount charged")
    if (isDinaOrTricycle && !paymentMode) return setMessage("Select payment mode")
    if (!product) return setMessage("Select a product")
    if (!loadedQuantity) return setMessage("Enter no. of bags")

    setSubmitting(true)
    const { data, error } = await apiMutate("trips", {
      action: "insert",
      table: "Trips",
      data: {
        driver_id: driver?.driver_id, plate_number: plateNumber, product,
        material_centre: loadingPointName, loaded_quantity: parseInt(loadedQuantity),
        ATC: showATC ? atc.trim() : null,
        order_no: showHbmOrderFields ? orderNo.trim() : null,
        child_order_no: showHbmOrderFields ? childOrderNo.trim() : null,
        amount_charged: isDinaOrTricycle ? parseFloat(amountCharged) : null,
        payment_mode: isDinaOrTricycle ? paymentMode : null,
        trip_status: "In transit",
      },
    })

    if (error || !data || !Array.isArray(data) || data.length === 0) { setMessage("Failed to start trip"); setSubmitting(false); return }
    if (truckSize !== "Tricycle") {
      await apiMutate("trips", { action: "update", table: "Trucks", data: { status: "Loaded" }, filters: { plate_number: plateNumber } })
    }
    setActiveTrip(data[0]); setRemaining(parseInt(loadedQuantity)); setOffloadedSoFar(0); setStops([]); setLoadMoreEntries([])
    setSubmitting(false); setShowEndConfirm(false); setMessage(""); navigateTo("active-trip")
  }

  async function handleEndTrip() {
    if (!activeTrip) return
    setSubmitting(true)

    await clearOfflineTripData(activeTrip.trip_id);
    await apiMutate("trips", { action: "update", table: "Trips", data: { trip_status: "Completed", updated_at: toISOString() }, filters: { trip_id: activeTrip.trip_id } })
    await apiMutate("trips", { action: "update", table: "Trucks", data: { status: "Empty" }, filters: { plate_number: activeTrip.plate_number } })
    setSubmitting(false); setShowEndConfirm(false); setActiveTrip(null); setStops([]); setLoadMoreEntries([]); setRemaining(0); setOffloadedSoFar(0); navigateTo("dashboard")
  }

  async function handleHoldTrip() {
    if (!activeTrip) return
    setSubmitting(true)
    const newStatus = activeTrip.trip_status === "On hold" ? "In transit" : "On hold"
    await apiMutate("trips", { action: "update", table: "Trips", data: { trip_status: newStatus }, filters: { trip_id: activeTrip.trip_id } })
    setActiveTrip({ ...activeTrip, trip_status: newStatus }); setSubmitting(false); setShowHoldConfirm(false)
  }

  async function handleReportDiscrepancy() {
    const shortage = parseInt(discShortage) || 0
    const caked = parseInt(discCaked) || 0

    if (discrepancyType === 'shortage') {
      if (shortage === 0) return setDiscError("Enter shortage bags count")
      if (shortage < 0) return setDiscError("Values cannot be negative")
      if (shortage > remaining) return setDiscError(`Shortage cannot exceed remaining bags (${remaining})`)
    } else {
      if (caked === 0) return setDiscError("Enter caked bags count")
      if (caked < 0) return setDiscError("Values cannot be negative")
    }

    setDiscSubmitting(true)
    
    const discrepancyData = {
      trip_id: activeTrip?.trip_id,
      driver_id: driver?.driver_id,
      shortage: discrepancyType === 'shortage' ? shortage : 0,
      caked_bags: discrepancyType === 'caked' ? caked : 0,
      discrepancy_type: discrepancyType,
      notes: discNotes.trim() || null,
    }

    const result = await submitAction(
      'discrepancy',
      activeTrip?.trip_id ?? '',
      'trip_discrepancies',
      discrepancyData
    )

    setDiscSubmitting(false)

    if (!result.success) {
      setDiscError(result.error || "Failed to submit report")
      return
    }

    setShowDiscrepancyModal(false)
    setDiscrepancyType('shortage')
    setDiscShortage(""); setDiscCaked(""); setDiscNotes(""); setDiscError("")
    
    if (result.offline) {
      setMessage("Γ£à Report saved offline. Will sync when connected.")
    }
    
    if (activeTrip) fetchStops(activeTrip.trip_id, activeTrip.loaded_quantity)
  }

  async function handleLoadMore() {
    const qty = parseInt(loadMoreQty)
    if (!loadMoreCategory) return setLoadMoreError("Select a loading point type")
    if (!loadMoreLocationName) return setLoadMoreError("Select a loading point")
    if (!loadMoreProduct) return setLoadMoreError("Select a product")
    if (!qty || qty <= 0) return setLoadMoreError("Enter a valid number of bags")
    if (!activeTrip) return

    setLoadMoreSubmitting(true)
    const newTotal = activeTrip.loaded_quantity + qty

    const updateData = {
      trip_id: activeTrip.trip_id,
      loaded_quantity: newTotal,
      trip_status: activeTrip.trip_status,
      updated_at: toISOString(),
    }

    const result = await submitAction(
      'load_more',
      activeTrip.trip_id,
      'Trips',
      updateData
    )

    setLoadMoreSubmitting(false)

    if (!result.success) {
      setLoadMoreError(result.error || "Failed to update bags")
      return
    }

    const moreCat = loadMoreCategory
    const moreLoc = loadMoreLocationName
    const moreProd = loadMoreProduct

    setActiveTrip({ ...activeTrip, loaded_quantity: newTotal }); setRemaining(remaining + qty)
    setShowLoadMoreModal(false); setLoadMoreQty(""); setLoadMoreCategory("")
    setLoadMoreLocationName(""); setLoadMoreProduct(""); setLoadMoreProductOptions([]); setLoadMoreError("")

    if (!result.offline && navigator.onLine && activeTrip) {
      await apiMutate("trips", {
        action: "insert",
        table: "trip_load_more",
        data: {
          trip_id: activeTrip.trip_id,
          quantity: qty,
          loading_point_type: moreCat,
          loading_point_name: moreLoc,
          product: moreProd,
        },
      })
      await fetchLoadMoreEntries(activeTrip.trip_id)
    }

    if (result.offline) {
      setMessage("Γ£à Saved offline. Will update when you are connected.")
    }
  }

  async function handleSubmitComplaint(thenEndTrip = false) {
    if (!complaintTruck) return setComplaintError("Select a truck")
    if (!complaintType) return setComplaintError("Select a complaint type")
    if (!complaintNotes.trim()) return setComplaintError("Please describe the issue")

    if (!isOnline) {
      setComplaintError("ΓÜá∩╕Å Internet required to submit complaints")
      return
    }

    setComplaintSubmitting(true)
    const { error } = await apiMutate("admin", {
      action: "insert",
      table: "driver_complaints",
      data: {
        driver_id: driver?.driver_id, trip_id: activeTrip?.trip_id ?? null,
        plate_number: complaintTruck, complaint_type: complaintType, notes: complaintNotes.trim(),
      },
    })
    setComplaintSubmitting(false)
    if (error) { setComplaintError("Failed to submit complaint"); return }

    setShowComplaintModal(false); setComplaintType(""); setComplaintTruck("")
    setComplaintNotes(""); setComplaintError(""); setComplaintPendingEndTrip(false)
    if (thenEndTrip) { handleEndTrip() } else { setComplaintsRefreshKey(k => k + 1) }
  }

  useEffect(() => {
    if (!showMyComplaints) return
    let cancelled = false
    ;(async () => {
      setFetchingComplaints(true)
      const { data } = await supabase
        .from("driver_complaints")
        .select("complaint_id, complaint_type, notes, plate_number, reported_at, resolved")
        .eq("driver_id", driver?.driver_id)
        .order("reported_at", { ascending: false })
      if (!cancelled) {
        setMyComplaints(data || [])
        setFetchingComplaints(false)
      }
    })()
    return () => { cancelled = true }
  }, [showMyComplaints, complaintsRefreshKey])

  async function handleMarkResolved(id: string) {
    setResolvingComplaintId(id)
    try {
      await apiMutate("admin", {
        action: "update", table: "driver_complaints",
        data: { resolved: true }, filters: { complaint_id: id },
      })
      setMyComplaints(prev => prev.map(c => c.complaint_id === id ? { ...c, resolved: true } : c))
    } finally {
      setResolvingComplaintId(null)
    }
  }

  function openComplaintFromEndTrip() {
    setComplaintPendingEndTrip(true); setShowEndConfirm(false); setShowComplaintModal(true)
  }

  function handleStopLogged(quantityOffloaded: number) {
    setRemaining(remaining - quantityOffloaded);
    setOffloadedSoFar(offloadedSoFar + quantityOffloaded);

    if (navigator.onLine && activeTrip) {
      fetchStops(activeTrip.trip_id, activeTrip.loaded_quantity)
    }

    navigateTo("active-trip")
  }

