          {isLow && <p style={{ margin: "8px 0 0", fontSize: FONT_SIZE.sm, color: "#f5a623", fontWeight: 600 }}>ΓÜá∩╕Å Below threshold (Γéª{lowThreshold.toLocaleString()})</p>}
