                  <div>
                    <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Litres Authorised</p>
                    <p style={{ margin: "2px 0 0", fontWeight: 700, fontSize: FONT_SIZE.lg, color: "#0070f3" }}>{atf.litres}L</p>
