@keyframes pulseGlow { 0%, 100% { box-shadow: 0 0 5px rgba(16, 185, 129, 0.3); border-color: #6ee7b7; } 50% { box-shadow: 0 0 20px rgba(16, 185, 129, 0.6); border-color: #34d399; } }`}</style>
    </div>
