            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {filteredSales.slice(0, salesPage * PAGE_SIZE).map(sale => {
                const totalAmount = sale.lines.reduce((sum, line) => sum + (line.total_amount ?? 0), 0)
                const hasBrokerPricing = sale.lines.some(line => line.price_per_bag === null)

                return (
                <div key={sale.group_id} style={{ background: "white", border: "1px solid #e2e8f0", borderRadius: 12, padding: 16, boxShadow: "0 1px 3px rgba(0,0,0,0.05)" }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 12 }}>
                    <div style={{ flex: 1 }}>
                      <p style={{ margin: 0, fontWeight: 700, fontSize: FONT_SIZE.lg, color: "#0f172a" }}>
                        {sale.lines.length === 1 ? sale.lines[0].product : `${sale.lines.length} products`}
                      </p>
                      {sale.customer_name && <p style={{ margin: "4px 0 0", fontSize: FONT_SIZE.sm, color: "#64748b" }}>{sale.customer_name}</p>}
                      {sale.broker_name && <p style={{ margin: "4px 0 0", fontSize: FONT_SIZE.sm, color: "#0070f3", fontWeight: 500 }}>Broker: {sale.broker_name}</p>}
                      <p style={{ margin: "4px 0 0", fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>{formatDateTime(sale.sold_at)}</p>
                    </div>
                    <div style={{ textAlign: "right" }}>
                      {!hasBrokerPricing ? (
                        <>
                          <p style={{ margin: 0, fontWeight: 700, fontSize: FONT_SIZE.lg, color: "#16a34a" }}>Γéª{totalAmount.toLocaleString()}</p>
                          <span style={{ fontSize: FONT_SIZE.xs, padding: "3px 8px", borderRadius: 6, background: "#f0f7ff", color: "#0070f3", fontWeight: 600, display: "inline-block", marginTop: 4 }}>{sale.payment_mode}</span>
                        </>
                      ) : (
                        <>
                          <p style={{ margin: 0, fontWeight: 700, fontSize: FONT_SIZE.lg, color: "#94a3b8", fontStyle: "italic" }}>Provided by broker</p>
                          <span style={{ fontSize: FONT_SIZE.xs, padding: "3px 8px", borderRadius: 6, background: "#f0f7ff", color: "#0070f3", fontWeight: 600, display: "inline-block", marginTop: 4 }}>{sale.payment_mode}</span>
                        </>
                      )}
                    </div>
                  </div>

                  {sale.broker_id && (
                    <div style={{ background: "#f8fafc", borderRadius: 8, padding: "10px 12px", marginBottom: 10, border: "1px solid #e2e8f0" }}>
                      <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Status</p>
                      <span style={{
                        fontSize: FONT_SIZE.xs, padding: "4px 10px", borderRadius: 6,
                        background: sale.status === "Pending" ? "#fffbeb" : sale.status === "Confirmed" ? "#ecfdf5" : "#fef2f2",
                        color: getStatusColor(sale.status), fontWeight: 600, display: "inline-block", marginTop: 4,
                      }}>
                        {sale.status}
                      </span>
                      {sale.status === "Rejected" && sale.rejection_reason && (
                        <div style={{ display: "flex", gap: 10, alignItems: "flex-start", marginTop: 8, padding: 10, background: "#fef2f2", borderRadius: 8, border: "1px solid #fecaca" }}>
                          <div style={{ background: "#ef4444", color: "white", padding: 3, borderRadius: "50%", flexShrink: 0, marginTop: 1 }}>
                            <Icon icon="mdi:close" width={12} height={12} />
                          </div>
                          <div>
                            <p style={{ margin: "0 0 4px 0", color: "#ef4444", fontSize: FONT_SIZE.xs, fontWeight: 600 }}>Rejected by broker</p>
                            <div style={{ padding: "8px 10px", background: "white", borderRadius: 6, border: "1px solid #fecaca", color: "#7f1d1d", fontSize: FONT_SIZE.xs, fontStyle: "italic" }}>
                              &ldquo;{sale.rejection_reason}&rdquo;
                            </div>
                          </div>
                        </div>
                      )}
                    </div>
                  )}

                  {(() => {
                    const deliveryModeConfig: Record<string, { label: string; icon: string; bg: string; border: string; color: string }> = {
                      self: { label: "Self", icon: "mdi:account", bg: "#f0fdf4", border: "#bbf7d0", color: "#16a34a" },
                      tricycle: { label: sale.tricycle_number || "Tricycle", icon: "mdi:rickshaw", bg: "#eff6ff", border: "#bfdbfe", color: "#0070f3" },
                      truck: { label: sale.truck_plate || "Truck", icon: "mdi:truck", bg: "#fefce8", border: "#fde68a", color: "#ca8a04" },
                    }
                    const cfg = deliveryModeConfig[sale.delivery_mode]
                    if (!cfg) return null
                    return (
                      <div style={{ background: cfg.bg, borderRadius: 8, padding: "10px 12px", marginBottom: 10, border: `1px solid ${cfg.border}` }}>
                        <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Delivery Mode</p>
                        <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 4 }}>
                          <Icon icon={cfg.icon} width={18} height={18} color={cfg.color} />
                          <p style={{ margin: 0, fontWeight: 600, fontSize: FONT_SIZE.base, color: cfg.color }}>{cfg.label}</p>
                        </div>
                      </div>
                    )
                  })()}

                  <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                    {sale.lines.map(line => (
                      <div key={line.sale_id} style={{ display: "grid", gridTemplateColumns: line.price_per_bag !== null ? "1.4fr 0.7fr 0.9fr" : "1.4fr 0.7fr", gap: 8 }}>
                        <div style={{ background: "#f8fafc", borderRadius: 8, padding: "8px 12px" }}>
                          <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Product</p>
                          <p style={{ margin: "2px 0 0", fontWeight: 600, fontSize: FONT_SIZE.base, color: "#0f172a" }}>{line.product}</p>
                        </div>
                        <div style={{ background: "#f8fafc", borderRadius: 8, padding: "8px 12px" }}>
                          <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Bags</p>
                          <p style={{ margin: "2px 0 0", fontWeight: 600, fontSize: FONT_SIZE.base, color: "#0f172a" }}>{line.quantity}</p>
                        </div>
                        {line.price_per_bag !== null && (
                          <div style={{ background: "#f8fafc", borderRadius: 8, padding: "8px 12px" }}>
                            <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Price/Bag</p>
                            <p style={{ margin: "2px 0 0", fontWeight: 600, fontSize: FONT_SIZE.base, color: "#0f172a" }}>Γéª{line.price_per_bag.toLocaleString()}</p>
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
                )
              })}
            </div>
          </div>
        )}

        {/* Stock Tab */}
        {tab === "stock" && (
          <div>
            <p style={{ margin: "0 0 16px 0", fontWeight: 700, fontSize: FONT_SIZE.lg, color: "#0f172a" }}>Current Stock</p>
            {stock.length === 0 && <p style={{ color: "#64748b", fontSize: FONT_SIZE.base }}>No stock data yet.</p>}
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {stock.map(s => (
                <div key={s.product} style={{ background: "white", border: "1px solid #e2e8f0", borderRadius: 12, padding: 16, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <p style={{ margin: 0, fontWeight: 600, fontSize: FONT_SIZE.lg, color: "#0f172a" }}>{s.product}</p>
                  <p style={{ margin: 0, fontWeight: 700, fontSize: FONT_SIZE.lg, color: s.balance === 0 ? "#ef4444" : s.balance < 50 ? "#f5a623" : "#0070f3" }}>
                    {s.balance} <span style={{ fontSize: FONT_SIZE.sm, fontWeight: 500, color: "#64748b", marginLeft: 4 }}>bags</span>
                  </p>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Confirm Supply Modal */}
      {confirmingStop && (
        <div onClick={() => { setConfirmingStop(null); setSupplyLines([{ product: "", quantity: "" }]); setConfirmError(""); setShowDiscrepancyPrompt(false); setDiscrepancyNote("") }} style={{ position: "fixed", inset: 0, background: "rgba(15, 23, 42, 0.6)", backdropFilter: "blur(4px)", display: "flex", alignItems: isMobile ? "flex-end" : "center", justifyContent: "center", zIndex: 100, padding: isMobile ? 0 : 24 }}>
          <div onClick={e => e.stopPropagation()} style={{ background: "white", borderRadius: isMobile ? "20px 20px 0 0" : 12, padding: isMobile ? "28px 20px" : 32, width: "100%", maxWidth: 480, maxHeight: "90vh", overflowY: "auto", boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.25)" }}>
            <h3 style={{ margin: "0 0 6px 0", fontSize: FONT_SIZE.xl, fontWeight: 700, color: "#0f172a" }}>Confirm Supply</h3>
            <p style={{ color: "#94a3b8", fontSize: FONT_SIZE.sm, margin: "0 0 4px 0" }}>
              {confirmingStop.plate_number} ┬╖ {confirmingStop.driver_name}
            </p>
            <p style={{ color: "#64748b", fontSize: FONT_SIZE.sm, margin: "0 0 20px 0" }}>
              Total: <strong>{confirmingStop.quantity_offloaded} bags</strong>
            </p>

            <p style={{ fontWeight: 700, fontSize: FONT_SIZE.base, margin: "0 0 4px 0", color: "#0f172a" }}>Breakdown by Product *</p>
            <p style={{ fontSize: FONT_SIZE.xs, color: "#94a3b8", margin: "0 0 12px 0" }}>Total should match bags delivered</p>

            <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 16 }}>
              {supplyLines.map((line, i) => (
                <div key={i} style={{ display: "flex", gap: 8, alignItems: "center", width: "100%" }}>
                  <ModernInput
                    as="select"
                    value={line.product}
                    onChange={e => updateSupplyLine(i, "product", e.target.value)}
                    style={{ flex: 1, minWidth: 0, padding: "10px 12px", borderRadius: 6, border: "1px solid #e0e0e0", fontSize: FONT_SIZE.sm, boxSizing: "border-box" }}
                  >
                    <option value="">Select product</option>
                    {allProducts.map(p => (<option key={p} value={p}>{p}</option>))}
                  </ModernInput>
                  <ModernInput
                    type="number"
                    placeholder="Qty"
                    value={line.quantity}
                    onChange={e => updateSupplyLine(i, "quantity", e.target.value)}
                    onKeyDown={(e: any) => { if (e.key === "-" || e.key === "e") e.preventDefault() }}
                    style={{ flex: 1, width: isMobile ? 90 : 110, flexShrink: 0, padding: "10px 12px", borderRadius: 6, border: "1px solid #e0e0e0", fontSize: FONT_SIZE.sm, boxSizing: "border-box" }}
                  />
                  {supplyLines.length > 1 && (
                    <button onClick={() => removeSupplyLine(i)} style={{ background: "none", border: "none", cursor: "pointer", color: "#ef4444", fontSize: 18, lineHeight: 1, padding: 0, width: 24, height: 24, display: "flex", alignItems: "center", justifyContent: "center" }}>Γ£ò</button>
                  )}
                </div>
              ))}
            </div>

            <div style={{ padding: "8px 12px", background: "#f8fafc", borderRadius: 6, marginBottom: 16, border: "1px solid #e2e8f0" }}>
              <p style={{ margin: 0, fontSize: FONT_SIZE.sm, color: "#0f172a" }}>
                Total entered: <strong style={{ color: supplyLines.reduce((s, l) => s + (parseInt(l.quantity) || 0), 0) === confirmingStop.quantity_offloaded ? "#16a34a" : "#f5a623" }}>
                  {supplyLines.reduce((s, l) => s + (parseInt(l.quantity) || 0), 0)}
                </strong> / {confirmingStop.quantity_offloaded}
              </p>
            </div>

            <button onClick={addSupplyLine} style={{ width: "100%", padding: "8px 12px", background: "white", border: "1px dashed #0070f3", color: "#0070f3", borderRadius: 6, cursor: "pointer", fontSize: FONT_SIZE.sm, fontWeight: 600, marginBottom: 20, minHeight: 40 }}>
              + Add Product Line
            </button>

            {showDiscrepancyPrompt && (
              <div style={{ padding: 16, background: "#fffbeb", border: "1px solid #fde68a", borderRadius: 8, marginBottom: 16 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
                  <Icon icon="mdi:alert-circle" width={20} color="#d97706" />
                  <p style={{ margin: 0, fontWeight: 700, fontSize: FONT_SIZE.sm, color: "#92400e" }}>Quantity Mismatch Detected</p>
                </div>
                <p style={{ margin: "0 0 12px", fontSize: FONT_SIZE.sm, color: "#78350f" }}>
                  Your count (<strong>{supplyLines.reduce((s, l) => s + (parseInt(l.quantity) || 0), 0)}</strong>) differs from the driver's quantity (<strong>{confirmingStop.quantity_offloaded}</strong>). Please explain the difference.
                </p>
                <textarea
                  value={discrepancyNote}
                  onChange={e => { setDiscrepancyNote(e.target.value); setConfirmError("") }}
                  placeholder="e.g. 2 bags were damaged during offloading"
                  rows={3}
                  style={{ width: "100%", padding: "10px 12px", borderRadius: 6, border: "1px solid #fbbf24", fontSize: FONT_SIZE.sm, resize: "vertical", boxSizing: "border-box", fontFamily: "inherit", background: "white", color: "#0f172a" }}
                />
              </div>
            )}

            {confirmError && <div style={{ padding: 12, background: "#fef2f2", borderLeft: "4px solid #ef4444", borderRadius: 4, marginBottom: 16, color: "#b91c1c", fontSize: FONT_SIZE.sm }}>{confirmError}</div>}

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              <button onClick={() => { setConfirmingStop(null); setSupplyLines([{ product: "", quantity: "" }]); setConfirmError(""); setShowDiscrepancyPrompt(false); setDiscrepancyNote("") }} style={{ padding: "12px 16px", background: "white", border: "1px solid #cbd5e1", color: "#475569", borderRadius: 8, cursor: "pointer", fontWeight: 600, fontSize: FONT_SIZE.md, minHeight: 44 }}>Cancel</button>
              {showDiscrepancyPrompt ? (
                <button onClick={() => { setShowDiscrepancyPrompt(false); setConfirmError(""); setDiscrepancyNote("") }} style={{ padding: "12px 16px", background: "white", border: "1px solid #0070f3", color: "#0070f3", borderRadius: 8, cursor: "pointer", fontWeight: 600, fontSize: FONT_SIZE.md, minHeight: 44 }}>
                  Back to Edit
                </button>
              ) : (
                <button onClick={handleConfirmSupply} disabled={confirmLoading} style={{ padding: "12px 16px", background: "#0070f3", color: "white", border: "none", borderRadius: 8, cursor: confirmLoading ? "not-allowed" : "pointer", fontWeight: 600, fontSize: FONT_SIZE.md, opacity: confirmLoading ? 0.7 : 1, minHeight: 44 }}>
                  {confirmLoading ? "Confirming..." : "Confirm Supply"}
                </button>
              )}
            </div>

            {showDiscrepancyPrompt && (
              <button onClick={handleConfirmSupply} disabled={confirmLoading} style={{ width: "100%", padding: "12px 16px", background: "#0070f3", color: "white", border: "none", borderRadius: 8, cursor: confirmLoading ? "not-allowed" : "pointer", fontWeight: 600, fontSize: FONT_SIZE.md, opacity: confirmLoading ? 0.7 : 1, minHeight: 44, marginTop: 10 }}>
                {confirmLoading ? "Confirming..." : "Confirm with Discrepancy"}
              </button>
            )}
          </div>
        </div>
      )}

      {/* Log Sale Modal */}
      {showSaleModal && (
        <div onClick={() => { 
          setShowSaleModal(false)
          setSaleLines([{ product: "", quantity: "", price_per_bag: "" }])
          setSaleCustomer(null)
          setSalePayment("")
          setSaleError("")
          setDeliveryMode("self")
          setSaleTricycleId("")
          setTricycleSearch("")
          setSaleTruckPlate("")
          setTruckSearch("")
          setIsBrokerLinked(false)
          setSaleBroker(null)
          setBrokerSearch("")
          setSaleDate(new Date().toISOString().split("T")[0])
        }} style={{ position: "fixed", inset: 0, background: "rgba(15, 23, 42, 0.6)", backdropFilter: "blur(4px)", display: "flex", alignItems: isMobile ? "flex-end" : "center", justifyContent: "center", zIndex: 100, padding: isMobile ? 0 : 24 }}>
          <div onClick={e => e.stopPropagation()} style={{ background: "white", borderRadius: isMobile ? "20px 20px 0 0" : 12, padding: isMobile ? "28px 20px" : 32, width: "100%", maxWidth: 600, maxHeight: "90vh", overflowY: "auto", boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.25)" }}>
            <h3 style={{ margin: "0 0 20px 0", fontSize: FONT_SIZE.xl, fontWeight: 700, color: "#0f172a" }}>Log Sales</h3>

            {/* Broker Linked Toggle */}
            <div style={{ marginBottom: 20, padding: "12px", background: "#f0f7ff", borderRadius: 8, border: "1px solid #bfdbfe" }}>
              <label style={{ display: "flex", alignItems: "center", gap: 10, cursor: "pointer" }}>
                <input
                  type="checkbox"
                  checked={isBrokerLinked}
                  onChange={e => { setIsBrokerLinked(e.target.checked); setSaleBroker(null); setSaleError("") }}
                  style={{ width: 18, height: 18, cursor: "pointer" }}
                />
                <span style={{ margin: "4px 0 0", fontWeight: 600, color: "#0070f3", fontSize: FONT_SIZE.sm }}>Broker-linked sales</span>
              </label>
              <p style={{ margin: "6px 0 0", fontSize: FONT_SIZE.xs, color: "#64748b" }}>
                {isBrokerLinked ? "Broker will provide the prices" : ""}
              </p>
            </div>

            {/* Products Section */}
            <div style={{ marginBottom: 20 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
                <label style={{ fontWeight: 700, fontSize: FONT_SIZE.base, color: "#0f172a" }}>Products *</label>
                <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>{saleLines.length} product(s)</p>
              </div>

              <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 12 }}>
                {saleLines.map((line, i) => (
                  <div key={i} style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr 1fr" : "2fr 1fr " + (isBrokerLinked ? "0fr" : "1fr") + " auto", gap: 8, alignItems: "center" }}>
                    <ModernInput
                      as="select"
                      value={line.product}
                      onChange={e => updateSaleLine(i, "product", e.target.value)}
                      style={{ padding: "10px 12px", borderRadius: 6, border: "1px solid #e0e0e0", fontSize: FONT_SIZE.sm, boxSizing: "border-box", minHeight: 44 }}
                    >
                      <option value="">Select product</option>
                      {stock.filter(s => s.balance > 0).map(s => (
                        <option key={s.product} value={s.product}>{s.product} ({s.balance})</option>
                      ))}
                    </ModernInput>

                    <ModernInput
                      type="number"
                      placeholder="Qty"
                      value={line.quantity}
                      onChange={e => updateSaleLine(i, "quantity", e.target.value)}
                      style={{ padding: "10px 12px", borderRadius: 6, border: "1px solid #e0e0e0", fontSize: FONT_SIZE.sm, boxSizing: "border-box", minHeight: 44 }}
                    />

                    {!isBrokerLinked && (
                      <ModernInput
                        type="text"
                        inputMode="numeric"
                        placeholder="Price per bag"
                        value={line.price_per_bag}
                        onChange={e => updateSaleLine(i, "price_per_bag", formatAmount(e.target.value))}
                        style={{ padding: "10px 12px", borderRadius: 6, border: "1px solid #e0e0e0", fontSize: FONT_SIZE.sm, boxSizing: "border-box", minHeight: 44 }}
                      />
                    )}

                    {saleLines.length > 1 && (
                      <button onClick={() => removeSaleLine(i)} style={{ background: "none", border: "none", cursor: "pointer", color: "#ef4444", fontSize: 18, lineHeight: 1, padding: 0, width: 24, height: 24, display: "flex", alignItems: "center", justifyContent: "center" }}>Γ£ò</button>
                    )}
                  </div>
                ))}
              </div>

              <button onClick={addSaleLine} style={{ width: "100%", padding: "8px 12px", background: "white", border: "1px dashed #0070f3", color: "#0070f3", borderRadius: 6, cursor: "pointer", fontSize: FONT_SIZE.sm, fontWeight: 600, minHeight: 40 }}>
                + Add Another Product
              </button>
            </div>

            {/* Broker Selection */}
            {isBrokerLinked && (
              <div style={{ marginBottom: 16, position: "relative" }}>
                <label style={{ display: "block", fontWeight: 600, marginBottom: 6, fontSize: FONT_SIZE.sm, color: "#475569" }}>Broker *</label>
                {brokers.length === 0
                  ? <p style={{ fontSize: FONT_SIZE.sm, color: "#94a3b8", margin: 0 }}>No brokers available.</p>
                  : (
                    <div style={{ position: "relative" }}>
                      <ModernInput
                        type="text"
                        placeholder="Search brokerΓÇª"
                        value={brokerSearch}
                        onChange={e => { setBrokerSearch(e.target.value); setBrokerDropOpen(true) }}
                        onFocus={() => setBrokerDropOpen(true)}
                        onBlur={() => setTimeout(() => setBrokerDropOpen(false), 150)}
                        style={{ width: "100%", padding: "10px 12px", borderRadius: 6, border: "1px solid #e0e0e0", fontSize: FONT_SIZE.base, boxSizing: "border-box", minHeight: 44 }}
                      />
                      {brokerDropOpen && (
                        <ul style={{ position: "absolute", top: "calc(100% + 4px)", left: 0, right: 0, background: "white", border: "1px solid #e2e8f0", borderRadius: 8, listStyle: "none", margin: 0, padding: 4, maxHeight: 200, overflowY: "auto", zIndex: 50, boxShadow: "0 4px 12px rgba(0,0,0,0.1)" }}>
                          {brokers
                            .filter(b => b.broker_name.toLowerCase().includes(brokerSearch.toLowerCase()))
                            .map(b => (
                              <li
                                key={b.broker_id}
                                onMouseDown={() => { setSaleBroker(b); setBrokerSearch(b.broker_name); setBrokerDropOpen(false); setSaleError("") }}
                                style={{ padding: "10px 12px", cursor: "pointer", fontSize: FONT_SIZE.base, background: saleBroker?.broker_id === b.broker_id ? "#eff6ff" : "white", borderRadius: 6 }}
                              >
                                {b.broker_name}
                              </li>
                            ))}
                        </ul>
                      )}
                    </div>
                  )
                }
                {saleBroker && (
                  <div style={{ marginTop: 8, padding: "8px 12px", background: "#eff6ff", borderRadius: 6, fontSize: FONT_SIZE.sm, color: "#0070f3", fontWeight: 500 }}>
                    Selected: {saleBroker.broker_name}
                  </div>
                )}
              </div>
            )}

            {/* Customer Name */}
            <div style={{ marginBottom: 16 }}>
              <label style={{ display: "block", fontWeight: 600, marginBottom: 6, fontSize: FONT_SIZE.sm, color: "#475569" }}>Customer Name <span style={{ fontWeight: 400, color: "#94a3b8" }}>(optional)</span></label>
              <CustomerSelector 
                onSelect={(c: any) => { setSaleCustomer(c); setSaleError("") }} 
                allowUnsavedNew={true}
                initialValue={saleCustomer?.full_name || ""}
              />
              {saleCustomer && (
                <div style={{ marginTop: 8, padding: "8px 12px", background: "#eff6ff", borderRadius: 6, fontSize: FONT_SIZE.sm, color: "#0070f3", fontWeight: 500 }}>
                  Selected: {saleCustomer.full_name}
                </div>
              )}
            </div>

            {/* Delivery Mode */}
            <div style={{ marginBottom: 16 }}>
              <label style={{ display: "block", fontWeight: 600, marginBottom: 6, fontSize: FONT_SIZE.sm, color: "#475569" }}>Delivery Mode</label>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8 }}>
                {(["self", "tricycle", "truck"] as const).map(type => (
                  <button
                    key={type}
                    onClick={() => { setDeliveryMode(type); setSaleTricycleId(""); setSaleTruckPlate(""); setTruckSearch(""); setSaleError("") }}
                    style={{
                      padding: "10px 12px", borderRadius: 8, cursor: "pointer",
                      border: `1.5px solid ${deliveryMode === type ? "#0070f3" : "#e2e8f0"}`,
                      background: deliveryMode === type ? "#0070f3" : "white",
                      color: deliveryMode === type ? "white" : "#64748b",
                      fontWeight: deliveryMode === type ? 600 : 500, fontSize: FONT_SIZE.sm, minHeight: 44,
                    }}
                  >
                    {type === "self" ? "Self" : type === "truck" ? "Truck" : "Tricycle"}
                  </button>
                ))}
              </div>
            </div>

            {/* Tricycle Selection */}
            {deliveryMode === "tricycle" && (
              <div style={{ marginBottom: 16, position: "relative" }}>
                <label style={{ display: "block", fontWeight: 600, marginBottom: 6, fontSize: FONT_SIZE.sm, color: "#475569" }}>Tricycle *</label>
                {tricycles.length === 0
                  ? <p style={{ fontSize: FONT_SIZE.sm, color: "#94a3b8", margin: 0 }}>No tricycles available.</p>
                  : (
                    <div style={{ position: "relative" }}>
                      <ModernInput
                        type="text"
                        placeholder="Search tricycleΓÇª"
                        value={tricycleSearch}
                        onChange={e => { setTricycleSearch(e.target.value); setTricycleDropOpen(true) }}
                        onFocus={() => setTricycleDropOpen(true)}
                        onBlur={() => setTimeout(() => setTricycleDropOpen(false), 150)}
                        style={{ width: "100%", padding: "10px 12px", borderRadius: 6, border: "1px solid #e0e0e0", fontSize: FONT_SIZE.base, boxSizing: "border-box", minHeight: 44 }}
                      />
                      {tricycleDropOpen && (
                        <ul style={{ position: "absolute", top: "calc(100% + 4px)", left: 0, right: 0, background: "white", border: "1px solid #e2e8f0", borderRadius: 8, listStyle: "none", margin: 0, padding: 4, maxHeight: 200, overflowY: "auto", zIndex: 50, boxShadow: "0 4px 12px rgba(0,0,0,0.1)" }}>
                          {tricycles
                            .filter(t => t.tricycle_number.toLowerCase().includes(tricycleSearch.toLowerCase()))
                            .map(t => (
                              <li
                                key={t.tricycle_id}
                                onMouseDown={() => { setSaleTricycleId(t.tricycle_id); setTricycleSearch(t.tricycle_number); setTricycleDropOpen(false); setSaleError("") }}
                                style={{ padding: "10px 12px", cursor: "pointer", fontSize: FONT_SIZE.base, background: saleTricycleId === t.tricycle_id ? "#eff6ff" : "white", borderRadius: 6 }}
                              >
                                {t.tricycle_number}
                              </li>
                            ))}
                        </ul>
                      )}
                    </div>
                  )
                }
              </div>
            )}

            {/* Truck Selection */}
            {deliveryMode === "truck" && (
              <div style={{ marginBottom: 16, position: "relative" }}>
                <label style={{ display: "block", fontWeight: 600, marginBottom: 6, fontSize: FONT_SIZE.sm, color: "#475569" }}>Truck *</label>
                {trucks.length === 0
                  ? <p style={{ fontSize: FONT_SIZE.sm, color: "#94a3b8", margin: 0 }}>No trucks available.</p>
                  : (
                    <div style={{ position: "relative" }}>
                      <ModernInput
                        type="text"
                        placeholder="Search truckΓÇª"
                        value={truckSearch}
                        onChange={e => { setTruckSearch(e.target.value); setTruckDropOpen(true) }}
                        onFocus={() => setTruckDropOpen(true)}
                        onBlur={() => setTimeout(() => setTruckDropOpen(false), 150)}
                        style={{ width: "100%", padding: "10px 12px", borderRadius: 6, border: "1px solid #e0e0e0", fontSize: FONT_SIZE.base, boxSizing: "border-box", minHeight: 44 }}
                      />
                      {truckDropOpen && (
                        <ul style={{ position: "absolute", top: "calc(100% + 4px)", left: 0, right: 0, background: "white", border: "1px solid #e2e8f0", borderRadius: 8, listStyle: "none", margin: 0, padding: 4, maxHeight: 200, overflowY: "auto", zIndex: 50, boxShadow: "0 4px 12px rgba(0,0,0,0.1)" }}>
                          {trucks
                            .filter(t => t.plate_number.toLowerCase().includes(truckSearch.toLowerCase()) || (t.kbnl_truck_no || "").toLowerCase().includes(truckSearch.toLowerCase()))
                            .map(t => (
                              <li
                                key={t.plate_number}
                                onMouseDown={() => { setSaleTruckPlate(t.plate_number); setTruckSearch(`${t.plate_number}${t.kbnl_truck_no ? ` ┬╖ #${t.kbnl_truck_no}` : ""}`); setTruckDropOpen(false); setSaleError("") }}
                                style={{ padding: "10px 12px", cursor: "pointer", fontSize: FONT_SIZE.base, background: saleTruckPlate === t.plate_number ? "#eff6ff" : "white", borderRadius: 6 }}
                              >
                                {t.plate_number}{t.kbnl_truck_no ? ` ┬╖ #${t.kbnl_truck_no}` : ""}
                              </li>
                            ))}
                        </ul>
                      )}
                    </div>
                  )
                }
                {saleTruckPlate && (
                  <div style={{ marginTop: 8, padding: "8px 12px", background: "#fefce8", borderRadius: 6, fontSize: FONT_SIZE.sm, color: "#ca8a04", fontWeight: 500, border: "1px solid #fde68a" }}>
                    Selected: {saleTruckPlate}
                  </div>
                )}
              </div>
            )}

            {/* Sale Date */}
            <div style={{ marginBottom: 16 }}>
              <label style={{ display: "block", fontWeight: 600, marginBottom: 6, fontSize: FONT_SIZE.sm, color: "#475569" }}>Date of Sale</label>
              <ModernInput
                type="date"
                value={saleDate}
                onChange={e => { setSaleDate(e.target.value); setSaleError("") }}
                style={{ width: "100%", padding: "10px 12px", borderRadius: 6, border: "1px solid #e0e0e0", fontSize: FONT_SIZE.base, boxSizing: "border-box", minHeight: 44 }}
              />
            </div>

            {/* Payment Mode */}
            <div style={{ marginBottom: 24 }}>
              <label style={{ display: "block", fontWeight: 600, marginBottom: 6, fontSize: FONT_SIZE.sm, color: "#475569" }}>Payment Mode *</label>
              <ModernInput
                as="select"
                value={salePayment}
                onChange={e => { setSalePayment(e.target.value); setSaleError("") }}
                style={{ width: "100%", padding: "10px 12px", borderRadius: 6, border: "1px solid #e0e0e0", fontSize: FONT_SIZE.base, boxSizing: "border-box", minHeight: 44 }}
              >
                <option value="">Select payment mode</option>
                {PAYMENT_MODES.map(m => (<option key={m} value={m}>{m}</option>))}
              </ModernInput>
            </div>

            {salePayment === "Transfer" && (
              <>
                <div style={{ marginBottom: 16 }}>
                  <label style={{ display: "block", fontWeight: 600, marginBottom: 6, fontSize: FONT_SIZE.sm, color: "#475569" }}>Bank *</label>
                  <ModernInput
                    as="select"
                    value={saleBank}
                    onChange={e => { setSaleBank(e.target.value); setSaleError("") }}
                    style={{ width: "100%", padding: "10px 12px", borderRadius: 6, border: "1px solid #e0e0e0", fontSize: FONT_SIZE.base, boxSizing: "border-box", minHeight: 44 }}
                  >
                    <option value="">Select bank</option>
                    {BANKS.map(b => (<option key={b} value={b}>{b}</option>))}
                  </ModernInput>
                </div>
                <div style={{ marginBottom: 24 }}>
                  <label style={{ display: "block", fontWeight: 600, marginBottom: 6, fontSize: FONT_SIZE.sm, color: "#475569" }}>Depositor Name *</label>
                  <ModernInput
                    value={saleDepositor}
                    onChange={e => { setSaleDepositor(e.target.value); setSaleError("") }}
                    placeholder="Name on bank account"
                    style={{ width: "100%", padding: "10px 12px", borderRadius: 6, border: "1px solid #e0e0e0", fontSize: FONT_SIZE.base, boxSizing: "border-box", minHeight: 44 }}
                  />
                </div>
              </>
            )}

            {saleError && <div style={{ padding: 12, background: "#fef2f2", borderLeft: "4px solid #ef4444", borderRadius: 4, marginBottom: 16, color: "#b91c1c", fontSize: FONT_SIZE.sm }}>{saleError}</div>}

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              <button onClick={() => { 
                setShowSaleModal(false)
                setSaleLines([{ product: "", quantity: "", price_per_bag: "" }])
                setSaleCustomer(null)
                setSalePayment("")
                setSaleBank("")
                setSaleDepositor("")
                setSaleError("")
                setDeliveryMode("self")
                setSaleTricycleId("")
                setTricycleSearch("")
                setSaleTruckPlate("")
                setTruckSearch("")
                setIsBrokerLinked(false)
                setSaleBroker(null)
                setBrokerSearch("")
                setSaleDate(dayjs().format("YYYY-MM-DD"))
              }} style={{ padding: "12px 16px", background: "white", border: "1px solid #cbd5e1", color: "#475569", borderRadius: 8, cursor: "pointer", fontWeight: 600, fontSize: FONT_SIZE.md, minHeight: 44 }}>Cancel</button>
              <button onClick={handleLogSale} disabled={saleLoading} style={{ padding: "12px 16px", background: "#0070f3", color: "white", border: "none", borderRadius: 8, cursor: saleLoading ? "not-allowed" : "pointer", fontWeight: 600, fontSize: FONT_SIZE.md, opacity: saleLoading ? 0.7 : 1, minHeight: 44 }}>
                {saleLoading ? "Logging..." : `Log ${saleLines.filter(l => l.product).length} Sale(s)`}
              </button>
            </div>
          </div>
        </div>
      )}

      <ProfilePictureUpload
        isOpen={showPictureModal}
        onClose={() => setShowPictureModal(false)}
        userId={officer?.officer_id || ""}
        table="store_officers"
        idField="officer_id"
        currentUrl={officer?.profile_picture_url}
        onSuccess={(url) => setOfficer(prev => prev ? { ...prev, profile_picture_url: url } : prev)}
      />

      <ReportModal
        isOpen={showReportModal}
        onClose={() => setShowReportModal(false)}
        userId={officer?.officer_id || ""}
        userRole={Role.StoreOfficer}
      />
    </div>
  )
}

"use client"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { supabase } from "@/lib/supabase"
import { apiMutate } from "@/lib/api-mutation"
import RoleSwitcher from "@/components/RoleSwitcher"
import ReportModal from "@/components/ReportModal"
import ProfilePictureUpload from "@/components/ProfilePictureUpload"
import { FONT_SIZE } from "@/lib/constants"
import { usePolling } from "@/lib/hooks/usePolling"
import { useBreakpoint } from "@/app/hooks/useBreakpoint"
import { requireDashboardRole } from "@/lib/auth-helpers"
import { Role } from "@/lib/roles"
import { formatDateTime, formatTime } from "@/lib/date-utils"
import { useStops } from "@/lib/hooks/useStops"
import { Icon } from "@iconify/react"

type Supervisor = {
  supervisor_id: string
  full_name: string
  store_names: string[]
  profile_picture_url?: string
}

type StockBalance = { product: string; balance: number }

type VerificationRow = {
  product: string
  system_balance: number
  physical_count: string
  notes: string
}

type PastVerification = {
  verification_id: string
  verification_session_id: string
  product: string
  system_balance: number
  physical_count: number
  discrepancy: number
  notes: string | null
  verified_at: string
}

type Sale = {
  sale_id: string
  product: string
  quantity: number
  price_per_bag: number | null
  total_amount: number | null
  customer_name: string | null
  payment_mode: string
  delivery_mode: string
  tricycle_id: string | null
  truck_plate: string | null
  sold_at: string
  created_at: string
  broker_id: string | null
  status: string
  officer_id: string
  rejection_reason: string | null
}

type GroupedSale = {
  group_id: string
  customer_name: string | null
  payment_mode: string
  delivery_mode: string
  sold_at: string
  broker_id: string | null
  status: string
  rejection_reason: string | null
  lines: Sale[]
}

const PAYMENT_MODES = ["Cash", "Transfer", "POS", "Broker"]

export default function StoreSupervisorDashboard() {
  const bp = useBreakpoint()
  const isMobile = bp === "mobile"
  const router = useRouter()

  const [supervisor, setSupervisor] = useState<Supervisor | null>(null)
  const [selectedStore, setSelectedStore] = useState("")
  const [stock, setStock] = useState<StockBalance[]>([])
  const [loading, setLoading] = useState(true)
  const [noStoresAssigned, setNoStoresAssigned] = useState(false)
  const [tab, setTab] = useState<"verify" | "supplies" | "sales" | "history">("verify")
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null)
  const [showReportModal, setShowReportModal] = useState(false)
  const [showPictureModal, setShowPictureModal] = useState(false)

  // Verification state
  const [verificationRows, setVerificationRows] = useState<VerificationRow[]>([])
  const [verifyLoading, setVerifyLoading] = useState(false)
  const [verifyError, setVerifyError] = useState("")
  const [verifySuccess, setVerifySuccess] = useState(false)

  // Past verifications
  const [pastVerifications, setPastVerifications] = useState<PastVerification[]>([])
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set())

  // Sales state
  const [sales, setSales] = useState<Sale[]>([])
  const [salesPage, setSalesPage] = useState(1)
  const [salesPaymentFilter, setSalesPaymentFilter] = useState("")
  const [salesSortByAdded, setSalesSortByAdded] = useState(false)
  const PAGE_SIZE = 50

  // Stops (supplies) - read-only
  const [stopsFilter, setStopsFilter] = useState<{ store_name: string; pending: boolean } | null>(null)
  const { data: stopsFromHook, refetch: refetchStops } = useStops(stopsFilter ?? undefined)
  const [confirmedStops, setConfirmedStops] = useState<any[]>([])
  const [stopsPage, setStopsPage] = useState(1)

  // Profile picture
  const [profilePicUrl, setProfilePicUrl] = useState<string | undefined>()

  // Initialize
  useEffect(() => {
    async function init() {
      const { data: { session } } = await supabase.auth.getSession()
      if (!session) { router.push("/login"); return }

      const hasRole = await requireDashboardRole(session.user.id, Role.StoreSupervisor)
      if (!hasRole) { router.push("/login"); return }

      const { data: profile } = await supabase.from("Profiles").select("full_name, profile_picture_url").eq("user_id", session.user.id).single()
      const { data: sup } = await supabase.from("store_supervisors").select("supervisor_id, full_name, store_names, profile_picture_url").eq("supervisor_id", session.user.id).single()

      const name = sup?.full_name || profile?.full_name || ""
      const picUrl = sup?.profile_picture_url || profile?.profile_picture_url
      const stores = sup?.store_names || []

      setSupervisor({
        supervisor_id: session.user.id,
        full_name: name,
        store_names: stores,
        profile_picture_url: picUrl,
      })
      setProfilePicUrl(picUrl)

      if (stores.length > 0) {
        setSelectedStore(stores[0])
      } else {
        setNoStoresAssigned(true)
      }

      setLoading(false)
    }
    init()
  }, [router])

  // Fetch data when store changes
  useEffect(() => {
    if (!selectedStore) return
    fetchStock(selectedStore)
    fetchSales(selectedStore)
    fetchPastVerifications(selectedStore)
    setStopsFilter({ store_name: selectedStore, pending: false })
    setExpandedGroups(new Set())
    setLastUpdated(new Date())
  }, [selectedStore])

  usePolling(() => {
    fetchStock(selectedStore)
    fetchSales(selectedStore)
    fetchPastVerifications(selectedStore)
    refetchStops()
    setLastUpdated(new Date())
  }, 120000, !!selectedStore)

  // Confirmed stops
  useEffect(() => {
    if (stopsFromHook) {
      const confirmed = (stopsFromHook as any[]).filter((s: any) => s.confirmed && !s.disputed)
      setConfirmedStops(confirmed)
    }
  }, [stopsFromHook])

  // Initialize verification rows when stock loads
  useEffect(() => {
    if (stock.length > 0 && verificationRows.length === 0) {
      setVerificationRows(stock.map(s => ({
        product: s.product,
        system_balance: s.balance,
        physical_count: "",
        notes: "",
      })))
    }
  }, [stock])

  async function fetchStock(storeName: string) {
    const { data } = await supabase
      .from("store_stock")
      .select("product, balance")
      .eq("store_name", storeName)
      .order("product", { ascending: true })
    setStock(data || [])
  }

  async function fetchSales(storeName: string) {
    const { data } = await supabase
      .from("store_sales")
      .select("sale_id, product, quantity, price_per_bag, total_amount, customer_name, payment_mode, delivery_mode, tricycle_id, truck_plate, sold_at, created_at, broker_id, status, officer_id, rejection_reason")
      .eq("store_name", storeName)
      .order("sold_at", { ascending: false })
    setSales(data || [])
  }

  async function fetchPastVerifications(storeName: string) {
    const { data } = await supabase
      .from("stock_verifications")
      .select("verification_id, verification_session_id, product, system_balance, physical_count, discrepancy, notes, verified_at")
      .eq("store_name", storeName)
      .order("verified_at", { ascending: false })
      .limit(100)
    setPastVerifications(data || [])
  }

  function updateVerificationRow(index: number, field: "physical_count" | "notes", value: string) {
    setVerificationRows(prev => prev.map((r, i) => i === index ? { ...r, [field]: value } : r))
    setVerifyError("")
    setVerifySuccess(false)
  }

  async function handleSubmitVerification() {
    if (!supervisor) return

    const rowsToSubmit = verificationRows.filter(r => r.physical_count !== "")
    if (rowsToSubmit.length === 0) {
      setVerifyError("Enter physical count for at least one product")
      return
    }

    for (const row of rowsToSubmit) {
      const count = parseInt(row.physical_count)
      if (isNaN(count) || count < 0) {
        setVerifyError(`Invalid physical count for ${row.product}`)
        return
      }
    }

    setVerifyLoading(true)
    setVerifyError("")

    try {
      const sessionId = crypto.randomUUID()
      for (const row of rowsToSubmit) {
        const { error } = await apiMutate("finance", {
          action: "insert",
          table: "stock_verifications",
          data: {
            supervisor_id: supervisor.supervisor_id,
            store_name: selectedStore,
            product: row.product,
            system_balance: row.system_balance,
            physical_count: parseInt(row.physical_count),
            notes: row.notes || null,
            verification_session_id: sessionId,
          },
        })
        if (error) {
          setVerifyError(`Failed to save verification for ${row.product}: ${error}`)
          setVerifyLoading(false)
          return
        }
      }

      setVerifySuccess(true)
      setVerificationRows(stock.map(s => ({
        product: s.product,
        system_balance: s.balance,
        physical_count: "",
        notes: "",
      })))
      await fetchPastVerifications(selectedStore)
      setTimeout(() => setVerifySuccess(false), 3000)
    } catch {
      setVerifyError("Network error while saving verifications")
    } finally {
      setVerifyLoading(false)
    }
  }

  function getStatusColor(status: string) {
    if (status === "Pending") return "#d97706"
    if (status === "Confirmed") return "#16a34a"
    return "#dc2626"
  }

  // Group sales
  const groupedSales: GroupedSale[] = (() => {
    let filtered = sales
    if (salesPaymentFilter) {
      filtered = filtered.filter(s => s.payment_mode === salesPaymentFilter)
    }
    const sorted = [...filtered].sort((a, b) => {
      if (salesSortByAdded) return new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
      return new Date(b.sold_at).getTime() - new Date(a.sold_at).getTime()
    })

    const groups: GroupedSale[] = []
    for (const sale of sorted) {
      const key = `${sale.sold_at}_${sale.customer_name}_${sale.payment_mode}_${sale.delivery_mode}_${sale.broker_id}_${sale.status}`
      const existing = groups.find(g => g.group_id === key)
      if (existing) {
        existing.lines.push(sale)
      } else {
        groups.push({
          group_id: key,
          customer_name: sale.customer_name,
          payment_mode: sale.payment_mode,
          delivery_mode: sale.delivery_mode,
          sold_at: sale.sold_at,
          broker_id: sale.broker_id,
          status: sale.status,
          rejection_reason: sale.rejection_reason,
          lines: [sale],
        })
      }
    }
    return groups
  })()

  // Group past verifications by session ID
  const groupedVerifications: { key: string; verified_at: string; items: PastVerification[] }[] = (() => {
    const sorted = [...pastVerifications].sort((a, b) => new Date(b.verified_at).getTime() - new Date(a.verified_at).getTime())
    const groups: { key: string; verified_at: string; items: PastVerification[] }[] = []
    for (const v of sorted) {
      const existing = groups.find(g => g.key === v.verification_session_id)
      if (existing) {
        existing.items.push(v)
      } else {
        groups.push({ key: v.verification_session_id, verified_at: v.verified_at, items: [v] })
      }
    }
    return groups
  })()

  if (loading) {
    return (
      <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "'Inter', sans-serif" }}>
        <p style={{ color: "#94a3b8", fontSize: FONT_SIZE.base }}>Loading...</p>
      </div>
    )
  }

  if (noStoresAssigned) {
    return (
      <div style={{ minHeight: "100vh", background: "#f5f5f7", fontFamily: "'Inter', sans-serif" }}>
        <div style={{
          background: "linear-gradient(135deg, #0f0f1e 0%, #1a1a2e 100%)",
          padding: isMobile ? "16px" : "16px 32px",
          borderBottom: "1px solid rgba(255,255,255,0.08)",
        }}>
          <div style={{ maxWidth: 1200, margin: "0 auto", display: "flex", alignItems: "center", gap: isMobile ? 12 : 16, justifyContent: "space-between" }}>
            <div style={{ display: "flex", alignItems: "center", gap: isMobile ? 12 : 16 }}>
              <div style={{
                width: isMobile ? 40 : 48, height: isMobile ? 40 : 48, borderRadius: "50%",
                background: profilePicUrl ? "transparent" : "rgba(255,255,255,0.15)",
                border: "2px solid rgba(255,255,255,0.2)", display: "flex", alignItems: "center", justifyContent: "center",
                flexShrink: 0, overflow: "hidden",
              }}>
                {profilePicUrl ? (
                  <img src={profilePicUrl} alt={supervisor?.full_name} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                ) : (
                  <span style={{ fontSize: isMobile ? 18 : 20, fontWeight: 700, color: "#fff" }}>{supervisor?.full_name.charAt(0).toUpperCase()}</span>
                )}
              </div>
              <div>
                <h1 style={{ margin: 0, fontSize: isMobile ? FONT_SIZE.lg : FONT_SIZE.xl, fontWeight: 700, color: "#fff" }}>{supervisor?.full_name}</h1>
                <RoleSwitcher currentRole={Role.StoreSupervisor} style={{ margin: "2px 0 0", fontSize: FONT_SIZE.sm, color: "rgba(255,255,255,0.7)" }} />
              </div>
            </div>
            <button
              onClick={async () => { await supabase.auth.signOut(); router.push("/login") }}
              style={{
                padding: "8px 16px",
                background: "rgba(255, 85, 85, 0.2)",
                color: "#ff5555",
                border: "1.5px solid rgba(255, 85, 85, 0.3)",
                borderRadius: 6,
                cursor: "pointer",
                fontSize: FONT_SIZE.sm,
                fontWeight: 600,
                minHeight: 40,
                whiteSpace: "nowrap",
                display: "flex",
                alignItems: "center",
                gap: 6,
                transition: "all 0.2s ease",
              }}
              onMouseEnter={(e) => {
                (e.currentTarget as HTMLButtonElement).style.background = "rgba(255, 85, 85, 0.3)";
                (e.currentTarget as HTMLButtonElement).style.borderColor = "rgba(255, 85, 85, 0.5)"
              }}
              onMouseLeave={(e) => {
                (e.currentTarget as HTMLButtonElement).style.background = "rgba(255, 85, 85, 0.2)";
                (e.currentTarget as HTMLButtonElement).style.borderColor = "rgba(255, 85, 85, 0.3)"
              }}
            >
              <Icon icon="mdi:logout" width={16} />
              Logout
            </button>
          </div>
        </div>
        <div style={{ padding: isMobile ? "16px" : "32px", maxWidth: 1200, margin: "0 auto" }}>
          <div style={{ background: "white", border: "1px solid #e2e8f0", borderRadius: 12, padding: isMobile ? 24 : 40, textAlign: "center", boxShadow: "0 1px 3px rgba(0,0,0,0.05)" }}>
            <div style={{ width: 56, height: 56, borderRadius: "50%", background: "rgba(245, 158, 11, 0.1)", display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 16px" }}>
              <Icon icon="mdi:store-alert" width={28} color="#f59e0b" />
            </div>
            <h2 style={{ margin: "0 0 8px", fontSize: FONT_SIZE.xl, fontWeight: 700, color: "#0f172a" }}>No Stores Assigned</h2>
            <p style={{ margin: "0 0 4px", fontSize: FONT_SIZE.base, color: "#64748b", lineHeight: 1.6 }}>
              You don&apos;t have any stores assigned to your account yet.
            </p>
            <p style={{ margin: 0, fontSize: FONT_SIZE.sm, color: "#94a3b8" }}>
              Contact your admin to assign stores to your profile.
            </p>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div style={{ minHeight: "100vh", background: "#f5f5f7", fontFamily: "'Inter', sans-serif" }}>
      {/* Profile Banner */}
      <div style={{
        background: "linear-gradient(135deg, #0f0f1e 0%, #1a1a2e 100%)",
        padding: isMobile ? "16px" : "16px 32px",
        borderBottom: "1px solid rgba(255,255,255,0.08)",
      }}>
        <div style={{ maxWidth: 1200, margin: "0 auto", display: "flex", alignItems: "center", gap: isMobile ? 12 : 16, justifyContent: "space-between", flexWrap: "wrap" }}>
          <div style={{ display: "flex", alignItems: "center", gap: isMobile ? 12 : 16 }}>
            <div style={{
              width: isMobile ? 40 : 48, height: isMobile ? 40 : 48, borderRadius: "50%",
              background: profilePicUrl ? "transparent" : "rgba(255,255,255,0.15)",
              border: "2px solid rgba(255,255,255,0.2)", display: "flex", alignItems: "center", justifyContent: "center",
              flexShrink: 0, overflow: "hidden", cursor: "pointer",
            }} onClick={() => setShowPictureModal(true)}>
              {profilePicUrl ? (
                <img src={profilePicUrl} alt={supervisor?.full_name} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
              ) : (
                <span style={{ fontSize: isMobile ? 18 : 20, fontWeight: 700, color: "#fff" }}>{supervisor?.full_name.charAt(0).toUpperCase()}</span>
              )}
            </div>
            <div>
              <h1 style={{ margin: 0, fontSize: isMobile ? FONT_SIZE.lg : FONT_SIZE.xl, fontWeight: 700, color: "#fff" }}>{supervisor?.full_name}</h1>
              <RoleSwitcher currentRole={Role.StoreSupervisor} style={{ margin: "2px 0 0", fontSize: FONT_SIZE.sm, color: "rgba(255,255,255,0.7)" }} />
            </div>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            {/* Store Switcher */}
            {supervisor && supervisor.store_names.length > 1 && (
              <select
                value={selectedStore}
                onChange={e => { setSelectedStore(e.target.value); setVerificationRows([]); setVerifySuccess(false); setVerifyError("") }}
                style={{
                  padding: "8px 12px", borderRadius: 8, fontSize: FONT_SIZE.sm,
                  border: "1.5px solid rgba(255,255,255,0.2)", background: "rgba(255,255,255,0.1)",
                  color: "#fff", cursor: "pointer", appearance: "none",
                  backgroundImage: "url(\"data:image/svg+xml,%3Csvg width='12' height='8' viewBox='0 0 12 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1.5L6 6.5L11 1.5' stroke='white' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E\")",
                  backgroundRepeat: "no-repeat", backgroundPosition: "right 10px center", paddingRight: 30,
                }}
              >
                {supervisor.store_names.map(s => <option key={s} value={s} style={{ color: "#000", background: "#fff" }}>{s}</option>)}
              </select>
            )}
            <button onClick={() => setShowReportModal(true)} style={{ padding: "8px 14px", background: "rgba(245, 166, 35, 0.15)", color: "#f5a623", border: "1px solid rgba(245, 166, 35, 0.3)", borderRadius: 8, cursor: "pointer", fontWeight: 600, fontSize: FONT_SIZE.sm, display: "flex", alignItems: "center", gap: 6, minHeight: 36, whiteSpace: "nowrap" }}>
              <Icon icon="mdi:alert-circle-outline" width={16} />
              {!isMobile && "Report"}
            </button>
            <button
              onClick={async () => { await supabase.auth.signOut(); router.push("/login") }}
              style={{
                padding: "8px 16px",
                background: "rgba(255, 85, 85, 0.2)",
                color: "#ff5555",
                border: "1.5px solid rgba(255, 85, 85, 0.3)",
                borderRadius: 6,
                cursor: "pointer",
                fontSize: FONT_SIZE.sm,
                fontWeight: 600,
                minHeight: 40,
                whiteSpace: "nowrap",
                display: "flex",
                alignItems: "center",
                gap: 6,
                transition: "all 0.2s ease",
              }}
              onMouseEnter={(e) => {
                (e.currentTarget as HTMLButtonElement).style.background = "rgba(255, 85, 85, 0.3)";
                (e.currentTarget as HTMLButtonElement).style.borderColor = "rgba(255, 85, 85, 0.5)"
              }}
              onMouseLeave={(e) => {
                (e.currentTarget as HTMLButtonElement).style.background = "rgba(255, 85, 85, 0.2)";
                (e.currentTarget as HTMLButtonElement).style.borderColor = "rgba(255, 85, 85, 0.3)"
              }}
            >
              <Icon icon="mdi:logout" width={16} />
              Logout
            </button>
          </div>
        </div>
      </div>

      <div style={{ padding: isMobile ? "16px" : "32px", maxWidth: 1200, margin: "0 auto" }}>
        {/* Stock Summary */}
        <div style={{ background: "white", border: "1px solid #e2e8f0", borderRadius: 12, padding: isMobile ? 16 : 24, marginBottom: 24, boxShadow: "0 1px 3px rgba(0,0,0,0.05)" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
            <div>
              {selectedStore && (
                <p style={{ margin: "0 0 2px", fontSize: FONT_SIZE.xs, fontWeight: 600, color: "#0070f3", textTransform: "uppercase", letterSpacing: "0.5px" }}>{selectedStore}</p>
              )}
              <p style={{ margin: 0, fontWeight: 700, fontSize: FONT_SIZE.lg, color: "#0f172a" }}>Stock Balance</p>
            </div>
            <p style={{ margin: 0, fontWeight: 700, fontSize: FONT_SIZE.lg, color: "#0f172a" }}>
              Total: <span style={{ color: "#0070f3" }}>{stock.reduce((sum, s) => sum + s.balance, 0).toLocaleString()}</span> <span style={{ fontSize: FONT_SIZE.sm, fontWeight: 500, color: "#64748b" }}>bags</span>
            </p>
          </div>
          {stock.length === 0 ? (
            <p style={{ color: "#64748b", fontSize: FONT_SIZE.base, margin: 0 }}>No stock recorded yet.</p>
          ) : (
            <div style={{ display: "grid", gridTemplateColumns: isMobile ? "repeat(2, 1fr)" : "repeat(auto-fit, minmax(160px, 1fr))", gap: 12 }}>
              {stock.map(s => (
                <div key={s.product} style={{ background: "#f0f7ff", border: "1.5px solid #bfdbfe", borderRadius: 8, padding: "12px 14px" }}>
                  <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#64748b" }}>{s.product}</p>
                  <p style={{ margin: "6px 0 0", fontWeight: 700, fontSize: FONT_SIZE["2xl"], color: s.balance === 0 ? "#ef4444" : s.balance < 50 ? "#f5a623" : "#0070f3" }}>
                    {s.balance}<span style={{ fontSize: FONT_SIZE.xs, fontWeight: 500, color: "#64748b", marginLeft: 4 }}>bags</span>
                  </p>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Tabs */}
        <div style={{ display: "flex", gap: 8, marginBottom: 24, flexWrap: "wrap" }}>
          {([
            { key: "verify" as const, label: "Verify Stock" },
            { key: "supplies" as const, label: "Supplies" },
            { key: "sales" as const, label: "Sales" },
            { key: "history" as const, label: "Verification History" },
          ]).map(t => (
            <button
              key={t.key}
              onClick={() => setTab(t.key)}
              style={{
                padding: "8px 16px", borderRadius: 6, fontSize: FONT_SIZE.sm, cursor: "pointer",
                border: `1.5px solid ${tab === t.key ? "" : "#e2e8f0"}`,
                background: tab === t.key ? "#171717" : "white",
                color: tab === t.key ? "white" : "#64748b",
                fontWeight: tab === t.key ? 600 : 500, transition: "all 0.2s", minHeight: 40,
              }}
            >
              {t.label}
            </button>
          ))}
        </div>

        {/* Verify Stock Tab */}
        {tab === "verify" && (
          <div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16, flexWrap: "wrap", gap: 12 }}>
              <div>
                <p style={{ margin: 0, fontWeight: 700, fontSize: FONT_SIZE.lg, color: "#0f172a" }}>Stock Verification</p>
                <p style={{ margin: "4px 0 0", fontSize: FONT_SIZE.sm, color: "#64748b" }}>Enter physical counts after inspecting the store</p>
              </div>
              {lastUpdated && (
                <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Updated: {formatTime(lastUpdated)}</p>
              )}
            </div>

            {stock.length === 0 ? (
              <p style={{ color: "#64748b", fontSize: FONT_SIZE.base }}>No stock to verify.</p>
            ) : (
              <>
                <div style={{ display: "flex", flexDirection: "column", gap: 12, marginBottom: 20 }}>
                  {verificationRows.map((row, i) => {
                    const discrepancy = row.physical_count !== "" ? parseInt(row.physical_count) - row.system_balance : null
                    return (
                      <div key={row.product} style={{ background: "white", border: "1px solid #e2e8f0", borderRadius: 12, padding: 16, boxShadow: "0 1px 3px rgba(0,0,0,0.05)" }}>
                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 12 }}>
                          <div>
                            <p style={{ margin: 0, fontWeight: 700, fontSize: FONT_SIZE.lg, color: "#0f172a" }}>{row.product}</p>
                            <p style={{ margin: "4px 0 0", fontSize: FONT_SIZE.sm, color: "#64748b" }}>
                              System balance: <strong style={{ color: row.system_balance === 0 ? "#ef4444" : row.system_balance < 50 ? "#f5a623" : "#0070f3" }}>{row.system_balance}</strong> bags
                            </p>
                          </div>
                          {discrepancy !== null && discrepancy !== 0 && (
                            <span style={{
                              padding: "4px 10px", borderRadius: 6, fontSize: FONT_SIZE.xs, fontWeight: 700,
                              background: discrepancy > 0 ? "#ecfdf5" : "#fef2f2",
                              color: discrepancy > 0 ? "#16a34a" : "#dc2626",
                            }}>
                              {discrepancy > 0 ? "+" : ""}{discrepancy} bags
                            </span>
                          )}
                          {discrepancy !== null && discrepancy === 0 && (
                            <span style={{ padding: "4px 10px", borderRadius: 6, fontSize: FONT_SIZE.xs, fontWeight: 700, background: "#ecfdf5", color: "#16a34a" }}>
                              Matched
                            </span>
                          )}
                        </div>
                        <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
                          <div style={{ flex: 1, minWidth: 150 }}>
                            <label style={{ display: "block", fontSize: FONT_SIZE.xs, fontWeight: 600, color: "#475569", marginBottom: 4 }}>Physical Count *</label>
                            <input
                              type="number"
                              min="0"
                              placeholder="Enter count"
                              value={row.physical_count}
                              onChange={e => updateVerificationRow(i, "physical_count", e.target.value)}
                              onKeyDown={e => { if (e.key === "-" || e.key === "e") e.preventDefault() }}
                              style={{ width: "100%", padding: "10px 12px", borderRadius: 8, border: "1.5px solid #e5e5e5", fontSize: FONT_SIZE.base, boxSizing: "border-box", background: "#f9f9f9" }}
                            />
                          </div>
                          <div style={{ flex: 2, minWidth: 200 }}>
                            <label style={{ display: "block", fontSize: FONT_SIZE.xs, fontWeight: 600, color: "#475569", marginBottom: 4 }}>Notes (optional)</label>
                            <input
                              type="text"
                              placeholder="e.g. damaged bags, spilled"
                              value={row.notes}
                              onChange={e => updateVerificationRow(i, "notes", e.target.value)}
                              style={{ width: "100%", padding: "10px 12px", borderRadius: 8, border: "1.5px solid #e5e5e5", fontSize: FONT_SIZE.base, boxSizing: "border-box", background: "#f9f9f9" }}
                            />
                          </div>
                        </div>
                      </div>
                    )
                  })}
                </div>

                {verifyError && (
                  <div style={{ padding: 12, background: "#fef2f2", borderLeft: "4px solid #ef4444", borderRadius: 4, marginBottom: 16, color: "#b91c1c", fontSize: FONT_SIZE.sm }}>{verifyError}</div>
                )}
                {verifySuccess && (
                  <div style={{ padding: 12, background: "#ecfdf5", borderLeft: "4px solid #16a34a", borderRadius: 4, marginBottom: 16, color: "#166534", fontSize: FONT_SIZE.sm }}>Verification saved successfully.</div>
                )}

                <button
                  onClick={handleSubmitVerification}
                  disabled={verifyLoading || verificationRows.every(r => r.physical_count === "")}
                  style={{
                    width: "100%", padding: "14px 20px",
                    background: verifyLoading ? "#94a3b8" : "#0070f3",
                    color: "white", border: "none", borderRadius: 10,
                    fontSize: FONT_SIZE.md, fontWeight: 700, cursor: verifyLoading ? "not-allowed" : "pointer",
                    opacity: verifyLoading || verificationRows.every(r => r.physical_count === "") ? 0.6 : 1,
                    transition: "all 0.2s",
                  }}
                >
                  {verifyLoading ? "Saving..." : "Submit Verification"}
                </button>
              </>
            )}
          </div>
        )}

        {/* Supplies Tab (read-only) */}
        {tab === "supplies" && (
          <div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16, flexWrap: "wrap", gap: 12 }}>
              <p style={{ margin: 0, fontWeight: 700, fontSize: FONT_SIZE.lg, color: "#0f172a" }}>Supply Records ({confirmedStops.length})</p>
              <div style={{ display: "flex", alignItems: "center", gap: 12, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>
                {lastUpdated && `Updated: ${formatTime(lastUpdated)}`}
                <button onClick={refetchStops} style={{ padding: "6px 12px", fontSize: FONT_SIZE.xs, cursor: "pointer", borderRadius: 6, border: "1px solid #e2e8f0", background: "white", color: "#64748b" }}>Refresh</button>
              </div>
            </div>

            {confirmedStops.length === 0 && <p style={{ color: "#64748b", fontSize: FONT_SIZE.base }}>No supply records yet.</p>}

            {confirmedStops.length > PAGE_SIZE && (
              <div style={{ display: "flex", justifyContent: "center", gap: 8, marginBottom: 16 }}>
                <button disabled={stopsPage <= 1} onClick={() => setStopsPage(p => Math.max(1, p - 1))} style={{ padding: "6px 14px", background: stopsPage <= 1 ? "#f0f0f0" : "white", border: "1px solid #e2e8f0", borderRadius: 8, cursor: stopsPage <= 1 ? "not-allowed" : "pointer", fontSize: FONT_SIZE.xs, color: stopsPage <= 1 ? "#ccc" : "#64748b" }}>ΓåÉ Previous</button>
                <span style={{ display: "flex", alignItems: "center", fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Page {stopsPage} of {Math.ceil(confirmedStops.length / PAGE_SIZE)}</span>
                <button disabled={stopsPage >= Math.ceil(confirmedStops.length / PAGE_SIZE)} onClick={() => setStopsPage(p => p + 1)} style={{ padding: "6px 14px", background: stopsPage >= Math.ceil(confirmedStops.length / PAGE_SIZE) ? "#f0f0f0" : "white", border: "1px solid #e2e8f0", borderRadius: 8, cursor: stopsPage >= Math.ceil(confirmedStops.length / PAGE_SIZE) ? "not-allowed" : "pointer", fontSize: FONT_SIZE.xs, color: stopsPage >= Math.ceil(confirmedStops.length / PAGE_SIZE) ? "#ccc" : "#64748b" }}>Next ΓåÆ</button>
              </div>
            )}

            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {confirmedStops.slice(0, stopsPage * PAGE_SIZE).map((stop: any) => (
                <div key={stop.stop_id} style={{ background: "white", border: "1px solid #e2e8f0", borderRadius: 12, padding: 16, boxShadow: "0 1px 3px rgba(0,0,0,0.05)" }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                    <div>
                      <p style={{ margin: 0, fontWeight: 700, fontSize: FONT_SIZE.lg, color: "#0f172a" }}>{stop.plate_number || "ΓÇö"}</p>
                      <p style={{ margin: "4px 0 0", fontSize: FONT_SIZE.sm, color: "#64748b" }}>{stop.driver_name || "ΓÇö"}</p>
                      <p style={{ margin: "4px 0 0", fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>{stop.stop_time ? formatDateTime(stop.stop_time) : "ΓÇö"}</p>
                    </div>
                    <div style={{ textAlign: "right" }}>
                      <p style={{ margin: "0 0 4px 0", fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Bags delivered</p>
                      <p style={{ margin: 0, fontWeight: 700, fontSize: FONT_SIZE["2xl"], color: "#0070f3" }}>{stop.quantity_offloaded}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Sales Tab (read-only) */}
        {tab === "sales" && (
          <div>
            <div style={{ display: "flex", flexDirection: isMobile ? "column" : "row", justifyContent: "space-between", alignItems: isMobile ? "flex-start" : "center", gap: 12, marginBottom: 16 }}>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
                <button
                  onClick={() => setSalesSortByAdded(!salesSortByAdded)}
                  style={{ padding: "8px 12px", borderRadius: 8, fontSize: FONT_SIZE.xs, cursor: "pointer", border: "1.5px solid #e2e8f0", background: "white", color: "#64748b", fontWeight: 500 }}
                >
                  Sort: {salesSortByAdded ? "Date Added" : "Sale Date"}
                </button>
                <div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
                  {PAYMENT_MODES.map(mode => (
                    <button
                      key={mode}
                      onClick={() => setSalesPaymentFilter(salesPaymentFilter === mode ? "" : mode)}
                      style={{
                        padding: "6px 12px", borderRadius: 20, fontSize: FONT_SIZE.xs, cursor: "pointer",
                        border: `1.5px solid ${salesPaymentFilter === mode ? "#0070f3" : "#e2e8f0"}`,
                        background: salesPaymentFilter === mode ? "#0070f3" : "white",
                        color: salesPaymentFilter === mode ? "white" : "#64748b",
                        fontWeight: salesPaymentFilter === mode ? 600 : 500, transition: "all 0.15s",
                      }}
                    >
                      {mode}
                    </button>
                  ))}
                </div>
              </div>
              {lastUpdated && <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Updated: {formatTime(lastUpdated)}</p>}
            </div>

            {groupedSales.length === 0 && <p style={{ color: "#64748b", fontSize: FONT_SIZE.base }}>No sales records.</p>}

            {groupedSales.length > PAGE_SIZE && (
              <div style={{ display: "flex", justifyContent: "center", gap: 8, marginBottom: 16 }}>
                <button disabled={salesPage <= 1} onClick={() => setSalesPage(p => Math.max(1, p - 1))} style={{ padding: "6px 14px", background: salesPage <= 1 ? "#f0f0f0" : "white", border: "1px solid #e2e8f0", borderRadius: 8, cursor: salesPage <= 1 ? "not-allowed" : "pointer", fontSize: FONT_SIZE.xs, color: salesPage <= 1 ? "#ccc" : "#64748b" }}>ΓåÉ Previous</button>
                <span style={{ display: "flex", alignItems: "center", fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Page {salesPage} of {Math.ceil(groupedSales.length / PAGE_SIZE)}</span>
                <button disabled={salesPage >= Math.ceil(groupedSales.length / PAGE_SIZE)} onClick={() => setSalesPage(p => p + 1)} style={{ padding: "6px 14px", background: salesPage >= Math.ceil(groupedSales.length / PAGE_SIZE) ? "#f0f0f0" : "white", border: "1px solid #e2e8f0", borderRadius: 8, cursor: salesPage >= Math.ceil(groupedSales.length / PAGE_SIZE) ? "not-allowed" : "pointer", fontSize: FONT_SIZE.xs, color: salesPage >= Math.ceil(groupedSales.length / PAGE_SIZE) ? "#ccc" : "#64748b" }}>Next ΓåÆ</button>
              </div>
            )}

            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {groupedSales.slice(0, salesPage * PAGE_SIZE).map(sale => {
                const totalAmount = sale.lines.reduce((sum, l) => sum + (l.total_amount || 0), 0)
                const totalBags = sale.lines.reduce((sum, l) => sum + l.quantity, 0)
                return (
                  <div key={sale.group_id} style={{ background: "white", border: "1px solid #e2e8f0", borderRadius: 12, padding: 16, boxShadow: "0 1px 3px rgba(0,0,0,0.05)" }}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 10 }}>
                      <div>
                        <p style={{ margin: 0, fontWeight: 700, fontSize: FONT_SIZE.lg, color: "#0f172a" }}>{sale.customer_name || "Walk-in"}</p>
                        <p style={{ margin: "4px 0 0", fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>{sale.sold_at ? formatDateTime(sale.sold_at) : "ΓÇö"}</p>
                      </div>
                      <div style={{ textAlign: "right" }}>
                        {totalAmount > 0 && <p style={{ margin: 0, fontWeight: 700, fontSize: FONT_SIZE.lg, color: "#16a34a" }}>Γéª{totalAmount.toLocaleString()}</p>}
                        <span style={{ fontSize: FONT_SIZE.xs, padding: "3px 8px", borderRadius: 6, background: "#f0f7ff", color: "#0070f3", fontWeight: 600, display: "inline-block", marginTop: 4 }}>{sale.payment_mode}</span>
                      </div>
                    </div>

                    {sale.broker_id && (
                      <div style={{ background: "#f8fafc", borderRadius: 8, padding: "10px 12px", marginBottom: 10, border: "1px solid #e2e8f0" }}>
                        <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Status</p>
                        <span style={{ fontSize: FONT_SIZE.xs, padding: "4px 10px", borderRadius: 6, background: sale.status === "Pending" ? "#fffbeb" : sale.status === "Confirmed" ? "#ecfdf5" : "#fef2f2", color: getStatusColor(sale.status), fontWeight: 600, display: "inline-block", marginTop: 4 }}>
                          {sale.status}
                        </span>
                        {sale.status === "Rejected" && sale.rejection_reason && (
                          <div style={{ marginTop: 8, padding: "8px 10px", background: "#fef2f2", border: "1px solid #fecaca", borderRadius: 6 }}>
                            <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                              <Icon icon="mdi:alert-circle" width={14} color="#b91c1c" />
                              <span style={{ fontSize: FONT_SIZE.xs, fontWeight: 600, color: "#b91c1c" }}>Rejected:</span>
                              <span style={{ fontSize: FONT_SIZE.sm, color: "#7f1d1d", fontStyle: "italic", background: "white", padding: "2px 8px", borderRadius: 4, border: "1px solid #fecaca" }}>&ldquo;{sale.rejection_reason}&rdquo;</span>
                            </div>
                          </div>
                        )}
                      </div>
                    )}

                    <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                      {sale.lines.map(line => (
                        <div key={line.sale_id} style={{ display: "grid", gridTemplateColumns: line.price_per_bag !== null ? "1.4fr 0.7fr 0.9fr" : "1.4fr 0.7fr", gap: 8 }}>
                          <div style={{ background: "#f8fafc", borderRadius: 8, padding: "8px 12px" }}>
                            <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Product</p>
                            <p style={{ margin: "2px 0 0", fontWeight: 600, fontSize: FONT_SIZE.base, color: "#0f172a" }}>{line.product}</p>
                          </div>
                          <div style={{ background: "#f8fafc", borderRadius: 8, padding: "8px 12px" }}>
                            <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Bags</p>
                            <p style={{ margin: "2px 0 0", fontWeight: 600, fontSize: FONT_SIZE.base, color: "#0f172a" }}>{line.quantity}</p>
                          </div>
                          {line.price_per_bag !== null && (
                            <div style={{ background: "#f8fafc", borderRadius: 8, padding: "8px 12px" }}>
                              <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Price/Bag</p>
                              <p style={{ margin: "2px 0 0", fontWeight: 600, fontSize: FONT_SIZE.base, color: "#0f172a" }}>Γéª{line.price_per_bag.toLocaleString()}</p>
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        )}

        {/* Verification History Tab */}
        {tab === "history" && (
          <div>
            <p style={{ margin: "0 0 16px 0", fontWeight: 700, fontSize: FONT_SIZE.lg, color: "#0f172a" }}>Verification History</p>
            {groupedVerifications.length === 0 && <p style={{ color: "#64748b", fontSize: FONT_SIZE.base }}>No verifications yet.</p>}
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {groupedVerifications.map(group => {
                const isExpanded = expandedGroups.has(group.key)
                const matchedCount = group.items.filter(v => v.discrepancy === 0).length
                const mismatchedCount = group.items.filter(v => v.discrepancy !== 0).length
                return (
                  <div key={group.key} style={{ background: "white", border: "1px solid #e2e8f0", borderRadius: 12, overflow: "hidden", boxShadow: "0 1px 3px rgba(0,0,0,0.05)" }}>
                    <button
                      onClick={() => setExpandedGroups(prev => {
                        const next = new Set(prev)
                        if (next.has(group.key)) next.delete(group.key)
                        else next.add(group.key)
                        return next
                      })}
                      style={{
                        width: "100%", padding: isMobile ? "14px 16px" : "16px 20px",
                        background: isExpanded ? "#f8fafc" : "white",
                        border: "none", borderBottom: isExpanded ? "1px solid #e2e8f0" : "none",
                        cursor: "pointer", textAlign: "left",
                        display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12,
                      }}
                    >
                      <div style={{ display: "flex", alignItems: "center", gap: 12, minWidth: 0 }}>
                        <Icon
                          icon={isExpanded ? "mdi:chevron-down" : "mdi:chevron-right"}
                          width={20}
                          color="#64748b"
                          style={{ flexShrink: 0, transition: "transform 0.2s" }}
                        />
                        <div style={{ minWidth: 0 }}>
                          <p style={{ margin: 0, fontWeight: 600, fontSize: FONT_SIZE.base, color: "#0f172a" }}>{formatDateTime(group.verified_at)}</p>
                          <p style={{ margin: "2px 0 0", fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>
                            {group.items.length} product{group.items.length !== 1 ? "s" : ""}
                            {matchedCount > 0 && <span style={{ color: "#16a34a" }}> ┬╖ {matchedCount} matched</span>}
                            {mismatchedCount > 0 && <span style={{ color: "#dc2626" }}> ┬╖ {mismatchedCount} mismatched</span>}
                          </p>
                        </div>
                      </div>
                    </button>
                    {isExpanded && (
                      <div style={{ padding: isMobile ? "12px 16px" : "16px 20px", display: "flex", flexDirection: "column", gap: 10 }}>
                        {group.items.map(v => (
                          <div key={v.verification_id} style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", padding: "10px 14px", background: "#f8fafc", borderRadius: 8, border: "1px solid #e2e8f0" }}>
                            <div style={{ minWidth: 0 }}>
                              <p style={{ margin: 0, fontWeight: 600, fontSize: FONT_SIZE.base, color: "#0f172a" }}>{v.product}</p>
                              <div style={{ display: "flex", gap: 12, marginTop: 4, fontSize: FONT_SIZE.sm, color: "#64748b" }}>
                                <span>System: <strong>{v.system_balance}</strong></span>
                                <span>Physical: <strong>{v.physical_count}</strong></span>
                              </div>
                              {v.notes && <p style={{ margin: "4px 0 0", fontSize: FONT_SIZE.xs, color: "#94a3b8", fontStyle: "italic" }}>{v.notes}</p>}
                            </div>
                            {v.discrepancy !== 0 && (
                              <span style={{
                                padding: "4px 10px", borderRadius: 6, fontSize: FONT_SIZE.xs, fontWeight: 700, flexShrink: 0, marginLeft: 12,
                                background: v.discrepancy > 0 ? "#ecfdf5" : "#fef2f2",
                                color: v.discrepancy > 0 ? "#16a34a" : "#dc2626",
                              }}>
                                {v.discrepancy > 0 ? "+" : ""}{v.discrepancy}
                              </span>
                            )}
                            {v.discrepancy === 0 && (
                              <span style={{ padding: "4px 10px", borderRadius: 6, fontSize: FONT_SIZE.xs, fontWeight: 700, background: "#ecfdf5", color: "#16a34a", flexShrink: 0, marginLeft: 12 }}>Matched</span>
                            )}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                )
              })}
            </div>
          </div>
        )}
      </div>

      <ReportModal isOpen={showReportModal} onClose={() => setShowReportModal(false)} userId={supervisor?.supervisor_id || ""} userRole={Role.StoreSupervisor} />

      <ProfilePictureUpload
        isOpen={showPictureModal}
        onClose={() => setShowPictureModal(false)}
        userId={supervisor?.supervisor_id || ""}
        table="store_supervisors"
        idField="supervisor_id"
        currentUrl={profilePicUrl}
        onSuccess={(url) => setProfilePicUrl(url)}
      />
    </div>
  )
}

"use client"

import { useEffect, useState, useRef } from "react"
import { useRouter } from "next/navigation"
import { supabase } from "@/lib/supabase"
import { apiMutate } from "@/lib/api-mutation"
import RoleSwitcher from "@/components/RoleSwitcher"
import { parseAmount } from "@/lib/formatAmount"
import { Icon } from "@iconify/react"
import { useBreakpoint } from "@/app/hooks/useBreakpoint"
import ReportModal from "@/components/ReportModal"
import ProfilePictureUpload from "@/components/ProfilePictureUpload"
import { FONT_SIZE } from "@/lib/constants"
import { usePolling } from "@/lib/hooks/usePolling"
import { requireDashboardRole } from "@/lib/auth-helpers"
import { Role } from "@/lib/roles"
import { useATFs } from "@/lib/hooks/useATFs"
import MaintenanceSection from "@/components/truck-admin/MaintenanceSection"
import MonitorTrucksSection from "@/components/truck-admin/MonitorTrucksSection"
import ATFSection from "@/components/truck-admin/ATFSection"
import ProcurementSection from "@/components/truck-admin/ProcurementSection"
import BalanceSection from "@/components/truck-admin/BalanceSection"
import SideTripsSection from "@/components/truck-admin/SideTripsSection"
import DieselConsumptionSection from "@/components/truck-admin/DieselConsumptionSection"
import dynamic from "next/dynamic"

const ProfilePictureUploadModal = dynamic(() => import("@/components/ProfilePictureUpload"))

type MaintenanceReport = {
  report_id: string
  plate_number: string
  manager_name: string
  maintenance_type: string
  maintenance_location: string | null
  amount: number
  notes: string | null
  status: "Pending" | "Validated" | "Rejected"
  rejection_reason: string | null
  reported_at: string
}

type MaintenanceDeposit = {
  deposit_id: string
  amount: number
  note: string | null
  deposited_by: string
  created_at: string
}

type BulkProcurement = {
  procurement_id: string
  item_name: string
  total_amount: number
  notes: string | null
  logged_at: string
  distributions: { plate_number: string; amount_allocated: number }[]
}

type FeedItem =
  | { kind: "report"; data: MaintenanceReport; date: string }
  | { kind: "procurement"; data: BulkProcurement; date: string }

type ATF = {
  request_id: string
  atf_code: string | null
  plate_number: string
  driver_name: string
  officer_name: string
  company_name: string
  litres: number
  atf_status: string
  requested_at: string
  rate_per_litre: number | null
  total_amount: number | null
  fuel_balance: number | null
  engine_type: string | null
}

type TruckAdmin = {
  admin_id: string
  full_name: string
  profile_picture_url?: string
}

function generateATFCode(): string {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
  let code = "ATF-"
  for (let i = 0; i < 5; i++) code += chars[Math.floor(Math.random() * chars.length)]
  return code
}

const SECTION_LABELS = {
  "maintenance": { label: "Maintenance", icon: "mdi:wrench" },
  "monitor": { label: "Monitor Trucks", icon: "mdi:truck-check" },
  "atf": { label: "ATF", icon: "mdi:gas-station" },
  "procurement": { label: "Procurement", icon: "mdi:package" },
  "balance": { label: "Top Up", icon: "mdi:plus-circle" },
  "side-trips": { label: "Side Trips", icon: "mdi:road-variant" },
  "diesel": { label: "Diesel Consumption", icon: "mdi:fuel" },
} satisfies Record<string, { label: string; icon: string }>

type SectionKey = keyof typeof SECTION_LABELS

export default function TruckAdminDashboard() {
  const router = useRouter()
  const bp = useBreakpoint()
  const isMobile = bp === "mobile"
  const isTablet = bp === "tablet"
  const isNarrow = isMobile || isTablet

  const [admin, setAdmin] = useState<TruckAdmin | null>(null)
  const [reports, setReports] = useState<MaintenanceReport[]>([])
  const [procurements, setProcurements] = useState<BulkProcurement[]>([])
  const [deposits, setDeposits] = useState<MaintenanceDeposit[]>([])
  const [balanceMap, setBalanceMap] = useState<Record<string, number>>({})
  const [maintenanceBalance, setMaintenanceBalance] = useState<number | null>(null)
  const [atfs, setAtfs] = useState<ATF[]>([])
  const { data: atfsFromHook, refetch: refetchATFs } = useATFs({ all: true })
  useEffect(() => { setAtfs(atfsFromHook) }, [atfsFromHook])
  const [loading, setLoading] = useState(true)
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null)
  const [active, setActive] = useState<SectionKey>("maintenance")
  const [filter, setFilter] = useState("All")
  const [atfFilter, setAtfFilter] = useState("All")
  const [feedPage, setFeedPage] = useState(1)
  const [atfPage, setAtfPage] = useState(1)
  const PAGE_SIZE = 50

  const [showPictureModal, setShowPictureModal] = useState(false)
  const [showReportModal, setShowReportModal] = useState(false)

  const [validating, setValidating] = useState<MaintenanceReport | null>(null)
  const [validateLoading, setValidateLoading] = useState(false)
  const [rejecting, setRejecting] = useState<MaintenanceReport | null>(null)
  const [rejectReason, setRejectReason] = useState("")
  const [rejectError, setRejectError] = useState("")
  const [rejectLoading, setRejectLoading] = useState(false)

  const [authorisingATF, setAuthorisingATF] = useState<ATF | null>(null)
  const [authoriseLoading, setAuthoriseLoading] = useState(false)

  const [invalidatingATF, setInvalidatingATF] = useState<ATF | null>(null)
  const [invalidateReason, setInvalidateReason] = useState("")
  const [invalidateError, setInvalidateError] = useState("")
  const [invalidateLoading, setInvalidateLoading] = useState(false)

  const [sideTrips, setSideTrips] = useState<{ id: string; driver_id: string; plate_number: string; item_description: string; created_at: string; driver_name: string; kbnl_truck_no: string | null }[]>([])
  const [sideTripsLoading, setSideTripsLoading] = useState(false)
  const [sideTripsViewMode, setSideTripsViewMode] = useState<"card" | "table">("card")

  const [procItem, setProcItem] = useState("")
  const [procTotal, setProcTotal] = useState("")
  const [procNotes, setProcNotes] = useState("")
  const [procError, setProcError] = useState("")
  const [procLoading, setProcLoading] = useState(false)

  const [depositAmount, setDepositAmount] = useState("")
  const [depositNote, setDepositNote] = useState("")
  const [depositError, setDepositError] = useState("")
  const [depositLoading, setDepositLoading] = useState(false)

  const [sidebarOpen, setSidebarOpen] = useState(true)
  const [drawerOpen, setDrawerOpen] = useState(false)
  const bannerRef = useRef<HTMLDivElement>(null)
  const [bannerHeight, setBannerHeight] = useState(64)

  const isSectionKey = (value: string | null): value is SectionKey =>
    !!value && value in SECTION_LABELS

  useEffect(() => {
    const el = bannerRef.current
    if (!el) return
    const update = () => setBannerHeight(el.offsetHeight)
    const ro = new ResizeObserver(update)
    ro.observe(el)
    update()
    return () => ro.disconnect()
  }, [loading])

  async function fetchSideTrips() {
    setSideTripsLoading(true)
    const { data } = await supabase
      .from("side_trips")
      .select("*")
      .order("created_at", { ascending: false })

    if (data) {
      const enriched = await Promise.all(
        data.map(async (t) => {
          const [driverRes, truckRes] = await Promise.all([
            supabase.from("Drivers").select("full_name").eq("driver_id", t.driver_id).single(),
            supabase.from("Trucks").select("kbnl_truck_no").eq("plate_number", t.plate_number).single(),
          ])
          return {
            ...t,
            driver_name: driverRes.data?.full_name ?? "Unknown",
            kbnl_truck_no: truckRes.data?.kbnl_truck_no ?? null,
          }
        })
      )
      setSideTrips(enriched)
    }
    setSideTripsLoading(false)
  }

  useEffect(() => {
    if (active === "side-trips" && sideTrips.length === 0) fetchSideTrips()
  }, [active])

  useEffect(() => {
    async function init() {
      const { data: { session } } = await supabase.auth.getSession()
      if (!session) { router.push("/login"); return }
      const user = session.user

      const hasRole = await requireDashboardRole(user.id, Role.TruckAdmin)
      if (!hasRole) { router.push("/login"); return }

      const { data: profile } = await supabase.from("Profiles").select("full_name").eq("user_id", user.id).single()

      const { data: adm } = await supabase
        .from("truck_admins")
        .select("admin_id, full_name, profile_picture_url")
        .eq("admin_id", user.id)
        .single()

      if (!adm) { router.push("/login"); return }

      setAdmin({ ...adm, full_name: profile?.full_name ?? adm.full_name })

      const params = new URLSearchParams(window.location.search)
      const section = params.get("section")
      if (isSectionKey(section)) setActive(section)

      await Promise.all([fetchReports(), fetchProcurements(), fetchMaintenanceBalance(), fetchDeposits()])
      setLoading(false)
    }
    init()
  }, [])

  usePolling(() => {
    fetchReports(); fetchProcurements(); fetchMaintenanceBalance(); refetchATFs(); fetchDeposits()
    if (active === "side-trips") fetchSideTrips()
  }, 120000, !!admin)

  useEffect(() => {
    const handlePopState = () => {
      const params = new URLSearchParams(window.location.search)
      const section = params.get("section")
      if (isSectionKey(section)) setActive(section)
    }
    window.addEventListener("popstate", handlePopState)
    return () => window.removeEventListener("popstate", handlePopState)
  }, [])

  function navigate(key: SectionKey) {
    setActive(key)
    if (isNarrow) setDrawerOpen(false)
    window.history.pushState(null, "", `${window.location.pathname}?section=${key}`)
  }

  async function fetchMaintenanceBalance() {
    const { data } = await supabase.from("maintenance_balance").select("current_balance").eq("id", 1).single()
    if (data) setMaintenanceBalance(data.current_balance)
  }

  async function fetchReports() {
    const { data: raw } = await supabase
      .from("maintenance_reports")
      .select("report_id, plate_number, manager_id, maintenance_type, maintenance_location, amount, notes, status, rejection_reason, reported_at")
      .order("reported_at", { ascending: false })
    if (!raw) { setReports([]); return }

    const managerIds = [...new Set(raw.map(r => r.manager_id).filter(Boolean))]
    const { data: managers } = managerIds.length
      ? await supabase.from("truck_officers").select("manager_id, full_name").in("manager_id", managerIds)
      : { data: [] }
    const managerMap = Object.fromEntries((managers || []).map(m => [m.manager_id, m.full_name]))

    const enriched = raw.map(r => ({
      ...r,
      manager_name: managerMap[r.manager_id] ?? "Unknown",
      maintenance_location: r.maintenance_location ?? null,
    }))
    setReports(enriched)
    setLastUpdated(new Date())
  }

  async function fetchProcurements() {
    const { data: raw } = await supabase.from("bulk_procurement").select("procurement_id, item_name, total_amount, notes, logged_at").order("logged_at", { ascending: false })
    if (!raw) { setProcurements([]); return }
    const ids = raw.map(p => p.procurement_id)
    const { data: allDists } = ids.length
      ? await supabase.from("procurement_distributions").select("procurement_id, plate_number, amount_allocated").in("procurement_id", ids)
      : { data: [] }
    const distMap: Record<string, { plate_number: string; amount_allocated: number }[]> = {}
    for (const d of allDists || []) {
      if (!distMap[d.procurement_id]) distMap[d.procurement_id] = []
      distMap[d.procurement_id].push({ plate_number: d.plate_number, amount_allocated: d.amount_allocated })
    }
    const enriched = raw.map(p => ({ ...p, distributions: distMap[p.procurement_id] || [] }))
    setProcurements(enriched)
  }

  async function fetchDeposits() {
    const { data } = await supabase.from("maintenance_deposits").select("*").order("created_at", { ascending: false })
    if (data) setDeposits(data)
  }

  async function handleValidate() {
    if (!validating) return
    setValidateLoading(true)

    const { data, error } = await apiMutate("maintenance", {
      action: "rpc",
      function: "validate_maintenance_report",
      params: { p_report_id: validating.report_id },
    })
    if (error) { setValidateLoading(false); return }

    if (data && typeof data === "object" && "new_balance" in (data as Record<string, unknown>)) {
      setMaintenanceBalance((data as { new_balance: number }).new_balance)
    } else {
      setMaintenanceBalance(Math.max(0, (maintenanceBalance ?? 0) - validating.amount))
    }
    setValidateLoading(false)
    setValidating(null)
    fetchReports()
  }

  async function handleReject() {
    if (!rejecting) return
    if (!rejectReason.trim()) return setRejectError("Please provide a reason")
    setRejectLoading(true)
    await apiMutate("maintenance", {
      action: "update",
      table: "maintenance_reports",
      data: { status: "Rejected", rejection_reason: rejectReason.trim() },
      filters: { report_id: rejecting.report_id },
    })
    setRejectLoading(false); setRejecting(null); setRejectReason(""); setRejectError("")
    fetchReports()
  }

  async function handleAuthoriseATF() {
    if (!authorisingATF) return
    setAuthoriseLoading(true)

    const code = generateATFCode()
    const { error } = await apiMutate("fuel", {
      action: "update",
      table: "fuel_requests",
      data: { atf_status: "Authorised", atf_code: code, authorised_by: admin?.admin_id },
      filters: { request_id: authorisingATF.request_id },
    })

    setAuthoriseLoading(false)
    if (error) return
    setAuthorisingATF(null)
    refetchATFs()
  }

  async function handleInvalidate() {
    if (!invalidatingATF) return
    if (!invalidateReason.trim()) return setInvalidateError("Provide a reason for invalidation")

    setInvalidateLoading(true)
    const { error } = await apiMutate("fuel", {
      action: "rpc",
      function: "invalidate_atf",
      params: {
        p_request_id: invalidatingATF.request_id,
        p_reason: invalidateReason.trim(),
      },
    })

    if (error) {
      setInvalidateError(error)
      setInvalidateLoading(false)
      return
    }

    setInvalidateLoading(false)
    setInvalidatingATF(null)
    setInvalidateReason("")
    setInvalidateError("")
    refetchATFs()
  }

  async function handleDeposit() {
    const amount = parseAmount(depositAmount)
    if (!depositAmount || amount <= 0) return setDepositError("Enter a valid amount")
    setDepositLoading(true)

    const { data, error } = await apiMutate("maintenance", {
      action: "rpc",
      function: "add_maintenance_deposit",
      params: { p_amount: amount, p_note: depositNote.trim() || null },
    })
    if (error) { setDepositError(error); setDepositLoading(false); return }

    if (data && typeof data === "object" && "new_balance" in (data as Record<string, unknown>)) {
      setMaintenanceBalance((data as { new_balance: number }).new_balance)
    } else {
      setMaintenanceBalance((prev) => (prev ?? 0) + amount)
    }
    setDepositLoading(false); setDepositAmount(""); setDepositNote(""); setDepositError("")
  }

  async function handleLogProcurement() {
    if (!procItem.trim()) return setProcError("Enter item name")
    const totalNum = parseAmount(procTotal)
    if (!procTotal || totalNum <= 0) return setProcError("Enter a valid total amount")
    setProcLoading(true)

    const { data, error } = await apiMutate("maintenance", {
      action: "rpc",
      function: "deduct_maintenance_balance",
      params: {
        p_amount: totalNum,
        p_item_name: procItem.trim(),
        p_notes: procNotes.trim() || null,
      },
    })
    setProcLoading(false)
    if (error) { setProcError(error); return }

    if (data && typeof data === "object" && "new_balance" in (data as Record<string, unknown>)) {
      setMaintenanceBalance((data as { new_balance: number }).new_balance)
    } else {
      setMaintenanceBalance((prev) => Math.max(0, (prev ?? 0) - totalNum))
    }
    setProcItem(""); setProcTotal(""); setProcNotes(""); setProcError("")
    await fetchProcurements()
    navigate("maintenance"); setFilter("Bulk Procurement")
  }

  useEffect(() => {
    const map: Record<string, number> = {}
    const records: { id: string; amount: number; created_at: string }[] = [
      ...reports.filter(r => r.status === "Validated").map(r => ({
        id: r.report_id, amount: r.amount, created_at: r.reported_at
      })),
      ...procurements.map(p => ({
        id: p.procurement_id, amount: p.total_amount, created_at: p.logged_at
      })),
      ...deposits.map(d => ({
        id: d.deposit_id, amount: -d.amount, created_at: d.created_at
      })),
    ]
    records.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime())

    let running = maintenanceBalance ?? 0
    for (const rec of records) {
      map[rec.id] = running
      running += rec.amount
    }
    setBalanceMap(map)
  }, [reports, procurements, deposits, maintenanceBalance])

  const feedItems: FeedItem[] = [
    ...reports.map(r => ({ kind: "report" as const, data: r, date: r.reported_at })),
    ...procurements.map(p => ({ kind: "procurement" as const, data: p, date: p.logged_at })),
  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())

  const filteredFeedAll = filter === "All" ? feedItems
    : filter === "Bulk Procurement" ? feedItems.filter(f => f.kind === "procurement")
