    const { data: profile } = user ? await supabase
      .from("Profiles")
      .select("role")
      .eq("user_id", user.id)
      .single() : { data: null }

    const role = profile?.role
    const dashboard = role ? getRoleDashboard(role) : "/login"
    setMessage("Password set! Redirecting...")
    setIsError(false)
    setTimeout(() => router.push(dashboard), 1500)
