"use client"

import { useCallback, useEffect, useState } from 'react';
import { apiMutate } from '@/lib/api-mutation';
import {
  savePendingTripAction,
  getPendingTripActionCount,
} from '@/lib/offline/tripsDb';

interface UseOfflineTripActionResult {
  submitAction: (
    type: 'stop' | 'discrepancy' | 'load_more',
    tripId: string,
    tableName: string,
    data: Record<string, any>
  ) => Promise<{ success: boolean; error?: string; offline?: boolean }>;
  isSubmitting: boolean;
  isOnline: boolean;
}

export function useOfflineTripAction(): UseOfflineTripActionResult {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const goOnline = () => setIsOnline(true);
    const goOffline = () => setIsOnline(false);
    window.addEventListener('online', goOnline);
    window.addEventListener('offline', goOffline);
    return () => {
      window.removeEventListener('online', goOnline);
      window.removeEventListener('offline', goOffline);
    };
  }, []);

  const submitAction = useCallback(
    async (
      type: 'stop' | 'discrepancy' | 'load_more',
      tripId: string,
      tableName: string,
      data: Record<string, any>
    ) => {
      setIsSubmitting(true);

      try {
        if (isOnline) {
          console.log(`[Trip Action] Online - submitting ${type} immediately`);

          let result;
          if (type === 'load_more') {
            const { loaded_quantity, trip_status, updated_at } = data;
            result = await apiMutate("trips", {
              action: "update",
              table: "Trips",
              data: { loaded_quantity, trip_status, updated_at },
              filters: { trip_id: tripId },
            })
          } else {
            result = await apiMutate("trips", {
              action: "insert",
              table: tableName,
              data,
            })
          }

          if (result.error) {
            console.error(`[Trip Action] Submit failed:`, result.error);
            setIsSubmitting(false);
            return { success: false, error: result.error };
          }

          console.log(`[Trip Action] ${type} submitted successfully`);
          setIsSubmitting(false);
          return { success: true };
        }

        console.log(`[Trip Action] Offline - saving ${type} locally`);
        await savePendingTripAction(type, tripId, data);
        setIsSubmitting(false);
        return { success: true, offline: true };
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Unknown error';
        console.error(`[Trip Action] Error:`, error);
        setIsSubmitting(false);
        return { success: false, error: message };
      }
    },
    [isOnline]
  );

  return {
    submitAction,
    isSubmitting,
    isOnline,
  };
}

export function usePendingTripCount(): number {
  const [count, setCount] = useState(0);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    let mounted = true;
    const refreshCount = async () => {
      const newCount = await getPendingTripActionCount();
      if (mounted) setCount(newCount);
    };

    window.addEventListener('online', refreshCount);
    refreshCount();

    return () => {
      mounted = false;
      window.removeEventListener('online', refreshCount);
    };
  }, []);

  return count;
}

import { useEffect, useState } from 'react';
import { supabase } from '@/lib/supabase';

const STORAGE_KEY = 'kbnl_pwa_prompted';
const FIRST_LOGIN_KEY = 'kbnl_first_login';

export function usePWAInstall() {
  const [hasBeenPrompted, setHasBeenPrompted] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [session, setSession] = useState<any>(null);

  useEffect(() => {
    // Get session on mount
    supabase.auth.getSession().then(({ data }) => {
      setSession(data.session);
    });

    // Listen for auth changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      (_event, session) => {
        setSession(session);
      }
    );

    return () => subscription?.unsubscribe();
  }, []);

  useEffect(() => {
    const initPWAState = async () => {
      try {
        const localPrompted = localStorage.getItem(STORAGE_KEY);
        
        if (localPrompted === 'true') {
          setHasBeenPrompted(true);
          setIsLoading(false);
          return;
        }

        if (!session?.user?.id) {
          setIsLoading(false);
          return;
        }

        const localFirstLogin = localStorage.getItem(FIRST_LOGIN_KEY);
        if (!localFirstLogin) {
          setHasBeenPrompted(false);
          localStorage.setItem(FIRST_LOGIN_KEY, session.user.id);
        } else {
          setHasBeenPrompted(true);
        }
      } catch (error) {
        console.error('Error initializing PWA state:', error);
        setHasBeenPrompted(true);
      } finally {
        setIsLoading(false);
      }
    };

    initPWAState();
  }, [session?.user?.id]);

  const markAsPrompted = () => {
    localStorage.setItem(STORAGE_KEY, 'true');
    setHasBeenPrompted(true);
  };

  const resetPrompt = () => {
    localStorage.removeItem(STORAGE_KEY);
    localStorage.removeItem(FIRST_LOGIN_KEY);
    setHasBeenPrompted(false);
  };

  return {
    hasBeenPrompted,
    markAsPrompted,
    resetPrompt,
    isLoading,
  };
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { supabase } from '@/lib/supabase'

const VAPID_PUBLIC_KEY = process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY || ''

function urlBase64ToUint8Array(base64String: string) {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4)
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/')
  const rawData = window.atob(base64)
  const outputArray = new Uint8Array(rawData.length)
  for (let i = 0; i < rawData.length; ++i) {
    outputArray[i] = rawData.charCodeAt(i)
  }
  return outputArray
}

async function getSWRegistration(): Promise<ServiceWorkerRegistration | null> {
  if (!('serviceWorker' in navigator)) return null
  try {
    return await navigator.serviceWorker.ready
  } catch {
    return null
  }
}

function sleep(ms: number) {
  return new Promise(resolve => setTimeout(resolve, ms))
}

// Log the current service worker registration state for diagnostics.
function logSWState(reg: ServiceWorkerRegistration, tag: string) {
  console.log(`[Push] ${tag} SW state:`, {
    controller: navigator.serviceWorker.controller?.scriptURL || null,
    active: reg.active?.state || null,
    installing: reg.installing?.state || null,
    waiting: reg.waiting?.state || null,
    scope: reg.scope,
  })
}

// Wait until the service worker controls the page (or timeout). Some browsers
// require a controlling SW before pushManager.subscribe() will succeed.
async function waitForController(reg: ServiceWorkerRegistration, timeoutMs = 5000): Promise<boolean> {
  if (navigator.serviceWorker.controller) return true

  return new Promise((resolve) => {
    const timer = setTimeout(() => {
      navigator.serviceWorker.removeEventListener('controllerchange', onController)
      resolve(false)
    }, timeoutMs)

    function onController() {
      clearTimeout(timer)
      navigator.serviceWorker.removeEventListener('controllerchange', onController)
      resolve(true)
    }

    // Re-check immediately in case the controller was set between the first
    // check and the listener being attached.
    if (navigator.serviceWorker.controller) {
      clearTimeout(timer)
      resolve(true)
      return
    }

    navigator.serviceWorker.addEventListener('controllerchange', onController)
  })
}

// Guards against React StrictMode double-firing effects in dev, which can
// trigger concurrent pushManager.subscribe() calls (the second fails with
// AbortError "Registration failed - push service error").
let subscribeInFlight = false

// Some browsers keep a push subscription tied to a *stale* registration after
// the SW is replaced. That orphan can make Chrome's push service reject new
// subscriptions with AbortError "Registration failed - push service error".
// Try to unsubscribe from every registration's push manager, then retry.
async function clearOrphanedSubscriptions(): Promise<void> {
  if (!('serviceWorker' in navigator)) return
  try {
    const regs = await navigator.serviceWorker.getRegistrations()
    for (const r of regs) {
      try {
        const sub = await r.pushManager.getSubscription()
        if (sub) await sub.unsubscribe().catch(() => {})
      } catch {
        // ignore ΓÇö registration may not have a push manager available
      }
    }
  } catch {
    // ignore
  }
}

// Create a browser push subscription. Retries transient AbortError failures
// (e.g. the service worker is mid-activation or the push service hiccups).
async function createBrowserSubscription(reg: ServiceWorkerRegistration): Promise<PushSubscription | null> {
  if (!VAPID_PUBLIC_KEY) {
    console.error('[Push] NEXT_PUBLIC_VAPID_PUBLIC_KEY is not set. Cannot create subscription.')
    return null
  }

  const existing = await reg.pushManager.getSubscription().catch(() => null)
  if (existing) {
    logSWState(reg, 'existing-subscription')
    return existing
  }

  // Ensure the SW controls the page before subscribing.
  logSWState(reg, 'pre-subscribe')
  const controlled = await waitForController(reg)
  if (!controlled) {
    console.warn('[Push] SW does not control the page; subscribing anyway (may fail).')
  }

  const options = {
    userVisibleOnly: true,
    applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY),
  }

  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const subscription = await reg.pushManager.subscribe(options)
      logSWState(reg, 'subscribed')
      return subscription
    } catch (err) {
      const name = (err as DOMException)?.name
      const isTransient = name === 'AbortError' || name === 'InvalidStateError'
      if (!isTransient) throw err
      logSWState(reg, `subscribe-failed-${name}`)
      // Clean up any orphaned subscriptions tied to stale registrations, which
      // is a common cause of persistent "Registration failed - push service
      // error" in Chrome after SW unregister/re-register cycles.
      if (attempt === 1) {
        console.warn('[Push] Attempting to clear orphaned push subscriptions...')
        await clearOrphanedSubscriptions()
      }
      if (attempt < 2) {
        console.warn(`[Push] subscribe() failed (${name}), retrying in ${500 * (attempt + 1)}ms...`)
        await sleep(500 * (attempt + 1))
      } else {
        throw err
      }
    }
  }
  return null
}

// Send the browser subscription to our API so it can be persisted.
async function persistSubscription(subscription: PushSubscription): Promise<boolean> {
  const sub = JSON.parse(JSON.stringify(subscription))
  const { data: { session } } = await supabase.auth.getSession()

  const headers: Record<string, string> = { 'Content-Type': 'application/json' }
  if (session?.access_token) {
    headers['Authorization'] = `Bearer ${session.access_token}`
  }

  const res = await fetch('/api/push/subscribe', {
    method: 'POST',
    headers,
    body: JSON.stringify({
      endpoint: sub.endpoint,
      keys: { p256dh: sub.keys.p256dh, auth: sub.keys.auth },
    }),
  })

  return res.ok
}

export function usePushNotifications() {
  const [permission, setPermission] = useState<NotificationPermission>('default')
  const [isSubscribed, setIsSubscribed] = useState(false)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const hasNotification = typeof Notification !== 'undefined'

    if (!('serviceWorker' in navigator) || !('PushManager' in window)) {
      if (hasNotification) setPermission(Notification.permission)
      setIsSubscribed(false)
      setLoading(false)
      return
    }

    if (hasNotification) setPermission(Notification.permission)

    navigator.serviceWorker.ready.then((reg) => {
      reg.pushManager.getSubscription().then((subscription) => {
        setIsSubscribed(!!subscription)
        setLoading(false)
      }).catch(() => {
        setLoading(false)
      })
    }).catch(() => {
      setLoading(false)
    })
  }, [])

  const subscribe = useCallback(async () => {
    if (!('serviceWorker' in navigator) || !('PushManager' in window)) return false

    if (subscribeInFlight) return false
    subscribeInFlight = true

    try {
      if (typeof Notification === 'undefined') return false
      const result = await Notification.requestPermission()
      setPermission(result)

      if (result !== 'granted') return false

      const reg = await getSWRegistration()
      if (!reg || !reg.active) return false

      const subscription = await createBrowserSubscription(reg)
      if (!subscription) return false

      const ok = await persistSubscription(subscription)
      if (!ok) {
        console.error('[Push] Server rejected subscription')
        await subscription.unsubscribe().catch(() => {})
        setIsSubscribed(false)
        return false
      }

      setIsSubscribed(true)
      return true
    } catch (err) {
      console.error('[Push] Subscribe failed:', err)
      return false
    } finally {
      subscribeInFlight = false
    }
  }, [])

  const unsubscribe = useCallback(async () => {
    if (!('serviceWorker' in navigator)) return false

    try {
      const reg = await getSWRegistration()
      if (!reg) return false

      const subscription = await reg.pushManager.getSubscription()

      if (!subscription) return true

      const endpoint = subscription.endpoint
      const { data: { session } } = await supabase.auth.getSession()

      const headers: Record<string, string> = { 'Content-Type': 'application/json' }
      if (session?.access_token) {
        headers['Authorization'] = `Bearer ${session.access_token}`
      }

      await subscription.unsubscribe()

      await fetch('/api/push/unsubscribe', {
        method: 'DELETE',
        headers,
        body: JSON.stringify({ endpoint }),
      })

      setIsSubscribed(false)
      return true
    } catch (err) {
      console.error('[Push] Unsubscribe failed:', err)
      return false
    }
  }, [])

  const reSubscribe = useCallback(async () => {
    if (!('serviceWorker' in navigator) || !('PushManager' in window)) return

    // Skip if a subscribe is already in flight (StrictMode double-fire guard).
    if (subscribeInFlight) return

    subscribeInFlight = true

    try {
      const reg = await getSWRegistration()
      if (!reg || !reg.active) return

      // If permission is not granted yet, there's nothing to re-subscribe.
      if (typeof Notification !== 'undefined' && Notification.permission !== 'granted') {
        return
      }

      const subscription = await createBrowserSubscription(reg)
      if (!subscription) return

      const ok = await persistSubscription(subscription)
      if (!ok) {
        console.error('[Push] Re-subscribe rejected by server')
      } else {
        setIsSubscribed(true)
      }
    } catch (err) {
      const name = (err as DOMException)?.name
      const msg = (err as Error)?.message || ''
      if (name === 'AbortError' && msg.includes('push service')) {
        console.error(
          '[Push] Re-subscribe failed: Chrome push service rejected the subscription. ' +
          'Clear site data for this origin (Settings > Privacy > Clear browsing data > ' +
          '"Cookies and other site data"), then reload and log in again.'
        )
      } else {
        console.error('[Push] Re-subscribe failed:', err)
      }
    } finally {
      subscribeInFlight = false
    }
  }, [])

  return {
    permission,
    isSubscribed,
    loading,
    subscribe,
    unsubscribe,
    reSubscribe,
    isSupported: typeof window !== 'undefined' && 'serviceWorker' in navigator && 'PushManager' in window && typeof Notification !== 'undefined',
  }
}

"use client"

import { useState, useEffect, useCallback } from "react"
import { supabase } from "@/lib/supabase"

interface UseSupabaseQueryOptions<T> {
  table: string
  select?: string
  filters?: Record<string, unknown>
  order?: { column: string; ascending?: boolean }
  limit?: number
  enabled?: boolean
}

interface UseSupabaseQueryResult<T> {
  data: T[]
  loading: boolean
  error: string | null
  refetch: () => void
}

export function useSupabaseQuery<T = Record<string, unknown>>({
  table,
  select = "*",
  filters,
  order,
  limit,
  enabled = true,
}: UseSupabaseQueryOptions<T>): UseSupabaseQueryResult<T> {
  const [data, setData] = useState<T[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [refreshKey, setRefreshKey] = useState(0)

  const refetch = useCallback(() => {
    setRefreshKey(k => k + 1)
  }, [])

  useEffect(() => {
    if (!enabled) {
      setLoading(false)
      return
    }

    let cancelled = false

    async function fetchData() {
      setLoading(true)
      setError(null)

      try {
        let query: any = supabase
          .from(table)
          .select(select) as any

        if (filters) {
          for (const [key, value] of Object.entries(filters)) {
            query = query.eq(key, value)
          }
        }

        if (order) {
          query = query.order(order.column, { ascending: order.ascending ?? false })
        }

        if (limit) {
          query = query.limit(limit)
        }

        const { data: result, error: queryError } = await query

        if (!cancelled) {
          if (queryError) {
            setError(queryError.message)
            setData([])
          } else {
            setData((result || []) as T[])
          }
          setLoading(false)
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : "Query failed")
          setData([])
          setLoading(false)
        }
      }
    }

    fetchData()

    return () => {
      cancelled = true
    }
  }, [table, select, JSON.stringify(filters), order?.column, order?.ascending, limit, enabled, refreshKey])

  return { data, loading, error, refetch }
}

"use client"

import ModernInput from "@/components/ModernInput";
import SplashScreen from "@/components/SplashScreen";
import { useState, useRef, useEffect } from "react"
import { supabase } from "@/lib/supabase"
import { Icon } from "@iconify/react"
import { useRouter } from "next/navigation"
import { getRoleDashboard } from "@/lib/permissions"

export default function LoginPage() {
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [message, setMessage] = useState("")
  const [loading, setLoading] = useState(false)
  const [showPassword, setShowPassword] = useState(false)
  const [showSplash, setShowSplash] = useState(true)
  const [mode, setMode] = useState<"login" | "forgot-step1" | "forgot-step2">("login")
  const [forgotEmail, setForgotEmail] = useState("")
  const [newPassword, setNewPassword] = useState("")
  const [confirmNewPassword, setConfirmNewPassword] = useState("")
  const [forgotMessage, setForgotMessage] = useState("")
  const [forgotLoading, setForgotLoading] = useState(false)
  const [showNewPassword, setShowNewPassword] = useState(false)
  const [showConfirmPassword, setShowConfirmPassword] = useState(false)
  const router = useRouter()

  useEffect(() => {
    supabase.auth.signOut()
  }, [])

  const passwordInputRef = useRef<HTMLInputElement | null>(null)

  async function handleLogin() {
    if (loading) return
    if (!email || !password) return setMessage("Enter email and password")
    setLoading(true)
    setMessage("")

    let timedOut = false
    const timer = setTimeout(() => {
      timedOut = true
      setLoading(false)
      setMessage("Connection timed out. Please check your network and try again.")
    }, 15000)

    const { data, error } = await supabase.auth.signInWithPassword({ email, password })

    clearTimeout(timer)
    if (timedOut) return

    if (error) {
      setMessage(error.message)
      setLoading(false)
      return
    }

    function isNetworkError(err: any) {
      const msg = err?.message?.toLowerCase() || ""
      return msg.includes("failed to fetch") ||
        msg.includes("networkerror") ||
        msg.includes("network error") ||
        msg.includes("timeout") ||
        msg.includes("fetch")
    }

    function queryWithTimeout<T>(promise: PromiseLike<{ data: T | null; error: any }>, ms = 10000): Promise<{ data: T | null; error: any }> {
      return Promise.race([
        promise,
        new Promise<{ data: null; error: { message: string } }>((resolve) =>
          setTimeout(() => resolve({ data: null, error: { message: "timeout" } }), ms)
        ),
      ])
    }

    // Fetch role from Profiles
    const profileResult = await queryWithTimeout<{ role: string; must_change_password: boolean; is_deactivated: boolean }>(
      supabase
        .from("Profiles")
        .select("role, must_change_password, is_deactivated")
        .eq("user_id", data.user.id)
        .single()
    )

    const profile = profileResult.data
    const profileError = profileResult.error

    if (profileError || !profile) {
      if (isNetworkError(profileError)) {
        setLoading(false)
        setMessage("Network error. Please check your connection and try again.")
        return
      }
      await supabase.auth.signOut()
      setMessage("Profile not found. Contact admin.")
      setLoading(false)
      return
    }

    if (profile.is_deactivated) {
      await supabase.auth.signOut()
      setMessage("Your account has been deactivated. Contact admin.")
      setLoading(false)
      return
    }

    if (profile.role === "Driver") {
      const driverResult = await queryWithTimeout<{ status: string }>(
        supabase
          .from("Drivers")
          .select("status")
          .eq("driver_id", data.user.id)
          .single()
      )

      const driverError = driverResult.error
      const driverData = driverResult.data

      if (driverError || !driverData) {
        if (isNetworkError(driverError)) {
          setLoading(false)
          setMessage("Network error. Please check your connection and try again.")
          return
        }
        await supabase.auth.signOut()
        setMessage("Unable to verify driver status. Contact admin.")
        setLoading(false)
        return
      }

      if (driverData?.status === "Suspended") {
        await supabase.auth.signOut()
        setMessage("Your account has been suspended. Contact admin.")
        setLoading(false)
        return
      }
    }

    // Check if user must change password
    if (profile.must_change_password) {
      setLoading(false)
      router.push("/auth/set-password")
      return
    }

    setLoading(false)

    // Route based on role
    const dashboard = getRoleDashboard(profile.role)
    if (dashboard === "/login") {
      await supabase.auth.signOut()
      setMessage("Unknown role. Contact admin.")
    } else {
      router.push(dashboard)
    }
  }

  function switchToForgotStep1() {
    setForgotEmail(email)
    setForgotMessage("")
    setNewPassword("")
    setConfirmNewPassword("")
    setMode("forgot-step1")
  }

  function switchToLogin() {
    setMode("login")
    setForgotMessage("")
    setForgotLoading(false)
  }

  function handleForgotStep1() {
    if (!forgotEmail) return setForgotMessage("Enter your email address")
    setMode("forgot-step2")
    setForgotMessage("")
  }

  async function handleForgotStep2() {
    if (forgotLoading) return
    if (!newPassword) return setForgotMessage("Enter a new password")
    if (newPassword.length < 6) return setForgotMessage("Password must be at least 6 characters")
    if (newPassword !== confirmNewPassword) return setForgotMessage("Passwords do not match")
    setForgotLoading(true)
    setForgotMessage("")

    try {
      const res = await fetch("/api/reset-password", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: forgotEmail, newPassword }),
      })
      const data = await res.json().catch(() => null)
      if (!res.ok) {
        setForgotMessage(data?.error || "Failed to reset password")
        return
      }
      setForgotMessage("Password reset successfully! You can now log in with your new password.")
      setTimeout(() => switchToLogin(), 2500)
    } catch {
      setForgotMessage("Network error. Please try again.")
    } finally {
      setForgotLoading(false)
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      if (e.currentTarget === passwordInputRef.current) {
        handleLogin()
      } else {
        passwordInputRef.current?.focus()
      }
    }
  }

  if (showSplash) {
    return <SplashScreen onComplete={() => setShowSplash(false)} logoSrc="/logo.png" companyName="KbNL" />
  }

  return (
    <div style={{
      minHeight: "100vh",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      background: "linear-gradient(135deg, #ffffff 0%, #f5f7fa 100%)",
      padding: "20px",
      fontFamily: "'Segoe UI', 'Helvetica Neue', sans-serif",
    }}>
      <style>{`
        @keyframes containerSlideIn {
          from {
            opacity: 0;
            transform: translateY(20px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }

        @keyframes fadeIn {
          from {
            opacity: 0;
          }
          to {
            opacity: 1;
          }
        }

        .login-container {
          animation: containerSlideIn 0.6s ease-out;
        }

        .logo-section {
          animation: fadeIn 0.6s ease-out;
        }

        .form-section {
          animation: fadeIn 0.6s ease-out 0.1s backwards;
          animation-fill-mode: forwards;
        }

        .input-group {
          animation: fadeIn 0.6s ease-out 0.2s backwards;
          animation-fill-mode: forwards;
        }

        .signin-button {
          animation: fadeIn 0.6s ease-out 0.3s backwards;
          animation-fill-mode: forwards;
          transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .signin-button:hover:not(:disabled) {
          transform: translateY(-2px);
          box-shadow: 0 12px 24px rgba(0, 112, 243, 0.24);
        }

        .signin-button:active:not(:disabled) {
          transform: translateY(0);
        }

        .message-container {
          animation: fadeIn 0.3s ease-out;
        }

        /* Hide browser native password reveal */
        input[type="password"]::-ms-reveal,
        input[type="password"]::-ms-clear {
          display: none;
        }
        input[type="password"]::-webkit-credentials-auto-fill-button {
          display: none !important;
        }

        .password-wrapper {
          position: relative;
        }

        .password-toggle {
          position: absolute;
          right: 12px;
          top: 50%;
          transform: translateY(-50%);
          background: none;
          border: none;
          cursor: pointer;
          padding: 4px;
          display: flex;
          align-items: center;
          justify-content: center;
          color: #94a3b8;
          transition: color 0.2s ease;
          z-index: 1;
        }

        .password-toggle:hover {
          color: #171717;
        }
      `}</style>

      <div className="login-container" style={{
        width: "100%",
        maxWidth: 420,
        background: "white",
        borderRadius: 20,
        padding: "48px 40px",
        boxShadow: "0 20px 60px rgba(0, 0, 0, 0.08)",
        border: "1px solid rgba(0, 0, 0, 0.06)",
      }}>
        {/* Logo Section */}
        <div className="logo-section" style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          marginBottom: 40,
        }}>
          <div style={{
            width: 80,
            height: 80,
            borderRadius: 16,
            background: "linear-gradient(135deg, rgba(0, 112, 243, 0.1) 0%, rgba(0, 112, 243, 0.05) 100%)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            marginBottom: 20,
            border: "1px solid rgba(0, 112, 243, 0.15)",
          }}>
            <img
              src="/logo.png"
              alt="KbNL Logo"
              style={{
                width: "60%",
                height: "60%",
                objectFit: "contain",
              }}
              onError={(e) => {
                // Fallback: show initials if logo fails
                (e.currentTarget as HTMLImageElement).style.display = "none"
              }}
            />
          </div>
          <h1 style={{
            fontSize: 28,
            fontWeight: 700,
            color: "#171717",
            margin: "0 0 8px 0",
            letterSpacing: "-0.5px",
          }}>
            K<span style={{ fontSize: 16 }}>b</span>NL
          </h1>
          <p style={{
            fontSize: 14,
            color: "#888",
            margin: 0,
            fontWeight: 500,
            letterSpacing: "0.5px",
            textTransform: "uppercase",
            textAlign: "center",
          }}>
            Operations Management System
          </p>
        </div>

        {/* Form Section */}
        <div className="form-section">
          {mode === "login" ? (
            <>
              <div className="input-group" style={{ marginBottom: 16 }}>
                <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: "#171717", marginBottom: 8, letterSpacing: "0.3px", textTransform: "uppercase" }}>
                  Email Address
                </label>
                <ModernInput
                  type="email"
                  placeholder="you@company.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  onKeyDown={handleKeyDown}
                  style={{ width: "100%", padding: "12px 16px", boxSizing: "border-box", fontSize: 16, border: "1.5px solid #e5e5e5", borderRadius: 10, background: "#f9f9f9", transition: "all 0.2s ease" }}
                  data-modern-input="migrated"
                />
              </div>

              <div className="input-group" style={{ marginBottom: 28 }}>
                <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: "#171717", marginBottom: 8, letterSpacing: "0.3px", textTransform: "uppercase" }}>
                  Password
                </label>
                <div className="password-wrapper">
                  <ModernInput
                    type={showPassword ? "text" : "password"}
                    ref={passwordInputRef}
                    placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    onKeyDown={handleKeyDown}
                    style={{ width: "100%", padding: "12px 48px 12px 16px", boxSizing: "border-box", fontSize: 16, border: "1.5px solid #e5e5e5", borderRadius: 10, background: "#f9f9f9", transition: "all 0.2s ease" }}
                    data-modern-input="migrated"
                  />
                  <button type="button" className="password-toggle" onClick={() => setShowPassword((prev) => !prev)} aria-label={showPassword ? "Hide password" : "Show password"}>
                    <Icon icon={showPassword ? "mdi:eye-off" : "mdi:eye"} width={20} height={20} />
                  </button>
                </div>
              </div>

              <div style={{ textAlign: "right", marginBottom: 24, marginTop: -12 }}>
                <button type="button" onClick={switchToForgotStep1} style={{ background: "none", border: "none", color: "#0070f3", cursor: "pointer", fontSize: 13, fontWeight: 500, padding: 0 }}>
                  Forgot password?
                </button>
              </div>

              <button onClick={handleLogin} disabled={loading} className="signin-button" style={{ width: "100%", padding: 14, background: loading ? "#0070f3" : "#0070f3", color: "white", border: "none", borderRadius: 10, fontSize: 16, fontWeight: 600, cursor: loading ? "not-allowed" : "pointer", opacity: loading ? 0.85 : 1, letterSpacing: "0.3px", position: "relative" }}>
                {loading ? (
                  <span style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}>
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" style={{ animation: "spin 1s linear infinite" }}>
                      <style>{`@keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }`}</style>
                      <circle cx="12" cy="12" r="10" stroke="white" strokeWidth="2" strokeDasharray="16" opacity="0.3" />
                      <path d="M12 2a10 10 0 0 1 10 10" stroke="white" strokeWidth="2" strokeLinecap="round" />
                    </svg>
                    Signing in...
                  </span>
                ) : "Sign In"}
              </button>

              {message && (() => {
                const isErrorMsg = message.toLowerCase().includes("suspended") || message.toLowerCase().includes("error") || message.toLowerCase().includes("not found") || message.toLowerCase().includes("unknown") || message.toLowerCase().includes("unable") || message.toLowerCase().includes("timed out") || message.toLowerCase().includes("failed to fetch")
                return (
                  <div className="message-container" style={{ marginTop: 20, padding: 12, background: isErrorMsg ? "rgba(239, 68, 68, 0.08)" : "rgba(34, 197, 94, 0.08)", border: `1.5px solid ${isErrorMsg ? "rgba(239, 68, 68, 0.3)" : "rgba(34, 197, 94, 0.3)"}`, borderRadius: 10, fontSize: 14, color: isErrorMsg ? "#dc2626" : "#16a34a", fontWeight: 500, textAlign: "center", lineHeight: 1.4 }}>
                    {message}
                  </div>
                )
              })()}
            </>
          ) : mode === "forgot-step1" ? (
            <>
              <div className="input-group" style={{ marginBottom: 16 }}>
                <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: "#171717", marginBottom: 8, letterSpacing: "0.3px", textTransform: "uppercase" }}>
                  Email Address
                </label>
                <ModernInput
                  type="email"
                  placeholder="you@company.com"
                  value={forgotEmail}
                  onChange={(e) => setForgotEmail(e.target.value)}
                  style={{ width: "100%", padding: "12px 16px", boxSizing: "border-box", fontSize: 16, border: "1.5px solid #e5e5e5", borderRadius: 10, background: "#f9f9f9", transition: "all 0.2s ease" }}
                  data-modern-input="migrated"
                />
              </div>

              <p style={{ margin: "0 0 20px", fontSize: 13, color: "#888", lineHeight: 1.5 }}>
                Enter your email to reset your password. If an account exists, you will be able to set a new password.
              </p>

              <button onClick={handleForgotStep1} disabled={forgotLoading} className="signin-button" style={{ width: "100%", padding: 14, background: "#0070f3", color: "white", border: "none", borderRadius: 10, fontSize: 16, fontWeight: 600, cursor: forgotLoading ? "not-allowed" : "pointer", opacity: forgotLoading ? 0.85 : 1, letterSpacing: "0.3px", position: "relative" }}>
                {forgotLoading ? (
                  <span style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}>
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" style={{ animation: "spin 1s linear infinite" }}>
                      <style>{`@keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }`}</style>
                      <circle cx="12" cy="12" r="10" stroke="white" strokeWidth="2" strokeDasharray="16" opacity="0.3" />
                      <path d="M12 2a10 10 0 0 1 10 10" stroke="white" strokeWidth="2" strokeLinecap="round" />
                    </svg>
                    Checking...
                  </span>
                ) : "Continue"}
              </button>

              <div style={{ textAlign: "center", marginTop: 20 }}>
                <button type="button" onClick={switchToLogin} style={{ background: "none", border: "none", color: "#0070f3", cursor: "pointer", fontSize: 13, fontWeight: 500, padding: 0 }}>
                  Back to login
                </button>
              </div>

              {forgotMessage && (
                <div className="message-container" style={{ marginTop: 20, padding: 12, background: "rgba(239, 68, 68, 0.08)", border: "1.5px solid rgba(239, 68, 68, 0.3)", borderRadius: 10, fontSize: 14, color: "#dc2626", fontWeight: 500, textAlign: "center", lineHeight: 1.4 }}>
                  {forgotMessage}
                </div>
              )}
            </>
          ) : (
            <>
              <div className="input-group" style={{ marginBottom: 16 }}>
                <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: "#171717", marginBottom: 8, letterSpacing: "0.3px", textTransform: "uppercase" }}>
                  New Password
                </label>
                <div className="password-wrapper">
                  <ModernInput
                    type={showNewPassword ? "text" : "password"}
                    placeholder="Min 6 characters"
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    style={{ width: "100%", padding: "12px 48px 12px 16px", boxSizing: "border-box", fontSize: 16, border: "1.5px solid #e5e5e5", borderRadius: 10, background: "#f9f9f9", transition: "all 0.2s ease" }}
                    data-modern-input="migrated"
                  />
                  <button type="button" className="password-toggle" onClick={() => setShowNewPassword((prev) => !prev)} aria-label={showNewPassword ? "Hide password" : "Show password"}>
                    <Icon icon={showNewPassword ? "mdi:eye-off" : "mdi:eye"} width={20} height={20} />
                  </button>
                </div>
              </div>

              <div className="input-group" style={{ marginBottom: 20 }}>
                <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: "#171717", marginBottom: 8, letterSpacing: "0.3px", textTransform: "uppercase" }}>
                  Confirm New Password
                </label>
                <div className="password-wrapper">
                  <ModernInput
                    type={showConfirmPassword ? "text" : "password"}
                    placeholder="Re-enter new password"
                    value={confirmNewPassword}
                    onChange={(e) => setConfirmNewPassword(e.target.value)}
                    style={{ width: "100%", padding: "12px 48px 12px 16px", boxSizing: "border-box", fontSize: 16, border: "1.5px solid #e5e5e5", borderRadius: 10, background: "#f9f9f9", transition: "all 0.2s ease" }}
                    data-modern-input="migrated"
                  />
                  <button type="button" className="password-toggle" onClick={() => setShowConfirmPassword((prev) => !prev)} aria-label={showConfirmPassword ? "Hide password" : "Show password"}>
                    <Icon icon={showConfirmPassword ? "mdi:eye-off" : "mdi:eye"} width={20} height={20} />
                  </button>
                </div>
              </div>

              <button onClick={handleForgotStep2} disabled={forgotLoading} className="signin-button" style={{ width: "100%", padding: 14, background: forgotLoading ? "#0070f3" : "#0070f3", color: "white", border: "none", borderRadius: 10, fontSize: 16, fontWeight: 600, cursor: forgotLoading ? "not-allowed" : "pointer", opacity: forgotLoading ? 0.85 : 1, letterSpacing: "0.3px", position: "relative" }}>
                {forgotLoading ? (
                  <span style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}>
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" style={{ animation: "spin 1s linear infinite" }}>
                      <style>{`@keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }`}</style>
                      <circle cx="12" cy="12" r="10" stroke="white" strokeWidth="2" strokeDasharray="16" opacity="0.3" />
                      <path d="M12 2a10 10 0 0 1 10 10" stroke="white" strokeWidth="2" strokeLinecap="round" />
                    </svg>
                    Resetting...
                  </span>
                ) : "Reset Password"}
              </button>

              <div style={{ textAlign: "center", marginTop: 20 }}>
                <button type="button" onClick={switchToLogin} style={{ background: "none", border: "none", color: "#0070f3", cursor: "pointer", fontSize: 13, fontWeight: 500, padding: 0 }}>
                  Back to login
                </button>
              </div>

              {forgotMessage && (() => {
                const isSuccess = forgotMessage.includes("successfully")
                return (
                  <div className="message-container" style={{ marginTop: 20, padding: 12, background: isSuccess ? "rgba(34, 197, 94, 0.08)" : "rgba(239, 68, 68, 0.08)", border: `1.5px solid ${isSuccess ? "rgba(34, 197, 94, 0.3)" : "rgba(239, 68, 68, 0.3)"}`, borderRadius: 10, fontSize: 14, color: isSuccess ? "#16a34a" : "#dc2626", fontWeight: 500, textAlign: "center", lineHeight: 1.4 }}>
                    {forgotMessage}
                  </div>
                )
              })()}
            </>
          )}
        </div>

        {/* Footer */}
        <div style={{
          marginTop: 32,
          paddingTop: 24,
          borderTop: "1px solid #e5e5e5",
          textAlign: "center",
          fontSize: 13,
          color: "#999",
          lineHeight: 1.6,
        }}>
          <p style={{ margin: 0 }}>For technical support, contact the admin team</p>
          <p style={{ margin: "4px 0 0 0", fontSize: 12 }}>┬⌐ 2026 Kpaksbuddy Nigeria Limited</p>
          <p style={{ margin: "4px 0 0 0", fontSize: 12, color: "#0070f3" }}>Developed by: Alderton Burke & Partners</p>
        </div>
      </div>
    </div>
  );
}

"use client"

import { useEffect, useRef, useState } from "react"
import ModernInput from "@/components/ModernInput"
import { supabase } from "@/lib/supabase"
import { getCachedBrokers, cacheBrokers } from '@/lib/offline/tripsDb'

type Broker = { broker_id: string; broker_name: string; phone_number?: string | null }
type Props = { onSelect: (broker: Broker) => void }

export default function BrokerDropdown({ onSelect }: Props) {
  const containerRef = useRef<HTMLDivElement>(null)
  const [brokers, setBrokers] = useState<Broker[]>([])
  const [search, setSearch] = useState("")
  const [selected, setSelected] = useState<Broker | null>(null)
  const [open, setOpen] = useState(false)
  const [isOnline, setIsOnline] = useState(true)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    setIsOnline(navigator.onLine)
    window.addEventListener('online', () => setIsOnline(true))
    window.addEventListener('offline', () => setIsOnline(false))
    return () => {
      window.removeEventListener('online', () => setIsOnline(true))
      window.removeEventListener('offline', () => setIsOnline(false))
    }
  }, [])

  useEffect(() => {
    async function loadBrokers() {
      setLoading(true)
      try {
        if (isOnline) {
          // Try online fetch first
          const { data, error } = await supabase
            .from("Brokers")
            .select("broker_id, broker_name, phone_number")
            .order("broker_name", { ascending: true })
          
          if (!error && data) {
            setBrokers(data)
            // Cache for offline use
            await cacheBrokers(data)
          } else {
            // Fallback to cache if online fetch fails
            const cached = await getCachedBrokers()
            setBrokers(cached)
          }
        } else {
          // Offline: use cache
          const cached = await getCachedBrokers()
          setBrokers(cached)
        }
      } catch (error) {
        console.error('[BrokerDropdown] Error loading brokers:', error)
        // Try cache as last resort
        try {
          const cached = await getCachedBrokers()
          setBrokers(cached)
        } catch (cacheError) {
          console.error('[BrokerDropdown] Cache also failed:', cacheError)
          setBrokers([])
        }
      } finally {
        setLoading(false)
      }
    }

    loadBrokers()
  }, [isOnline])

  useEffect(() => {
    if (!open) return
    function handleClick(e: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setOpen(false)
      }
    }
    document.addEventListener("mousedown", handleClick)
    return () => document.removeEventListener("mousedown", handleClick)
  }, [open])

  const filtered = brokers.filter(b => b.broker_name.toLowerCase().includes(search.toLowerCase()))

  function handleSelect(broker: Broker) {
    setSelected(broker)
    setSearch(broker.broker_name)
    setOpen(false)
    onSelect(broker)
  }

  return (
    <div ref={containerRef} style={{ fontFamily: "Arial" }}>
      <div style={{ position: "relative", width: "100%" }}>
        <ModernInput
          type="text"
          placeholder={loading ? "Loading brokers..." : "Search broker..."}
          value={search}
          onChange={(e) => { setSearch(e.target.value); setSelected(null); setOpen(true) }}
          onFocus={() => setOpen(true)}
          disabled={loading}
          style={{
            width: "100%", padding: "12px 14px", fontSize: 15,
            boxSizing: "border-box", borderRadius: 8,
            border: "1.5px solid #ccc",
            background: "white", color: "#171717",
            outline: "none", minHeight: 48,
            opacity: loading ? 0.6 : 1,
          }}
        />

        {!isOnline && brokers.length > 0 && (
          <div style={{
            position: "absolute", top: -28, right: 0,
            fontSize: 11, color: "#f5a623", fontWeight: "bold",
            background: "#fff8e1", padding: "4px 8px", borderRadius: 4,
          }}>
            ≡ƒôí Using cached data
          </div>
        )}

        {open && filtered.length > 0 && (
          <ul style={{
            position: "absolute", top: "100%", left: 0, right: 0,
            background: "white", border: "1.5px solid #ccc", borderTop: "none",
            borderRadius: "0 0 8px 8px", listStyle: "none", margin: 0, padding: 0,
            maxHeight: 200, overflowY: "auto", zIndex: 10,
            boxShadow: "0 4px 12px rgba(0,0,0,0.1)"
          }}>
            {filtered.map(broker => (
              <li
                key={broker.broker_id}
                onClick={() => handleSelect(broker)}
                style={{ padding: "12px 14px", cursor: "pointer", borderBottom: "1px solid #eee", fontSize: 14, color: "#171717" }}
                onMouseEnter={e => (e.currentTarget.style.background = "#f0f7ff")}
                onMouseLeave={e => (e.currentTarget.style.background = "white")}
              >
                <div style={{ fontWeight: 500 }}>{broker.broker_name}</div>
                {broker.phone_number && <div style={{ fontSize: 12, color: "#94a3b8", marginTop: 2 }}>{broker.phone_number}</div>}
              </li>
            ))}
          </ul>
        )}

        {open && search && filtered.length === 0 && !loading && (
          <div style={{
            position: "absolute", top: "100%", left: 0, right: 0,
            background: "white", border: "1.5px solid #ccc", borderTop: "none",
            borderRadius: "0 0 8px 8px", padding: "12px 14px",
            color: "#999", fontSize: 14,
            boxShadow: "0 4px 12px rgba(0,0,0,0.1)"
          }}>
            No broker found
          </div>
        )}
      </div>

      {selected && (
        <div style={{ marginTop: 8, padding: "8px 12px", background: "#eff6ff", borderRadius: 6, fontSize: 13, color: "#0070f3", fontWeight: 500 }}>
          Selected: {selected.broker_name}
        </div>
      )}
    </div>
  )
}

"use client"

import { useEffect, useState, useMemo } from "react"
import { supabase } from "@/lib/supabase"
import { apiMutate } from "@/lib/api-mutation"
import { formatAmount, parseAmount } from "@/lib/formatAmount"
import { usePolling } from "@/lib/hooks/usePolling"

type Props = {
  clerkId: string
  officeName: string
  fullName: string
}

type CashDeposit = {
  deposit_id: string
  office_name: string
  amount: number
  note: string | null
  deposited_by: string
  created_at: string
}

type CashExpense = {
  expense_id: string
  clerk_id: string
  title: string
  total_amount: number
  status: "Pending" | "Authorised" | "Rejected"
  authorised_by: string | null
  rejection_reason: string | null
  created_at: string
  resolved_at: string | null
}

type ExpenseItemInput = {
  item_name: string
  amount: string
}

type ExpenseItem = {
  item_id: string
  item_name: string
  amount: number
}

export default function CashOfficerPanel({ clerkId, officeName, fullName }: Props) {
  const [officeBalance, setOfficeBalance] = useState<number>(0)
  const [expenses, setExpenses] = useState<CashExpense[]>([])
  const [deposits, setDeposits] = useState<CashDeposit[]>([])
  const [loading, setLoading] = useState(true)
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null)
  const [filter, setFilter] = useState("All")

  // New Expense Modal
  const [showLogModal, setShowLogModal] = useState(false)
  const [expenseTitle, setExpenseTitle] = useState("")
  const [items, setItems] = useState<ExpenseItemInput[]>([{ item_name: "", amount: "" }])
  const [submitLoading, setSubmitLoading] = useState(false)
  const [errorMsg, setErrorMsg] = useState("")
  const [successMsg, setSuccessMsg] = useState("")

  // Detail Modal
  const [viewingExpense, setViewingExpense] = useState<CashExpense | null>(null)
  const [viewingItems, setViewingItems] = useState<ExpenseItem[]>([])
  const [loadingItems, setLoadingItems] = useState(false)

  useEffect(() => {
    if (clerkId && officeName) {
      loadData()
    }
  }, [clerkId, officeName])

  usePolling(() => {
    fetchOfficeBalance()
    fetchExpenses()
    fetchDeposits()
  }, 30000, !!clerkId && !!officeName)

  async function loadData() {
    setLoading(true)
    await Promise.all([
      fetchOfficeBalance(),
      fetchExpenses(),
      fetchDeposits()
    ])
    setLoading(false)
  }

  async function fetchOfficeBalance() {
    const { data } = await supabase
      .from("cash_offices")
      .select("current_balance")
      .eq("office_name", officeName)
      .single()
    if (data) setOfficeBalance(data.current_balance)
    setLastUpdated(new Date())
  }

  const balanceMap = useMemo(() => {
    const map: Record<string, number> = {}
    const records: { id: string; amount: number; timestamp: string }[] = [
      ...expenses.filter(e => e.status === "Authorised").map(e => ({
        id: e.expense_id, amount: e.total_amount, timestamp: e.resolved_at ?? e.created_at
      })),
      ...deposits.map(d => ({
        id: d.deposit_id, amount: -d.amount, timestamp: d.created_at
      })),
    ]
    records.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
    let running = officeBalance
    for (const rec of records) {
      map[rec.id] = running
      running += rec.amount
    }
    return map
  }, [expenses, deposits, officeBalance])

  async function fetchExpenses() {
    const { data } = await supabase
      .from("cash_expenses")
      .select("*")
      .eq("office_name", officeName)
      .order("created_at", { ascending: false })
    if (data) setExpenses(data)
  }

  async function fetchDeposits() {
    const { data } = await supabase
      .from("cash_deposits")
      .select("*")
      .eq("office_name", officeName)
      .order("created_at", { ascending: false })
    if (data) setDeposits(data)
  }

  function handleAddItem() {
    setItems(prev => [...prev, { item_name: "", amount: "" }])
  }

  function handleRemoveItem(index: number) {
    if (items.length === 1) return
    setItems(prev => prev.filter((_, i) => i !== index))
  }

  function handleItemChange(index: number, field: keyof ExpenseItemInput, value: string) {
    const updated = [...items]
    if (field === "amount") {
      updated[index].amount = formatAmount(value)
    } else {
      updated[index].item_name = value
    }
    setItems(updated)
  }

  const runningTotal = items.reduce((sum, item) => {
    const val = parseAmount(item.amount)
    return sum + (isNaN(val) ? 0 : val)
  }, 0)

  async function handleSubmitExpense() {
    if (!expenseTitle.trim()) {
      setErrorMsg("Expense title is required")
      return
    }

    const validatedItems = items.map(item => {
      const amt = parseAmount(item.amount)
      return {
        item_name: item.item_name.trim(),
        amount: amt
      }
    })

    const hasEmptyItem = validatedItems.some(it => !it.item_name || isNaN(it.amount) || it.amount <= 0)
    if (hasEmptyItem) {
      setErrorMsg("All items must have a valid name and amount greater than 0")
      return
    }

    setSubmitLoading(true)
    setErrorMsg("")

    const { data: expData, error: expError } = await apiMutate("finance", {
      action: "insert", table: "cash_expenses",
      data: {
        office_name: officeName,
        clerk_id: clerkId,
        title: expenseTitle.trim(),
        total_amount: runningTotal,
        status: "Pending"
      },
    })

    if (expError) {
      setSubmitLoading(false)
      setErrorMsg("Failed to create expense: " + expError)
      return
    }

    const expenseData = Array.isArray(expData) ? expData[0] : expData as { expense_id: string }
    const expenseId = expenseData.expense_id
    const itemsToInsert = validatedItems.map(it => ({
      expense_id: expenseId,
      item_name: it.item_name,
      amount: it.amount
    }))

    let itemsError: string | null = null
    for (const item of itemsToInsert) {
      const { error } = await apiMutate("finance", {
        action: "insert", table: "cash_expense_items", data: item,
      })
      if (error) { itemsError = error; break }
    }

    if (itemsError) {
      await apiMutate("finance", { action: "delete", table: "cash_expenses", filters: { expense_id: expenseId } })
      setSubmitLoading(false)
      setErrorMsg("Failed to save individual items: " + itemsError)
      return
    }

    setSubmitLoading(false)

    setSuccessMsg("Expense logged successfully!")
    setShowLogModal(false)
    setExpenseTitle("")
    setItems([{ item_name: "", amount: "" }])

    await Promise.all([
      fetchOfficeBalance(),
      fetchExpenses(),
      fetchDeposits()
    ])

    setTimeout(() => setSuccessMsg(""), 3000)
  }

  async function handleViewDetails(exp: CashExpense) {
    setViewingExpense(exp)
    setLoadingItems(true)
    const { data } = await supabase
      .from("cash_expense_items")
      .select("*")
      .eq("expense_id", exp.expense_id)
    setViewingItems(data || [])
    setLoadingItems(false)
  }

  async function handleCancelExpense(expenseId: string) {
    if (!confirm("Are you sure you want to cancel and delete this pending expense?")) return

    setLoading(true)
    setErrorMsg("")
    const { error: itemsError } = await apiMutate("finance", { action: "delete", table: "cash_expense_items", filters: { expense_id: expenseId } })

    if (itemsError) {
      setErrorMsg("Failed to delete expense items: " + itemsError)
      setLoading(false)
      return
    }

    const { error: expError } = await apiMutate("finance", { action: "delete", table: "cash_expenses", filters: { expense_id: expenseId } })

    if (expError) {
      setErrorMsg("Failed to delete expense: " + expError)
    }

    await Promise.all([
      fetchOfficeBalance(),
      fetchExpenses(),
      fetchDeposits()
    ])
    setLoading(false)
  }

  return (
    <div>
      {successMsg && (
        <div style={{ padding: "12px 16px", background: "#e6fffa", border: "1px solid #319795", color: "#234e52", borderRadius: 8, marginBottom: 24, fontWeight: "bold" }}>
          {successMsg}
        </div>
      )}

      {/* Office Status Panel */}
      <div style={{
        background: "white",
        borderRadius: 12,
        padding: 24,
        border: "1px solid #eee",
        boxShadow: "0 2px 8px rgba(0,0,0,0.04)",
        marginBottom: 24,
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        flexWrap: "wrap",
        gap: 20
      }}>
        <div>
          <span style={{ fontSize: 12, color: "#888", textTransform: "uppercase", fontWeight: "bold", letterSpacing: 0.5 }}>
            {officeName} Office Cash Balance
          </span>
          <h1 style={{ margin: "4px 0 4px", fontSize: 32, color: "#111", display: "flex", alignItems: "baseline", gap: 4 }}>
            <span style={{ fontSize: 20, color: "#555" }}>Γéª</span>
            {officeBalance.toLocaleString()}
          </h1>
          {lastUpdated && (
            <span style={{ fontSize: 11, color: "#888" }}>
              Last updated: {lastUpdated.toLocaleTimeString()}
            </span>
          )}
        </div>

        <button
          onClick={() => { setShowLogModal(true); setErrorMsg("") }}
          style={{
            padding: "12px 24px",
            background: "#0070f3",
            color: "white",
            border: "none",
            borderRadius: 8,
            cursor: "pointer",
            fontWeight: "bold",
            fontSize: 14,
            boxShadow: "0 2px 6px rgba(0,112,243,0.3)"
          }}
          title={`Log an office expense under ${officeName} office.`}
        >
          + Log New Expense
        </button>
      </div>

      {errorMsg && (
        <div style={{ padding: "12px 16px", background: "#fff5f5", border: "1px solid #fed7d7", color: "#c53030", borderRadius: 8, marginBottom: 24, fontWeight: "bold" }}>
          {errorMsg}
        </div>
      )}

      {/* Expense History Table */}
      <div style={{ background: "white", borderRadius: 12, border: "1px solid #eee", padding: 24 }}>
        <h3 style={{ margin: "0 0 20px" }}>My Logged Expenses</h3>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 20 }}>
          {["All", "Pending", "Authorised", "Rejected"].map(f => {
            let activeColor = "white"
            let activeBg = "#171717"
            if (f === "Pending") { activeColor = "#0070f3"; activeBg = "rgba(0, 112, 243, 0.1)" }
            if (f === "Authorised") { activeColor = "#16a34a"; activeBg = "rgba(22, 163, 74, 0.1)" }
            if (f === "Rejected") { activeColor = "#ef4444"; activeBg = "rgba(239, 68, 68, 0.1)" }
            return (
              <button key={f} onClick={() => setFilter(f)} style={{
                padding: "6px 14px", borderRadius: 20, fontSize: 12, cursor: "pointer",
                border: `1.5px solid ${filter === f ? activeColor : "#e2e8f0"}`,
                background: filter === f ? activeBg : "white",
                color: filter === f ? activeColor : "#64748b",
                fontWeight: filter === f ? 600 : 500,
                transition: "all 0.2s",
                minHeight: 40,
              }} onMouseEnter={e => { if (filter !== f) { e.currentTarget.style.borderColor = "#cbd5e1"; e.currentTarget.style.background = "#f8fafc" } }} onMouseLeave={e => { if (filter !== f) { e.currentTarget.style.borderColor = "#e2e8f0"; e.currentTarget.style.background = "white" } }}>
                {f}
              </button>
            )
          })}
        </div>

        {loading ? (
          <p style={{ color: "#888", textAlign: "center", padding: "40px 0" }}>Loading expenses...</p>
        ) : expenses.filter(e => e.clerk_id === clerkId && (filter === "All" || e.status === filter)).length === 0 ? (
          <p style={{ color: "#888", textAlign: "center", padding: "40px 0" }}>No {filter === "All" ? "" : filter.toLowerCase()} expenses found.</p>
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))", gap: "16px" }}>
            {expenses.filter(e => e.clerk_id === clerkId && (filter === "All" || e.status === filter)).map((exp) => {
              let statusBg = "#eee"
              let statusColor = "#666"
              if (exp.status === "Pending") { statusBg = "#ebf8ff"; statusColor = "#2b6cb0" }
              else if (exp.status === "Authorised") { statusBg = "#f0fff4"; statusColor = "#2f855a" }
              else if (exp.status === "Rejected") { statusBg = "#fff5f5"; statusColor = "#c53030" }

              return (
                <div key={exp.expense_id} style={{ border: "1px solid #eee", borderRadius: 12, padding: 16, background: "white", display: "flex", flexDirection: "column", gap: 12, boxShadow: "0 2px 8px rgba(0,0,0,0.04)" }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <span style={{ fontSize: 13, color: "#888", fontWeight: "500" }}>{new Date(exp.created_at).toLocaleDateString()}</span>
                    <span style={{ padding: "4px 10px", borderRadius: 12, fontSize: 11, background: statusBg, color: statusColor, fontWeight: "bold", letterSpacing: 0.3 }}>
                      {exp.status}
                    </span>
                  </div>
                  <div>
                    <h4 style={{ margin: "0 0 6px 0", fontSize: 16, color: "#111", lineHeight: 1.3 }}>{exp.title}</h4>
                    <div style={{ fontSize: 20, fontWeight: "bold", color: "#333", display: "flex", alignItems: "baseline", gap: 2 }}>
                      <span style={{ fontSize: 14, color: "#666" }}>Γéª</span>
                      {exp.total_amount.toLocaleString()}
                    </div>
                    {exp.status === "Authorised" && balanceMap[exp.expense_id] !== undefined && (
                      <span style={{ marginTop: 4, fontSize: 11, fontWeight: 600, color: "#16a34a", background: "#f0fdf4", padding: "2px 8px", borderRadius: 4, display: "inline-block" }}>
                        Balance after: Γéª{balanceMap[exp.expense_id].toLocaleString()}
                      </span>
                    )}
                  </div>

                  {exp.status === "Rejected" && exp.rejection_reason && (
                    <div style={{ background: "#fff5f5", padding: "10px", borderRadius: "8px", color: "#c53030", fontSize: 12, border: "1px solid #fed7d7" }}>
                      <strong style={{ display: "block", marginBottom: 2 }}>Reason for rejection:</strong>
                      {exp.rejection_reason}
                    </div>
                  )}

                  <div style={{ display: "flex", gap: 10, marginTop: "auto", paddingTop: 16, borderTop: "1px solid #f0f0f0" }}>
                    <button
                      onClick={() => handleViewDetails(exp)}
                      style={{ flex: 1, padding: "10px", cursor: "pointer", borderRadius: 8, border: "1px solid #0070f3", color: "#0070f3", background: "rgba(0,112,243,0.05)", fontSize: 13, fontWeight: "bold", transition: "all 0.2s ease" }}
                    >
                      Details
                    </button>
                    {exp.status === "Pending" && (
                      <button
                        onClick={() => handleCancelExpense(exp.expense_id)}
                        style={{ flex: 1, padding: "10px", cursor: "pointer", borderRadius: 8, border: "1px solid #ff4444", color: "#ff4444", background: "rgba(255,68,68,0.05)", fontSize: 13, fontWeight: "bold", transition: "all 0.2s ease" }}
                      >
                        Cancel
                      </button>
                    )}
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </div>

      {/* MODALS */}
      {/* 1. Log Expense Modal */}
      {showLogModal && (
        <div style={modalOverlay}>
          <div style={modalContent}>
            <h3 style={{ margin: "0 0 16px 0" }}>Log New Expense</h3>

            <div style={{ marginBottom: 16 }}>
              <label style={label}>Expense Title *</label>
              <input
                type="text"
                placeholder="e.g. Generator Maintenance"
                value={expenseTitle}
                onChange={(e) => { setExpenseTitle(e.target.value); setErrorMsg("") }}
                style={inputStyle}
                autoFocus
              />
            </div>

            <div style={{ marginBottom: 16 }}>
              <label style={label}>Line Items *</label>
              <div style={{ display: "flex", flexDirection: "column", gap: 10, maxHeight: 220, overflowY: "auto", paddingRight: 4, marginBottom: 10 }}>
                {items.map((item, idx) => (
                  <div key={idx} style={{ display: "flex", gap: 8, alignItems: "center" }}>
                    <input
                      type="text"
                      placeholder="Item name"
                      value={item.item_name}
                      onChange={(e) => handleItemChange(idx, "item_name", e.target.value)}
                      style={{ ...inputStyle, flex: 2 }}
                    />
                    <input
                      type="text"
                      placeholder="Price"
                      value={item.amount}
                      onChange={(e) => handleItemChange(idx, "amount", e.target.value)}
                      style={{ ...inputStyle, flex: 1, textAlign: "right", fontWeight: "bold" }}
                    />
                    <button
                      onClick={() => handleRemoveItem(idx)}
                      disabled={items.length === 1}
                      style={{
                        padding: "8px 12px", background: "#ff4444", color: "white",
                        border: "none", borderRadius: 4, cursor: items.length === 1 ? "not-allowed" : "pointer",
                        opacity: items.length === 1 ? 0.5 : 1
                      }}
                    >
                      Γ£ò
                    </button>
                  </div>
                ))}
              </div>

              <button
                onClick={handleAddItem}
                style={{
                  background: "none", border: "1px dashed #0070f3", color: "#0070f3",
                  padding: "6px 12px", borderRadius: 4, cursor: "pointer", fontSize: 13, fontWeight: "bold"
                }}
              >
                + Add Another Item
              </button>
            </div>

            {/* Running Total Box */}
            <div style={{
              background: "#f7fafc", border: "1px solid #edf2f7",
              padding: 12, borderRadius: 6, display: "flex", justifyContent: "space-between",
              alignItems: "center", marginBottom: 20
            }}>
              <span style={{ fontWeight: "bold", fontSize: 13, color: "#4a5568" }}>Total Amount:</span>
              <span style={{ fontWeight: "bold", fontSize: 18, color: "#2b6cb0" }}>
                Γéª{runningTotal.toLocaleString()}
              </span>
            </div>

            {errorMsg && <p style={errorStyle}>{errorMsg}</p>}

            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={() => setShowLogModal(false)} 

              style={{ ...cancelBtn, flex: 1, padding: "10px", cursor: "pointer", borderRadius: 8, border: "1px solid #ff4444", color: "#ff4444", background: "rgba(255,68,68,0.05)", fontSize: 13, fontWeight: "bold", transition: "all 0.2s ease" }}> Cancel
              </button>

              <button
                onClick={handleSubmitExpense}
                disabled={submitLoading}
                style={{ ...primaryBtn, flex: 1, padding: "10px", cursor: "pointer", borderRadius: 8, border: "1px solid #0070f3", color: "white", background: "#0070f3", fontSize: 13, fontWeight: "bold", transition: "all 0.2s ease" }}
              >

                {submitLoading ? "Submitting..." : "Submit Expense"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 2. Expense Details Modal */}
      {viewingExpense && (
        <div onClick={() => setViewingExpense(null)} style={modalOverlay}>
          <div onClick={(e) => e.stopPropagation()} style={modalContent}>
            <h3 style={{ margin: "0 0 4px 0" }}>{viewingExpense.title}</h3>
            <p style={{ margin: "0 0 16px", color: "#888", fontSize: 12 }}>
              Logged on {new Date(viewingExpense.created_at).toLocaleString()}
            </p>

            <div style={{ marginBottom: 16 }}>
              <h4 style={{ margin: "0 0 8px 0", fontSize: 13 }}>Items Breakdown</h4>
              {loadingItems ? (
                <p style={{ color: "#888", fontSize: 13 }}>Loading details...</p>
              ) : viewingItems.length === 0 ? (
                <p style={{ color: "#888", fontSize: 13 }}>No items found.</p>
              ) : (
                <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                  {viewingItems.map(item => (
                    <div key={item.item_id} style={{ display: "flex", justifyContent: "space-between", fontSize: 13, paddingBottom: 4, borderBottom: "1px dashed #eee" }}>
                      <span>{item.item_name}</span>
                      <span style={{ fontWeight: "bold" }}>Γéª{item.amount.toLocaleString()}</span>
                    </div>
                  ))}
                  <div style={{ display: "flex", justifyContent: "space-between", fontSize: 14, fontWeight: "bold", paddingTop: 8, borderTop: "1px solid #eee" }}>
                    <span>Total</span>
                    <span style={{ color: "#0070f3" }}>Γéª{viewingExpense.total_amount.toLocaleString()}</span>
                  </div>
                </div>
              )}
            </div>

            {viewingExpense.resolved_at && (
              <div style={{ background: "#f3f4f6", padding: 12, borderRadius: 6, fontSize: 12, color: "#555", marginBottom: 20 }}>
                {viewingExpense.status === "Authorised" ? (
                  <div>Γ£ô Authorised on {new Date(viewingExpense.resolved_at).toLocaleString()}</div>
                ) : (
                  <div>
                    Γ¥î Rejected on {new Date(viewingExpense.resolved_at).toLocaleString()}
                    <div style={{ marginTop: 4, paddingLeft: 12, borderLeft: "2px solid #ff4444", color: "#c53030" }}>
                      Reason: "{viewingExpense.rejection_reason}"
                    </div>
                  </div>
                )}
              </div>
            )}

            <button onClick={() => setViewingExpense(null)} style={{ ...cancelBtn, width: "100%" }}>
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

const label: React.CSSProperties = { display: "block", fontWeight: "bold", marginBottom: 6, fontSize: 13 }
const inputStyle: React.CSSProperties = { width: "100%", padding: 10, boxSizing: "border-box", borderRadius: 6, border: "1px solid #ddd", fontSize: 14 }
const errorStyle: React.CSSProperties = { color: "red", fontSize: 13, marginBottom: 12 }
const primaryBtn: React.CSSProperties = { padding: "10px 0", background: "#0070f3", color: "white", border: "none", borderRadius: 6, cursor: "pointer", fontWeight: "bold" }
const cancelBtn: React.CSSProperties = { padding: "10px 0", background: "white", border: "1px solid #ddd", borderRadius: 6, cursor: "pointer" }

const modalOverlay: React.CSSProperties = {
  position: "fixed", inset: 0, background: "rgba(0,0,0,0.5)",
  display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100
}

const modalContent: React.CSSProperties = {
  background: "white", borderRadius: 12, padding: 32,
  width: 460, maxWidth: "90vw", boxShadow: "0 8px 32px rgba(0,0,0,0.2)"
}

"use client"

import { useState, useEffect } from "react"
import { Icon } from "@iconify/react"
import { supabase } from "@/lib/supabase"
import { apiMutate } from "@/lib/api-mutation"
import { formatAmount, parseAmount } from "@/lib/formatAmount"
import { useBreakpoint } from "@/app/hooks/useBreakpoint"
import CustomerSelector from "./CustomerSelector"
import { BANKS } from "@/lib/constants"

type Customer = { customer_id: string; full_name: string; isNew?: boolean }

type Payment = {
  payment_id: string
  bank_name: string
  payment_date: string
  depositor_name: string | null
  customer_id: string | null
  customer_name: string | null
  amount: number
  status: "Pending" | "Posted"
  posted_by: string | null
  posted_at: string | null
  created_at: string
}

type ViewMode = "card" | "table"

const fontSize = {
  xs: 12, sm: 13, base: 14, md: 15, lg: 16, xl: 20, "2xl": 24, "3xl": 28
}

export default function CustomerPayments({ brokerId }: { brokerId: string }) {
  const bp = useBreakpoint()
  const isMobile = bp === "mobile"
  const [payments, setPayments] = useState<Payment[]>([])
  const [loading, setLoading] = useState(true)
  const [viewMode, setViewMode] = useState<ViewMode>("card")
  const [showModal, setShowModal] = useState(false)
  const [editingPayment, setEditingPayment] = useState<Payment | null>(null)

  const [bankName, setBankName] = useState("")
  const [paymentDate, setPaymentDate] = useState("")
  const [depositorName, setDepositorName] = useState("")
  const [amount, setAmount] = useState("")
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null)

  const [submitting, setSubmitting] = useState(false)
  const [message, setMessage] = useState("")
  const [profilesMap, setProfilesMap] = useState<Record<string, string>>({})

  useEffect(() => { fetchPayments(); fetchProfiles() }, [brokerId])

  async function fetchPayments() {
    setLoading(true)
    const { data, error } = await supabase
      .from("customer_payments")
      .select("*")
      .eq("broker_id", brokerId)
      .order("created_at", { ascending: false })
    if (!error && data) setPayments(data)
    setLoading(false)
  }

  async function fetchProfiles() {
    const { data: profiles } = await supabase.from("Profiles").select("user_id, full_name")
    const { data: brokers } = await supabase.from("Brokers").select("broker_id, broker_name")
    const pMap: Record<string, string> = {}
    profiles?.forEach(p => { pMap[p.user_id] = p.full_name })
    brokers?.forEach(b => { if (!pMap[b.broker_id]) pMap[b.broker_id] = b.broker_name })
    setProfilesMap(pMap)
  }

  function openModal(payment?: Payment) {
    if (payment) {
      setEditingPayment(payment)
      setBankName(payment.bank_name)
      setPaymentDate(payment.payment_date)
      setDepositorName(payment.depositor_name || "")
      setAmount(payment.amount.toString())
      setSelectedCustomer({ customer_id: payment.customer_id || "", full_name: payment.customer_name || "", isNew: !payment.customer_id })
    } else {
      setEditingPayment(null); setBankName(""); setPaymentDate(""); setDepositorName(""); setAmount(""); setSelectedCustomer(null)
    }
    setMessage(""); setShowModal(true)
  }

  async function handleSubmit() {
    if (!bankName) return setMessage("Please select a bank")
    if (!paymentDate) return setMessage("Payment date is required")
    if (!selectedCustomer) return setMessage("Please select or add a customer")
    if (!depositorName.trim()) return setMessage("Depositor's name is required")
    const parsedAmount = parseAmount(amount)
    if (isNaN(parsedAmount) || parsedAmount <= 0) return setMessage("Valid amount is required")

    setSubmitting(true); setMessage("")
    const payload = {
      broker_id: brokerId, bank_name: bankName, payment_date: paymentDate,
      depositor_name: depositorName.trim(), amount: parsedAmount,
      customer_id: selectedCustomer?.customer_id || null,
      customer_name: selectedCustomer.full_name,
    }

    if (editingPayment) {
      const { data, error } = await apiMutate<unknown[]>("finance", { action: "update", table: "customer_payments", data: payload, filters: { payment_id: editingPayment.payment_id, status: "Pending" } })
      if (error) setMessage("Failed to update: " + error)
      else if (data && data.length === 0) setMessage("This payment has already been posted and can no longer be edited.")
      else { setShowModal(false); fetchPayments() }
    } else {
      const { error } = await apiMutate("finance", { action: "insert", table: "customer_payments", data: payload })
      if (error) setMessage("Failed to log: " + error)
      else { setShowModal(false); fetchPayments() }
    }
    setSubmitting(false)
  }

  const statusStyle = (s: string) => {
    if (s === "Posted") return { bg: "#d1fae5", color: "#065f46", border: "#a7f3d0" }
    return { bg: "#f0f7ff", color: "#0c4a6e", border: "#bfdbfe" }
  }

  const thStyle: React.CSSProperties = {
    padding: "12px 16px", fontWeight: 600, fontSize: fontSize.xs,
    color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px",
  }

  return (
    <div>
      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20, flexWrap: "wrap", gap: 12 }}>
        <h2 style={{ margin: 0, fontSize: isMobile ? 20 : 22, color: "#171717", fontWeight: 700 }}>Customer Payments</h2>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          {payments.length > 0 && (
            <div style={{ display: "flex", background: "white", border: "1px solid #e2e8f0", borderRadius: 8, padding: 4, gap: 0 }}>
              <button onClick={() => setViewMode("card")} style={{
                padding: "8px 12px", background: viewMode === "card" ? "#0070f3" : "transparent",
                color: viewMode === "card" ? "white" : "#64748b", border: "none", borderRadius: 6,
                cursor: "pointer", fontSize: fontSize.xs, fontWeight: 600, transition: "all 0.2s ease",
                minWidth: 44, height: 40, display: "flex", alignItems: "center", justifyContent: "center",
              }} title="Card view">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M3 3h8v8H3V3zm10 0h8v8h-8V3zM3 13h8v8H3v-8zm10 0h8v8h-8v-8z"/></svg>
              </button>
              <button onClick={() => setViewMode("table")} style={{
                padding: "8px 12px", background: viewMode === "table" ? "#0070f3" : "transparent",
                color: viewMode === "table" ? "white" : "#64748b", border: "none", borderRadius: 6,
                cursor: "pointer", fontSize: fontSize.xs, fontWeight: 600, transition: "all 0.2s ease",
                minWidth: 44, height: 40, display: "flex", alignItems: "center", justifyContent: "center",
              }} title="Table view">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M3 4h18v2H3V4zm0 7h18v2H3v-2zm0 7h18v2H3v-2z"/></svg>
              </button>
            </div>
          )}
          <button onClick={() => openModal()} style={{
            padding: "10px 16px", background: "#0070f3", color: "white", border: "none", borderRadius: 8,
            cursor: "pointer", fontWeight: 600, fontSize: fontSize.md, display: "flex", alignItems: "center", gap: 6,
            boxShadow: "0 4px 12px rgba(0,112,243,0.2)", transition: "all 0.2s", minHeight: 40,
          }} onMouseEnter={e => { if (!isMobile) e.currentTarget.style.transform = "translateY(-1px)" }} onMouseLeave={e => { if (!isMobile) e.currentTarget.style.transform = "none" }}>
            <Icon icon="mdi:plus" width={18} /> Add Payment
          </button>
        </div>
      </div>

      {/* Content */}
      {loading ? (
        <div style={{ display: "flex", justifyContent: "center", padding: "64px 0" }}>
          <div style={{ width: 36, height: 36, border: "3px solid #e2e8f0", borderTopColor: "#0070f3", borderRadius: "50%", animation: "spin 0.8s linear infinite" }} />
        </div>
      ) : payments.length === 0 ? (
        <div style={{ textAlign: "center", padding: "60px 24px", background: "white", borderRadius: 12, border: "1px solid #e2e8f0", boxShadow: "0 1px 3px rgba(0,0,0,0.05)" }}>
          <div style={{ width: 56, height: 56, background: "#f1f5f9", borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 16px" }}>
            <Icon icon="mdi:cash-register" width={28} color="#94a3b8" />
          </div>
          <p style={{ margin: 0, color: "#94a3b8", fontSize: 15 }}>No payments logged yet</p>
        </div>
      ) : viewMode === "card" ? (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))", gap: 12 }}>
          {payments.map(p => {
            const ss = statusStyle(p.status)
            return (
              <div key={p.payment_id} style={{ background: "white", borderRadius: 12, border: "1px solid #e2e8f0", padding: 20, boxShadow: "0 1px 3px rgba(0,0,0,0.05)", transition: "all 0.2s ease" }}
                onMouseEnter={e => { e.currentTarget.style.boxShadow = "0 4px 12px rgba(0,0,0,0.08)"; e.currentTarget.style.borderColor = "#cbd5e1" }}
                onMouseLeave={e => { e.currentTarget.style.boxShadow = "0 1px 3px rgba(0,0,0,0.05)"; e.currentTarget.style.borderColor = "#e2e8f0" }}
              >
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 12 }}>
                  <div>
                    <h3 style={{ margin: "0 0 4px 0", fontSize: fontSize.lg, color: "#0f172a", fontWeight: 600 }}>{p.customer_name}</h3>
                    <p style={{ margin: 0, fontSize: fontSize.sm, color: "#64748b" }}>{p.bank_name} &bull; {new Date(p.payment_date).toLocaleDateString()}</p>
                  </div>
                  <span style={{ padding: "4px 10px", borderRadius: 6, fontSize: fontSize.xs, fontWeight: 500, background: ss.bg, color: ss.color, border: `1px solid ${ss.border}`, flexShrink: 0 }}>
                    {p.status}
                  </span>
                </div>

                <div style={{ fontSize: 24, fontWeight: "bold", color: "#0f172a", marginBottom: 16 }}>
                  Γéª{p.amount.toLocaleString()}
                </div>

                {p.depositor_name && (
                  <p style={{ margin: "0 0 16px 0", fontSize: fontSize.sm, color: "#475569" }}>
                    <Icon icon="mdi:account-cash" width={14} style={{ verticalAlign: "middle", marginRight: 4 }} />
                    Depositor: {p.depositor_name}
                  </p>
                )}

                {p.status === "Pending" && (
                  <button onClick={() => openModal(p)} style={{
                    width: "100%", padding: "10px", background: "#f0f7ff", color: "#0070f3",
                    border: "1px solid #bfdbfe", borderRadius: 8, cursor: "pointer", fontWeight: 600,
                    fontSize: fontSize.sm, display: "flex", alignItems: "center", justifyContent: "center", gap: 6, transition: "all 0.2s",
                  }} onMouseEnter={e => { e.currentTarget.style.background = "#e0efff"; e.currentTarget.style.borderColor = "#0070f3" }} onMouseLeave={e => { e.currentTarget.style.background = "#f0f7ff"; e.currentTarget.style.borderColor = "#bfdbfe" }}>
                    <Icon icon="mdi:pencil" width={16} /> Edit Payment
                  </button>
                )}
                {p.status === "Posted" && (
                  <div style={{ marginTop: 12, padding: "10px 12px", background: "#f0fdf4", borderRadius: 8, fontSize: fontSize.sm, color: "#166534" }}>
                    <p style={{ margin: 0, fontWeight: 600 }}>Posted by {profilesMap[p.posted_by || ""] || "Admin"}</p>
                    {p.posted_at && <p style={{ margin: "4px 0 0 0", color: "#16a34a", fontSize: fontSize.xs }}>{new Date(p.posted_at).toLocaleString()}</p>}
                  </div>
                )}
              </div>
            )
          })}
        </div>
      ) : (
        <div style={{ background: "white", borderRadius: 12, border: "1px solid #e2e8f0", boxShadow: "0 1px 3px rgba(0,0,0,0.05)", overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", textAlign: "left" }}>
            <thead>
              <tr style={{ background: "#f8fafc", borderBottom: "1px solid #e2e8f0" }}>
                <th style={thStyle}>Customer</th>
                <th style={thStyle}>Bank</th>
                <th style={{ ...thStyle, textAlign: "right" }}>Amount</th>
                <th style={thStyle}>Date</th>
                <th style={thStyle}>Status</th>
                <th style={{ ...thStyle, textAlign: "right" }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {payments.map((p, idx) => {
                const ss = statusStyle(p.status)
                return (
                  <tr key={p.payment_id} style={{ borderBottom: idx === payments.length - 1 ? "none" : "1px solid #e2e8f0", transition: "background 0.2s" }}
                    onMouseEnter={e => e.currentTarget.style.background = "#f8fafc"}
                    onMouseLeave={e => e.currentTarget.style.background = "transparent"}
                  >
                    <td style={{ padding: "12px 16px", color: "#0f172a", fontSize: fontSize.base, fontWeight: 500 }}>{p.customer_name}</td>
                    <td style={{ padding: "12px 16px", color: "#475569", fontSize: fontSize.sm }}>{p.bank_name}</td>
                    <td style={{ padding: "12px 16px", textAlign: "right", color: "#0f172a", fontSize: fontSize.base, fontWeight: 600 }}>Γéª{p.amount.toLocaleString()}</td>
                    <td style={{ padding: "12px 16px", color: "#64748b", fontSize: fontSize.sm }}>{new Date(p.payment_date).toLocaleDateString()}</td>
                    <td style={{ padding: "12px 16px" }}>
                      <span style={{ padding: "4px 10px", borderRadius: 6, fontSize: fontSize.xs, fontWeight: 500, background: ss.bg, color: ss.color, border: `1px solid ${ss.border}`, display: "inline-block" }}>
                        {p.status}
                      </span>
                      {p.status === "Posted" && p.posted_by && (
                        <div style={{ marginTop: 4, fontSize: fontSize.xs, color: "#16a34a" }}>
                          by {profilesMap[p.posted_by] || "Admin"}
                        </div>
                      )}
                    </td>
                    <td style={{ padding: "12px 16px", textAlign: "right" }}>
                      {p.status === "Pending" && (
                        <button onClick={() => openModal(p)} style={{ padding: "6px 10px", cursor: "pointer", borderRadius: 5, border: "1px solid #e2e8f0", color: "#0070f3", background: "#f0f7ff", fontSize: fontSize.sm, fontWeight: 500, transition: "all 0.2s", minHeight: 32, minWidth: 32, display: "inline-flex", alignItems: "center", justifyContent: "center" }}
                          onMouseEnter={e => { e.currentTarget.style.background = "#e0efff"; e.currentTarget.style.borderColor = "#0070f3" }}
                          onMouseLeave={e => { e.currentTarget.style.background = "#f0f7ff"; e.currentTarget.style.borderColor = "#e2e8f0" }}
                        >
                          <Icon icon="mdi:pencil" width={14} />
                        </button>
                      )}
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal */}
      {showModal && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(15,23,42,0.6)", backdropFilter: "blur(4px)", display: "flex", alignItems: isMobile ? "flex-end" : "center", justifyContent: "center", zIndex: 100, padding: isMobile ? 0 : 24 }}>
          <div style={{ background: "white", borderRadius: isMobile ? "20px 20px 0 0" : 12, padding: isMobile ? "28px 20px" : 32, width: "100%", maxWidth: 480, maxHeight: "90vh", overflowY: "auto", boxShadow: "0 25px 50px -12px rgba(0,0,0,0.25)" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
              <h3 style={{ margin: 0, fontSize: fontSize.xl, fontWeight: 700, color: "#0f172a" }}>{editingPayment ? "Edit Payment" : "Log Customer Payment"}</h3>
              <button onClick={() => setShowModal(false)} style={{ background: "none", border: "none", color: "#94a3b8", cursor: "pointer", padding: 0, width: 32, height: 32, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20, transition: "color 0.2s" }}
                onMouseEnter={e => e.currentTarget.style.color = "#64748b"} onMouseLeave={e => e.currentTarget.style.color = "#94a3b8"}
              >
                <Icon icon="mdi:close" width={20} />
              </button>
            </div>

            <div style={{ marginBottom: 16 }}>
              <label style={{ display: "block", fontWeight: 600, marginBottom: 6, fontSize: fontSize.sm, color: "#475569" }}>Bank *</label>
              <select value={bankName} onChange={e => { setBankName(e.target.value); setMessage("") }} style={{ width: "100%", padding: "12px 14px", borderRadius: 8, border: "1.5px solid #e2e8f0", fontSize: fontSize.base, background: "white", color: "#0f172a", minHeight: 48, boxSizing: "border-box" }}>
                <option value="">Select bank...</option>
                {BANKS.map(b => <option key={b} value={b}>{b}</option>)}
              </select>
            </div>

            <div style={{ marginBottom: 16 }}>
              <label style={{ display: "block", fontWeight: 600, marginBottom: 6, fontSize: fontSize.sm, color: "#475569" }}>Date of Payment *</label>
              <input type="date" value={paymentDate} onChange={e => { setPaymentDate(e.target.value); setMessage("") }} style={{ width: "100%", padding: "12px 14px", borderRadius: 8, border: "1.5px solid #e2e8f0", fontSize: fontSize.base, background: "white", color: "#0f172a", minHeight: 48, boxSizing: "border-box" }} />
            </div>

            <div style={{ marginBottom: 16 }}>
              <label style={{ display: "block", fontWeight: 600, marginBottom: 6, fontSize: fontSize.sm, color: "#475569" }}>Amount (Γéª) *</label>
              <input type="text" placeholder="e.g. 500,000" value={amount} onChange={e => { setAmount(formatAmount(e.target.value)); setMessage("") }} style={{ width: "100%", padding: "12px 14px", borderRadius: 8, border: "1.5px solid #e2e8f0", fontSize: fontSize.base, background: "white", color: "#0f172a", minHeight: 48, boxSizing: "border-box" }} />
