      )}

      <style>{`
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
      `}</style>
    </div>
  )
}

"use client"

import { useEffect, useState } from "react"
import { Icon } from "@iconify/react"
import ModernInput from "@/components/ModernInput"
import { supabase } from "@/lib/supabase"
import { apiMutate } from "@/lib/api-mutation"
import { getCachedCustomers, cacheCustomers } from '@/lib/offline/tripsDb'
import { generateCustomerId } from '@/lib/customerUtils'

type Customer = { customer_id: string; full_name: string; phone_number: string; is_new?: boolean; isNew?: boolean }
type Props = { onSelect: (customer: Customer) => void; allowUnsavedNew?: boolean; initialValue?: string }

export default function CustomerSelector({ onSelect, allowUnsavedNew, initialValue }: Props) {
  const [customers, setCustomers] = useState<Customer[]>([])
  const [search, setSearch] = useState(initialValue || "")
  const [selected, setSelected] = useState<Customer | null>(null)
  const [open, setOpen] = useState(false)
  const [creating, setCreating] = useState(false)
  const [newName, setNewName] = useState("")
  const [newPhone, setNewPhone] = useState("")
  const [message, setMessage] = useState("")
  const [isOnline, setIsOnline] = useState(true)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    setIsOnline(navigator.onLine)
    window.addEventListener('online', () => setIsOnline(true))
    window.addEventListener('offline', () => setIsOnline(false))
    return () => {
      window.removeEventListener('online', () => setIsOnline(true))
      window.removeEventListener('offline', () => setIsOnline(false))
    }
  }, [])

  useEffect(() => {
    async function loadCustomers() {
      setLoading(true)
      try {
        if (isOnline) {
          // Try online fetch first
          const { data, error } = await supabase
            .from("Customers")
            .select("customer_id, full_name, phone_number, is_new")
            .order("full_name", { ascending: true })
          
          if (!error && data) {
            setCustomers(data)
            // Cache for offline use
            await cacheCustomers(data)
          } else {
            // Fallback to cache if online fetch fails
            const cached = await getCachedCustomers()
            setCustomers(cached)
          }
        } else {
          // Offline: use cache
          const cached = await getCachedCustomers()
          setCustomers(cached)
        }
      } catch (error) {
        console.error('[CustomerSelector] Error loading customers:', error)
        // Try cache as last resort
        try {
          const cached = await getCachedCustomers()
          setCustomers(cached)
        } catch (cacheError) {
          console.error('[CustomerSelector] Cache also failed:', cacheError)
          setCustomers([])
        }
      } finally {
        setLoading(false)
      }
    }

    loadCustomers()
  }, [isOnline])

  const filtered = customers.filter(c => (c.full_name || "").toLowerCase().includes((search || "").toLowerCase()))

  function handleSelect(customer: Customer) {
    setSelected(customer)
    setSearch(customer.full_name)
    setOpen(false)
    setCreating(false)
    onSelect(customer)
  }

  async function handleCreate() {
    if (!newName.trim()) { setMessage("Customer name is required"); return }

    if (allowUnsavedNew) {
      const tempCustomer = { customer_id: "", full_name: newName, phone_number: newPhone || "", isNew: true }
      handleSelect(tempCustomer)
      setNewName("")
      setNewPhone("")
      setCreating(false)
      setMessage("")
      return
    }

    if (!isOnline) {
      setMessage("ΓÜá∩╕Å Internet required to create new customers")
      return
    }

    try {
      const customerId = await generateCustomerId()
      const { data, error } = await apiMutate<Customer[]>(
        "finance",
        {
          action: "insert",
          table: "Customers",
          data: { customer_id: customerId, full_name: newName, phone_number: newPhone || null, is_new: true }
        }
      )

      if (error) {
        setMessage("Failed to create customer")
        return
      }

      // Refresh cache after creating
      const { data: allCustomers, error: fetchError } = await supabase
        .from("Customers")
        .select("customer_id, full_name, phone_number, is_new")
        .order("full_name", { ascending: true })
      
      if (!fetchError && allCustomers) {
        setCustomers(allCustomers)
        await cacheCustomers(allCustomers)
      }

      const createdCustomer = data?.[0]
      if (!createdCustomer) {
        setMessage("Customer created but could not be loaded")
        return
      }
      handleSelect(createdCustomer)
      setNewName("")
      setNewPhone("")
      setCreating(false)
      setMessage("")
    } catch {
      setMessage("Network error, please try again")
    }
  }

  const fieldStyle: React.CSSProperties = {
    width: "100%", padding: "12px 14px", boxSizing: "border-box",
    borderRadius: 8, border: "1.5px solid #ccc",
    fontSize: 14, background: "white", color: "#171717",
    outline: "none", minHeight: 48,
  }

  return (
    <div style={{ fontFamily: "Arial" }}>
      <div style={{ position: "relative", width: "100%" }}>
        <ModernInput
          type="text"
          placeholder={loading ? "Loading customers..." : "Search customer..."}
          value={search}
          onChange={(e) => { setSearch(e.target.value); setSelected(null); setOpen(true); setCreating(false) }}
          onFocus={() => setOpen(true)}
          disabled={loading}
          style={{ ...fieldStyle, opacity: loading ? 0.6 : 1 }}
        />

        {!isOnline && customers.length > 0 && (
          <div style={{
            position: "absolute", top: -28, right: 0,
            fontSize: 11, color: "#f5a623", fontWeight: "bold",
            background: "#fff8e1", padding: "4px 8px", borderRadius: 4,
          }}>
            ≡ƒôí Using cached data
          </div>
        )}

        {open && search && (
          <ul style={{
            position: "absolute", top: "100%", left: 0, right: 0,
            background: "white", border: "1.5px solid #ccc", borderTop: "none",
            borderRadius: "0 0 8px 8px", listStyle: "none", margin: 0, padding: 0,
            maxHeight: 200, overflowY: "auto", zIndex: 10,
            boxShadow: "0 4px 12px rgba(0,0,0,0.1)"
          }}>
            {filtered.map(c => (
              <li
                key={c.customer_id}
                onClick={() => handleSelect(c)}
                style={{ padding: "12px 14px", cursor: "pointer", borderBottom: "1px solid #eee", fontSize: 14, color: "#171717", display: "flex", alignItems: "center", justifyContent: "space-between" }}
                onMouseEnter={e => (e.currentTarget.style.background = "#f0f7ff")}
                onMouseLeave={e => (e.currentTarget.style.background = "white")}
              >
                <span>{c.full_name}</span>
                {c.is_new && (
                  <span style={{ fontSize: 10, padding: "2px 6px", background: "#fef3c7", color: "#92400e", borderRadius: 4, fontWeight: "bold" }}>NEW</span>
                )}
              </li>
            ))}
            {isOnline && (
              <li
                onClick={() => { setCreating(true); setOpen(false) }}
                style={{ padding: "12px 14px", cursor: "pointer", color: "#0070f3", fontWeight: "bold", borderTop: "1px solid #eee", fontSize: 14 }}
                onMouseEnter={e => (e.currentTarget.style.background = "#f0f7ff")}
                onMouseLeave={e => (e.currentTarget.style.background = "white")}
              >
                + Create new customer
              </li>
            )}
          </ul>
        )}
      </div>

      {creating && (
        <div style={{ marginTop: 12, padding: 16, border: "1.5px solid #ddd", borderRadius: 8, background: "#fafafa" }}>
          <p style={{ fontWeight: "bold", marginBottom: 12, fontSize: 14, color: "#171717" }}>New Customer</p>
          <ModernInput
            type="text"
            placeholder="Full name *"
            value={newName}
            onChange={e => setNewName(e.target.value)}
            style={{ ...fieldStyle, marginBottom: 10 }}
          />
          <ModernInput
            type="text"
            placeholder="Phone number (optional)"
            value={newPhone}
            onChange={e => setNewPhone(e.target.value)}
            style={{ ...fieldStyle, marginBottom: 12 }}
          />
          <div style={{ display: "flex", gap: 8 }}>
            <button
              onClick={handleCreate}
              style={{ flex: 1, padding: "10px 0", background: "#0070f3", color: "white", border: "none", borderRadius: 6, cursor: "pointer", fontWeight: "bold", fontSize: 14, minHeight: 44 }}
            >
              Save Customer
            </button>
            <button
              onClick={() => setCreating(false)}
              style={{ flex: 1, padding: "10px 0", background: "white", border: "1.5px solid #ddd", borderRadius: 6, cursor: "pointer", fontSize: 14, minHeight: 44 }}
            >
              Cancel
            </button>
          </div>
          {message && <p style={{ color: "red", marginTop: 8, fontSize: 13 }}>{message}</p>}
        </div>
      )}

      {selected && !creating && (
        <div style={{ marginTop: 8, padding: "8px 12px", background: "#f0f7ff", borderRadius: 6, fontSize: 13, color: "#0070f3", fontWeight: 500, display: "flex", alignItems: "center", gap: 6 }}>
          <Icon icon="mdi:check-circle" width={16} />
          Selected: {selected.full_name}
          {selected.is_new && (
            <span style={{ fontSize: 10, padding: "2px 6px", background: "#fef3c7", color: "#92400e", borderRadius: 4, fontWeight: "bold" }}>NEW</span>
          )}
        </div>
      )}
    </div>
  )
}

"use client"

import React, { forwardRef, useMemo, useState } from "react"
import { Icon } from "@iconify/react"

type ModernInputStyle = React.CSSProperties

type OptionItem = { value: string; label: string }

type BaseProps = {
  as?: "input" | "select" | "textarea"
  options?: Array<OptionItem | string>
  containerStyle?: React.CSSProperties
  style?: React.CSSProperties
  className?: string
}

type InputProps = BaseProps &
  Omit<React.InputHTMLAttributes<HTMLInputElement>, "onChange"> & {
    as?: "input"
    onChange?: React.ChangeEventHandler<HTMLInputElement>
  }

type TextareaProps = BaseProps &
  React.TextareaHTMLAttributes<HTMLTextAreaElement> & {
    as: "textarea"
  }

type SelectProps = BaseProps &
  React.SelectHTMLAttributes<HTMLSelectElement> & {
    as: "select"
  }

type ModernInputProps = InputProps | TextareaProps | SelectProps

const DEFAULT_BORDER_COLOR = "#d1d5db"
const FOCUSED_BORDER_COLOR = "#f5a623"
const FILLED_BORDER_COLOR = "#0070f3"

type FieldState = "idle" | "focused" | "filled"

function deriveBorder(
  border: React.CSSProperties["border"],
  color: string
) {
  if (!border) return `1px solid ${color}`

  const parts = String(border).trim().split(" ")
  const width = parts[0] || "1px"
  const style = parts[1] || "solid"

  return `${width} ${style} ${color}`
}

const baseStyles: ModernInputStyle = {
  width: "100%",
  padding: "12px 14px",
  boxSizing: "border-box",
  borderRadius: 10,
  background: "white",
  color: "#171717",
  fontSize: 15,
  minHeight: 48,
  outline: "none",
  transition:
    "border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease",
}

const ModernInput = forwardRef<HTMLElement, ModernInputProps>(
  (
    {
      as = "input",
      style,
      containerStyle,
      className,
      options,
      value,
      defaultValue,
      onFocus,
      onBlur,
      children,
      ...rest
    },
    ref
  ) => {
    const [state, setState] = useState<FieldState>("idle")

    const isFilled = useMemo(() => {
      const v = value ?? defaultValue
      return (
        v !== undefined &&
        v !== null &&
        String(v).trim() !== ""
      )
    }, [value, defaultValue])

    const borderColor =
      state === "focused"
        ? FOCUSED_BORDER_COLOR
        : state === "filled"
        ? FILLED_BORDER_COLOR
        : DEFAULT_BORDER_COLOR

    const mergedStyle: React.CSSProperties = {
      ...baseStyles,
      ...style,
      border: deriveBorder(style?.border, borderColor),
      boxShadow:
        state === "focused"
          ? "0 0 0 3px rgba(245, 166, 35, 0.15)"
          : style?.boxShadow,
    }

    const handleFocus = (e: any) => {
      setState("focused")
      onFocus?.(e)
    }

    const handleBlur = (e: any) => {
      setState(isFilled ? "filled" : "idle")
      onBlur?.(e)
    }

    if (as === "textarea") {
      return (
        <textarea
          ref={ref as React.Ref<HTMLTextAreaElement>}
          style={mergedStyle}
          className={className}
          value={value as string | undefined}
          defaultValue={defaultValue as string | undefined}
          onFocus={handleFocus}
          onBlur={handleBlur}
          {...(rest as React.TextareaHTMLAttributes<HTMLTextAreaElement>)}
        />
      )
    }

    if (as === "select") {
      return (
        <div
          style={{
            position: "relative",
            width: "100%",
            ...containerStyle,
          }}
        >
          <select
            ref={ref as React.Ref<HTMLSelectElement>}
            style={{
              ...mergedStyle,

              // Hide browser default arrow
              appearance: "none",
              WebkitAppearance: "none",
              MozAppearance: "none",

              // Space for custom icon
              paddingRight: 42,

              cursor: "pointer",
            }}
            className={className}
            value={value as string | number | undefined}
            defaultValue={defaultValue as string | number | undefined}
            onFocus={handleFocus}
            onBlur={handleBlur}
            {...(rest as React.SelectHTMLAttributes<HTMLSelectElement>)}
          >
            {children}

            {options?.map((o, i) =>
              typeof o === "string" ? (
                <option key={i} value={o}>
                  {o}
                </option>
              ) : (
                <option key={o.value ?? i} value={o.value}>
                  {o.label}
                </option>
              )
            )}
          </select>

          <Icon
            icon="mdi:chevron-down"
            width={20}
            height={20}
            style={{
              position: "absolute",
              right: 14,
              top: "50%",
              transform: "translateY(-50%)",
              color: "#94a3b8",
              pointerEvents: "none",
            }}
          />
        </div>
      )
    }

    const inputProps = rest as React.InputHTMLAttributes<HTMLInputElement>
    const { type: inputType, onChange: origOnChange, ...inputRest } = inputProps

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (inputType === "number" && e.target.value.startsWith("-")) {
        return
      }
      origOnChange?.(e)
    }

    return (
      <input
        ref={ref as React.Ref<HTMLInputElement>}
        type={inputType}
        style={mergedStyle}
        className={className}
        value={value as string | number | undefined}
        defaultValue={defaultValue as string | number | undefined}
        onFocus={handleFocus}
        onBlur={handleBlur}
        onChange={handleChange}
        {...inputRest}
        onWheel={(e) => {
          if (inputType === "number") (e.target as HTMLElement).blur()
        }}
      />
    )
  }
)

ModernInput.displayName = "ModernInput"

export default ModernInput

'use client'

import { useState, useEffect, useRef } from 'react'
import { Icon } from '@iconify/react'
import { usePushNotifications } from '@/app/hooks/usePushNotifications'

const BANNER_DISMISSED_KEY = 'kbnl_notif_banner_dismissed'

export default function NotificationBanner() {
  const { permission, isSubscribed, isSupported, loading } = usePushNotifications()
  const [visible, setVisible] = useState(false)
  const bannerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (loading || !isSupported) return
    if (permission !== 'default' || isSubscribed) {
      setVisible(false)
      return
    }
    const dismissed = localStorage.getItem(BANNER_DISMISSED_KEY)
    if (!dismissed) setVisible(true)
  }, [permission, isSubscribed, isSupported, loading])

  useEffect(() => {
    if (!visible || !bannerRef.current) return
    const height = bannerRef.current.offsetHeight
    document.body.style.paddingTop = `${height}px`
    return () => {
      document.body.style.paddingTop = ''
    }
  }, [visible])

  if (!visible) return null

  function dismiss() {
    localStorage.setItem(BANNER_DISMISSED_KEY, 'true')
    setVisible(false)
  }

  return (
    <div
      ref={bannerRef}
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        zIndex: 9999,
        background: 'linear-gradient(135deg, #0070f3 0%, #0051c7 100%)',
        color: 'white',
        padding: '14px 20px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 12,
        boxShadow: '0 2px 12px rgba(0,0,0,0.15)',
      }}
    >
      <Icon icon="mdi:bell-ring-outline" width={22} style={{ flexShrink: 0 }} />
      <p style={{
        margin: 0,
        fontSize: 14,
        fontWeight: 500,
        textAlign: 'center',
        lineHeight: 1.4,
      }}>
        <strong>Stay updated!</strong> KbNL will ask for permission to send you notifications.
        Please accept to receive important updates about your work.
      </p>
      <button
        onClick={dismiss}
        aria-label="Dismiss notification banner"
        style={{
          background: 'rgba(255,255,255,0.2)',
          border: 'none',
          color: 'white',
          borderRadius: 8,
          padding: '8px 16px',
          fontSize: 13,
          fontWeight: 600,
          cursor: 'pointer',
          whiteSpace: 'nowrap',
          flexShrink: 0,
        }}
      >
        Got it
      </button>
    </div>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { Icon } from '@iconify/react'
import { usePushNotifications } from '@/app/hooks/usePushNotifications'

const PROMPT_DISMISSED_AT_KEY = 'kbnl_notif_prompt_dismissed_at'
const RE_PROMPT_INTERVAL_MS = 48 * 60 * 60 * 1000 // 48 hours

function msSinceDismissal(): number | null {
  const raw = localStorage.getItem(PROMPT_DISMISSED_AT_KEY)
  if (!raw) return null
  const at = Number(raw)
  if (!Number.isFinite(at)) return null
  return Date.now() - at
}

export default function NotificationPermissionPrompt() {
  const { permission, isSubscribed, subscribe, isSupported, loading } = usePushNotifications()
  const [visible, setVisible] = useState(false)
  const [subscribing, setSubscribing] = useState(false)
  const [showDeniedHint, setShowDeniedHint] = useState(false)
  const primaryBtnRef = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    if (loading || !isSupported) return
    if (permission === 'granted' || isSubscribed) {
      setVisible(false)
      setShowDeniedHint(false)
      return
    }

    if (permission === 'denied') {
      const elapsed = msSinceDismissal()
      if (elapsed === null) {
        setShowDeniedHint(true)
        return
      }
      if (elapsed >= RE_PROMPT_INTERVAL_MS) {
        setShowDeniedHint(true)
      }
      return
    }

    const elapsed = msSinceDismissal()
    if (elapsed !== null && elapsed < RE_PROMPT_INTERVAL_MS) return

    setVisible(true)
  }, [permission, isSubscribed, loading, isSupported])

  useEffect(() => {
    if (primaryBtnRef.current) primaryBtnRef.current.focus()
  }, [visible, showDeniedHint])

  if (!visible && !showDeniedHint) return null
  if (!isSupported) return null

  function dismiss() {
    localStorage.setItem(PROMPT_DISMISSED_AT_KEY, String(Date.now()))
    setVisible(false)
    setShowDeniedHint(false)
  }

  async function handleAllow() {
    setSubscribing(true)
    const result = await subscribe()
    setSubscribing(false)
    if (result) {
      setVisible(false)
      setShowDeniedHint(false)
    }
  }

  if (showDeniedHint) {
    return (
      <div
        role="dialog"
        aria-modal="false"
        aria-labelledby="notif-deny-title"
        style={{
          position: 'fixed',
          bottom: 20,
          left: '50%',
          transform: 'translateX(-50%)',
          zIndex: 9998,
          background: 'white',
          borderRadius: 16,
          boxShadow: '0 8px 32px rgba(0,0,0,0.15)',
          padding: '24px 28px',
          maxWidth: 420,
          width: 'calc(100% - 32px)',
          textAlign: 'center',
        }}
      >
        <div style={{
          width: 48,
          height: 48,
          borderRadius: '50%',
          background: '#fef2f2',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          margin: '0 auto 16px',
        }}>
          <Icon icon="mdi:bell-off-outline" width={24} color="#ef4444" />
        </div>
        <h3
          id="notif-deny-title"
          style={{
            margin: '0 0 8px',
            fontSize: 18,
            fontWeight: 700,
            color: '#1a1a1a',
          }}
        >
          Notifications Blocked
        </h3>
        <p style={{
          margin: '0 0 12px',
          fontSize: 14,
          color: '#64748b',
          lineHeight: 1.5,
        }}>
          Notifications are currently blocked in your browser. To enable them:
        </p>
        <ol style={{
          margin: '0 0 20px',
          padding: '0 0 0 20px',
          fontSize: 13,
          color: '#64748b',
          lineHeight: 1.8,
          textAlign: 'left',
        }}>
          <li>Click the lock icon <Icon icon="mdi:lock-outline" width={14} style={{ verticalAlign: -2 }} /> in the address bar</li>
          <li>Find <strong>Notifications</strong> and set to <strong>Allow</strong></li>
          <li>Refresh this page</li>
        </ol>
        <button
          ref={primaryBtnRef}
          onClick={dismiss}
          style={{
            background: '#f1f5f9',
            border: 'none',
            borderRadius: 10,
            padding: '10px 20px',
            fontSize: 14,
            fontWeight: 600,
            color: '#64748b',
            cursor: 'pointer',
          }}
        >
