        zIndex: 9998,
        background: 'white',
        borderRadius: 16,
        boxShadow: '0 8px 32px rgba(0,0,0,0.15)',
        padding: '24px 28px',
        maxWidth: 400,
        width: 'calc(100% - 32px)',
        textAlign: 'center',
