      <p style={{
        margin: '0 0 20px',
        fontSize: 14,
        color: '#64748b',
        lineHeight: 1.5,
      }}>
        Get real-time updates about trips, payments, and important alerts.
        You won&apos;t miss anything important.
      </p>
      <div style={{ display: 'flex', gap: 10, justifyContent: 'center' }}>
        <button
          onClick={dismiss}
          style={{
            background: '#f1f5f9',
            border: 'none',
