        <button
          ref={primaryBtnRef}
          onClick={handleAllow}
          disabled={subscribing}
          style={{
            background: '#0070f3',
            border: 'none',
            borderRadius: 10,
            padding: '10px 24px',
            fontSize: 14,
            fontWeight: 600,
