'use client';

import { useEffect, useRef, useState } from 'react';
import { usePWAInstall } from '@/app/hooks/usePWAInstall';

interface BeforeInstallPromptEvent extends Event {
  prompt: () => Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

export default function PWAInstallPrompt() {
  const [showPrompt, setShowPrompt] = useState(false);
  const deferredPrompt = useRef<BeforeInstallPromptEvent | null>(null);
  const { hasBeenPrompted, markAsPrompted } = usePWAInstall();
  const [isInstalled, setIsInstalled] = useState(false);
  const promptedRef = useRef(hasBeenPrompted);
  promptedRef.current = hasBeenPrompted;

  useEffect(() => {
    if (window.matchMedia('(display-mode: standalone)').matches) {
      setIsInstalled(true);
      return;
    }

    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      deferredPrompt.current = e as BeforeInstallPromptEvent;
      if (!promptedRef.current) {
        setShowPrompt(true);
        markAsPrompted();
      }
    };

    const handleAppInstalled = () => {
      setIsInstalled(true);
      setShowPrompt(false);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    window.addEventListener('appinstalled', handleAppInstalled);

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
      window.removeEventListener('appinstalled', handleAppInstalled);
    };
  }, [markAsPrompted]);

  const handleInstall = async () => {
    if (!deferredPrompt.current) return;

    try {
      await deferredPrompt.current.prompt();
      const { outcome } = await deferredPrompt.current.userChoice;

      if (outcome === 'accepted') {
        setIsInstalled(true);
        setShowPrompt(false);
      }

      deferredPrompt.current = null;
    } catch (error) {
      console.error('PWA installation error:', error);
    }
  };

  const handleDismiss = () => {
    setShowPrompt(false);
    deferredPrompt.current = null;
  };

  if (!showPrompt || isInstalled) {
    return null;
  }

  return (
    <div
      style={{
        position: 'fixed',
        bottom: 0,
        right: 0,
        zIndex: 9999,
        maxWidth: 380,
        animation: 'slideUp 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)',
      }}
    >
      <div
        style={{
          backgroundColor: '#fff',
          borderRadius: 16,
          boxShadow:
            '0 10px 40px rgba(0, 0, 0, 0.16), 0 0 0 1px rgba(0, 0, 0, 0.08)',
          padding: 20,
          fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
        }}
      >
        {/* Header */}
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            marginBottom: 12,
            gap: 12,
          }}
        >
          <div>
            <img
            src="/logo-192.png"
            alt="KbNL Logo"
            style={{ width: 48, height: 48 }}
            />
          </div>
          <div>
            <div
              style={{
                fontSize: 14,
                fontWeight: 600,
                color: '#171717',
                lineHeight: 1.2,
              }}
            >
              Get KbNL App on Your Phone
            </div>
            <div
              style={{
                fontSize: 12,
                color: '#666',
                lineHeight: 1.2,
              }}
            >
              Faster & better experience
            </div>
          </div>
        </div>

        {/* Description */}
        <p
          style={{
            fontSize: 13,
            color: '#555',
            lineHeight: 1.5,
            margin: '12px 0 16px 0',
            fontWeight: 400,
          }}
        >
          Install the app for quick access, full screen experience, and better performance. 
        </p>

        {/* Benefits */}
        <ul
          style={{
            fontSize: 12,
            color: '#666',
            lineHeight: 1.6,
            margin: '12px 0 16px 0',
            paddingLeft: 18,
            listStyle: 'disc',
          }}
        >
          <li>No need to type the URL</li>
          <li>Easily access your favourite features</li>
          <li>Fast app-like experience</li>
        </ul>

        {/* Buttons */}
        <div
          style={{
            display: 'flex',
            gap: 8,
            marginTop: 16,
          }}
        >
          <button
            onClick={handleInstall}
            style={{
              flex: 1,
              minHeight: 44,
              backgroundColor: '#0070f3',
              color: '#fff',
              border: 'none',
              borderRadius: 10,
              fontSize: 14,
              fontWeight: 600,
              cursor: 'pointer',
              transition: 'all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1)',
              boxShadow: '0 4px 12px rgba(0, 112, 243, 0.25)',
            }}
            onMouseEnter={(e) => {
              const target = e.currentTarget as HTMLButtonElement;
              target.style.boxShadow =
                '0 8px 20px rgba(0, 112, 243, 0.35)';
              target.style.transform = 'translateY(-2px)';
            }}
            onMouseLeave={(e) => {
              const target = e.currentTarget as HTMLButtonElement;
              target.style.boxShadow =
                '0 4px 12px rgba(0, 112, 243, 0.25)';
              target.style.transform = 'translateY(0)';
            }}
          >
            Install App
          </button>
          <button
            onClick={handleDismiss}
            style={{
              flex: 1,
              minHeight: 44,
              backgroundColor: '#f5f5f5',
              color: '#666',
              border: 'none',
              borderRadius: 10,
              fontSize: 14,
              fontWeight: 600,
              cursor: 'pointer',
              transition: 'all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1)',
            }}
            onMouseEnter={(e) => {
              const target = e.currentTarget as HTMLButtonElement;
              target.style.backgroundColor = '#e8e8e8';
            }}
            onMouseLeave={(e) => {
              const target = e.currentTarget as HTMLButtonElement;
              target.style.backgroundColor = '#f5f5f5';
            }}
          >
            Maybe Later
          </button>
        </div>
      </div>

      {/* Keyframe animation */}
      <style>{`
        @keyframes slideUp {
          from {
            opacity: 0;
            transform: translateY(20px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
      `}</style>
    </div>
  );
}

"use client"

import { useState, useRef } from "react"
import { Icon } from "@iconify/react"
import { supabase } from "@/lib/supabase"
import { STORAGE_BUCKET, MAX_FILE_SIZE, FONT_SIZE } from "@/lib/constants"

interface ProfilePictureUploadProps {
  isOpen: boolean
  onClose: () => void
  userId: string
  table: string
  idField: string
  currentUrl?: string
  onSuccess: (url: string) => void
}

export default function ProfilePictureUpload({
  isOpen,
  onClose,
  userId,
  table,
  idField,
  currentUrl,
  onSuccess,
}: ProfilePictureUploadProps) {
  const fileInputRef = useRef<HTMLInputElement>(null)
  const [selectedFile, setSelectedFile] = useState<File | null>(null)
  const [preview, setPreview] = useState<string | null>(null)
  const [uploading, setUploading] = useState(false)
  const [error, setError] = useState("")

  function handleClose() {
    setSelectedFile(null)
    setPreview(null)
    setError("")
    onClose()
  }

  function handleFileSelect(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]
    if (!file) return

    if (!file.type.startsWith("image/")) {
      setError("Please select an image file")
      return
    }

    if (file.size > MAX_FILE_SIZE) {
      setError("Image must be less than 1MB")
      return
    }

    setSelectedFile(file)
    setError("")

    const reader = new FileReader()
    reader.onload = (event) => {
      setPreview(event.target?.result as string)
    }
    reader.readAsDataURL(file)
  }

  async function handleUpload() {
    if (!selectedFile) {
      setError("Please select an image")
      return
    }

    setUploading(true)
    setError("")

    try {
      const { data: { session } } = await supabase.auth.getSession()
      if (!session) { setError("Session expired"); setUploading(false); return }

      const rawExt = selectedFile.name.split(".").pop()?.toLowerCase() ?? ""
      const fileExt = /^[a-z0-9]+$/.test(rawExt) ? rawExt : "jpg"
      const fileName = `${userId}-${Date.now()}.${fileExt}`
      const filePath = `${userId}/${fileName}`

      const { error: uploadError } = await supabase.storage
        .from(STORAGE_BUCKET)
        .upload(filePath, selectedFile, { upsert: false })

      if (uploadError) { setError("Upload failed"); setUploading(false); return }

      const { data: { publicUrl } } = supabase.storage
        .from(STORAGE_BUCKET)
        .getPublicUrl(filePath)

      const { error: updateError } = await supabase
        .from(table)
        .update({ profile_picture_url: publicUrl })
        .eq(idField, userId)

      if (updateError) {
        await supabase.storage.from(STORAGE_BUCKET).remove([filePath])
        setError("Failed to save profile")
        setUploading(false)
        return
      }

      if (currentUrl) {
        const oldPath = new URL(currentUrl).pathname.split("/").slice(-2).join("/")
        await supabase.storage.from(STORAGE_BUCKET).remove([oldPath])
      }

      onSuccess(publicUrl)
      setUploading(false)
      handleClose()
    } catch {
      setError("Something went wrong")
      setUploading(false)
    }
  }

  if (!isOpen) return null

  return (
    <div
      onClick={handleClose}
      style={{
        position: "fixed", inset: 0, background: "rgba(15, 23, 42, 0.6)",
        backdropFilter: "blur(4px)", display: "flex", alignItems: "flex-end",
        justifyContent: "center", zIndex: 100,
      }}
    >
      <div
        onClick={e => e.stopPropagation()}
        style={{
          background: "white", borderRadius: "20px 20px 0 0",
          padding: "28px 20px", width: "100%", maxWidth: 420,
          maxHeight: "90vh", overflowY: "auto",
          boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.25)",
        }}
      >
        <h3 style={{ margin: "0 0 6px 0", fontSize: FONT_SIZE.xl, fontWeight: 700, color: "#0f172a" }}>
          Update Profile Picture
        </h3>
        <p style={{ margin: "0 0 20px 0", fontSize: FONT_SIZE.sm, color: "#64748b" }}>
          PNG, JPG up to 1MB
        </p>

        {preview ? (
          <div style={{ marginBottom: 20 }}>
            <p style={{ margin: "0 0 8px 0", fontSize: FONT_SIZE.sm, fontWeight: 600, color: "#0f172a" }}>Preview</p>
            <img
              src={preview}
              alt="Preview"
              style={{
                width: "100%", height: 200, objectFit: "cover",
                borderRadius: 12, border: "2px solid #e2e8f0",
              }}
            />
          </div>
        ) : (
          <div
            onClick={() => fileInputRef.current?.click()}
            style={{
              border: "2px dashed #0070f3", borderRadius: 12,
              padding: "32px 16px", cursor: "pointer", background: "#f0f7ff",
              marginBottom: 20, display: "flex", flexDirection: "column",
              alignItems: "center", justifyContent: "center",
            }}
          >
            <Icon icon="mdi:cloud-upload" width={40} height={40} color="#0070f3" style={{ marginBottom: 8 }} />
            <p style={{ margin: "0 0 4px 0", fontSize: FONT_SIZE.base, fontWeight: 700, color: "#0070f3" }}>
              Click to upload
            </p>
            <p style={{ margin: 0, fontSize: FONT_SIZE.sm, color: "#64748b" }}>
              or drag and drop
            </p>
          </div>
        )}

        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          onChange={handleFileSelect}
          style={{ display: "none" }}
        />

        {error && (
          <div style={{ padding: 12, background: "#fef2f2", borderLeft: "4px solid #ef4444", borderRadius: 4, marginBottom: 16, color: "#b91c1c", fontSize: FONT_SIZE.sm, fontWeight: 600 }}>
            {error}
          </div>
        )}

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
          <button
            onClick={handleClose}
            style={{ padding: "12px 16px", background: "white", border: "1px solid #cbd5e1", color: "#475569", borderRadius: 8, cursor: "pointer", fontWeight: 700, fontSize: FONT_SIZE.md, minHeight: 44 }}
          >
            Cancel
          </button>
          <button
            onClick={handleUpload}
            disabled={uploading || !selectedFile}
            style={{
              padding: "12px 16px",
              background: selectedFile ? "#0070f3" : "#bfdbfe",
              color: "white", border: "none", borderRadius: 8,
              cursor: selectedFile && !uploading ? "pointer" : "not-allowed",
              fontWeight: 700, fontSize: FONT_SIZE.md, minHeight: 44,
              opacity: uploading ? 0.7 : 1,
            }}
          >
            {uploading ? "Uploading..." : "Upload"}
          </button>
        </div>
      </div>
    </div>
  )
}

"use client"

import React, { ReactNode } from "react"
import { Icon } from "@iconify/react"

type ProtectedSectionProps = {
  requiredRoles: string[]
  userRole?: string
  children: ReactNode
  fallback?: ReactNode
}

export default function ProtectedSection({
  requiredRoles,
  userRole,
  children,
  fallback,
}: ProtectedSectionProps) {
  const isAuthorized = userRole && requiredRoles.includes(userRole)

  if (!isAuthorized) {
    return fallback ? (
      <>{fallback}</>
    ) : (
      <div style={{
        padding: "40px 20px",
        textAlign: "center",
        background: "#fef2f2",
        borderRadius: 12,
        border: "1px solid #fecaca",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 12,
      }}>
        <Icon icon="mdi:lock" width={32} color="#ef4444" />
        <div>
          <p style={{ margin: 0, fontSize: 16, fontWeight: 700, color: "#0f172a" }}>
            Not Authorized
          </p>
          <p style={{ margin: "6px 0 0", fontSize: 14, color: "#64748b" }}>
            You don't have permission to access this section.
          </p>
        </div>
      </div>
    )
  }

  return <>{children}</>
}

"use client"

import { useEffect, useRef, useState } from "react"
import { Icon } from "@iconify/react"
import { supabase } from "@/lib/supabase"
import { apiMutate } from "@/lib/api-mutation"

type ReportItem = {
  id: string
  message: string
  created_at: string
  resolved: boolean
}

type ReportModalProps = {
  isOpen: boolean
  onClose: () => void
  userId: string
  userRole: string
}

const fontSize = { xs: 12, sm: 13, base: 14, md: 15 }

export default function ReportModal({ isOpen, onClose, userId, userRole }: ReportModalProps) {
  const [mode, setMode] = useState<"list" | "form" | "success">("list")
  const [reports, setReports] = useState<ReportItem[]>([])
  const [loading, setLoading] = useState(false)
  const [resolving, setResolving] = useState<string | null>(null)
  const [message, setMessage] = useState("")
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState("")
  const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    if (isOpen) {
      setMode("list")
      fetchReports()
    }
  }, [isOpen])

  useEffect(() => {
    return () => {
      if (closeTimerRef.current) clearTimeout(closeTimerRef.current)
    }
  }, [])

  async function fetchReports() {
    setLoading(true)
    const { data } = await supabase
      .from("reports")
      .select("id, message, created_at, resolved")
      .eq("user_id", userId)
      .order("created_at", { ascending: false })
    setReports((data || []) as ReportItem[])
    setLoading(false)
  }

  async function handleResolve(id: string) {
    setResolving(id)
    try {
      await apiMutate("admin", {
        action: "update", table: "reports",
        data: { resolved: true }, filters: { id },
      })
      setReports(prev => prev.map(r => r.id === id ? { ...r, resolved: true } : r))
    } catch {
      // silent
    } finally {
      setResolving(null)
    }
  }

  function handleClose() {
    if (closeTimerRef.current) {
      clearTimeout(closeTimerRef.current)
      closeTimerRef.current = null
    }
    setMessage(""); setError(""); setSubmitting(false)
    setMode("list"); setReports([])
    onClose()
  }

  async function handleSubmit() {
    if (!userId.trim() || !userRole.trim()) {
      setError("Unable to identify your account. Please refresh and try again.")
      return
    }
    if (!message.trim()) {
      setError("Please describe your issue")
      return
    }
    setSubmitting(true)
    setError("")

    try {
      const { error: insertError } = await apiMutate("reports", {
        action: "insert", table: "reports",
        data: { user_id: userId, role: userRole, message: message.trim(), resolved: false },
      })

      if (insertError) {
        setError("Failed to submit. Try again.")
        return
      }

      setMode("success")
      closeTimerRef.current = setTimeout(() => {
        setMode("list")
        setMessage("")
        fetchReports()
      }, 1500)
    } catch {
      setError("Failed to submit. Try again.")
    } finally {
      setSubmitting(false)
    }
  }

  if (!isOpen) return null

  const modalOverlay: React.CSSProperties = {
    position: "fixed", inset: 0, background: "rgba(15, 23, 42, 0.6)",
    backdropFilter: "blur(4px)",
    display: "flex", alignItems: "center", justifyContent: "center",
    zIndex: 100, padding: 24,
  }

  const modalBox: React.CSSProperties = {
    background: "white", borderRadius: 12, padding: 32,
    width: "100%", maxWidth: 480, maxHeight: "85vh", overflowY: "auto",
    boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.25)",
    fontFamily: "'Inter', sans-serif",
  }

  const labelStyle: React.CSSProperties = {
    fontWeight: 600, display: "block",
    marginBottom: 8, fontSize: 13, color: "#475569",
  }

  const unresolved = reports.filter(r => !r.resolved)
  const resolvedCount = reports.filter(r => r.resolved).length

  return (
    <div style={modalOverlay} onClick={handleClose}>
      <div style={modalBox} onClick={e => e.stopPropagation()}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
          <h2 style={{ margin: 0, fontSize: 18, fontWeight: 700, color: "#0f172a" }}>
            {mode === "list" ? "My Reports" : mode === "success" ? "" : "Submit Report"}
          </h2>
          <button
            onClick={handleClose}
            style={{ background: "none", border: "none", cursor: "pointer", padding: 4, color: "#94a3b8", transition: "color 0.2s" }}
            onMouseEnter={e => e.currentTarget.style.color = "#475569"}
            onMouseLeave={e => e.currentTarget.style.color = "#94a3b8"}
          >
            <Icon icon="mdi:close" width={20} />
          </button>
        </div>

        {mode === "success" ? (
          <div style={{ textAlign: "center", padding: "24px 0" }}>
            <div style={{ width: 56, height: 56, background: "#f0fff4", borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 12px", border: "2px solid #86efac" }}>
              <Icon icon="mdi:check-circle" width={28} color="#16a34a" />
            </div>
            <p style={{ fontSize: 16, fontWeight: 600, color: "#0f172a", margin: 0 }}>Report submitted successfully!</p>
          </div>
        ) : mode === "form" ? (
          <>
            <div style={{ marginBottom: 16 }}>
              <label style={labelStyle}>Describe your issue</label>
              <textarea
                placeholder="Explain the problem you're experiencing..."
                value={message}
                onChange={e => { setMessage(e.target.value); setError("") }}
                style={{
                  width: "100%", padding: "12px 16px",
                  boxSizing: "border-box", borderRadius: 8,
                  border: "1.5px solid #e2e8f0", fontSize: 14,
                  background: "#f9f9f9", color: "#0f172a",
                  minHeight: 120, resize: "vertical",
                  outline: "none", fontFamily: "'Inter', sans-serif",
                  transition: "border-color 0.2s ease",
                }}
