                ) : (
                  <><Icon icon="mdi:send" width={16} /> Submit</>
                )}
              </button>
            </div>
          </>
        ) : (
          <>
            <div style={{ padding: "14px 16px", background: "#eff6ff", border: "1px solid #bfdbfe", borderRadius: 10, marginBottom: 16, display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
