        />
      </div>

      {/* Company Name */}
      <h1 className="splash-text" style={{
        fontSize: 32,
        fontWeight: 700,
        color: "#171717",
        margin: 0,
        textAlign: "center",
        letterSpacing: "-0.5px",
        fontFamily: "'Segoe UI', 'Helvetica Neue', sans-serif",
      }}>
        Kpaksbuddy Nig Ltd
      </h1>

      {/* Tagline */}
      <p className="splash-subtitle" style={{
        fontSize: 14,
        color: "#888",
        marginTop: 8,
        marginBottom: 48,
        fontWeight: 500,
        letterSpacing: "0.5px",
        textTransform: "uppercase",
        textAlign: "center",
        maxWidth: 360,
      }}>
        Company Operations Management System
      </p>

      {/* Loader Dots */}
      <div className="splash-loader" style={{
        display: "flex",
        gap: 8,
        justifyContent: "center",
      }}>
        <div style={{
          width: 8,
          height: 8,
          borderRadius: "50%",
          background: "#0070f3",
          animation: "pulse 1.5s ease-in-out 0s infinite",
        }} />
        <div style={{
          width: 8,
          height: 8,
          borderRadius: "50%",
          background: "#0070f3",
          animation: "pulse 1.5s ease-in-out 0.2s infinite",
        }} />
        <div style={{
          width: 8,
          height: 8,
          borderRadius: "50%",
          background: "#0070f3",
          animation: "pulse 1.5s ease-in-out 0.4s infinite",
        }} />
      </div>
    </div>
  )
}

