                                padding: "6px 10px", cursor: canEdit ? "pointer" : "not-allowed", borderRadius: 5,
                                border: "1px solid #fee2e2", color: canEdit ? "#ef4444" : "#94a3b8", background: canEdit ? "#fef2f2" : "#e2e8f0",
                                fontSize: FONT_SIZE.sm, fontWeight: 500, transition: "all 0.2s",
                                minHeight: 32, minWidth: 32, display: "flex", alignItems: "center", justifyContent: "center",
                              }}
                              onMouseEnter={(e) => { if (!canEdit) return; e.currentTarget.style.background = "#fee2e2" }}
                              onMouseLeave={(e) => { if (!canEdit) return; e.currentTarget.style.background = "#fef2f2" }}
                            >
                              Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}

      {/* Modals */}
      {(showInviteModal || editingClerk || deletingId) && (
        <div
          style={{
            position: "fixed", inset: 0, background: "rgba(15, 23, 42, 0.6)",
            backdropFilter: "blur(4px)", display: "flex",
            alignItems: isMobile ? "flex-end" : "center", justifyContent: "center",
            zIndex: 100, padding: isMobile ? 0 : 24, animation: "fadeIn 0.2s ease-out",
          }}
        >
          <style>{`@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } } @keyframes slideUp { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }`}</style>
          <div
            style={{
              background: "white", borderRadius: isMobile ? "20px 20px 0 0" : 12,
              padding: isMobile ? "28px 20px" : 32, width: "100%", maxWidth: 420,
              maxHeight: "90vh", overflowY: "auto",
              boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.25)",
              animation: "slideUp 0.3s cubic-bezier(0.16, 1, 0.3, 1)",
            }}
          >
            {/* Invite Modal */}
            {showInviteModal && (
              <>
                {inviteResult ? (
                  <InviteSuccessCard
                    tempPassword={inviteResult.tempPassword}
                    email={inviteResult.email}
                    onClose={() => { closeModals(); setInviteResult(null) }}
                  />
                ) : (
                  <>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
                      <h3 style={{ margin: 0, color: "#0f172a", fontSize: FONT_SIZE.xl, fontWeight: 700 }}>
                        Add Cash Officer
                      </h3>
                      <button
                        onClick={closeModals}
                        style={{ background: "none", border: "none", color: "#94a3b8", cursor: "pointer", padding: 0, width: 32, height: 32, display: "flex", alignItems: "center", justifyContent: "center", transition: "color 0.2s" }}
                        onMouseEnter={(e) => (e.currentTarget.style.color = "#64748b")}
                        onMouseLeave={(e) => (e.currentTarget.style.color = "#94a3b8")}
                      >
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                          <line x1="18" y1="6" x2="6" y2="18" /><line x1="6" y1="6" x2="18" y2="18" />
                        </svg>
                      </button>
                    </div>

                    <div style={{ display: "flex", flexDirection: "column", gap: 14, marginBottom: 20 }}>
                      <div>
                        <label style={{ display: "block", marginBottom: 6, color: "#475569", fontSize: FONT_SIZE.sm, fontWeight: 500 }}>Full Name *</label>
                        <ModernInput type="text" placeholder="e.g. John Doe" value={fullName} onChange={(e: any) => { setFullName(e.target.value); setMessage("") }} onKeyDown={(e: any) => { if (e.key === "Enter") phoneRef.current?.focus() }} readOnly={!canEdit} style={inputStyle} autoFocus />
                      </div>
                      <div>
                        <label style={{ display: "block", marginBottom: 6, color: "#475569", fontSize: FONT_SIZE.sm, fontWeight: 500 }}>Phone Number</label>
                        <ModernInput ref={phoneRef} type="text" placeholder="e.g. 08012345678" value={phoneNumber} onChange={(e: any) => { setPhoneNumber(e.target.value); setMessage("") }} onKeyDown={(e: any) => { if (e.key === "Enter") emailRef.current?.focus() }} readOnly={!canEdit} style={inputStyle} />
                      </div>
                      <div>
                        <label style={{ display: "block", marginBottom: 6, color: "#475569", fontSize: FONT_SIZE.sm, fontWeight: 500 }}>Email Address *</label>
                        <ModernInput ref={emailRef} type="email" placeholder="e.g. clerk@example.com" value={email} onChange={(e: any) => { setEmail(e.target.value); setMessage("") }} readOnly={!canEdit} style={inputStyle} />
                      </div>
                      <div>
                        <label style={{ display: "block", marginBottom: 6, color: "#475569", fontSize: FONT_SIZE.sm, fontWeight: 500 }}>Assigned Office *</label>
                        <select value={officeName} onChange={(e) => { setOfficeName(e.target.value); setMessage("") }} disabled={!canEdit} style={inputStyle}>
                          <option value="">Select office</option>
                          {OFFICE_LOCATIONS.map(o => (<option key={o} value={o}>{o} Office</option>))}
                        </select>
                      </div>
                    </div>

                    {message && (
                      <div style={{ padding: 12, background: "#fef2f2", borderLeft: "4px solid #ef4444", borderRadius: 4, marginBottom: 20, color: "#b91c1c", fontSize: FONT_SIZE.sm }}>
                        {message}
                      </div>
                    )}

                    <button
                      onClick={handleInvite}
                      disabled={submitting || !canEdit}
                      style={{
                        width: "100%", padding: "12px 16px", background: submitting || !canEdit ? "#94a3b8" : "#0070f3", color: "white",
                        border: "none", borderRadius: 8, cursor: submitting || !canEdit ? "not-allowed" : "pointer",
                        fontWeight: 600, fontSize: FONT_SIZE.md, transition: "opacity 0.2s",
                        opacity: submitting ? 0.7 : 1, minHeight: 44,
                      }}
                    >
                      {submitting ? "Adding User..." : "Add User"}
                    </button>
                  </>
                )}
              </>
            )}

            {/* Edit Modal */}
            {editingClerk && (
              <>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
                  <h3 style={{ margin: 0, color: "#0f172a", fontSize: FONT_SIZE.xl, fontWeight: 700 }}>
                    Edit Clerk
                  </h3>
                  <button
                    onClick={closeModals}
                    style={{ background: "none", border: "none", color: "#94a3b8", cursor: "pointer", padding: 0, width: 32, height: 32, display: "flex", alignItems: "center", justifyContent: "center", transition: "color 0.2s" }}
                    onMouseEnter={(e) => (e.currentTarget.style.color = "#64748b")}
                    onMouseLeave={(e) => (e.currentTarget.style.color = "#94a3b8")}
                  >
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                      <line x1="18" y1="6" x2="6" y2="18" /><line x1="6" y1="6" x2="18" y2="18" />
                    </svg>
                  </button>
                </div>

                <div style={{ display: "flex", flexDirection: "column", gap: 14, marginBottom: 20 }}>
                  <div>
                    <label style={{ display: "block", marginBottom: 6, color: "#475569", fontSize: FONT_SIZE.sm, fontWeight: 500 }}>Full Name *</label>
                    <ModernInput type="text" value={editName} onChange={(e: any) => { setEditName(e.target.value); setMessage("") }} onKeyDown={(e: any) => { if (e.key === "Enter") editPhoneRef.current?.focus() }} readOnly={!canEdit} style={inputStyle} autoFocus />
                  </div>
                  <div>
                    <label style={{ display: "block", marginBottom: 6, color: "#475569", fontSize: FONT_SIZE.sm, fontWeight: 500 }}>Phone Number</label>
                    <ModernInput ref={editPhoneRef} type="text" value={editPhone} onChange={(e: any) => { setEditPhone(e.target.value); setMessage("") }} onKeyDown={(e: any) => { if (e.key === "Enter") handleUpdate() }} readOnly={!canEdit} style={inputStyle} />
                  </div>
                </div>

                <div style={{ padding: 12, background: "#f1f5f9", borderRadius: 6, marginBottom: 20, fontSize: FONT_SIZE.sm, color: "#475569" }}>
                  <strong>Office:</strong> {editingClerk.office_name}
                </div>

                {message && (
                  <div style={{ padding: 12, background: "#fef2f2", borderLeft: "4px solid #ef4444", borderRadius: 4, marginBottom: 20, color: "#b91c1c", fontSize: FONT_SIZE.sm }}>
                    {message}
                  </div>
                )}

                <button
                  onClick={handleUpdate}
                  disabled={submitting || !canEdit}
                  style={{
                    width: "100%", padding: "12px 16px", background: submitting || !canEdit ? "#94a3b8" : "#0070f3", color: "white",
                    border: "none", borderRadius: 8, cursor: submitting || !canEdit ? "not-allowed" : "pointer",
                    fontWeight: 600, fontSize: FONT_SIZE.md, transition: "opacity 0.2s",
                    opacity: submitting ? 0.7 : 1, minHeight: 44,
                  }}
                >
                  {submitting ? "Saving..." : "Save Changes"}
                </button>
              </>
            )}

            {/* Delete Modal */}
            {deletingId && (
              <>
                <div style={{ display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center" }}>
                  <div
                    style={{
                      width: 64, height: 64, background: "#fef2f2", color: "#ef4444",
                      borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 20,
                    }}
                  >
                    <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                      <path d="M3 6h18" />
                      <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
                      <line x1="10" y1="11" x2="10" y2="17" />
                      <line x1="14" y1="11" x2="14" y2="17" />
                    </svg>
                  </div>
                  <h3 style={{ margin: "0 0 12px", color: "#0f172a", fontSize: FONT_SIZE.xl, fontWeight: 700 }}>
                    Delete Cash Officer
                  </h3>
                  <p style={{ margin: "0 0 20px", color: "#64748b", fontSize: FONT_SIZE.base, lineHeight: 1.5 }}>
                    Are you sure you want to delete this cash officer? This action cannot be undone and will permanently remove their data.
                  </p>

                  {message && (
                    <div style={{ padding: 12, background: "#fef2f2", borderLeft: "4px solid #ef4444", borderRadius: 4, marginBottom: 20, color: "#b91c1c", fontSize: FONT_SIZE.sm, width: "100%", textAlign: "left" }}>
                      {message}
                    </div>
                  )}

                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, width: "100%" }}>
                    <button
                      onClick={closeModals}
                      style={{
                        padding: "12px 16px", background: "white", color: "#475569",
                        border: "1px solid #cbd5e1", borderRadius: 8, cursor: "pointer",
                        fontWeight: 600, fontSize: FONT_SIZE.md, minHeight: 44, transition: "all 0.2s",
                      }}
                      onMouseEnter={(e) => { e.currentTarget.style.background = "#f8fafc"; e.currentTarget.style.borderColor = "#0070f3"; e.currentTarget.style.color = "#0070f3" }}
                      onMouseLeave={(e) => { e.currentTarget.style.background = "white"; e.currentTarget.style.borderColor = "#cbd5e1"; e.currentTarget.style.color = "#475569" }}
                    >
                      Cancel
                    </button>
                    <button
                      onClick={() => handleDelete(deletingId)}
                      disabled={submitting || !canEdit}
                      style={{
                        padding: "12px 16px", background: submitting || !canEdit ? "#94a3b8" : "#ef4444", color: "white",
                        border: "none", borderRadius: 8, cursor: submitting || !canEdit ? "not-allowed" : "pointer",
                        fontWeight: 600, fontSize: FONT_SIZE.md, opacity: submitting ? 0.7 : 1,
                        minHeight: 44, transition: "all 0.2s",
                      }}
                      onMouseEnter={(e) => { if (!submitting && canEdit) e.currentTarget.style.background = "#dc2626" }}
                      onMouseLeave={(e) => { e.currentTarget.style.background = submitting || !canEdit ? "#94a3b8" : "#ef4444" }}
                    >
                      {submitting ? "Deleting..." : "Yes, Delete"}
                    </button>
                  </div>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import { FONT_SIZE } from "@/lib/constants"
import { usePolling } from "@/lib/hooks/usePolling"

import { useState, useEffect } from "react"
import { supabase } from "@/lib/supabase"
import { apiMutate } from "@/lib/api-mutation"
import { Icon } from "@iconify/react"
import { usePermissions } from "@/lib/PermissionContext"

type Complaint = {
  complaint_id: string
  driver_name: string
  plate_number: string
  kbnl_truck_no: string | null
  complaint_type: string
  notes: string
  reported_at: string
  resolved: boolean
  trip_id: string | null
}

type ViewMode = "card" | "table"

function useBreakpoint() {
  const [isDesktop, setIsDesktop] = useState(false)
  const [isMobile, setIsMobile] = useState(true)
  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth < 640)
      setIsDesktop(window.innerWidth >= 640)
    }
    handleResize()
    window.addEventListener("resize", handleResize)
    return () => window.removeEventListener("resize", handleResize)
  }, [])
  return { isMobile, isDesktop }
}



const filters = ["All", "Unresolved", "Resolved"]

export default function Complaints() {
  const { isMobile, isDesktop } = useBreakpoint()
  const { getAccess } = usePermissions()
  const canEdit = getAccess("complaints").canEdit
  const [complaints, setComplaints] = useState<Complaint[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState("Unresolved")
  const [viewMode, setViewMode] = useState<ViewMode>("card")
  const [resolving, setResolving] = useState<string | null>(null)
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null)

  useEffect(() => {
    fetchComplaints()
  }, [])

  usePolling(fetchComplaints, 120000)

  async function fetchComplaints() {
    const [driverRes, reportRes] = await Promise.all([
      supabase.from("driver_complaints").select("complaint_id, driver_id, plate_number, complaint_type, notes, reported_at, resolved, trip_id").order("reported_at", { ascending: false }),
      supabase.from("reports").select("*").order("created_at", { ascending: false }),
    ])

    const driverComplaints = await Promise.all((driverRes.data || []).map(async (c) => {
      const [driverRes, truckRes] = await Promise.all([
        supabase.from("Drivers").select("full_name").eq("driver_id", c.driver_id).single(),
        supabase.from("Trucks").select("kbnl_truck_no").eq("plate_number", c.plate_number).single(),
      ])
      return {
        complaint_id: c.complaint_id,
        driver_name: driverRes.data?.full_name ?? "Unknown",
        plate_number: c.plate_number,
        kbnl_truck_no: truckRes.data?.kbnl_truck_no ?? null,
        complaint_type: c.complaint_type,
        notes: c.notes,
        reported_at: c.reported_at,
        resolved: c.resolved ?? false,
        trip_id: c.trip_id,
      }
    }))

    const reportComplaints = await Promise.all((reportRes.data || []).map(async (r: any) => {
      const { data: profile } = await supabase.from("Profiles").select("full_name").eq("user_id", r.user_id).single()
      return {
        complaint_id: `report-${r.id}`,
        driver_name: profile?.full_name ?? "Unknown",
        plate_number: r.role,
        kbnl_truck_no: null,
        complaint_type: "User Report",
        notes: r.message,
        reported_at: r.created_at,
        resolved: r.resolved ?? false,
        trip_id: null,
      }
    }))

    const merged = [...driverComplaints, ...reportComplaints].sort(
      (a, b) => new Date(b.reported_at).getTime() - new Date(a.reported_at).getTime()
    )

    setComplaints(merged)
    setLastUpdated(new Date())
    setLoading(false)
  }

  async function handleResolve(id: string) {
    if (!canEdit) return
    setResolving(id)
    try {
      if (id.startsWith("report-")) {
        const reportId = id.replace("report-", "")
        const { error } = await apiMutate("admin", { action: "update", table: "reports", data: { resolved: true }, filters: { id: reportId } })
        if (error) console.error("Resolve report error:", error)
      } else {
        const { error } = await apiMutate("admin", { action: "update", table: "driver_complaints", data: { resolved: true }, filters: { complaint_id: id } })
        if (error) console.error("Resolve complaint error:", error)
      }
      fetchComplaints()
    } catch {
      console.error("Network error resolving complaint")
    } finally {
      setResolving(null)
    }
  }

  const filtered = filter === "All"
    ? complaints
    : filter === "Resolved"
    ? complaints.filter(c => c.resolved)
    : complaints.filter(c => !c.resolved)

  const resolvedCount = complaints.filter(c => c.resolved).length
  const unresolvedCount = complaints.filter(c => !c.resolved).length

  return (
    <div style={{ minHeight: "100vh", background: "#f8fafc", padding: isMobile ? "16px" : "32px", fontFamily: "'Inter', sans-serif" }}>
      <div style={{ display: "flex", flexDirection: isMobile ? "column" : "row", justifyContent: "space-between", alignItems: isMobile ? "flex-start" : "center", gap: 16, marginBottom: 32 }}>
        <div>
          <h1 style={{ margin: 0, color: "#0f172a", fontSize: isMobile ? FONT_SIZE["2xl"] : FONT_SIZE["3xl"], fontWeight: 700, letterSpacing: "-0.5px" }}>
            Driver Complaints
          </h1>
          <p style={{ margin: "8px 0 0", color: "#64748b", fontSize: FONT_SIZE.base }}>
            {unresolvedCount} unresolved ┬╖ {resolvedCount} resolved
          </p>
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: 12, width: isMobile ? "100%" : "auto" }}>
          {complaints.length > 0 && (
            <div style={{ display: "flex", background: "white", border: "1px solid #e2e8f0", borderRadius: 8, padding: 4, gap: 0 }}>
              <button onClick={() => setViewMode("card")} style={{ padding: "8px 12px", background: viewMode === "card" ? "#0070f3" : "transparent", color: viewMode === "card" ? "white" : "#64748b", border: "none", borderRadius: 6, cursor: "pointer", fontSize: FONT_SIZE.xs, fontWeight: 600, transition: "all 0.2s ease", minWidth: 44, height: 40, display: "flex", alignItems: "center", justifyContent: "center" }} title="Card view">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M3 3h8v8H3V3zm10 0h8v8h-8V3zM3 13h8v8H3v-8zm10 0h8v8h-8v-8z" /></svg>
              </button>
              <button onClick={() => setViewMode("table")} style={{ padding: "8px 12px", background: viewMode === "table" ? "#0070f3" : "transparent", color: viewMode === "table" ? "white" : "#64748b", border: "none", borderRadius: 6, cursor: "pointer", fontSize: FONT_SIZE.xs, fontWeight: 600, transition: "all 0.2s ease", minWidth: 44, height: 40, display: "flex", alignItems: "center", justifyContent: "center" }} title="Table view">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M3 4h18v2H3V4zm0 7h18v2H3v-2zm0 7h18v2H3v-2z" /></svg>
              </button>
            </div>
          )}


          <button onClick={fetchComplaints} style={{ padding: "10px 16px", background: "white", color: "#0070f3", border: "1px solid #e2e8f0", borderRadius: 8, cursor: "pointer", fontWeight: 500, fontSize: FONT_SIZE.sm, transition: "all 0.2s ease", display: "flex", alignItems: "center", gap: 6, minHeight: 40 }} onMouseEnter={e => { e.currentTarget.style.background = "#f8fafc"; e.currentTarget.style.borderColor = "#0070f3" }} onMouseLeave={e => { e.currentTarget.style.background = "white"; e.currentTarget.style.borderColor = "#e2e8f0" }}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M23 4v6h-6" /><path d="M1 20v-6h6" /><path d="M3.51 9a9 9 0 0 1 14.85-3.36M20.49 15a9 9 0 0 1-14.85 3.36" /></svg>
            Refresh
          </button>
        </div>
      </div>

      {lastUpdated && (
        <p style={{ fontSize: FONT_SIZE.xs, color: "#94a3b8", marginBottom: 20 }}>
          Updated {lastUpdated.toLocaleTimeString()}
        </p>
      )}

      <div style={{ display: "flex", gap: 8, marginBottom: 24, flexWrap: "wrap" }}>
        {filters.map(f => {
          const count = f === "All" ? complaints.length : f === "Resolved" ? resolvedCount : unresolvedCount
          return (
            <button
              key={f}
              onClick={() => setFilter(f)}
              style={{
                padding: "6px 12px",
                borderRadius: 24,
                fontSize: FONT_SIZE.xs,
                cursor: "pointer",
                border: "1px solid",
                background: filter === f ? (f === "Resolved" ? "#f0fff4" : f === "Unresolved" ? "#fdf5d3" : "#f1f5f9") : "white",
                color: filter === f ? (f === "Resolved" ? "#2f855a" : f === "Unresolved" ? "#f59e0b" : "#0f172a") : "#64748b",
                borderColor: filter === f ? (f === "Resolved" ? "#2f855a" : f === "Unresolved" ? "#fde68a" : "#cbd5e1") : "#e2e8f0",
                fontWeight: filter === f ? 600 : 500,
                transition: "all 0.2s ease"
              }}
            >
              {f} {count > 0 && <span style={{ marginLeft: 4, fontWeight: 500 }}>({count})</span>}
            </button>
          )
        })}
      </div>

      {loading ? (
        <div style={{ display: "flex", justifyContent: "center", padding: "64px 0" }}>
          <div style={{ width: 40, height: 40, borderRadius: "50%", border: "3px solid #e2e8f0", borderTopColor: "#0070f3", animation: "spin 1s linear infinite" }} />
          <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
        </div>
      ) : filtered.length === 0 ? (
        <div style={{ textAlign: "center", padding: "64px 24px", background: "white", borderRadius: 12, border: "1px solid #e2e8f0" }}>
          <div style={{ width: 64, height: 64, background: "#f1f5f9", borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 16px" }}>
            <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2"><path d="M12 8v8m0 0v-2m0 2v4M8 12h8" /></svg>
          </div>
          <h3 style={{ margin: "0 0 8px", color: "#0f172a", fontSize: FONT_SIZE.xl, fontWeight: 600 }}>No {filter.toLowerCase()} complaints</h3>
          <p style={{ color: "#64748b", fontSize: FONT_SIZE.base }}>Great work! Keep the operations smooth.</p>
        </div>
      ) : (
        <>
          {viewMode === "card" && (
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {filtered.map(c => (
                <div
                  key={c.complaint_id}
                  style={{
                    background: "white",
                    borderRadius: 12,
                    padding: 16,
                    border: `1px solid ${c.resolved ? "#e2e8f0" : "#fef3c7"}`,
                    boxShadow: "0 1px 3px rgba(0, 0, 0, 0.05)",
                    opacity: c.resolved ? 0.75 : 1,
                    transition: "all 0.2s ease"
                  }}
                  onMouseEnter={e => { if (!c.resolved) { e.currentTarget.style.boxShadow = "0 4px 12px rgba(0, 0, 0, 0.08)"; e.currentTarget.style.borderColor = "#fcd34d" } }}
                  onMouseLeave={e => { e.currentTarget.style.boxShadow = "0 1px 3px rgba(0, 0, 0, 0.05)"; e.currentTarget.style.borderColor = "#fef3c7" }}
                >
                  <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 12, marginBottom: 12 }}>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <h3 style={{ margin: "0 0 4px", color: "#0f172a", fontSize: FONT_SIZE.lg, fontWeight: 600 }}>
