"use client"

import { useState, useEffect, useRef } from "react"
import { supabase } from "@/lib/supabase"
import ModernInput from "@/components/ModernInput"
import { usePermissions } from "@/lib/PermissionContext"
import { fetchStores } from "@/lib/stores"

type FuelCompany = {
  company_id: string
  company_name: string
}

const ALL_ROLES = [
  { key: "SuperAdmin", label: "Super Admin", group: "admin", needsField: null },
  { key: "Supervisor", label: "Supervisor", group: "admin", needsField: null },
  { key: "CashAuthorizer", label: "Cash Authorizer", group: "admin", needsField: "office" },
  { key: "Broker", label: "Broker", group: "admin", needsField: null },
  { key: "TruckAdmin", label: "Truck Admin", group: "admin", needsField: null },
  { key: "DeskOfficer", label: "Desk Officer", group: "admin", needsField: null },
  { key: "ATCOfficer", label: "ATC Officer", group: "admin", needsField: null },
  { key: "Driver", label: "Driver", group: "other", needsField: null },
  { key: "StationManager", label: "Station Manager", group: "other", needsField: "company" },
  { key: "TruckOfficer", label: "Truck Officer", group: "other", needsField: null },
  { key: "StoreOfficer", label: "Store Officer", group: "other", needsField: "store" },
  { key: "CashOfficer", label: "Cash Officer", group: "other", needsField: "office" },
  { key: "StoreSupervisor", label: "Store Supervisor", group: "other", needsField: "stores" },
]

const OFFICE_LOCATIONS = ["Uyo", "Ikom", "Calabar", "Ogoja"]

type InviteResult = {
  success: boolean
  tempPassword?: string
  error?: string
  userId?: string
}

export default function InviteUsers() {
  const { getAccess } = usePermissions()
  const canEdit = getAccess("invite-users").canEdit

  const [email, setEmail] = useState("")
  const [fullName, setFullName] = useState("")
  const [phoneNumber, setPhoneNumber] = useState("")
  const [selectedRoles, setSelectedRoles] = useState<Set<string>>(new Set())
  const [companyId, setCompanyId] = useState("")
  const [storeName, setStoreName] = useState("")
  const [officeName, setOfficeName] = useState("")
  const [cashAuthOffice, setCashAuthOffice] = useState("")
  const [message, setMessage] = useState("")
  const [isError, setIsError] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [result, setResult] = useState<InviteResult | null>(null)
  const [copied, setCopied] = useState(false)
  const [companies, setCompanies] = useState<FuelCompany[]>([])
  const [allProducts, setAllProducts] = useState<string[]>([])
  const [openingBalance, setOpeningBalance] = useState<{ product: string; quantity: string }[]>([
    { product: "", quantity: "" }
  ])
  const [storeNames, setStoreNames] = useState<Set<string>>(new Set())
  const [storeLocations, setStoreLocations] = useState<string[]>([])

  const phoneRef = useRef<HTMLInputElement>(null)
  const emailRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    supabase.from("fuel_companies").select("company_id, company_name").order("company_name").then(({ data }) => {
      if (data) setCompanies(data)
    })
    supabase.rpc("get_products").then(({ data }) => {
      if (data) setAllProducts(data.map((r: { value: string }) => r.value))
    })
    fetchStores().then(setStoreLocations)
  }, [])

  function toggleRole(role: string) {
    if (!canEdit) return
    setSelectedRoles((prev) => {
      const next = new Set(prev)
      if (next.has(role)) next.delete(role)
      else next.add(role)
      return next
    })
    setMessage("")
  }

  function needsField(field: string): boolean {
    return ALL_ROLES.some((r) => selectedRoles.has(r.key) && r.needsField === field)
  }

  function addOpeningBalanceLine() {
    setOpeningBalance([...openingBalance, { product: "", quantity: "" }])
  }

  function removeOpeningBalanceLine(index: number) {
    if (openingBalance.length === 1) return
    setOpeningBalance(openingBalance.filter((_, i) => i !== index))
  }

  function updateOpeningBalanceLine(index: number, field: "product" | "quantity", value: string) {
    setOpeningBalance(openingBalance.map((l, i) => (i === index ? { ...l, [field]: value } : l)))
  }

  async function handleSubmit() {
    if (!fullName.trim()) { setMessage("Full name is required"); setIsError(true); return }
    if (!email.trim()) { setMessage("Email is required"); setIsError(true); return }
    if (selectedRoles.size === 0) { setMessage("Select at least one role"); setIsError(true); return }
    if (needsField("company") && !companyId) { setMessage("Select a company for Station Manager"); setIsError(true); return }
    if (needsField("store") && !storeName) { setMessage("Select a store for Store Officer"); setIsError(true); return }
    if (needsField("stores") && storeNames.size === 0) { setMessage("Select at least one store for Store Supervisor"); setIsError(true); return }
    if (needsField("office") && selectedRoles.has("CashOfficer") && !officeName) { setMessage("Select an office for Cash Officer"); setIsError(true); return }
    if (needsField("office") && selectedRoles.has("CashAuthorizer") && !cashAuthOffice) { setMessage("Select an assigned office for Cash Authorizer"); setIsError(true); return }

    const validLines = openingBalance.filter(l => l.product && parseInt(l.quantity) > 0)
    const products = validLines.map(l => l.product)
    if (new Set(products).size !== products.length) {
      setMessage("Duplicate products in opening stock ΓÇö merge them")
      setIsError(true)
      return
    }

    setSubmitting(true)
    setMessage("")
    setResult(null)

    try {
      const res = await fetch("/api/invite-user", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          email,
          fullName,
          phoneNumber: phoneNumber || undefined,
          roles: [...selectedRoles],
          companyId: companyId || undefined,
          storeName: storeName || undefined,
          storeNames: storeNames.size > 0 ? [...storeNames] : undefined,
          officeName: officeName || undefined,
          assignedOffice: cashAuthOffice || undefined,
          openingBalance: validLines.length > 0 ? validLines : undefined,
        }),
      })

      const data = await res.json()

      if (!res.ok) {
        setMessage(data.error || "Failed to invite user")
        setIsError(true)
        return
      }

      setResult({ success: true, tempPassword: data.tempPassword, userId: data.userId })
      setCopied(false)
    } catch {
      setMessage("Network error, please try again")
      setIsError(true)
    } finally {
      setSubmitting(false)
    }
  }

  async function copyPassword() {
    if (!result?.tempPassword) return
    try {
      await navigator.clipboard.writeText(result.tempPassword)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    } catch {
      // fallback
      const el = document.createElement("textarea")
      el.value = result.tempPassword
      document.body.appendChild(el)
      el.select()
      document.execCommand("copy")
      document.body.removeChild(el)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    }
  }

  function resetForm() {
    setEmail("")
    setFullName("")
    setPhoneNumber("")
    setSelectedRoles(new Set())
    setCompanyId("")
    setStoreName("")
    setOfficeName("")
    setCashAuthOffice("")
    setOpeningBalance([{ product: "", quantity: "" }])
    setStoreNames(new Set())
    setMessage("")
    setResult(null)
    setCopied(false)
  }

  const checkboxStyle = (checked: boolean): React.CSSProperties => ({
    width: 18,
    height: 18,
    borderRadius: 4,
    border: `2px solid ${checked ? "#0070f3" : "#d0d0d0"}`,
    background: checked ? "#0070f3" : "white",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    cursor: "pointer",
    flexShrink: 0,
    transition: "all 0.15s ease",
  })

  const roleBadgeStyle = (checked: boolean): React.CSSProperties => ({
    display: "flex",
    alignItems: "center",
    gap: 10,
    padding: "8px 12px",
    borderRadius: 8,
    border: `1.5px solid ${checked ? "#0070f3" : "#e5e5e5"}`,
    background: checked ? "rgba(0, 112, 243, 0.06)" : "white",
    cursor: "pointer",
    transition: "all 0.15s ease",
    fontSize: 14,
    color: checked ? "#0070f3" : "#333",
    fontWeight: checked ? 600 : 400,
  })

  const inputStyle: React.CSSProperties = {
    width: "100%",
    padding: "12px 14px",
    boxSizing: "border-box",
    fontSize: 14,
    border: "1.5px solid #e5e5e5",
    borderRadius: 10,
    background: "#f9f9f9",
    transition: "all 0.2s ease",
  }

  const labelStyle: React.CSSProperties = {
    display: "block", fontSize: 13, fontWeight: 600,
    color: "#171717", marginBottom: 8, letterSpacing: "0.3px",
  }

  const adminRoles = ALL_ROLES.filter((r) => r.group === "admin")
  const otherRoles = ALL_ROLES.filter((r) => r.group === "other")

  return (
    <div style={{ maxWidth: 640, fontFamily: "'Inter', sans-serif" }}>
      <h1 style={{ margin: "0 0 4px 0", color: "#0f172a", fontSize: 24, fontWeight: 700 }}>
        Invite Users
      </h1>
      <p style={{ margin: "0 0 28px 0", color: "#64748b", fontSize: 14 }}>
        Create a new user account with one or more roles.
      </p>

      {result?.success ? (
        <div style={{
          background: "white",
          border: "1px solid #e2e8f0",
          borderRadius: 16,
          padding: 32,
          boxShadow: "0 4px 16px rgba(0,0,0,0.06)",
          textAlign: "center",
        }}>
          <div style={{
            width: 56, height: 56, borderRadius: "50%",
            background: "rgba(34, 197, 94, 0.1)",
            display: "flex", alignItems: "center", justifyContent: "center",
            margin: "0 auto 16px",
          }}>
            <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#16a34a" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="20 6 9 17 4 12" />
            </svg>
          </div>

          <h2 style={{ margin: "0 0 4px", color: "#0f172a", fontSize: 20, fontWeight: 700 }}>
            User Created
          </h2>
          <p style={{ margin: "0 0 20px", color: "#64748b", fontSize: 14 }}>
            {email}
          </p>

          <div style={{
            background: "#f0f7ff",
            border: "1.5px dashed #0070f3",
            borderRadius: 12,
            padding: "20px 24px",
            marginBottom: 20,
          }}>
            <p style={{ margin: "0 0 8px", color: "#0c4a6e", fontSize: 12, fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.5px" }}>
              Temporary Password
            </p>
            <p style={{
              margin: "0 0 12px",
              fontSize: 28,
              fontWeight: 700,
              color: "#0070f3",
              fontFamily: "'Fira Code', 'Cascadia Code', monospace",
              letterSpacing: "0.5px",
            }}>
              {result.tempPassword}
            </p>
            <button
              onClick={copyPassword}
              style={{
                padding: "8px 20px",
                background: copied ? "#16a34a" : "#0070f3",
                color: "white",
                border: "none",
                borderRadius: 8,
                fontSize: 14,
                fontWeight: 600,
                cursor: "pointer",
                transition: "all 0.2s",
              }}
            >
              {copied ? "Copied!" : "Copy Password"}
            </button>
          </div>

          <div style={{
            background: "#fffbeb",
            border: "1px solid #fcd34d",
            borderRadius: 8,
            padding: "12px 16px",
            marginBottom: 24,
            textAlign: "left",
          }}>
            <p style={{ margin: 0, fontSize: 13, color: "#78350f", lineHeight: 1.5 }}>
              ΓÜá∩╕Å This is the only time this password will be shown. Share it securely with the user.
              They will be asked to change it on first login.
            </p>
          </div>

          <button
            onClick={resetForm}
            style={{
              padding: "10px 24px",
              background: "white",
              color: "#0f172a",
              border: "1px solid #cbd5e1",
              borderRadius: 8,
              fontSize: 14,
              fontWeight: 600,
              cursor: "pointer",
            }}
          >
            Invite Another User
          </button>
        </div>
      ) : (
        <div style={{
          background: "white",
          border: "1px solid #e2e8f0",
          borderRadius: 16,
          padding: 28,
          boxShadow: "0 4px 16px rgba(0,0,0,0.06)",
        }}>
          {/* Basic Info */}
          <div style={{ display: "flex", flexDirection: "column", gap: 16, marginBottom: 24 }}>
            <div>
              <label style={labelStyle}>Full Name *</label>
              <ModernInput
                type="text" placeholder="e.g. John Doe"
                value={fullName}
                onChange={(e: any) => { setFullName(e.target.value); setMessage("") }}
                onKeyDown={(e: any) => { if (e.key === "Enter") phoneRef.current?.focus() }}
                style={inputStyle}
                autoFocus
                readOnly={!canEdit}
              />
            </div>
            <div>
              <label style={labelStyle}>Phone Number</label>
              <ModernInput
                ref={phoneRef}
                type="text" placeholder="e.g. 08012345678"
                value={phoneNumber}
                onChange={(e: any) => { setPhoneNumber(e.target.value); setMessage("") }}
                onKeyDown={(e: any) => { if (e.key === "Enter") emailRef.current?.focus() }}
                style={inputStyle}
                readOnly={!canEdit}
              />
            </div>
            <div>
              <label style={labelStyle}>Email Address (username) *</label>
              <ModernInput
                ref={emailRef}
                type="email" placeholder="e.g. user@company.com"
                value={email}
                onChange={(e: any) => { setEmail(e.target.value); setMessage("") }}
                style={inputStyle}
                readOnly={!canEdit}
              />
            </div>
          </div>

          {/* Admin Roles */}
          <div style={{ marginBottom: 20 }}>
            <p style={{ margin: "0 0 10px", fontSize: 13, fontWeight: 600, color: "#0f172a", letterSpacing: "0.3px", textTransform: "uppercase" }}>
              Admin Panel Roles
            </p>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
              {adminRoles.map((r) => (
                <div key={r.key} onClick={() => toggleRole(r.key)} style={roleBadgeStyle(selectedRoles.has(r.key))}>
                  <div style={checkboxStyle(selectedRoles.has(r.key))}>
                    {selectedRoles.has(r.key) && (
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                        <polyline points="20 6 9 17 4 12" />
                      </svg>
                    )}
                  </div>
                  {r.label}
                </div>
              ))}
            </div>
          </div>

          {/* Other Roles */}
          <div style={{ marginBottom: 24 }}>
            <p style={{ margin: "0 0 10px", fontSize: 13, fontWeight: 600, color: "#0f172a", letterSpacing: "0.3px", textTransform: "uppercase" }}>
              Other Roles
            </p>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
              {otherRoles.map((r) => (
                <div key={r.key} onClick={() => toggleRole(r.key)} style={roleBadgeStyle(selectedRoles.has(r.key))}>
                  <div style={checkboxStyle(selectedRoles.has(r.key))}>
                    {selectedRoles.has(r.key) && (
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                        <polyline points="20 6 9 17 4 12" />
                      </svg>
                    )}
                  </div>
                  {r.label}
                </div>
              ))}
            </div>
          </div>

          {/* Conditional Fields */}
          {needsField("company") && (
            <div style={{ marginBottom: 16 }}>
              <label style={labelStyle}>Company (for Station Manager) *</label>
              <select
                value={companyId}
                onChange={(e) => setCompanyId(e.target.value)}
                style={{
                  ...inputStyle,
                  appearance: "none",
                  background: "#f9f9f9 url(\"data:image/svg+xml,%3Csvg width='12' height='8' viewBox='0 0 12 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1.5L6 6.5L11 1.5' stroke='%23999' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E\") no-repeat right 14px center",
                }}
              >
                <option value="">Select company...</option>
                {companies.map((c) => (
                  <option key={c.company_id} value={c.company_id}>{c.company_name}</option>
                ))}
              </select>
            </div>
          )}

          {needsField("store") && (
            <div>
              <div style={{ marginBottom: 16 }}>
                <label style={labelStyle}>Store (for Store Officer) *</label>
                <select
                  value={storeName}
                  onChange={(e) => {
                    setStoreName(e.target.value)
                    setOpeningBalance([{ product: "", quantity: "" }])
                  }}
                  style={{
                    ...inputStyle,
                    appearance: "none",
                    background: "#f9f9f9 url(\"data:image/svg+xml,%3Csvg width='12' height='8' viewBox='0 0 12 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1.5L6 6.5L11 1.5' stroke='%23999' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E\") no-repeat right 14px center",
                  }}
                >
                  <option value="">Select store...</option>
                  {storeLocations.map((s) => (
                    <option key={s} value={s}>{s}</option>
                  ))}
                </select>
              </div>

              {storeName && (
                <div style={{ marginBottom: 16 }}>
                  <p style={{ margin: "0 0 4px 0", fontWeight: 700, fontSize: 14, color: "#0f172a" }}>
                    Opening Stock Balance <span style={{ fontWeight: 400, fontSize: 12, color: "#94a3b8" }}>(optional)</span>
                  </p>
                  <p style={{ margin: "0 0 12px 0", fontSize: 12, color: "#94a3b8" }}>
                    Set the initial stock balance for <strong>{storeName}</strong>.
                  </p>

                  <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 12 }}>
                    {openingBalance.map((line, i) => (
                      <div key={i} style={{ display: "flex", gap: 8, alignItems: "center" }}>
                        <select
                          value={line.product}
                          onChange={(e) => updateOpeningBalanceLine(i, "product", e.target.value)}
                          style={{
                            ...inputStyle,
                            flex: 1,
                            appearance: "none",
                            background: "#f9f9f9 url(\"data:image/svg+xml,%3Csvg width='12' height='8' viewBox='0 0 12 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1.5L6 6.5L11 1.5' stroke='%23999' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E\") no-repeat right 14px center",
                          }}
                        >
                          <option value="">Select product</option>
                          {allProducts.map((p) => (
                            <option key={p} value={p}>{p}</option>
                          ))}
                        </select>
                        <input
                          type="number"
                          min="1"
                          placeholder="Qty"
                          value={line.quantity}
                          onChange={(e) => updateOpeningBalanceLine(i, "quantity", e.target.value)}
                          onKeyDown={(e) => { if (e.key === "-" || e.key === "e") e.preventDefault() }}
                          style={{ ...inputStyle, width: 100, flexShrink: 0 }}
                        />
                        {openingBalance.length > 1 && (
                          <button onClick={() => removeOpeningBalanceLine(i)} style={{ background: "none", border: "none", cursor: "pointer", color: "#ef4444", fontSize: 18, lineHeight: 1, padding: 0, width: 24, height: 24, display: "flex", alignItems: "center", justifyContent: "center" }}>X</button>
                        )}
                      </div>
                    ))}
                  </div>

                  <button onClick={addOpeningBalanceLine} style={{ width: "100%", padding: "8px 12px", background: "white", border: "1px dashed #0070f3", color: "#0070f3", borderRadius: 6, cursor: "pointer", fontSize: 13, fontWeight: 600, minHeight: 38 }}>
                    + Add Product
                  </button>
                </div>
              )}
            </div>
          )}

          {needsField("stores") && (
            <div style={{ marginBottom: 16 }}>
              <label style={labelStyle}>Stores (for Store Supervisor) *</label>
              <p style={{ margin: "0 0 8px 0", fontSize: 12, color: "#94a3b8" }}>Select one or more stores this supervisor will be responsible for.</p>
              <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                {storeLocations.map((s) => (
                  <div
                    key={s}
                    onClick={() => {
                      setStoreNames(prev => {
                        const next = new Set(prev)
                        if (next.has(s)) next.delete(s)
                        else next.add(s)
                        return next
                      })
                      setMessage("")
                    }}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 10,
                      padding: "8px 12px",
                      borderRadius: 8,
                      border: `1.5px solid ${storeNames.has(s) ? "#0070f3" : "#e5e5e5"}`,
                      background: storeNames.has(s) ? "rgba(0, 112, 243, 0.06)" : "white",
                      cursor: "pointer",
                      transition: "all 0.15s ease",
                      fontSize: 14,
                      color: storeNames.has(s) ? "#0070f3" : "#333",
                      fontWeight: storeNames.has(s) ? 600 : 400,
                    }}
                  >
                    <div style={checkboxStyle(storeNames.has(s))}>
                      {storeNames.has(s) && (
                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                          <polyline points="20 6 9 17 4 12" />
                        </svg>
                      )}
                    </div>
                    {s}
                  </div>
                ))}
              </div>
            </div>
          )}

          {selectedRoles.has("CashOfficer") && (
            <div style={{ marginBottom: 16 }}>
              <label style={labelStyle}>Office (for Cash Officer) *</label>
              <select
                value={officeName}
                onChange={(e) => setOfficeName(e.target.value)}
                style={{
                  ...inputStyle,
                  appearance: "none",
                  background: "#f9f9f9 url(\"data:image/svg+xml,%3Csvg width='12' height='8' viewBox='0 0 12 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1.5L6 6.5L11 1.5' stroke='%23999' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E\") no-repeat right 14px center",
                }}
              >
                <option value="">Select office...</option>
                {OFFICE_LOCATIONS.map((o) => (
                  <option key={o} value={o}>{o}</option>
                ))}
              </select>
            </div>
          )}

          {selectedRoles.has("CashAuthorizer") && (
            <div style={{ marginBottom: 16 }}>
              <label style={labelStyle}>Assigned Office (for Cash Authorizer) *</label>
              <select
                value={cashAuthOffice}
                onChange={(e) => setCashAuthOffice(e.target.value)}
                style={{
                  ...inputStyle,
                  appearance: "none",
                  background: "#f9f9f9 url(\"data:image/svg+xml,%3Csvg width='12' height='8' viewBox='0 0 12 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1.5L6 6.5L11 1.5' stroke='%23999' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E\") no-repeat right 14px center",
                }}
              >
                <option value="">Select office...</option>
                {OFFICE_LOCATIONS.map((o) => (
                  <option key={o} value={o}>{o}</option>
                ))}
              </select>
            </div>
          )}

          {message && (
            <div style={{
              padding: 12, borderRadius: 10, marginBottom: 16,
              background: isError ? "rgba(239, 68, 68, 0.08)" : "rgba(34, 197, 94, 0.08)",
              border: `1.5px solid ${isError ? "rgba(239, 68, 68, 0.3)" : "rgba(34, 197, 94, 0.3)"}`,
              color: isError ? "#dc2626" : "#16a34a",
              fontSize: 14, fontWeight: 500,
            }}>
              {message}
            </div>
          )}

          <button
            onClick={handleSubmit}
            disabled={submitting || !canEdit}
            style={{
              width: "100%",
              padding: 14,
              background: submitting || !canEdit ? "#94a3b8" : "#0070f3",
              color: "white",
              border: "none",
              borderRadius: 10,
              fontSize: 16,
              fontWeight: 600,
              cursor: submitting || !canEdit ? "not-allowed" : "pointer",
              opacity: submitting || !canEdit ? 0.7 : 1,
            }}
          >
            {submitting ? "Creating User..." : "Create User"}
          </button>
        </div>
      )}
    </div>
  )
}

"use client"

import { FONT_SIZE } from "@/lib/constants"

import { useState, useEffect, useRef } from "react"
import { supabase } from "@/lib/supabase"
import { apiMutate } from "@/lib/api-mutation"
import { usePermissions } from "@/lib/PermissionContext"
import { Role } from "@/lib/roles"

type Truck = {
  plate_number: string
  kbnl_truck_no: string
  truck_model: string
  capacity: number
  truck_size: string | null
  status: string
  engine_type: string
}

type ViewMode = "card" | "table"

const TRUCK_SIZES = ["20", "40/45", "Dina", "Tricycle"]
const ENGINE_TYPES = ["Diesel Engine", "CNG"]
const truckStatuses = ["Empty", "Loaded", "To Plant", "Undergoing Repairs", "Decommissioned"]

function useBreakpoint() {
  const [isDesktop, setIsDesktop] = useState(false)
  const [isMobile, setIsMobile] = useState(true)

  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth < 640)
      setIsDesktop(window.innerWidth >= 640)
    }

    handleResize()
    window.addEventListener("resize", handleResize)
    return () => window.removeEventListener("resize", handleResize)
  }, [])

  return { isMobile, isDesktop }
}



const getPillStyle = (filter: string, isActive: boolean) => {
  if (!isActive) {
    return { bg: "white", textColor: "#64748b", borderColor: "#e2e8f0" }
  }
  
  if (filter === "All") {
    return { bg: "#171717", textColor: "white", borderColor: "#171717" }
  } else if (filter === "Empty") {
    return { bg: "#f0fdf4", textColor: "#16a34a", borderColor: "#16a34a" }
  } else if (filter === "Loaded") {
    return { bg: "#eff6ff", textColor: "#0070f3", borderColor: "#0070f3" }
  } else if (filter === "To Plant") {
    return { bg: "#f8f0ff", textColor: "#874cf5", borderColor: "#874cf5" }
  } else if (filter === "Undergoing Repairs") {
    return { bg: "#fffbeb", textColor: "#f5a623", borderColor: "#f5a623" }
  } else if (filter === "Decommissioned") {
    return { bg: "#fef2f2", textColor: "#ef4444", borderColor: "#ef4444" }
  }
  
  return { bg: "white", textColor: "#64748b", borderColor: "#e2e8f0" }
}

export default function ManageTrucks() {
  const { isMobile } = useBreakpoint()
  const { getAccess, activeRole } = usePermissions()
  const baseCanEdit = getAccess("manage-trucks").canEdit
  const canEdit = baseCanEdit && activeRole !== Role.ATCOfficer
  const [trucks, setTrucks] = useState<Truck[]>([])
  const [loading, setLoading] = useState(true)
  const [viewMode, setViewMode] = useState<ViewMode>("card")
  const [editingTruck, setEditingTruck] = useState<Truck | null>(null)
  const [editKbnlNo, setEditKbnlNo] = useState("")
  const [editModel, setEditModel] = useState("")
  const [editCapacity, setEditCapacity] = useState("")
  const [editTruckSize, setEditTruckSize] = useState("")
  const [editEngineType, setEditEngineType] = useState("")
  const [editStatus, setEditStatus] = useState("")
  const [deletingPlate, setDeletingPlate] = useState<string | null>(null)
  const [message, setMessage] = useState("")
  const [submitting, setSubmitting] = useState(false)
  const [filterStatus, setFilterStatus] = useState("All")

  const capacityRef = useRef<HTMLInputElement>(null)

  async function fetchTrucks() {
    try {
      const { data, error } = await supabase
        .from("Trucks")
        .select("*")
        .order("kbnl_truck_no", { ascending: true })

      if (!error) setTrucks(data || [])
    } finally {
      setLoading(false)
    }
  }

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { fetchTrucks() }, [])

  const filterOptions = ["All", "Empty", "Loaded", "To Plant", "Undergoing Repairs", "Decommissioned"]
  const filteredTrucks = filterStatus === "All" ? trucks : trucks.filter((t) => t.status === filterStatus)

  function startEdit(truck: Truck) {
    setEditingTruck(truck)
    setEditKbnlNo(truck.kbnl_truck_no)
    setEditModel(truck.truck_model)
    setEditCapacity(truck.capacity.toString())
    setEditTruckSize(truck.truck_size ?? "")
    setEditEngineType(truck.engine_type)
    setEditStatus(truck.status)
    setMessage("")
  }

  function closeModals() {
    setEditingTruck(null)
    setDeletingPlate(null)
    setMessage("")
  }

  async function handleUpdate() {
    if (!canEdit) return
    if (!editingTruck) return
    if (!editKbnlNo.trim()) return setMessage("KbNL truck number is required")
    if (!editModel.trim()) return setMessage("Truck model is required")
    if (!editCapacity) return setMessage("Capacity is required")
    const capacity = Number(editCapacity)
    if (!Number.isInteger(capacity) || capacity <= 0) return setMessage("Capacity must be a positive whole number")

    setSubmitting(true)

    try {
      const { error } = await apiMutate("admin", {
        action: "update",
        table: "Trucks",
        data: {
          kbnl_truck_no: editKbnlNo.trim(),
          truck_model: editModel.trim(),
          capacity,
          truck_size: editTruckSize || null,
          engine_type: editEngineType,
          status: editStatus,
        },
        filters: { plate_number: editingTruck.plate_number },
      })

      if (error) {
        setMessage(error)
        return
      }

      closeModals()
      await fetchTrucks()
    } catch {
      setMessage("Failed to update truck")
    } finally {
      setSubmitting(false)
    }
  }

  async function handleDelete(plate_number: string) {
    if (!canEdit) return
    setSubmitting(true)

    try {
      const { error } = await apiMutate("admin", {
        action: "delete",
        table: "Trucks",
        filters: { plate_number },
      })

      if (error) {
        setMessage(error)
        return
      }

      closeModals()
      await fetchTrucks()
    } catch {
      setMessage("Failed to delete truck")
    } finally {
      setSubmitting(false)
    }
  }

  const statusPillColor = (status: string) => {
    const pill = getPillStyle(status, true)
    return { bg: pill.bg, color: pill.textColor, border: pill.borderColor }
  }

  const inputStyle: React.CSSProperties = {
    width: "100%",
    padding: "12px 14px",
    boxSizing: "border-box",
    borderRadius: 8,
    border: "1px solid #e0e0e0",
    fontSize: FONT_SIZE.base,
    background: "white",
    color: "#171717",
    minHeight: 48,
    transition: "border-color 0.2s ease",
  }

  return (
    <div style={{ minHeight: "100vh", background: "#f8fafc", padding: isMobile ? "16px" : "32px", fontFamily: "'Inter', sans-serif" }}>
      <div style={{ display: "flex", flexDirection: isMobile ? "column" : "row", justifyContent: "space-between", alignItems: isMobile ? "flex-start" : "center", gap: 16, marginBottom: 24 }}>
        <div>
          <h1 style={{ margin: 0, color: "#0f172a", fontSize: isMobile ? FONT_SIZE["2xl"] : FONT_SIZE["3xl"], fontWeight: 700, letterSpacing: "-0.5px" }}>
            Manage Trucks
          </h1>
          <p style={{ margin: "8px 0 0", color: "#64748b", fontSize: FONT_SIZE.base }}>
            Track fleet inventory and truck status.
          </p>
        </div>

        {trucks.length > 0 && (
          <div style={{ display: "flex", background: "white", border: "1px solid #e2e8f0", borderRadius: 8, padding: 4, gap: 0 }}>
            <button
              onClick={() => setViewMode("card")}
              style={{
                padding: "8px 12px",
                background: viewMode === "card" ? "#0070f3" : "transparent",
                color: viewMode === "card" ? "white" : "#64748b",
                border: "none",
                borderRadius: 6,
                cursor: "pointer",
                fontSize: FONT_SIZE.xs,
                fontWeight: 600,
                minWidth: 44,
                height: 40,
                display: "flex",
                alignItems: "center",
                justifyContent: "center"
              }}
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M3 3h8v8H3V3zm10 0h8v8h-8V3zM3 13h8v8H3v-8zm10 0h8v8h-8v-8z"/></svg>
            </button>
            <button
              onClick={() => setViewMode("table")}
              style={{
                padding: "8px 12px",
                background: viewMode === "table" ? "#0070f3" : "transparent",
                color: viewMode === "table" ? "white" : "#64748b",
                border: "none",
                borderRadius: 6,
                cursor: "pointer",
                fontSize: FONT_SIZE.xs,
                fontWeight: 600,
                minWidth: 44,
                height: 40,
                display: "flex",
                alignItems: "center",
                justifyContent: "center"
              }}
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M3 4h18v2H3V4zm0 7h18v2H3v-2zm0 7h18v2H3v-2z"/></svg>
            </button>
          </div>
        )}
      </div>

      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 24 }}>
        {filterOptions.map((option) => {
          const isActive = filterStatus === option
          const pill = getPillStyle(option, isActive)
          return (
            <button
              key={option}
              onClick={() => setFilterStatus(option)}
              style={{
                padding: "8px 14px",
                borderRadius: 20,
                fontSize: FONT_SIZE.sm,
                cursor: "pointer",
                border: `1.5px solid ${pill.borderColor}`,
                background: pill.bg,
                color: pill.textColor,
                fontWeight: isActive ? 600 : 500,
                transition: "all 0.2s"
              }}
              onMouseEnter={e => { if (!isActive) { e.currentTarget.style.background = "#f8fafc"; e.currentTarget.style.borderColor = "#cbd5e1" } }}
              onMouseLeave={e => { if (!isActive) { e.currentTarget.style.background = "white"; e.currentTarget.style.borderColor = "#e2e8f0" } }}
            >
              {option}
            </button>
          )
        })}
      </div>

      {loading ? (
        <div style={{ display: "flex", justifyContent: "center", padding: "64px 0" }}>
          <div style={{ width: 40, height: 40, borderRadius: "50%", border: "3px solid #e2e8f0", borderTopColor: "#0070f3", animation: "spin 1s linear infinite" }} />
          <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
        </div>
      ) : filteredTrucks.length === 0 ? (
        <div style={{ textAlign: "center", padding: "64px 24px", background: "white", borderRadius: 12, border: "1px solid #e2e8f0", boxShadow: "0 1px 3px rgba(0, 0, 0, 0.05)" }}>
          <h3 style={{ margin: "0 0 8px", color: "#0f172a", fontSize: FONT_SIZE.xl, fontWeight: 600 }}>No trucks found</h3>
          <p style={{ color: "#64748b", fontSize: FONT_SIZE.base, margin: 0 }}>
            {filterStatus === "All" ? "No trucks in the fleet." : `No trucks with status "${filterStatus}".`}
          </p>
        </div>
      ) : (
        <>
          {viewMode === "card" && (
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {filteredTrucks.map((truck) => {
                const pill = statusPillColor(truck.status)
                return (
                  <div key={truck.plate_number} style={{ background: "white", borderRadius: 12, padding: 16, border: "1px solid #e2e8f0", boxShadow: "0 1px 3px rgba(0, 0, 0, 0.05)", transition: "all 0.2s ease" }} onMouseEnter={e => { e.currentTarget.style.boxShadow = "0 4px 12px rgba(0, 0, 0, 0.08)"; e.currentTarget.style.borderColor = "#cbd5e1" }} onMouseLeave={e => { e.currentTarget.style.boxShadow = "0 1px 3px rgba(0, 0, 0, 0.05)"; e.currentTarget.style.borderColor = "#e2e8f0" }}>
                    <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 12, marginBottom: 12 }}>
                      <div style={{ flex: 1 }}>
                        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
                          <h3 style={{ margin: 0, color: "#0f172a", fontSize: FONT_SIZE.lg, fontWeight: 600 }}>{truck.plate_number}</h3>
                          <span style={{ color: "#94a3b8", fontSize: FONT_SIZE.xs }}>┬╖ #{truck.kbnl_truck_no}</span>
                        </div>
                        <p style={{ margin: 0, color: "#64748b", fontSize: FONT_SIZE.sm }}>{truck.truck_model}</p>
                      </div>
                      <span style={{ padding: "6px 12px", borderRadius: 16, fontSize: FONT_SIZE.xs, fontWeight: 600, background: pill.bg, color: pill.color, border: `1.5px solid ${pill.border}`, whiteSpace: "nowrap" }}>
                        {truck.status}
                      </span>
                    </div>

                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, padding: "12px 0", borderTop: "1px solid #f1f5f9", borderBottom: "1px solid #f1f5f9" }}>
                      <div>
                        <p style={{ margin: "0 0 4px 0", color: "#94a3b8", fontSize: FONT_SIZE.xs }}>Capacity</p>
                        <p style={{ margin: 0, color: "#0f172a", fontSize: FONT_SIZE.lg, fontWeight: 600 }}>{truck.capacity} bags</p>
                      </div>
                      <div>
                        <p style={{ margin: "0 0 4px 0", color: "#94a3b8", fontSize: FONT_SIZE.xs }}>Size (Tonnage)</p>
                        <p style={{ margin: 0, color: "#0f172a", fontSize: FONT_SIZE.lg, fontWeight: 600 }}>{truck.truck_size || "ΓÇö"}</p>
                      </div>
                    </div>

                    <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
                      <button
                        onClick={() => startEdit(truck)}
                        disabled={!canEdit}
                        style={{ flex: 1, padding: "8px 12px", cursor: !canEdit ? "not-allowed" : "pointer", borderRadius: 6, border: "1px solid #e2e8f0", color: "#0070f3", background: !canEdit ? "#94a3b8" : "#f0f7ff", fontSize: FONT_SIZE.sm, fontWeight: 500, transition: "all 0.2s" }}
                        onMouseEnter={e => { if (canEdit) { e.currentTarget.style.background = "#e0efff"; e.currentTarget.style.borderColor = "#0070f3" } }}
                        onMouseLeave={e => { if (canEdit) { e.currentTarget.style.background = "#f0f7ff"; e.currentTarget.style.borderColor = "#e2e8f0" } }}
                      >
                        Edit
                      </button>
                      <button
                        onClick={() => { setDeletingPlate(truck.plate_number); setMessage("") }}
                        disabled={!canEdit}
                        style={{ flex: 1, padding: "8px 12px", cursor: !canEdit ? "not-allowed" : "pointer", borderRadius: 6, border: "1px solid #fee2e2", color: "#ef4444", background: !canEdit ? "#94a3b8" : "#fef2f2", fontSize: FONT_SIZE.sm, fontWeight: 500, transition: "all 0.2s" }}
                        onMouseEnter={e => { if (canEdit) e.currentTarget.style.background = "#fee2e2" }}
                        onMouseLeave={e => { if (canEdit) e.currentTarget.style.background = "#fef2f2" }}
                      >
                        Delete
                      </button>
                    </div>
                  </div>
                )
              })}
            </div>
          )}

          {viewMode === "table" && (
            <div style={{ background: "white", borderRadius: 12, border: "1px solid #e2e8f0", boxShadow: "0 1px 3px rgba(0, 0, 0, 0.05)", overflowX: "auto" }}>
              <table style={{ width: "100%", borderCollapse: "collapse", textAlign: "left" }}>
                <thead>
                  <tr style={{ background: "#f8fafc", borderBottom: "1px solid #e2e8f0" }}>
                    <th style={{ padding: "12px 16px", fontWeight: 600, fontSize: FONT_SIZE.xs, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px" }}>Truck</th>
                    <th style={{ padding: "12px 16px", fontWeight: 600, fontSize: FONT_SIZE.xs, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px" }}>Model</th>
                    <th style={{ padding: "12px 16px", fontWeight: 600, fontSize: FONT_SIZE.xs, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px" }}>Size (Tonnage)</th>
                    <th style={{ padding: "12px 16px", fontWeight: 600, fontSize: FONT_SIZE.xs, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px" }}>Capacity</th>
                    <th style={{ padding: "12px 16px", fontWeight: 600, fontSize: FONT_SIZE.xs, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px" }}>Status</th>
                    <th style={{ padding: "12px 16px", fontWeight: 600, fontSize: FONT_SIZE.xs, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px", textAlign: "right" }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredTrucks.map((truck, idx) => {
                    const pill = statusPillColor(truck.status)
                    return (
                      <tr key={truck.plate_number} style={{ borderBottom: idx === filteredTrucks.length - 1 ? "none" : "1px solid #e2e8f0", transition: "background 0.2s ease" }} onMouseEnter={e => e.currentTarget.style.background = "#f8fafc"} onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                        <td style={{ padding: "12px 16px" }}>
                          <strong style={{ color: "#0f172a", fontSize: FONT_SIZE.base }}>{truck.plate_number}</strong>
                          <div style={{ fontSize: FONT_SIZE.xs, color: "#94a3b8", marginTop: 2 }}>#{truck.kbnl_truck_no}</div>
                        </td>
                        <td style={{ padding: "12px 16px", color: "#0f172a", fontSize: FONT_SIZE.base }}>{truck.truck_model}</td>
                        <td style={{ padding: "12px 16px", color: "#64748b", fontSize: FONT_SIZE.sm }}>{truck.truck_size || "ΓÇö"}</td>
                        <td style={{ padding: "12px 16px", color: "#0f172a", fontSize: FONT_SIZE.base, fontWeight: 500 }}>{truck.capacity}</td>
                        <td style={{ padding: "12px 16px" }}>
                          <span style={{ padding: "6px 10px", borderRadius: 14, fontSize: FONT_SIZE.xs, fontWeight: 600, background: pill.bg, color: pill.color, border: `1.5px solid ${pill.border}` }}>
                            {truck.status}
                          </span>
                        </td>
                        <td style={{ padding: "12px 16px", textAlign: "right" }}>
                          <div style={{ display: "flex", gap: 6, justifyContent: "flex-end" }}>
                            <button
                              onClick={() => startEdit(truck)}
                              disabled={!canEdit}
                              style={{ padding: "6px 10px", cursor: !canEdit ? "not-allowed" : "pointer", borderRadius: 6, border: "1px solid #e2e8f0", color: "#0070f3", background: !canEdit ? "#94a3b8" : "#f0f7ff", fontSize: FONT_SIZE.sm, fontWeight: 500, transition: "all 0.2s", minHeight: 32, minWidth: 32, display: "inline-flex", alignItems: "center", justifyContent: "center" }}
                              onMouseEnter={e => { if (canEdit) { e.currentTarget.style.background = "#e0efff"; e.currentTarget.style.borderColor = "#0070f3" } }}
                              onMouseLeave={e => { if (canEdit) { e.currentTarget.style.background = "#f0f7ff"; e.currentTarget.style.borderColor = "#e2e8f0" } }}
                            >
                              Edit
                            </button>
                            <button
                              onClick={() => { setDeletingPlate(truck.plate_number); setMessage("") }}
                              disabled={!canEdit}
                              style={{ padding: "6px 10px", cursor: !canEdit ? "not-allowed" : "pointer", borderRadius: 6, border: "1px solid #fee2e2", color: "#ef4444", background: !canEdit ? "#94a3b8" : "#fef2f2", fontSize: FONT_SIZE.sm, fontWeight: 500, transition: "all 0.2s", minHeight: 32, minWidth: 32, display: "inline-flex", alignItems: "center", justifyContent: "center" }}
                              onMouseEnter={e => { if (canEdit) e.currentTarget.style.background = "#fee2e2" }}
                              onMouseLeave={e => { if (canEdit) e.currentTarget.style.background = "#fef2f2" }}
                            >
                              Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}

      {(editingTruck || deletingPlate) && (
        <div
          onClick={closeModals}
          style={{ position: "fixed", inset: 0, background: "rgba(15, 23, 42, 0.6)", backdropFilter: "blur(4px)", display: "flex", alignItems: isMobile ? "flex-end" : "center", justifyContent: "center", zIndex: 100, padding: isMobile ? 0 : 24, animation: "fadeIn 0.2s ease-out" }}
        >
          <style>{`@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } } @keyframes slideUp { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }`}</style>
          <div
            onClick={e => e.stopPropagation()}
            style={{ background: "white", borderRadius: isMobile ? "20px 20px 0 0" : 12, padding: isMobile ? "28px 20px" : 32, width: "100%", maxWidth: 440, maxHeight: "90vh", overflowY: "auto", boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.25)", animation: "slideUp 0.3s cubic-bezier(0.16, 1, 0.3, 1)" }}
          >

            {editingTruck && (
              <>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
                  <h3 style={{ margin: 0, color: "#0f172a", fontSize: FONT_SIZE.xl, fontWeight: 700 }}>Edit Truck</h3>
                  <button onClick={closeModals} style={{ background: "none", border: "none", color: "#94a3b8", cursor: "pointer", padding: 0, width: 32, height: 32, display: "flex", alignItems: "center", justifyContent: "center", transition: "color 0.2s" }} onMouseEnter={e => e.currentTarget.style.color = "#64748b"} onMouseLeave={e => e.currentTarget.style.color = "#94a3b8"}><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>
                </div>

                <p style={{ margin: "0 0 20px 0", color: "#94a3b8", fontSize: FONT_SIZE.sm }}>Plate: {editingTruck.plate_number}</p>

                <div style={{ display: "flex", flexDirection: "column", gap: 14, marginBottom: 20 }}>
                  <div>
                    <label style={{ display: "block", marginBottom: 6, color: "#475569", fontSize: FONT_SIZE.sm, fontWeight: 500 }}>KbNL Truck No. *</label>
                    <input type="text" value={editKbnlNo} readOnly={!canEdit} onChange={(e) => { setEditKbnlNo(e.target.value); setMessage("") }} onKeyDown={(e) => { if (e.key === "Enter") capacityRef.current?.focus() }} style={inputStyle} />
                  </div>

                  <div>
                    <label style={{ display: "block", marginBottom: 6, color: "#475569", fontSize: FONT_SIZE.sm, fontWeight: 500 }}>Truck Model *</label>
                    <input type="text" value={editModel} readOnly={!canEdit} onChange={(e) => { setEditModel(e.target.value); setMessage("") }} onKeyDown={(e) => { if (e.key === "Enter") capacityRef.current?.focus() }} style={inputStyle} />
                  </div>

                  <div>
                    <label style={{ display: "block", marginBottom: 6, color: "#475569", fontSize: FONT_SIZE.sm, fontWeight: 500 }}>Capacity (bags) *</label>
                    <input ref={capacityRef} type="number" value={editCapacity} readOnly={!canEdit} onChange={(e) => { setEditCapacity(e.target.value); setMessage("") }} style={inputStyle} />
                  </div>

                  <div>
                    <label style={{ display: "block", marginBottom: 6, color: "#475569", fontSize: FONT_SIZE.sm, fontWeight: 500 }}>Truck Size (Tonnage)</label>
                    <select value={editTruckSize} disabled={!canEdit} onChange={(e) => setEditTruckSize(e.target.value)} style={{ ...inputStyle, appearance: "none", paddingRight: 32, backgroundImage: "url('data:image/svg+xml;charset=UTF-8,%3csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke=%22%23171717%22 stroke-width=%222%22%3e%3cpolyline points=%226 9 12 15 18 9%22%3e%3c/polyline%3e%3c/svg%3e')", backgroundRepeat: "no-repeat", backgroundPosition: "right 12px center", backgroundSize: "16px" }}>
                      <option value="">No size</option>
                      {TRUCK_SIZES.map((s) => (
                        <option key={s} value={s}>{s}</option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <label style={{ display: "block", marginBottom: 6, color: "#475569", fontSize: FONT_SIZE.sm, fontWeight: 500 }}>Engine Type</label>
                    <select value={editEngineType} disabled={!canEdit} onChange={(e) => setEditEngineType(e.target.value)} style={{ ...inputStyle, appearance: "none", paddingRight: 32, backgroundImage: "url('data:image/svg+xml;charset=UTF-8,%3csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke=%22%23171717%22 stroke-width=%222%22%3e%3cpolyline points=%226 9 12 15 18 9%22%3e%3c/polyline%3e%3c/svg%3e')", backgroundRepeat: "no-repeat", backgroundPosition: "right 12px center", backgroundSize: "16px" }}>
                      {ENGINE_TYPES.map((t) => (
                        <option key={t} value={t}>{t}</option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <label style={{ display: "block", marginBottom: 6, color: "#475569", fontSize: FONT_SIZE.sm, fontWeight: 500 }}>Status</label>
                    <select value={editStatus} disabled={!canEdit} onChange={(e) => setEditStatus(e.target.value)} style={{ ...inputStyle, appearance: "none", paddingRight: 32, backgroundImage: "url('data:image/svg+xml;charset=UTF-8,%3csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke=%22%23171717%22 stroke-width=%222%22%3e%3cpolyline points=%226 9 12 15 18 9%22%3e%3c/polyline%3e%3c/svg%3e')", backgroundRepeat: "no-repeat", backgroundPosition: "right 12px center", backgroundSize: "16px" }}>
                      {truckStatuses.map((s) => (
                        <option key={s} value={s}>{s}</option>
                      ))}
                    </select>
                  </div>
                </div>

                {message && <div style={{ padding: 12, background: "#fef2f2", borderLeft: "4px solid #ef4444", borderRadius: 4, marginBottom: 20, color: "#b91c1c", fontSize: FONT_SIZE.sm }}>{message}</div>}

                <button onClick={handleUpdate} disabled={submitting || !canEdit} style={{ width: "100%", padding: "12px 16px", background: submitting || !canEdit ? "#94a3b8" : "#0070f3", color: "white", border: "none", borderRadius: 8, cursor: submitting || !canEdit ? "not-allowed" : "pointer", fontWeight: 600, fontSize: FONT_SIZE.md, transition: "opacity 0.2s", opacity: submitting || !canEdit ? 0.7 : 1, minHeight: 44 }}>
                  {submitting ? "Saving..." : "Save Changes"}
                </button>
              </>
            )}

            {deletingPlate && (
              <>
                <div style={{ display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center" }}>
                  <div style={{ width: 64, height: 64, background: "#fef2f2", color: "#ef4444", borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 20 }}>
                    <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M3 6h18"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/></svg>
                  </div>
                  <h3 style={{ margin: "0 0 12px", color: "#0f172a", fontSize: FONT_SIZE.xl, fontWeight: 700 }}>Delete Truck</h3>
                  <p style={{ margin: "0 0 20px", color: "#64748b", fontSize: FONT_SIZE.base, lineHeight: 1.5 }}>Are you sure you want to delete <strong>{deletingPlate}</strong>? This action cannot be undone and will permanently remove the truck data.</p>

                  {message && <div style={{ padding: 12, background: "#fef2f2", borderLeft: "4px solid #ef4444", borderRadius: 4, marginBottom: 20, color: "#b91c1c", fontSize: FONT_SIZE.sm, width: "100%", textAlign: "left" }}>{message}</div>}

                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, width: "100%" }}>
                    <button onClick={closeModals} style={{ padding: "12px 16px", background: "white", color: "#475569", border: "1px solid #cbd5e1", borderRadius: 8, cursor: "pointer", fontWeight: 600, fontSize: FONT_SIZE.md, minHeight: 44, transition: "all 0.2s" }} onMouseEnter={e => { e.currentTarget.style.background = "#f8fafc"; e.currentTarget.style.borderColor = "#0070f3"; e.currentTarget.style.color = "#0070f3" }} onMouseLeave={e => { e.currentTarget.style.background = "white"; e.currentTarget.style.borderColor = "#cbd5e1"; e.currentTarget.style.color = "#475569" }}>
                      Cancel
                    </button>
                    <button onClick={() => handleDelete(deletingPlate)} disabled={submitting || !canEdit} style={{ padding: "12px 16px", background: submitting || !canEdit ? "#94a3b8" : "#ef4444", color: "white", border: "none", borderRadius: 8, cursor: submitting || !canEdit ? "not-allowed" : "pointer", fontWeight: 600, fontSize: FONT_SIZE.md, opacity: submitting || !canEdit ? 0.7 : 1, minHeight: 44, transition: "all 0.2s" }} onMouseEnter={e => { if (!submitting && canEdit) e.currentTarget.style.background = "#dc2626" }} onMouseLeave={e => { e.currentTarget.style.background = "#ef4444" }}>
                      {submitting ? "Deleting..." : "Yes, Delete"}
                    </button>
                  </div>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import { useState, useEffect, useMemo } from "react"
import { supabase } from "@/lib/supabase"
import { usePermissions } from "@/lib/PermissionContext"
import { ROLES } from "@/lib/permissions"
import { fetchStores } from "@/lib/stores"
import { Icon } from "@iconify/react"

const OFFICE_LOCATIONS = ["Uyo", "Ikom", "Calabar", "Ogoja"]

type FuelCompany = { company_id: string; company_name: string }

type UserRow = {
  user_id: string
  email: string
  full_name: string
  phone_number: string
  role: string
  is_deactivated: boolean
  must_change_password: boolean
  created_at: string
  last_sign_in_at: string | null
  roles: string[]
}

const ALL_ROLE_KEYS = Object.keys(ROLES).sort((a, b) => {
  const order = ["SuperAdmin", "Admin", "Supervisor", "Broker", "TruckAdmin", "DeskOfficer", "ATCOfficer", "CashAuthorizer", "Driver", "StationManager", "TruckOfficer", "StoreOfficer", "CashOfficer", "StoreSupervisor"]
  return order.indexOf(a) - order.indexOf(b)
})

const inputStyle: React.CSSProperties = {
  width: "100%",
  padding: "10px 14px",
  boxSizing: "border-box",
  fontSize: 14,
  border: "1.5px solid #e5e5e5",
  borderRadius: 8,
  background: "#f9f9f9",
  outline: "none",
  transition: "all 0.2s ease",
}

const labelStyle: React.CSSProperties = {
  display: "block",
  fontSize: 13,
  fontWeight: 600,
  color: "#171717",
  marginBottom: 8,
  letterSpacing: "0.3px",
}

export default function ManageUsers() {
  const { getAccess } = usePermissions()
  const canView = getAccess("manage-users").canView
  const canEdit = getAccess("manage-users").canEdit

  const [users, setUsers] = useState<UserRow[]>([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState("")
  const [roleFilter, setRoleFilter] = useState("")
  const [error, setError] = useState("")

  const [editingUser, setEditingUser] = useState<UserRow | null>(null)
  const [selectedRoles, setSelectedRoles] = useState<Set<string>>(new Set())
  const [roleSaveLoading, setRoleSaveLoading] = useState(false)
  const [roleSaveError, setRoleSaveError] = useState("")

  const [companyId, setCompanyId] = useState("")
  const [storeName, setStoreName] = useState("")
  const [officeName, setOfficeName] = useState("")
  const [cashAuthOffice, setCashAuthOffice] = useState("")
  const [storeNames, setStoreNames] = useState<Set<string>>(new Set())
  const [companies, setCompanies] = useState<FuelCompany[]>([])
  const [storeLocations, setStoreLocations] = useState<string[]>([])

  const [confirmAction, setConfirmAction] = useState<{
    user: UserRow
    action: "deactivate" | "activate"
  } | null>(null)
  const [confirmLoading, setConfirmLoading] = useState(false)

  async function fetchUsers() {
    setLoading(true)
    setError("")
    try {
      const res = await fetch("/api/manage-users", {
        headers: {
          Authorization: `Bearer ${(await supabase.auth.getSession()).data.session?.access_token}`,
        },
      })
      if (!res.ok) {
        const data = await res.json()
        setError(data.error || "Failed to load users")
        return
      }
      const data = await res.json()
      setUsers(data.users || [])
    } catch {
      setError("Network error while loading users")
    } finally {
      setLoading(false)
    }
  }

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => {
    if (canView) fetchUsers()
  }, [canView])

  useEffect(() => {
    supabase.from("fuel_companies").select("company_id, company_name").order("company_name").then(({ data }) => {
      if (data) setCompanies(data)
    })
    fetchStores().then(setStoreLocations)
  }, [])

  function needsField(field: string): boolean {
    if (field === "company") return selectedRoles.has("StationManager")
    if (field === "store") return selectedRoles.has("StoreOfficer")
    if (field === "stores") return selectedRoles.has("StoreSupervisor")
    if (field === "cashOffice") return selectedRoles.has("CashOfficer")
    if (field === "cashAuthOffice") return selectedRoles.has("CashAuthorizer")
    return false
  }

  const filteredUsers = useMemo(() => {
    let result = users
    if (search.trim()) {
      const q = search.toLowerCase()
      result = result.filter(
        u =>
          (u.full_name || "").toLowerCase().includes(q) ||
          (u.email || "").toLowerCase().includes(q) ||
          (u.phone_number || "").toLowerCase().includes(q)
      )
    }
    if (roleFilter) {
      result = result.filter(u => u.roles.includes(roleFilter))
    }
    return result
  }, [users, search, roleFilter])

  function openRoleEditor(user: UserRow) {
    if (!canEdit) return
    setEditingUser(user)
    setSelectedRoles(new Set(user.roles))
    setRoleSaveError("")
    setCompanyId("")
    setStoreName("")
    setOfficeName("")
    setCashAuthOffice("")
    setStoreNames(new Set())

    const queries: Promise<void>[] = []
    if (user.roles.includes("StationManager")) {
      queries.push(
        Promise.resolve(supabase.from("station_managers").select("company_id").eq("manager_id", user.user_id).single()
          .then(({ data }) => { if (data?.company_id) setCompanyId(data.company_id) }))
      )
    }
    if (user.roles.includes("StoreOfficer")) {
      queries.push(
        Promise.resolve(supabase.from("store_officers").select("store_name").eq("officer_id", user.user_id).single()
          .then(({ data }) => { if (data?.store_name) setStoreName(data.store_name) }))
      )
    }
    if (user.roles.includes("CashOfficer")) {
      queries.push(
        Promise.resolve(supabase.from("cash_officers").select("office_name").eq("clerk_id", user.user_id).single()
          .then(({ data }) => { if (data?.office_name) setOfficeName(data.office_name) }))
      )
    }
    if (user.roles.includes("CashAuthorizer")) {
      queries.push(
        Promise.resolve(supabase.from("cash_authorizers").select("assigned_office").eq("authorizer_id", user.user_id).single()
          .then(({ data }) => { if (data?.assigned_office) setCashAuthOffice(data.assigned_office) }))
      )
    }
    if (user.roles.includes("StoreSupervisor")) {
      queries.push(
        Promise.resolve(supabase.from("store_supervisors").select("store_names").eq("supervisor_id", user.user_id).single()
          .then(({ data }) => { if (data?.store_names) setStoreNames(new Set(data.store_names)) }))
      )
    }
    Promise.all(queries)
  }

  function toggleRole(role: string) {
    setSelectedRoles(prev => {
      const next = new Set(prev)
      if (next.has(role)) next.delete(role)
      else next.add(role)
      return next
    })
    setRoleSaveError("")
  }

  async function saveRoles() {
    if (!editingUser) return
    if (selectedRoles.size === 0) {
      setRoleSaveError("User must have at least one role")
      return
    }
    if (needsField("company") && !companyId) {
      setRoleSaveError("Select a company for Station Manager")
      return
    }
    if (needsField("store") && !storeName) {
      setRoleSaveError("Select a store for Store Officer")
      return
    }
    if (needsField("stores") && storeNames.size === 0) {
      setRoleSaveError("Select at least one store for Store Supervisor")
      return
    }
    if (needsField("cashOffice") && !officeName) {
      setRoleSaveError("Select an office for Cash Officer")
      return
    }
    if (needsField("cashAuthOffice") && !cashAuthOffice) {
      setRoleSaveError("Select an assigned office for Cash Authorizer")
      return
    }
    setRoleSaveLoading(true)
    setRoleSaveError("")
    try {
      const token = (await supabase.auth.getSession()).data.session?.access_token
      const res = await fetch("/api/manage-users", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          action: "reassign-roles",
          userId: editingUser.user_id,
          roles: [...selectedRoles],
          companyId: companyId || undefined,
          storeName: storeName || undefined,
          storeNames: storeNames.size > 0 ? [...storeNames] : undefined,
          officeName: officeName || undefined,
          assignedOffice: cashAuthOffice || undefined,
        }),
      })
      const data = await res.json()
      if (!res.ok) {
        setRoleSaveError(data.error || "Failed to save roles")
        return
      }
      const updatedRoles: string[] = data.roles || [...selectedRoles]
      setUsers(prev => prev.map(u =>
        u.user_id === editingUser.user_id ? { ...u, roles: updatedRoles } : u
      ))
      setEditingUser(null)
      setSelectedRoles(new Set())
      setCompanyId("")
      setStoreName("")
      setOfficeName("")
      setCashAuthOffice("")
      setStoreNames(new Set())
      await fetchUsers()
    } catch {
      setRoleSaveError("Network error")
    } finally {
      setRoleSaveLoading(false)
    }
  }

  async function confirmToggleActive() {
    if (!confirmAction) return
    setConfirmLoading(true)
    try {
      const token = (await supabase.auth.getSession()).data.session?.access_token
      const res = await fetch("/api/manage-users", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          action: confirmAction.action,
          userId: confirmAction.user.user_id,
        }),
      })
      const data = await res.json()
      if (!res.ok) {
        setError(data.error || `Failed to ${confirmAction.action} user`)
        setConfirmAction(null)
        return
      }
      setConfirmAction(null)
      await fetchUsers()
    } catch {
      setError("Network error")
    } finally {
      setConfirmLoading(false)
    }
  }

  const checkboxStyle = (checked: boolean): React.CSSProperties => ({
    width: 18,
    height: 18,
    borderRadius: 4,
    border: `2px solid ${checked ? "#0070f3" : "#d0d0d0"}`,
    background: checked ? "#0070f3" : "white",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    cursor: "pointer",
    flexShrink: 0,
    transition: "all 0.15s ease",
  })

  const roleBadgeStyle = (checked: boolean): React.CSSProperties => ({
    display: "flex",
    alignItems: "center",
    gap: 10,
    padding: "8px 12px",
    borderRadius: 8,
    border: `1.5px solid ${checked ? "#0070f3" : "#e5e5e5"}`,
    background: checked ? "rgba(0, 112, 243, 0.06)" : "white",
    cursor: "pointer",
    transition: "all 0.15s ease",
    fontSize: 14,
    color: checked ? "#0070f3" : "#333",
    fontWeight: checked ? 600 : 400,
  })

  const roleColors: Record<string, { bg: string; text: string }> = {
    SuperAdmin: { bg: "#fef3c7", text: "#92400e" },
    Admin: { bg: "#dbeafe", text: "#1e40af" },
    Supervisor: { bg: "#e0e7ff", text: "#3730a3" },
    CashAuthorizer: { bg: "#fce7f3", text: "#9d174d" },
    Broker: { bg: "#d1fae5", text: "#065f46" },
    TruckAdmin: { bg: "#e0f2fe", text: "#075985" },
    DeskOfficer: { bg: "#ede9fe", text: "#5b21b6" },
    ATCOfficer: { bg: "#f3e8ff", text: "#6b21a8" },
    Driver: { bg: "#fef2f2", text: "#991b1b" },
    StationManager: { bg: "#fefce8", text: "#854d0e" },
    TruckOfficer: { bg: "#f0fdf4", text: "#166534" },
    StoreOfficer: { bg: "#f0f9ff", text: "#0c4a6e" },
    CashOfficer: { bg: "#fff7ed", text: "#9a3412" },
    StoreSupervisor: { bg: "#ecfdf5", text: "#065f46" },
  }

  function RoleBadge({ role }: { role: string }) {
    const colors = roleColors[role] || { bg: "#f3f4f6", text: "#374151" }
    return (
      <span style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 4,
        padding: "2px 8px",
        borderRadius: 6,
        fontSize: 12,
        fontWeight: 600,
        background: colors.bg,
        color: colors.text,
        border: "1px solid transparent",
      }}>
        {role === "SuperAdmin" && <Icon icon="mdi:crown" width={12} />}
        {ROLES[role]?.label || role}
      </span>
    )
  }

  if (!canView) return null

  return (
    <div style={{ fontFamily: "'Inter', sans-serif", maxWidth: 1200 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 24, flexWrap: "wrap", gap: 12 }}>
        <div>
          <h1 style={{ margin: "0 0 4px 0", color: "#0f172a", fontSize: 24, fontWeight: 700 }}>Users</h1>
          <p style={{ margin: 0, color: "#64748b", fontSize: 14 }}>
            {loading ? "Loading..." : `${users.length} user${users.length !== 1 ? "s" : ""}`}
          </p>
        </div>
      </div>

      {error && (
        <div style={{
          padding: 12, borderRadius: 10, marginBottom: 16,
          background: "rgba(239, 68, 68, 0.08)",
          border: "1.5px solid rgba(239, 68, 68, 0.3)",
          color: "#dc2626", fontSize: 14, fontWeight: 500,
        }}>
          {error}
          <button onClick={fetchUsers} style={{
            marginLeft: 12, background: "none", border: "none",
            color: "#0070f3", cursor: "pointer", fontWeight: 600, fontSize: 13,
          }}>
            Retry
          </button>
        </div>
      )}

      <div style={{
        background: "white",
        border: "1px solid #e2e8f0",
        borderRadius: 16,
        boxShadow: "0 4px 16px rgba(0,0,0,0.06)",
        overflow: "hidden",
      }}>
        <div style={{
          padding: "16px 20px",
          borderBottom: "1px solid #e2e8f0",
          display: "flex",
          gap: 12,
          flexWrap: "wrap",
          alignItems: "center",
        }}>
          <div style={{ flex: 1, minWidth: 200, position: "relative" }}>
            <Icon icon="mdi:magnify" width={18} style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", color: "#94a3b8" }} />
            <input
