"use client"

import { FONT_SIZE } from "@/lib/constants"

import Image from "next/image"
import React, { useState, useEffect, useRef, useCallback } from "react"
import { supabase } from "@/lib/supabase"
import { apiMutate } from "@/lib/api-mutation"
import ModernInput from "@/components/ModernInput"
import InviteSuccessCard from "@/components/admin/InviteSuccessCard"
import { usePermissions } from "@/lib/PermissionContext"

type StationManager = {
  manager_id: string
  full_name: string
  phone_number: string | null
  status: string
  company_id: string
  company_name: string
  profile_picture_url?: string
}

type FuelCompany = {
  company_id: string
  company_name: string
}

type ViewMode = "card" | "table"

// Responsive breakpoint hook
function useBreakpoint() {
  const [isDesktop, setIsDesktop] = useState(false)
  const [isMobile, setIsMobile] = useState(true)

  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth < 640)
      setIsDesktop(window.innerWidth >= 640)
    }

    handleResize()
    window.addEventListener("resize", handleResize)
    return () => window.removeEventListener("resize", handleResize)
  }, [])

  return { isMobile, isDesktop }
}

// Fixed typography scale


export default function ManageStationManagers() {
  const { getAccess } = usePermissions()
  const canEdit = getAccess("station-managers").canEdit
  const { isMobile } = useBreakpoint()
  const [managers, setManagers] = useState<StationManager[]>([])
  const [loading, setLoading] = useState(true)
  const [viewMode, setViewMode] = useState<ViewMode>("card")
  const [companies, setCompanies] = useState<FuelCompany[]>([])
  const [showInviteModal, setShowInviteModal] = useState(false)
  const [editingManager, setEditingManager] = useState<StationManager | null>(null)
  const [deletingId, setDeletingId] = useState<string | null>(null)

  // Invite form
  const [fullName, setFullName] = useState("")
  const [phoneNumber, setPhoneNumber] = useState("")
  const [email, setEmail] = useState("")
  const [companyId, setCompanyId] = useState("")

  // New company form
  const [showNewCompanyForm, setShowNewCompanyForm] = useState(false)
  const [newCompanyName, setNewCompanyName] = useState("")
  const [creatingCompany, setCreatingCompany] = useState(false)

  // Edit form
  const [editName, setEditName] = useState("")
  const [editPhone, setEditPhone] = useState("")

  const [message, setMessage] = useState("")
  const [submitting, setSubmitting] = useState(false)
  const [inviteResult, setInviteResult] = useState<{ tempPassword: string; email: string } | null>(null)

  const phoneRef = useRef<HTMLInputElement>(null)
  const emailRef = useRef<HTMLInputElement>(null)
  const companyRef = useRef<HTMLSelectElement>(null)
  const newCompanyRef = useRef<HTMLInputElement>(null)
  const editPhoneRef = useRef<HTMLInputElement>(null)

  const fetchAll = useCallback(async () => {
    setLoading(true)
    try {
      await Promise.all([fetchManagers(), fetchCompanies()])
    } finally {
      setLoading(false)
    }
  }, [])

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => {
    fetchAll()
  }, [fetchAll])

  async function fetchManagers() {
    const { data } = await supabase
      .from("station_managers")
      .select("manager_id, full_name, phone_number, status, company_id, profile_picture_url")
      .order("full_name", { ascending: true })

    if (!data) return

    const enriched = await Promise.all(
      data.map(async (m) => {
        const { data: company } = await supabase
          .from("fuel_companies")
          .select("company_name")
          .eq("company_id", m.company_id)
          .single()

        return {
          ...m,
          company_name: company?.company_name ?? "Unknown",
        }
      })
    )

    setManagers(enriched)
  }

  async function fetchCompanies() {
    const { data } = await supabase
      .from("fuel_companies")
      .select("company_id, company_name")
      .order("company_name", { ascending: true })
    setCompanies(data || [])
  }

  async function handleCreateCompany() {
    if (creatingCompany) return
    if (!canEdit) return
    const name = newCompanyName.trim()
    if (!name) return setMessage("Enter a company name")

    setCreatingCompany(true)
    setMessage("")

    try {
      const { data, error } = await apiMutate<FuelCompany[]>("fuel", {
        action: "insert",
        table: "fuel_companies",
        data: { company_name: name },
      })

      if (error) {
        setMessage("Failed to create company: " + error)
        return
      }

      if (!data || !data[0]) {
        setMessage("Failed to create company: no data returned")
        return
      }

      const created: FuelCompany = {
        company_id: data[0].company_id,
        company_name: data[0].company_name,
      }

      setCompanies((prev) => [...prev, created].sort((a, b) => a.company_name.localeCompare(b.company_name)))
      setCompanyId(created.company_id)
      setShowNewCompanyForm(false)
      setNewCompanyName("")
      setMessage("")
    } catch {
      setMessage("Network error, please try again")
    } finally {
      setCreatingCompany(false)
    }
  }

  function closeModals() {
    setShowInviteModal(false)
    setEditingManager(null)
    setDeletingId(null)
    setShowNewCompanyForm(false)
    setNewCompanyName("")
    setFullName("")
    setPhoneNumber("")
    setEmail("")
    setCompanyId("")
    setEditName("")
    setEditPhone("")
    setMessage("")
    setInviteResult(null)
  }

  async function handleInvite() {
    if (!canEdit) return
    if (!fullName.trim()) return setMessage("Full name is required")
    if (!email.trim()) return setMessage("Email is required")
    if (!companyId) return setMessage("Select a fuel company")

    setSubmitting(true)

    try {
      const res = await fetch("/api/invite-user", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          email,
          fullName,
          phoneNumber,
          role: "StationManager",
          companyId,
        }),
      })

      const result = await res.json()

      if (!res.ok) {
        setMessage("Failed: " + result.error)
        return
      }

      setInviteResult({ tempPassword: result.tempPassword, email })
      fetchManagers()
    } catch {
      setMessage("Network error, please try again")
    } finally {
      setSubmitting(false)
    }
  }

  async function handleUpdate() {
    if (!canEdit) return
    if (!editingManager) return
    if (!editName.trim()) return setMessage("Name is required")

    setSubmitting(true)

    try {
      const { error } = await apiMutate("admin", {
        action: "update",
        table: "station_managers",
        data: { full_name: editName, phone_number: editPhone || null },
        filters: { manager_id: editingManager.manager_id },
      })

      if (error) {
        setMessage("Failed to update manager")
        return
      }
      closeModals()
      fetchManagers()
    } catch {
      setMessage("Network error, please try again")
    } finally {
      setSubmitting(false)
    }
  }

  async function handleDelete(managerId: string) {
    if (!canEdit) return
    setSubmitting(true)

    try {
      const { error } = await apiMutate("admin", {
        action: "delete",
        table: "station_managers",
        filters: { manager_id: managerId },
      })

      if (error) {
        setMessage("Failed to delete manager")
        return
      }

      closeModals()
      fetchManagers()
    } catch {
      setMessage("Network error, please try again")
    } finally {
      setSubmitting(false)
    }
  }

  const statusColor = (status: string) => {
    switch (status) {
      case "Active":
        return { bg: "#d1fae5", color: "#065f46", border: "#a7f3d0" }
      case "Invited":
        return { bg: "#f0f7ff", color: "#0c4a6e", border: "#bfdbfe" }
      case "Suspended":
        return { bg: "#fee2e2", color: "#7f1d1d", border: "#fecaca" }
      default:
        return { bg: "#f3f4f6", color: "#6b7280", border: "#e5e7eb" }
    }
  }

  const inputStyle: React.CSSProperties = {
    width: "100%",
    padding: "12px 14px",
    boxSizing: "border-box",
    borderRadius: 8,
    border: "1px solid #e0e0e0",
    fontSize: FONT_SIZE.base,
    background: "white",
    color: "#171717",
    minHeight: 48,
    transition: "border-color 0.2s ease",
  }

  return (
    <div
      style={{
        minHeight: "100vh",
        background: "#f8fafc",
        padding: isMobile ? "16px" : "32px",
        fontFamily: "'Inter', sans-serif",
      }}
    >
      {/* Header & Controls */}
      <div
        style={{
          display: "flex",
          flexDirection: isMobile ? "column" : "row",
          justifyContent: "space-between",
          alignItems: isMobile ? "flex-start" : "center",
          gap: 16,
          marginBottom: 32,
        }}
      >
        <div>
          <h1
            style={{
              margin: 0,
              color: "#0f172a",
              fontSize: isMobile ? FONT_SIZE["2xl"] : FONT_SIZE["3xl"],
              fontWeight: 700,
              letterSpacing: "-0.5px",
            }}
          >
            Station Managers
          </h1>
          <p
            style={{
              margin: "8px 0 0",
              color: "#64748b",
              fontSize: FONT_SIZE.base,
            }}
          >
            Manage station managers and their assigned fuel companies.
          </p>
        </div>

        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 12,
            width: isMobile ? "100%" : "auto",
          }}
        >
          {/* View Toggle */}
          {managers.length > 0 && (
            <div
              style={{
                display: "flex",
                background: "white",
                border: "1px solid #e2e8f0",
                borderRadius: 8,
                padding: 4,
                gap: 0,
              }}
            >
              <button
                onClick={() => setViewMode("card")}
                style={{
                  padding: "8px 12px",
                  background: viewMode === "card" ? "#0070f3" : "transparent",
                  color: viewMode === "card" ? "white" : "#64748b",
                  border: "none",
                  borderRadius: 6,
                  cursor: "pointer",
                  fontSize: FONT_SIZE.xs,
                  fontWeight: 600,
                  transition: "all 0.2s ease",
                  minWidth: 44,
                  height: 40,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
                title="Card view"
              >
                <svg
                  width="16"
                  height="16"
                  viewBox="0 0 24 24"
                  fill="currentColor"
                >
                  <path d="M3 3h8v8H3V3zm10 0h8v8h-8V3zM3 13h8v8H3v-8zm10 0h8v8h-8v-8z" />
                </svg>
              </button>
              <button
                onClick={() => setViewMode("table")}
                style={{
                  padding: "8px 12px",
                  background: viewMode === "table" ? "#0070f3" : "transparent",
                  color: viewMode === "table" ? "white" : "#64748b",
                  border: "none",
                  borderRadius: 6,
                  cursor: "pointer",
                  fontSize: FONT_SIZE.xs,
                  fontWeight: 600,
                  transition: "all 0.2s ease",
                  minWidth: 44,
                  height: 40,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
                title="Table view"
              >
                <svg
                  width="16"
                  height="16"
                  viewBox="0 0 24 24"
                  fill="currentColor"
                >
                  <path d="M3 4h18v2H3V4zm0 7h18v2H3v-2zm0 7h18v2H3v-2z" />
                </svg>
              </button>
            </div>
          )}

          {/* Add Button */}
          <button
            onClick={() => {
              setShowInviteModal(true)
              setMessage("")
            }}
            disabled={!canEdit}
            style={{
              padding: isMobile ? "10px 16px" : "12px 20px",
              background: !canEdit ? "#94a3b8" : "#0070f3",
              color: "white",
              border: "none",
              borderRadius: 8,
              cursor: !canEdit ? "not-allowed" : "pointer",
              fontWeight: 600,
              fontSize: FONT_SIZE.md,
              flex: isMobile ? 1 : "0 0 auto",
              boxShadow: "0 4px 12px rgba(0, 112, 243, 0.2)",
              transition: "all 0.2s ease",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: 6,
              minHeight: 40,
              whiteSpace: "nowrap",
            }}
            onMouseEnter={(e) => {
              if (!isMobile)
                (e.currentTarget.style.transform = "translateY(-2px)")
            }}
            onMouseLeave={(e) => {
              if (!isMobile) (e.currentTarget.style.transform = "none")
            }}
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
              <path d="M12 2c5.5 0 10 4.5 10 10s-4.5 10-10 10S2 17.5 2 12 6.5 2 12 2m0 2c-4.4 0-8 3.6-8 8s3.6 8 8 8 8-3.6 8-8-3.6-8-8-8m3.5 9h-3v3h-1v-3h-3v-1h3v-3h1v3h3v1z" />
            </svg>
            Add Manager
          </button>
        </div>
      </div>

      {/* Content Section */}
      {loading ? (
        <div style={{ display: "flex", justifyContent: "center", padding: "64px 0" }}>
          <div
            style={{
              width: 40,
              height: 40,
              borderRadius: "50%",
              border: "3px solid #e2e8f0",
              borderTopColor: "#0070f3",
              animation: "spin 1s linear infinite",
            }}
          />
          <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
        </div>
      ) : managers.length === 0 ? (
        <div
          style={{
            textAlign: "center",
            padding: "64px 24px",
            background: "white",
            borderRadius: 12,
            border: "1px solid #e2e8f0",
            boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.05)",
          }}
        >
          <div
            style={{
              width: 64,
              height: 64,
              background: "#f1f5f9",
              borderRadius: "50%",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              margin: "0 auto 16px",
            }}
          >
            <svg
              width="32"
              height="32"
              viewBox="0 0 24 24"
              fill="none"
              stroke="#94a3b8"
              strokeWidth="2"
            >
              <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
              <circle cx="9" cy="7" r="4" />
              <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
              <path d="M16 3.13a4 4 0 0 1 0 7.75" />
            </svg>
          </div>
          <h3
            style={{
              margin: "0 0 8px",
              color: "#0f172a",
              fontSize: FONT_SIZE.xl,
              fontWeight: 600,
            }}
          >
            No station managers yet
          </h3>
          <p
            style={{
              color: "#64748b",
              fontSize: FONT_SIZE.base,
              margin: "0 0 24px",
              maxWidth: 400,
              marginLeft: "auto",
              marginRight: "auto",
            }}
          >
            Get started by adding a new station manager. You&apos;ll manage their contact info and fuel company assignment here.
          </p>
          <button
            onClick={() => {
              setShowInviteModal(true)
              setMessage("")
            }}
            disabled={!canEdit}
            style={{
              padding: "10px 20px",
              background: !canEdit ? "#94a3b8" : "white",
              color: "#0f172a",
              border: "1px solid #cbd5e1",
              borderRadius: 8,
              cursor: !canEdit ? "not-allowed" : "pointer",
              fontWeight: 500,
              fontSize: FONT_SIZE.base,
              transition: "all 0.2s ease",
            }}
            onMouseEnter={(e) => { if (canEdit) e.currentTarget.style.background = "#f8fafc" }}
            onMouseLeave={(e) => { if (canEdit) e.currentTarget.style.background = "white" }}
          >
            Add First Manager
          </button>
        </div>
      ) : (
        <>
          {/* Card View */}
          {viewMode === "card" && (
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: 12,
              }}
            >
              {managers.map((manager) => {
                const { bg, color, border } = statusColor(manager.status)
                return (
                  <div
                    key={manager.manager_id}
                    style={{
                      background: "white",
                      borderRadius: 12,
                      padding: 16,
                      border: "1px solid #e2e8f0",
                      boxShadow: "0 1px 3px rgba(0, 0, 0, 0.05)",
                      transition: "all 0.2s ease",
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.boxShadow =
                        "0 4px 12px rgba(0, 0, 0, 0.08)"
                      e.currentTarget.style.borderColor = "#cbd5e1"
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.boxShadow =
                        "0 1px 3px rgba(0, 0, 0, 0.05)"
                      e.currentTarget.style.borderColor = "#e2e8f0"
                    }}
                  >
                    <div
                      style={{
                        display: "flex",
                        alignItems: "flex-start",
                        justifyContent: "space-between",
                        gap: 12,
                      }}
                    >
                      <div
                        style={{
                          display: "flex",
                          alignItems: "center",
                          gap: 12,
                          flex: 1,
                          minWidth: 0,
                        }}
                      >
                        <div
                          style={{
                            width: 40,
                            height: 40,
                            borderRadius: "50%",
                            background: manager.profile_picture_url ? "transparent" : "linear-gradient(135deg, #0070f3 0%, #0056d4 100%)",
                            color: "white",
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                            fontWeight: 600,
                            fontSize: FONT_SIZE.md,
                            flexShrink: 0,
                            overflow: "hidden",
                          }}
                        >
                          {manager.profile_picture_url ? (
                                <Image src={manager.profile_picture_url} alt={manager.full_name} width={36} height={36} unoptimized style={{ objectFit: "cover" }} />
                          ) : (
                            manager.full_name.charAt(0).toUpperCase()
                          )}
                        </div>
                        <div style={{ minWidth: 0 }}>
                          <h3
                            style={{
                              margin: "0 0 4px 0",
                              color: "#0f172a",
                              fontSize: FONT_SIZE.lg,
                              fontWeight: 600,
                              overflow: "hidden",
                              textOverflow: "ellipsis",
                              whiteSpace: "nowrap",
                            }}
                          >
                            {manager.full_name}
                          </h3>
                          <p
                            style={{
                              margin: 0,
                              color: "#64748b",
                              fontSize: FONT_SIZE.sm,
                              overflow: "hidden",
                              textOverflow: "ellipsis",
                              whiteSpace: "nowrap",
                            }}
                          >
                            {manager.company_name}
                          </p>
                        </div>
                      </div>
                      <span
                        style={{
                          padding: "4px 10px",
                          borderRadius: 6,
                          fontSize: FONT_SIZE.xs,
                          background: bg,
                          color: color,
                          border: `1px solid ${border}`,
                          fontWeight: 500,
                          flexShrink: 0,
                        }}
                      >
                        {manager.status}
                      </span>
                    </div>

                    <p
                      style={{
                        margin: "12px 0 0",
                        color: "#475569",
                        fontSize: FONT_SIZE.sm,
                      }}
                    >
                      {manager.phone_number || (
                        <span style={{ color: "#94a3b8", fontStyle: "italic" }}>
                          No phone number
                        </span>
                      )}
                    </p>

                    {/* Action Buttons */}
                    <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
                      <button
                        onClick={() => {
                          setEditingManager(manager)
                          setEditName(manager.full_name)
                          setEditPhone(manager.phone_number || "")
                          setMessage("")
                        }}
                        disabled={!canEdit}
                        style={{
                          flex: 1,
                          padding: "8px 12px",
                          cursor: !canEdit ? "not-allowed" : "pointer",
                          borderRadius: 6,
                          border: "1px solid #e2e8f0",
                          color: "#0070f3",
                          background: !canEdit ? "#94a3b8" : "#f0f7ff",
                          fontSize: FONT_SIZE.sm,
                          fontWeight: 500,
                          transition: "all 0.2s",
                        }}
                        onMouseEnter={(e) => {
                          if (canEdit) { e.currentTarget.style.background = "#e0efff"; e.currentTarget.style.borderColor = "#0070f3" }
                        }}
                        onMouseLeave={(e) => {
                          if (canEdit) { e.currentTarget.style.background = "#f0f7ff"; e.currentTarget.style.borderColor = "#e2e8f0" }
                        }}
                      >
                        Edit
                      </button>
                      <button
                        onClick={() => {
                          setDeletingId(manager.manager_id)
                          setMessage("")
                        }}
                        disabled={!canEdit}
                        style={{
                          flex: 1,
                          padding: "8px 12px",
                          cursor: !canEdit ? "not-allowed" : "pointer",
                          borderRadius: 6,
                          border: "1px solid #fee2e2",
                          color: "#ef4444",
                          background: !canEdit ? "#94a3b8" : "#fef2f2",
                          fontSize: FONT_SIZE.sm,
                          fontWeight: 500,
                          transition: "all 0.2s",
                        }}
                        onMouseEnter={(e) => {
                          if (canEdit) e.currentTarget.style.background = "#fee2e2"
                        }}
                        onMouseLeave={(e) => {
                          if (canEdit) e.currentTarget.style.background = "#fef2f2"
                        }}
                      >
                        Delete
                      </button>
                    </div>
                  </div>
                )
              })}
            </div>
          )}

          {/* Table View */}
          {viewMode === "table" && (
            <div
              style={{
                background: "white",
                borderRadius: 12,
                border: "1px solid #e2e8f0",
                boxShadow: "0 1px 3px rgba(0, 0, 0, 0.05)",
                overflowX: "auto",
              }}
            >
              <table
                style={{
                  width: "100%",
                  borderCollapse: "collapse",
                  textAlign: "left",
                }}
              >
                <thead>
                  <tr style={{ background: "#f8fafc", borderBottom: "1px solid #e2e8f0" }}>
                    <th
                      style={{
                        padding: "12px 16px",
                        fontWeight: 600,
                        fontSize: FONT_SIZE.xs,
                        color: "#64748b",
                        textTransform: "uppercase",
                        letterSpacing: "0.5px",
                      }}
                    >
                      Name
                    </th>
                    <th
                      style={{
                        padding: "12px 16px",
                        fontWeight: 600,
                        fontSize: FONT_SIZE.xs,
                        color: "#64748b",
                        textTransform: "uppercase",
                        letterSpacing: "0.5px",
                      }}
                    >
                      Phone
                    </th>
                    <th
                      style={{
                        padding: "12px 16px",
                        fontWeight: 600,
                        fontSize: FONT_SIZE.xs,
                        color: "#64748b",
                        textTransform: "uppercase",
                        letterSpacing: "0.5px",
                      }}
                    >
                      Company
                    </th>
                    <th
                      style={{
                        padding: "12px 16px",
                        fontWeight: 600,
                        fontSize: FONT_SIZE.xs,
                        color: "#64748b",
                        textTransform: "uppercase",
                        letterSpacing: "0.5px",
                      }}
                    >
                      Status
                    </th>
                    <th
                      style={{
                        padding: "12px 16px",
                        fontWeight: 600,
                        fontSize: FONT_SIZE.xs,
                        color: "#64748b",
                        textTransform: "uppercase",
                        letterSpacing: "0.5px",
                        textAlign: "right",
                      }}
                    >
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {managers.map((manager, idx) => {
                    const { bg, color, border } = statusColor(manager.status)
                    return (
                      <tr
                        key={manager.manager_id}
                        style={{
                          borderBottom:
                            idx === managers.length - 1
                              ? "none"
                              : "1px solid #e2e8f0",
                          transition: "background 0.2s ease",
                        }}
                        onMouseEnter={(e) =>
                          (e.currentTarget.style.background = "#f8fafc")
                        }
                        onMouseLeave={(e) =>
                          (e.currentTarget.style.background = "transparent")
                        }
                      >
                        <td style={{ padding: "12px 16px" }}>
                          <div
                            style={{
                              display: "flex",
                              alignItems: "center",
                              gap: 10,
                            }}
                          >
                            <div
                              style={{
                                width: 36,
                                height: 36,
                                borderRadius: "50%",
                                background: manager.profile_picture_url ? "transparent" : "linear-gradient(135deg, #0070f3 0%, #0056d4 100%)",
                                color: "white",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                fontWeight: 600,
                                fontSize: FONT_SIZE.base,
                                flexShrink: 0,
                                overflow: "hidden",
                              }}
                            >
                              {manager.profile_picture_url ? (
                            <Image src={manager.profile_picture_url} alt={manager.full_name} width={40} height={40} unoptimized style={{ objectFit: "cover" }} />
                              ) : (
                                manager.full_name.charAt(0).toUpperCase()
                              )}
                            </div>
                            <span
                              style={{
                                color: "#0f172a",
                                fontSize: FONT_SIZE.base,
                                fontWeight: 500,
                              }}
                            >
                              {manager.full_name}
                            </span>
                          </div>
                        </td>
                        <td
                          style={{
                            padding: "12px 16px",
                            color: "#475569",
                            fontSize: FONT_SIZE.sm,
                          }}
                        >
                          {manager.phone_number || (
                            <span
                              style={{
                                color: "#94a3b8",
                                fontStyle: "italic",
                              }}
                            >
                              Not provided
                            </span>
                          )}
                        </td>
                        <td
                          style={{
                            padding: "12px 16px",
                            color: "#475569",
                            fontSize: FONT_SIZE.sm,
                          }}
                        >
                          {manager.company_name}
                        </td>
                        <td style={{ padding: "12px 16px" }}>
                          <span
                            style={{
                              padding: "4px 10px",
                              borderRadius: 6,
                              fontSize: FONT_SIZE.xs,
                              background: bg,
                              color: color,
                              border: `1px solid ${border}`,
                              fontWeight: 500,
                              display: "inline-block",
                            }}
                          >
                            {manager.status}
                          </span>
                        </td>
                        <td
                          style={{
                            padding: "12px 16px",
                            textAlign: "right",
                          }}
                        >
                          <div
                            style={{
                              display: "flex",
                              gap: 6,
                              justifyContent: "flex-end",
                            }}
                          >
                            <button
                              onClick={() => {
                                setEditingManager(manager)
                                setEditName(manager.full_name)
                                setEditPhone(manager.phone_number || "")
                                setMessage("")
                              }}
                              disabled={!canEdit}
                              style={{
                                padding: "6px 10px",
                                cursor: !canEdit ? "not-allowed" : "pointer",
                                borderRadius: 5,
                                border: "1px solid #e2e8f0",
                                color: "#0070f3",
                                background: !canEdit ? "#94a3b8" : "#f0f7ff",
                                fontSize: FONT_SIZE.sm,
                                fontWeight: 500,
                                transition: "all 0.2s",
                                minHeight: 32,
                                minWidth: 32,
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                              }}
                              onMouseEnter={(e) => {
                                if (canEdit) { e.currentTarget.style.background = "#e0efff"; e.currentTarget.style.borderColor = "#0070f3" }
                              }}
                              onMouseLeave={(e) => {
                                if (canEdit) { e.currentTarget.style.background = "#f0f7ff"; e.currentTarget.style.borderColor = "#e2e8f0" }
                              }}
                            >
                              Edit
                            </button>
                            <button
                              onClick={() => {
                                setDeletingId(manager.manager_id)
                                setMessage("")
                              }}
                              disabled={!canEdit}
                              style={{
                                padding: "6px 10px",
                                cursor: !canEdit ? "not-allowed" : "pointer",
                                borderRadius: 5,
                                border: "1px solid #fee2e2",
                                color: "#ef4444",
                                background: !canEdit ? "#94a3b8" : "#fef2f2",
                                fontSize: FONT_SIZE.sm,
                                fontWeight: 500,
                                transition: "all 0.2s",
                                minHeight: 32,
                                minWidth: 32,
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                              }}
                              onMouseEnter={(e) => {
                                if (canEdit) e.currentTarget.style.background = "#fee2e2"
                              }}
                              onMouseLeave={(e) => {
                                if (canEdit) e.currentTarget.style.background = "#fef2f2"
                              }}
                            >
                              Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}

      {/* Modals */}
      {(showInviteModal || editingManager || deletingId) && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(15, 23, 42, 0.6)",
            backdropFilter: "blur(4px)",
            display: "flex",
            alignItems: isMobile ? "flex-end" : "center",
            justifyContent: "center",
            zIndex: 100,
            padding: isMobile ? 0 : 24,
            animation: "fadeIn 0.2s ease-out",
          }}
        >
          <style>{`@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } } @keyframes slideUp { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }`}</style>
          <div
            style={{
              background: "white",
              borderRadius: isMobile ? "20px 20px 0 0" : 12,
              padding: isMobile ? "28px 20px" : 32,
              width: "100%",
              maxWidth: 420,
              maxHeight: "90vh",
              overflowY: "auto",
              boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.25)",
              animation: "slideUp 0.3s cubic-bezier(0.16, 1, 0.3, 1)",
            }}
          >
            {/* Invite Modal */}
            {showInviteModal && (
              <>
                {inviteResult ? (
                  <InviteSuccessCard
                    tempPassword={inviteResult.tempPassword}
                    email={inviteResult.email}
                    onClose={() => { closeModals(); setInviteResult(null) }}
                  />
                ) : (
                  <>
                    <div
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        marginBottom: 24,
                      }}
                    >
                      <h3
                        style={{
                          margin: 0,
                          color: "#0f172a",
                          fontSize: FONT_SIZE.xl,
                          fontWeight: 700,
                        }}
                      >
                        Add Station Manager
                      </h3>
                      <button
                        onClick={closeModals}
                        style={{
                          background: "none",
                          border: "none",
                          color: "#94a3b8",
                          cursor: "pointer",
                          padding: 0,
                          width: 32,
                          height: 32,
                          display: "flex",
