            padding: "8px 12px",
            borderRadius: 8,
            border: `1.5px solid ${filterProduct ? "#0070f3" : "#e2e8f0"}`,
            fontSize: FONT_SIZE.sm,
            color: filterProduct ? "#0f172a" : "#94a3b8",
            background: "white",
            minHeight: 40,
            outline: "none",
            cursor: "pointer",
            flex: isMobile ? "1 1 100%" : "1 1 160px",
