                      </tr>
                      {group.sales.map((sale) => (
                        <tr key={sale.sale_id} style={{ borderBottom: "1px solid #e2e8f0", transition: "background 0.2s ease" }} onMouseEnter={e => e.currentTarget.style.background = "#f8fafc"} onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                          <td style={{ padding: "12px 16px", color: "#0f172a", fontSize: FONT_SIZE.base, fontWeight: 600 }}>{sale.store_name}</td>
                          <td style={{ padding: "12px 16px", color: "#0f172a", fontSize: FONT_SIZE.base }}>{sale.product}</td>
                          <td style={{ padding: "12px 16px", color: "#0f172a", fontSize: FONT_SIZE.base, fontWeight: 500 }}>{sale.quantity}</td>
                          <td style={{ padding: "12px 16px", color: "#64748b", fontSize: FONT_SIZE.sm }}>{formatAmount(sale.price_per_bag)}</td>
                          <td style={{ padding: "12px 16px", color: "#10b981", fontSize: FONT_SIZE.base, fontWeight: 600 }}>{formatAmount(sale.total_amount)}</td>
                          <td style={{ padding: "12px 16px", color: "#64748b", fontSize: FONT_SIZE.sm }}>{sale.customer_name || "ΓÇö"}</td>
                          <td style={{ padding: "12px 16px", color: "#64748b", fontSize: FONT_SIZE.sm }}>{sale.payment_mode}</td>
                          <td style={{ padding: "12px 16px", color: "#64748b", fontSize: FONT_SIZE.sm }}>{sale.delivery_mode}{sale.truck_plate ? ` (${sale.truck_plate})` : ""}</td>
                          <td style={{ padding: "12px 16px", color: "#64748b", fontSize: FONT_SIZE.sm }}>{sale.broker_name || "ΓÇö"}</td>
                          <td style={{ padding: "12px 16px" }}>
                            <span style={{ padding: "6px 10px", borderRadius: 14, fontSize: FONT_SIZE.xs, fontWeight: 600, background: sale.status === "Confirmed" ? "#ecfdf5" : sale.status === "Pending" ? "#fffbeb" : sale.status === "Rejected" ? "#fef2f2" : "#f1f5f9", color: sale.status === "Confirmed" ? "#10b981" : sale.status === "Pending" ? "#f5a623" : sale.status === "Rejected" ? "#ef4444" : "#475569", border: `1.5px solid ${sale.status === "Confirmed" ? "#10b981" : sale.status === "Pending" ? "#f5a623" : sale.status === "Rejected" ? "#ef4444" : "#cbd5e1"}` }}>
                              {sale.status}
                            </span>
                            {sale.status === "Rejected" && sale.rejection_reason && (
                              <div style={{ marginTop: 6, padding: "6px 8px", background: "white", borderRadius: 6, border: "1px solid #fecaca", color: "#7f1d1d", fontSize: FONT_SIZE.xs, fontStyle: "italic", maxWidth: 220 }}>
                                &ldquo;{sale.rejection_reason}&rdquo;
                              </div>
                            )}
                          </td>
                          <td style={{ padding: "12px 16px", color: "#94a3b8", fontSize: FONT_SIZE.xs }}>{new Date(sale.sold_at).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</td>
                        </tr>
                      ))}
                    </Fragment>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}
    </div>
  )
}

"use client"

import { FONT_SIZE } from "@/lib/constants"
import { usePolling } from "@/lib/hooks/usePolling"

import { useState, useEffect, useMemo } from "react"
import { supabase } from "@/lib/supabase"

type ActiveTruck = {
  trip_id: string
  plate_number: string
  kbnl_truck_no: string | null
  loaded_quantity: number
  remaining: number
  driver_name: string
  driver_phone: string
  trip_status: string
  route_points: string[]
}

type ViewMode = "card" | "table"

function useBreakpoint() {
  const [isDesktop, setIsDesktop] = useState(false)
  const [isMobile, setIsMobile] = useState(true)

  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth < 640)
      setIsDesktop(window.innerWidth >= 640)
    }
    handleResize()
    window.addEventListener("resize", handleResize)
    return () => window.removeEventListener("resize", handleResize)
  }, [])

  return { isMobile, isDesktop }
}

const getPillStyle = (filter: string, isActive: boolean) => {
  if (!isActive) {
    return { bg: "white", textColor: "#64748b", borderColor: "#e2e8f0" }
  }
  if (filter === "All") {
    return { bg: "#111", textColor: "white", borderColor: "#111" }
  } else if (filter === "In transit") {
    return { bg: "#ebf8ff", textColor: "#0070f3", borderColor: "#0070f3" }
  } else if (filter === "On hold") {
    return { bg: "#fffbeb", textColor: "#f5a623", borderColor: "#f5a623" }
  }
  return { bg: "white", textColor: "#64748b", borderColor: "#e2e8f0" }
}



const statusColor = (status: string) =>
  status === "In transit" ? "#0070f3" :
  status === "On hold" ? "#f5a623" :
  status === "Completed" ? "#10b981" : "#64748b"

const remainingColor = (remaining: number, loaded: number) => {
  if (remaining === 0) return "#ef4444"
  if (remaining < loaded * 0.2) return "#f59e0b"
  return "#10b981"
}

type Props = {
  plates?: string[]
}

export default function TruckMonitorSection({ plates }: Props) {
  useBreakpoint()
  const [trucks, setTrucks] = useState<ActiveTruck[]>([])
  const [loading, setLoading] = useState(true)
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null)
  const [filterStatus, setFilterStatus] = useState("All")
  const [viewMode, setViewMode] = useState<ViewMode>("card")

  const platesKey = useMemo(() => plates?.join(",") ?? "", [plates])

  const filterOptions = ["All", "In transit", "On hold"]

  async function fetchActiveTrucks() {
    const { data: trips } = await supabase.rpc("get_active_mdd_trucks_remaining", {
      p_plates: plates && plates.length > 0 ? plates : undefined,
    })

    if (!trips || trips.length === 0) {
      setTrucks([])
      setLastUpdated(new Date())
      setLoading(false)
      return
    }

    const enriched = trips.map((trip: any) => ({
      trip_id: trip.trip_id,
      plate_number: trip.plate_number,
      kbnl_truck_no: trip.kbnl_truck_no ?? null,
      loaded_quantity: trip.loaded_quantity,
      remaining: trip.remaining ?? trip.loaded_quantity,
      driver_name: trip.driver_name ?? "Unknown",
      driver_phone: trip.driver_phone ?? "ΓÇö",
      trip_status: trip.trip_status,
      route_points: trip.route_points ?? [],
    }))

    setTrucks(enriched)
    setLastUpdated(new Date())
    setLoading(false)
  }

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => {
    fetchActiveTrucks()
  }, [platesKey])

  usePolling(fetchActiveTrucks, 120000)

  const filteredTrucks = filterStatus === "All"
    ? trucks
    : trucks.filter(t => t.trip_status === filterStatus)

  return (
    <div>
      {/* Controls */}
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16, flexWrap: "wrap" }}>
        {trucks.length > 0 && (
          <div style={{ display: "flex", background: "white", border: "1px solid #e2e8f0", borderRadius: 8, padding: 4, gap: 0 }}>
            <button
              onClick={() => setViewMode("card")}
              style={{
                padding: "8px 12px", background: viewMode === "card" ? "#0070f3" : "transparent",
                color: viewMode === "card" ? "white" : "#64748b", border: "none", borderRadius: 6,
                cursor: "pointer", fontSize: FONT_SIZE.xs, fontWeight: 600,
                minWidth: 44, height: 40, display: "flex", alignItems: "center", justifyContent: "center",
              }}
              title="Card view"
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M3 3h8v8H3V3zm10 0h8v8h-8V3zM3 13h8v8H3v-8zm10 0h8v8h-8v-8z"/></svg>
            </button>
            <button
              onClick={() => setViewMode("table")}
              style={{
                padding: "8px 12px", background: viewMode === "table" ? "#0070f3" : "transparent",
                color: viewMode === "table" ? "white" : "#64748b", border: "none", borderRadius: 6,
