"use client"

import { useState, useEffect, useCallback } from "react"
import { Icon } from "@iconify/react"
import { supabase } from "@/lib/supabase"
import { apiMutate } from "@/lib/api-mutation"
import { formatAmount, parseAmount } from "@/lib/formatAmount"
import ModernInput from "@/components/ModernInput"
import CustomerSelector from "@/components/CustomerSelector"
import { useBreakpoint } from "@/app/hooks/useBreakpoint"

type Customer = { customer_id: string; full_name: string; phone_number: string; isNew?: boolean }

type SaleLine = {
  sale_id: string
  product: string
  quantity: number
  price_per_bag: number | null
  total_amount: number | null
  customer_name: string | null
  payment_mode: string
  delivery_mode: string
  tricycle_id: string | null
  truck_plate: string | null
  sold_at: string
  created_at: string
  status: string
  store_name: string
  rejection_reason: string | null
}

type SaleGroup = {
  group_id: string
  customer_name: string | null
  payment_mode: string
  delivery_mode: string
  tricycle_id: string | null
  truck_plate: string | null
  sold_at: string
  status: string
  store_name: string
  rejection_reason: string | null
  lines: SaleLine[]
}

export default function BrokerSaleConfirmations() {
  const bp = useBreakpoint()
  const isMobile = bp === "mobile"

  const [brokerId, setBrokerId] = useState<string | null>(null)
  const [activeFilter, setActiveFilter] = useState<"pending" | "confirmed" | "rejected">("pending")
  const [allGroups, setAllGroups] = useState<SaleGroup[]>([])
  const [loading, setLoading] = useState(true)

  const [confirmingGroup, setConfirmingGroup] = useState<SaleGroup | null>(null)
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null)
  const [linePrices, setLinePrices] = useState<Record<string, string>>({})
  const [rejectingGroup, setRejectingGroup] = useState<SaleGroup | null>(null)
  const [rejectReason, setRejectReason] = useState("")
  const [message, setMessage] = useState("")
  const [notification, setNotification] = useState("")
  const [submitting, setSubmitting] = useState(false)
  const [companyPriceMap, setCompanyPriceMap] = useState<Record<string, number>>({})

  useEffect(() => { initBroker() }, [])

  const initBroker = useCallback(async () => {
    const { data: { session } } = await supabase.auth.getSession()
    if (!session) { window.location.href = "/login"; return }
    setBrokerId(session.user.id)
    await Promise.all([
      fetchSales(session.user.id),
      fetchCompanyPrices(session.user.id),
    ])
    setLoading(false)
  }, [])

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { initBroker() }, [initBroker])

  async function fetchCompanyPrices(bId: string) {
    const { data, error } = await supabase
      .from("company_prices")
      .select("product_name, price_per_bag")
      .eq("broker_id", bId)
    if (!error && data) {
      const map: Record<string, number> = {}
      for (const row of data) map[row.product_name] = row.price_per_bag
      setCompanyPriceMap(map)
    }
  }

  async function fetchSales(bId: string) {
    const { data, error } = await supabase
      .from("store_sales")
      .select("sale_id, product, quantity, price_per_bag, total_amount, customer_name, payment_mode, delivery_mode, tricycle_id, truck_plate, sold_at, created_at, status, store_name, rejection_reason")
      .eq("broker_id", bId)
      .order("sold_at", { ascending: false })

    if (error) { console.error("Failed to fetch sales:", error); return }

    const groups = groupSales(data || [])
    setAllGroups(groups)
  }

  function groupSales(sales: SaleLine[]): SaleGroup[] {
    return sales.reduce<SaleGroup[]>((groups, sale) => {
      const groupId = [
        sale.sold_at.split("T")[0],
        sale.customer_name ?? "",
        sale.payment_mode,
        sale.delivery_mode,
        sale.status,
      ].join("|")

      const existing = groups.find(g => g.group_id === groupId)

      if (existing) {
        existing.lines.push(sale)
        return groups
      }

      groups.push({
        group_id: groupId,
        customer_name: sale.customer_name,
        payment_mode: sale.payment_mode,
        delivery_mode: sale.delivery_mode,
        tricycle_id: sale.tricycle_id,
        truck_plate: sale.truck_plate,
        sold_at: sale.sold_at,
        status: sale.status,
        store_name: sale.store_name,
        rejection_reason: sale.rejection_reason,
        lines: [sale],
      })

      return groups
    }, [])
  }

  function openConfirmModal(group: SaleGroup) {
    const prices: Record<string, string> = {}
    for (const line of group.lines) {
      const companyPrice = companyPriceMap[line.product]
      if (companyPrice) {
        prices[line.sale_id] = formatAmount(String(companyPrice))
      } else if (line.price_per_bag) {
        prices[line.sale_id] = formatAmount(String(line.price_per_bag))
      } else {
        prices[line.sale_id] = ""
      }
    }
    setConfirmingGroup(group)
    setSelectedCustomer(null)
    setLinePrices(prices)
    setMessage("")
  }

  function closeConfirmModal() {
    setConfirmingGroup(null)
    setSelectedCustomer(null)
    setLinePrices({})
    setMessage("")
  }

  function openRejectModal(group: SaleGroup) {
    setRejectingGroup(group)
    setRejectReason("")
    setMessage("")
  }

  function closeRejectModal() {
    setRejectingGroup(null)
    setRejectReason("")
    setMessage("")
  }

  async function handleConfirm() {
    if (!confirmingGroup) return

    for (const line of confirmingGroup.lines) {
      if (!linePrices[line.sale_id]) {
        setMessage(`Enter price per bag for ${line.product}`)
        return
      }
    }

    setSubmitting(true)
    try {
      const customerName = selectedCustomer?.full_name || confirmingGroup.customer_name
      const confirmed: string[] = []
      const unconfirmed: string[] = []

      for (const line of confirmingGroup.lines) {
        const price = parseAmount(linePrices[line.sale_id])

        const updateData: Record<string, unknown> = {
          price_per_bag: price,
          status: "Confirmed",
        }
        if (customerName) updateData.customer_name = customerName

        const { data, error } = await apiMutate("finance", {
          action: "update",
          table: "store_sales",
          data: updateData,
          filters: { sale_id: line.sale_id, status: "Pending", broker_id: brokerId },
        })

        if (error || !data || (Array.isArray(data) && data.length === 0)) {
          unconfirmed.push(line.product)
        } else {
          confirmed.push(line.product)
        }
      }

      if (confirmed.length > 0) {
        closeConfirmModal()
        if (brokerId) fetchSales(brokerId)
        if (unconfirmed.length > 0) {
          setNotification(`Confirmed ${confirmed.join(", ")}, but could not confirm ${unconfirmed.join(", ")}`)
        }
      } else {
        setMessage(`Could not confirm: ${unconfirmed.join(", ")}`)
        setSubmitting(false)
        return
      }
    } catch {
      setMessage("Failed to confirm sale. Please try again.")
    } finally {
      setSubmitting(false)
    }
  }

  async function handleReject() {
    if (!rejectingGroup || !rejectReason.trim()) {
      setMessage("Please provide a reason")
      return
    }

    setSubmitting(true)
    try {
      const updateData: Record<string, unknown> = {
        status: "Rejected",
        rejection_reason: rejectReason.trim(),
      }
      const saleIds = rejectingGroup.lines.map(line => line.sale_id)

      const { data, error } = await apiMutate("finance", {
        action: "update",
        table: "store_sales",
        data: updateData,
        filters: { sale_id: saleIds, status: "Pending", broker_id: brokerId },
      })

      if (error) {
        setMessage("Could not reject the selected sales")
        setSubmitting(false)
        return
      }

      const rejected = Array.isArray(data) ? data.length : 0
      if (rejected === 0) {
        setMessage("Could not reject any of the selected sales")
        setSubmitting(false)
        return
      }
      if (rejected < saleIds.length) {
        closeRejectModal()
        if (brokerId) fetchSales(brokerId)
        setNotification(`Rejected ${rejected} of ${saleIds.length} sales (${saleIds.length - rejected} had no matching pending sale)`)
        setSubmitting(false)
        return
      }

      closeRejectModal()
      if (brokerId) fetchSales(brokerId)
    } catch {
      setMessage("Failed to reject sale. Please try again.")
    } finally {
      setSubmitting(false)
    }
  }

  useEffect(() => {
    if (!notification) return
    const t = setTimeout(() => setNotification(""), 5000)
    return () => clearTimeout(t)
  }, [notification])

  if (loading) return <p style={{ color: "#888" }}>LoadingΓÇª</p>

  const pendingGroups = allGroups.filter(g => g.status === "Pending")
  const confirmedGroups = allGroups.filter(g => g.status === "Confirmed")
  const rejectedGroups = allGroups.filter(g => g.status === "Rejected")

  const visibleGroups = activeFilter === "pending" ? pendingGroups
    : activeFilter === "confirmed" ? confirmedGroups
    : rejectedGroups

  const filterOptions = [
    { key: "pending" as const, label: "Pending", count: pendingGroups.length, color: "#f5a623" },
    { key: "confirmed" as const, label: "Confirmed", count: confirmedGroups.length, color: "#10b981" },
    { key: "rejected" as const, label: "Rejected", count: rejectedGroups.length, color: "#ef4444" },
  ]

  const inputStyle: React.CSSProperties = {
    width: "100%", padding: isMobile ? "14px 12px" : "11px 12px",
    boxSizing: "border-box", borderRadius: 8, border: "1.5px solid #e5e5e5",
    fontSize: isMobile ? 16 : 14, background: "white", color: "#171717",
    minHeight: isMobile ? 48 : 42
  }
  const labelStyle: React.CSSProperties = {
    fontWeight: "600", display: "block", marginBottom: 6,
    fontSize: isMobile ? 14 : 13, color: "#444"
  }
  const modalOverlay: React.CSSProperties = {
    position: "fixed", inset: 0, background: "rgba(0,0,0,0.5)",
    display: "flex", alignItems: isMobile ? "flex-end" : "center",
    justifyContent: "center", zIndex: 100
  }
  const modalBox: React.CSSProperties = {
    background: "white", borderRadius: isMobile ? "20px 20px 0 0" : 14,
    padding: isMobile ? "24px 20px 40px" : 32,
    width: isMobile ? "100%" : 500,
    maxHeight: isMobile ? "92vh" : "88vh",
    overflowY: "auto", boxShadow: "0 8px 32px rgba(0,0,0,0.2)"
  }

  const PAYMENT_LABELS: Record<string, string> = {
    Cash: "Cash", Transfer: "Transfer", POS: "POS", Broker: "Broker"
  }
  const DELIVERY_LABELS: Record<string, string> = {
    self: "Self", tricycle: "Tricycle", truck: "Truck"
  }

  function formatDate(dateStr: string) {
    return new Date(dateStr).toLocaleDateString("en-NG", {
      day: "numeric", month: "short", year: "numeric"
    })
  }

  return (
    <div>
      {notification && (
        <div style={{ display: "flex", alignItems: "center", gap: 6, color: "#ef4444", marginBottom: 14, fontSize: 13, padding: "10px 14px", background: "#fef2f2", borderRadius: 8 }}>
          <Icon icon="mdi:alert-circle" width={15} />{notification}
        </div>
      )}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 20, flexWrap: "wrap", gap: 8 }}>
        <h2 style={{ margin: 0, fontSize: isMobile ? 22 : 20, color: "#171717" }}>Store Sales</h2>
      </div>

      <div style={{ display: "flex", gap: 8, marginBottom: 20, overflowX: "auto", scrollbarWidth: "none", paddingBottom: 8 }}>
        {filterOptions.map(({ key, label, count, color }) => {
          const isActive = activeFilter === key
          return (
            <button key={key} onClick={() => setActiveFilter(key)} style={{
              padding: isMobile ? "9px 16px" : "7px 14px", borderRadius: 20, fontSize: 13, cursor: "pointer",
              border: `1.5px solid ${isActive ? color : "#e2e8f0"}`,
              background: isActive ? `${color}1a` : "white",
              color: isActive ? color : "#64748b",
              fontWeight: isActive ? 600 : 500,
              minHeight: 38, whiteSpace: "nowrap", display: "flex", alignItems: "center", gap: 5, flexShrink: 0,
              transition: "all 0.2s ease",
            }}>
              {label}
              {count > 0 && (
                <span style={{
                  background: isActive ? "rgba(255,255,255,0.5)" : "#f1f5f9",
                  color: isActive ? color : "#64748b",
                  borderRadius: 10, padding: "1px 7px", fontSize: 11, fontWeight: 600,
                }}>
                  {count}
                </span>
              )}
            </button>
          )
        })}
      </div>

      {visibleGroups.length === 0 ? (
        <div style={{ textAlign: "center", padding: "60px 20px", color: "#bbb" }}>
          <Icon icon="mdi:store-off" width={40} style={{ display: "block", margin: "0 auto 10px" }} />
          <p style={{ margin: 0, fontSize: 14 }}>No {activeFilter} store sales</p>
        </div>
      ) : (
        visibleGroups.map((group) => (
          <div key={group.group_id} style={{
            background: "white", border: "1px solid #eee", borderRadius: 12,
            padding: isMobile ? "14px 16px" : "16px 20px", marginBottom: 10,
            boxShadow: "0 1px 4px rgba(0,0,0,0.05)"
          }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 10 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <div style={{ width: 36, height: 36, borderRadius: 9, background: "#fef3c7", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  <Icon icon="mdi:store" width={18} color="#f59e0b" />
                </div>
                <div>
                  <p style={{ margin: 0, fontWeight: "bold", fontSize: isMobile ? 15 : 14, color: "#171717" }}>
                    {group.store_name}
                  </p>
                  <p style={{ margin: "2px 0 0", fontSize: 12, color: "#888" }}>
                    {group.customer_name || "Walk-in"} ┬╖ {PAYMENT_LABELS[group.payment_mode] || group.payment_mode}
                  </p>
                </div>
              </div>
              <p style={{ margin: 0, fontSize: 11, color: "#aaa", flexShrink: 0, paddingLeft: 8 }}>
                {formatDate(group.sold_at)}
              </p>
            </div>

            <div style={{ padding: "10px 12px", background: "#f9f9f9", borderRadius: 8, marginBottom: 12 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
                <span style={{ fontSize: 12, color: "#888" }}>
                  <Icon icon="mdi:van-passenger" width={14} style={{ verticalAlign: "middle", marginRight: 4 }} />
                  {DELIVERY_LABELS[group.delivery_mode] || group.delivery_mode}
                </span>
                {group.truck_plate && <span style={{ fontSize: 12, color: "#888" }}>┬╖ {group.truck_plate}</span>}
              </div>
              {group.lines.map((line) => (
                <div key={line.sale_id} style={{
                  display: "flex", justifyContent: "space-between", alignItems: "center",
                  padding: "4px 0", borderBottom: "1px solid #eee"
                }}>
                  <div>
                    <span style={{ fontWeight: 600, fontSize: 14, color: "#171717" }}>{line.product}</span>
                    <span style={{ fontSize: 13, color: "#555", marginLeft: 8 }}>├ù {line.quantity}</span>
                  </div>
                  {line.price_per_bag && (
                    <span style={{ fontSize: 13, color: "#555" }}>
                      Γéª{formatAmount(String(line.price_per_bag))}/bag
                    </span>
                  )}
                </div>
              ))}
            </div>

            {activeFilter === "pending" && (
              <div style={{ display: "flex", gap: 8 }}>
                <button onClick={() => openConfirmModal(group)} style={{
                  flex: 1, padding: "11px 0", background: "#0070f3", color: "white",
                  border: "none", borderRadius: 8, cursor: "pointer", fontWeight: "bold",
                  fontSize: isMobile ? 14 : 13, minHeight: 44,
                  display: "flex", alignItems: "center", justifyContent: "center", gap: 6
                }}>
                  <Icon icon="mdi:check-circle" width={16} />
                  Confirm
                </button>
                <button onClick={() => openRejectModal(group)} style={{
                  flex: 1, padding: "11px 0", background: "white", color: "#ef4444",
                  border: "1.5px solid #ef4444", borderRadius: 8, cursor: "pointer",
                  fontWeight: "bold", fontSize: isMobile ? 14 : 13, minHeight: 44,
                  display: "flex", alignItems: "center", justifyContent: "center", gap: 6
                }}>
                  <Icon icon="mdi:close-circle" width={16} />
                  Reject
                </button>
              </div>
            )}
            {activeFilter === "confirmed" && (
              <div style={{ display: "flex", alignItems: "center", gap: 6, padding: "8px 10px", background: "#ecfdf5", borderRadius: 7 }}>
                <Icon icon="mdi:check-circle" width={16} color="#10b981" />
                <span style={{ fontSize: 13, color: "#10b981", fontWeight: "600" }}>Confirmed</span>
              </div>
            )}
            {activeFilter === "rejected" && (
              <div style={{ width: "100%" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 6, padding: "8px 10px", background: "#fef2f2", borderRadius: 7 }}>
                  <Icon icon="mdi:close-circle" width={16} color="#ef4444" />
                  <span style={{ fontSize: 13, color: "#ef4444", fontWeight: "600" }}>Rejected</span>
                </div>
                {group.rejection_reason && (
                  <div style={{ display: "flex", gap: 10, alignItems: "flex-start", marginTop: 8, padding: 10, background: "#fef2f2", borderRadius: 8, border: "1px solid #fecaca" }}>
                    <div style={{ background: "#ef4444", color: "white", padding: 3, borderRadius: "50%", flexShrink: 0, marginTop: 1 }}>
                      <Icon icon="mdi:close" width={12} height={12} />
                    </div>
                    <div>
                      <p style={{ margin: "0 0 4px 0", color: "#ef4444", fontSize: 12, fontWeight: 600 }}>Rejection reason</p>
                      <div style={{ padding: "8px 10px", background: "white", borderRadius: 6, border: "1px solid #fecaca", color: "#7f1d1d", fontSize: 12, fontStyle: "italic" }}>
                        &ldquo;{group.rejection_reason}&rdquo;
                      </div>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        ))
      )}

      {confirmingGroup && (
        <div onClick={closeConfirmModal} style={modalOverlay}>
          <div onClick={e => e.stopPropagation()} style={modalBox}>
            {isMobile && <div style={{ width: 40, height: 4, background: "#e0e0e0", borderRadius: 2, margin: "0 auto 20px" }} />}
            <h3 style={{ margin: "0 0 4px", color: "#171717", fontSize: isMobile ? 18 : 16 }}>Confirm Sale</h3>
            <p style={{ color: "#888", fontSize: 13, marginBottom: 20 }}>
              {confirmingGroup.store_name} ┬╖ {formatDate(confirmingGroup.sold_at)}
            </p>

            <div style={{ padding: "12px 14px", background: "#f9f9f9", borderRadius: 10, marginBottom: 20 }}>
              <p style={{ margin: "0 0 8px", fontSize: 12, color: "#888" }}>
                {PAYMENT_LABELS[confirmingGroup.payment_mode] || confirmingGroup.payment_mode} ┬╖ {DELIVERY_LABELS[confirmingGroup.delivery_mode] || confirmingGroup.delivery_mode}
              </p>
            </div>

            <div style={{ marginBottom: 16 }}>
              <label style={labelStyle}>Customer (correct if needed)</label>
              <CustomerSelector
                key={confirmingGroup.group_id}
                onSelect={(c) => setSelectedCustomer(c)}
                initialValue={confirmingGroup.customer_name ?? ""}
              />
            </div>

            {confirmingGroup.lines.map((line) => {
              const companyPrice = companyPriceMap[line.product]
              const enteredPrice = parseAmount(linePrices[line.sale_id])
              const showDiscount = companyPrice && enteredPrice && enteredPrice !== companyPrice
              return (
                <div key={line.sale_id} style={{ marginBottom: 16 }}>
                  <label style={labelStyle}>
                    {line.product} ├ù {line.quantity} ΓÇö Price Per Bag (Γéª) *
                  </label>
                  {companyPrice && (
                    <div style={{ padding: "8px 10px", background: "#f0f7ff", borderRadius: 7, marginBottom: 6, fontSize: 12, color: "#0070f3", fontWeight: 500, display: "flex", alignItems: "center", gap: 6 }}>
                      <Icon icon="mdi:information-outline" width={14} />
                      Company price: {formatAmount(String(companyPrice))}
                    </div>
                  )}
                  <ModernInput
                    type="text" inputMode="numeric"
                    placeholder={companyPrice ? formatAmount(String(companyPrice)) : "e.g. 10,500"}
                    value={linePrices[line.sale_id] || ""}
                    onChange={(e) => {
                      setLinePrices(prev => ({ ...prev, [line.sale_id]: formatAmount(e.target.value) }))
                      setMessage("")
                    }}
                    style={inputStyle}
                  />
                  {showDiscount && (
                    <div style={{ marginTop: 6, padding: "6px 10px", background: enteredPrice! < companyPrice ? "#fef9c3" : "#ecfdf5", borderRadius: 6, fontSize: 12, color: enteredPrice! < companyPrice ? "#854d0e" : "#166534", display: "flex", alignItems: "center", gap: 6 }}>
                      <Icon icon={enteredPrice! < companyPrice ? "mdi:tag-outline" : "mdi:tag-arrow-up-outline"} width={14} />
                      {enteredPrice! < companyPrice ? "Discount" : "Sale price"}: {formatAmount(String(enteredPrice))} vs {formatAmount(String(companyPrice))}
                    </div>
                  )}
                </div>
              )
            })}

            {message && (
              <div style={{ display: "flex", alignItems: "center", gap: 6, color: "#ef4444", marginBottom: 14, fontSize: 13 }}>
                <Icon icon="mdi:alert-circle" width={15} />{message}
              </div>
            )}

            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={closeConfirmModal} style={{
                flex: 1, padding: "13px 0", background: "white", border: "1.5px solid #e5e5e5",
                borderRadius: 10, cursor: "pointer", fontSize: 15, minHeight: 50, fontWeight: "bold"
              }}>
                Cancel
              </button>
              <button onClick={handleConfirm} disabled={submitting} style={{
                flex: 1, padding: "13px 0", background: submitting ? "#ccc" : "#0070f3",
                color: "white", border: "none", borderRadius: 10,
                cursor: submitting ? "not-allowed" : "pointer", fontSize: 15, minHeight: 50,
                fontWeight: "bold", display: "flex", alignItems: "center", justifyContent: "center", gap: 6
              }}>
                {submitting
                  ? <><Icon icon="mdi:loading" width={16} style={{ animation: "spin 1s linear infinite" }} />ConfirmingΓÇª</>
                  : <><Icon icon="mdi:check-circle" width={16} />Confirm Sale</>
                }
              </button>
            </div>
          </div>
        </div>
      )}

      {rejectingGroup && (
        <div onClick={closeRejectModal} style={modalOverlay}>
          <div onClick={e => e.stopPropagation()} style={modalBox}>
            {isMobile && <div style={{ width: 40, height: 4, background: "#e0e0e0", borderRadius: 2, margin: "0 auto 20px" }} />}
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
              <div style={{ width: 38, height: 38, borderRadius: 10, background: "#fef2f2", display: "flex", alignItems: "center", justifyContent: "center" }}>
                <Icon icon="mdi:close-circle" width={20} color="#ef4444" />
              </div>
              <h3 style={{ margin: 0, color: "#ef4444", fontSize: isMobile ? 18 : 16 }}>Reject Sale</h3>
            </div>
            <p style={{ color: "#888", fontSize: 13, marginBottom: 20 }}>
              {rejectingGroup.store_name} ┬╖ {formatDate(rejectingGroup.sold_at)}
            </p>

            <div style={{ marginBottom: 24 }}>
              <label style={labelStyle}>Reason for Rejection *</label>
              <ModernInput
                as="textarea"
                placeholder="e.g. This sale was not authorizedΓÇª"
                value={rejectReason}
                onChange={e => { setRejectReason(e.target.value); setMessage("") }}
                rows={4}
                style={{ ...inputStyle, resize: "none", minHeight: 110 }}
              />
            </div>

            {message && (
              <div style={{ display: "flex", alignItems: "center", gap: 6, color: "#ef4444", marginBottom: 14, fontSize: 13 }}>
                <Icon icon="mdi:alert-circle" width={15} />{message}
              </div>
            )}

            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={closeRejectModal} style={{
                flex: 1, padding: "13px 0", background: "white", border: "1.5px solid #e5e5e5",
                borderRadius: 10, cursor: "pointer", fontSize: 15, minHeight: 50, fontWeight: "bold"
              }}>
                Cancel
              </button>
              <button onClick={handleReject} disabled={submitting} style={{
                flex: 1, padding: "13px 0", background: submitting ? "#ccc" : "#ef4444",
                color: "white", border: "none", borderRadius: 10,
                cursor: submitting ? "not-allowed" : "pointer", fontSize: 15, minHeight: 50,
                fontWeight: "bold", display: "flex", alignItems: "center", justifyContent: "center", gap: 6
              }}>
                {submitting
                  ? <><Icon icon="mdi:loading" width={16} style={{ animation: "spin 1s linear infinite" }} />RejectingΓÇª</>
                  : <><Icon icon="mdi:close-circle" width={16} />Reject Sale</>
                }
              </button>
            </div>
          </div>
        </div>
      )}

      <style>{`@keyframes spin { from { transform: rotate(0deg) } to { transform: rotate(360deg) } }`}</style>
    </div>
  )
}

"use client"

import { useState, useEffect } from "react"
import { supabase } from "@/lib/supabase"
import CustomerPayments from "@/components/CustomerPayments"
import { useBreakpoint } from "@/app/hooks/useBreakpoint"

export default function BrokerPayments() {
  const bp = useBreakpoint()
  const isMobile = bp === "mobile"

  const [brokerId, setBrokerId] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)

  async function initBroker() {
    const { data: { session } } = await supabase.auth.getSession()
    if (!session) { window.location.href = "/login"; return }
    setBrokerId(session.user.id)
    setLoading(false)
  }

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => {
    initBroker()
  }, [])

  if (loading || !brokerId) {
    return <p style={{ color: "#888", fontSize: 15 }}>LoadingΓÇª</p>
  }

  return <CustomerPayments brokerId={brokerId} />
}

"use client"

import { useState, useEffect, useCallback } from "react"
import { Icon } from "@iconify/react"
import { supabase } from "@/lib/supabase"
import { apiMutate } from "@/lib/api-mutation"
import { formatAmount, parseAmount } from "@/lib/formatAmount"
import ModernInput from "@/components/ModernInput"
import CustomerSelector from "@/components/CustomerSelector"
import { useBreakpoint } from "@/app/hooks/useBreakpoint"

type Customer = {
  customer_id: string
  full_name: string
  phone_number: string
}

type Stop = {
  stop_id: string
  trip_id: string
  customer_id: string | null
  customer_name: string
  quantity_offloaded: number
  stop_location: string
  stop_time: string
  plate_number: string
  material_centre: string
  atc: string | null
  order_no: string | null
  child_order_no: string | null
  product: string
  confirmed: boolean
  disputed: boolean
}

export default function MyStops() {
  const bp = useBreakpoint()
  const isMobile = bp === "mobile"

  const [brokerId, setBrokerId] = useState<string | null>(null)
  const [activeFilter, setActiveFilter] = useState<"pending" | "confirmed" | "disputed">("pending")
  const [allStops, setAllStops] = useState<Stop[]>([])
  const [loading, setLoading] = useState(true)
  const [viewMode, setViewMode] = useState<"card" | "table">("card")

  const [selectedStop, setSelectedStop] = useState<Stop | null>(null)
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null)
  const [pricePerBag, setPricePerBag] = useState("")
  const [disputingStop, setDisputingStop] = useState<Stop | null>(null)
  const [disputeReason, setDisputeReason] = useState("")
  const [message, setMessage] = useState("")
  const [submitting, setSubmitting] = useState(false)
  const [companyPriceMap, setCompanyPriceMap] = useState<Record<string, number>>({})
  const [soldAtDifferentPrice, setSoldAtDifferentPrice] = useState(false)
  const [discount, setDiscount] = useState("")
  const [salePrice, setSalePrice] = useState("")

  const initBroker = useCallback(async () => {
    const { data: { session } } = await supabase.auth.getSession()
    if (!session) { window.location.href = "/login"; return }
    setBrokerId(session.user.id)
    const { data: priceData } = await supabase.from("company_prices").select("*")
    const priceMap: Record<string, number> = {}
    for (const p of (priceData || [])) priceMap[p.product] = p.price
    setCompanyPriceMap(priceMap)
    await fetchStops(session.user.id)
    setLoading(false)
  }, [])

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { initBroker() }, [initBroker])

  async function fetchStops(bId: string) {
    const { data: stops, error } = await supabase
      .from("Stops")
      .select(`
        stop_id, trip_id, customer_id, quantity_offloaded, stop_location, stop_time, confirmed, disputed,
        Trips!inner(plate_number, material_centre, ATC, order_no, child_order_no, product),
        Customers(full_name)
      `)
      .eq("broker_id", bId)
      .order("stop_time", { ascending: false })

    if (error) { console.error("Failed to fetch stops:", error); return }

    /* eslint-disable @typescript-eslint/no-explicit-any */
    const enriched = (stops || []).map((stop: any) => ({
      stop_id: stop.stop_id,
      trip_id: stop.trip_id,
      customer_id: stop.customer_id,
      quantity_offloaded: stop.quantity_offloaded,
      stop_location: stop.stop_location,
      stop_time: stop.stop_time,
      confirmed: stop.confirmed,
      disputed: stop.disputed,
      plate_number: stop.Trips?.plate_number ?? "Unknown",
      material_centre: stop.Trips?.material_centre ?? "",
      atc: stop.Trips?.ATC ?? null,
      order_no: stop.Trips?.order_no ?? null,
      child_order_no: stop.Trips?.child_order_no ?? null,
      product: stop.Trips?.product ?? "",
      customer_name: stop.Customers?.full_name ?? "Not provided",
    }))

    setAllStops(enriched)
  }

  function openConfirmModal(stop: Stop) {
    const cp = companyPriceMap[stop.product]
    setSelectedStop(stop)
    setSelectedCustomer(null)
    setPricePerBag(cp ? formatAmount(cp.toString()) : "")
    setSoldAtDifferentPrice(false)
    setDiscount("")
    setSalePrice("")
    setMessage("")
  }

  function closeModal() {
    setSelectedStop(null); setSelectedCustomer(null); setPricePerBag(""); setMessage(""); setSoldAtDifferentPrice(false); setDiscount(""); setSalePrice("")
  }

  function handleDiscountChange(raw: string) {
    const digits = raw.replace(/[^0-9]/g, "")
    if (digits === "") { setDiscount(""); setSalePrice(""); setPricePerBag(""); return }
    const discountVal = parseInt(digits)
    const cp = selectedStop ? companyPriceMap[selectedStop.product] ?? 0 : 0
    const saleAmount = Math.max(0, cp - discountVal)
    setDiscount(formatAmount(discountVal.toString()))
    setSalePrice(formatAmount(saleAmount.toString()))
    setPricePerBag(formatAmount(saleAmount.toString()))
    setMessage("")
  }

  function handleSalePriceChange(raw: string) {
    const digits = raw.replace(/[^0-9]/g, "")
    if (digits === "") { setSalePrice(""); setDiscount(""); setPricePerBag(""); return }
    const saleVal = parseInt(digits)
    const cp = selectedStop ? companyPriceMap[selectedStop.product] ?? 0 : 0
    const discountAmount = Math.max(0, cp - saleVal)
    setSalePrice(formatAmount(saleVal.toString()))
    setDiscount(formatAmount(discountAmount.toString()))
    setPricePerBag(formatAmount(saleVal.toString()))
    setMessage("")
  }

  function handleToggleDifferentPrice(checked: boolean) {
    setSoldAtDifferentPrice(checked)
    if (!checked) {
      const cp = selectedStop ? companyPriceMap[selectedStop.product] ?? 0 : 0
      setDiscount("")
      setSalePrice("")
      setPricePerBag(cp ? formatAmount(cp.toString()) : "")
    } else {
      const cp = selectedStop ? companyPriceMap[selectedStop.product] ?? 0 : 0
      setDiscount("0")
      setSalePrice(cp ? formatAmount(cp.toString()) : "")
    }
  }

  async function handleDispute() {
    if (!disputingStop || !disputeReason.trim()) { setMessage("Please provide a reason"); return }
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return

    setSubmitting(true)
    try {
      const { error } = await apiMutate("trips", {
        action: "update", table: "Stops",
        data: { disputed: true, dispute_reason: disputeReason, disputed_by: user.id },
        filters: { stop_id: disputingStop.stop_id },
      })
      if (error) { setMessage("Failed to dispute stop"); return }
      setDisputingStop(null); setDisputeReason(""); if (brokerId) fetchStops(brokerId)
    } catch {
      setMessage("Failed to dispute stop")
    } finally {
      setSubmitting(false)
    }
  }

  async function handleConfirm() {
    if (!selectedStop || !pricePerBag) { setMessage("Price per bag required"); return }
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return

    setSubmitting(true)
    try {
      const customerIdToSave = selectedCustomer?.customer_id ?? selectedStop.customer_id

      const { error } = await apiMutate("trips", {
        action: "transaction",
        sub_actions: [
          {
            action: "update", table: "Stops",
            data: { confirmed: true, customer_id: customerIdToSave, updated_by: user.id },
            filters: { stop_id: selectedStop.stop_id },
          },
          {
            action: "insert", table: "Stop_Confirmations",
            data: { stop_id: selectedStop.stop_id, broker_id: brokerId, customer_id: customerIdToSave, price_per_bag: parseAmount(pricePerBag) },
          },
        ],
      })

      if (error) { setMessage("Failed to confirm stop. Please try again."); return }
      closeModal()
      if (brokerId) fetchStops(brokerId)
    } catch {
      setMessage("Failed to confirm stop. Please try again.")
    } finally {
      setSubmitting(false)
    }
  }

  if (loading) return <p style={{ color: "#888" }}>LoadingΓÇª</p>

  const pendingStops = allStops.filter(s => !s.confirmed && !s.disputed)
  const confirmedStops = allStops.filter(s => s.confirmed)
  const disputedStops = allStops.filter(s => s.disputed)

  const visibleStops = activeFilter === "pending" ? pendingStops : activeFilter === "confirmed" ? confirmedStops : disputedStops

  const filterOptions = [
    { key: "pending" as const, label: "Pending", count: pendingStops.length, color: "#0070f3" },
    { key: "confirmed" as const, label: "Confirmed", count: confirmedStops.length, color: "#10b981" },
    { key: "disputed" as const, label: "Disputed", count: disputedStops.length, color: "#ff4444" },
  ]

  const inputStyle: React.CSSProperties = { width: "100%", padding: isMobile ? "14px 12px" : "11px 12px", boxSizing: "border-box", borderRadius: 8, border: "1.5px solid #e5e5e5", fontSize: isMobile ? 16 : 14, background: "white", color: "#171717", minHeight: isMobile ? 48 : 42 }
  const labelStyle: React.CSSProperties = { fontWeight: "600", display: "block", marginBottom: 6, fontSize: isMobile ? 14 : 13, color: "#444" }
  const modalOverlay: React.CSSProperties = { position: "fixed", inset: 0, background: "rgba(0,0,0,0.5)", display: "flex", alignItems: isMobile ? "flex-end" : "center", justifyContent: "center", zIndex: 100 }
  const modalBox: React.CSSProperties = { background: "white", borderRadius: isMobile ? "20px 20px 0 0" : 14, padding: isMobile ? "24px 20px 40px" : 32, width: isMobile ? "100%" : 420, maxHeight: isMobile ? "92vh" : "88vh", overflowY: "auto", boxShadow: "0 8px 32px rgba(0,0,0,0.2)" }

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 20, flexWrap: "wrap", gap: 8 }}>
        <h2 style={{ margin: 0, fontSize: isMobile ? 22 : 20, color: "#171717" }}>My Stops</h2>
        {allStops.length > 0 && (
          <div style={{ display: "flex", background: "white", border: "1px solid #e2e8f0", borderRadius: 8, padding: 4, gap: 0 }}>
            <button onClick={() => setViewMode("card")} style={{
              padding: "8px 12px", background: viewMode === "card" ? "#0070f3" : "transparent",
              color: viewMode === "card" ? "white" : "#64748b", border: "none", borderRadius: 6,
              cursor: "pointer", fontSize: 12, fontWeight: 600, transition: "all 0.2s ease",
              minWidth: 44, height: 40, display: "flex", alignItems: "center", justifyContent: "center",
            }} title="Card view">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M3 3h8v8H3V3zm10 0h8v8h-8V3zM3 13h8v8H3v-8zm10 0h8v8h-8v-8z"/></svg>
            </button>
            <button onClick={() => setViewMode("table")} style={{
              padding: "8px 12px", background: viewMode === "table" ? "#0070f3" : "transparent",
              color: viewMode === "table" ? "white" : "#64748b", border: "none", borderRadius: 6,
              cursor: "pointer", fontSize: 12, fontWeight: 600, transition: "all 0.2s ease",
              minWidth: 44, height: 40, display: "flex", alignItems: "center", justifyContent: "center",
            }} title="Table view">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M3 4h18v2H3V4zm0 7h18v2H3v-2zm0 7h18v2H3v-2z"/></svg>
            </button>
          </div>
        )}
      </div>

      <div style={{ display: "flex", gap: 8, marginBottom: 20, overflowX: "auto", scrollbarWidth: "none", paddingBottom: 8 }}>
        {filterOptions.map(({ key, label, count }) => {
          const isActive = activeFilter === key
          const activeBg = key === "pending" ? "rgba(0,112,243,0.1)" : key === "confirmed" ? "rgba(16,185,129,0.1)" : "rgba(239,68,68,0.1)"
          const activeColor = key === "pending" ? "#0070f3" : key === "confirmed" ? "#10b981" : "#ef4444"
          const activeBorder = key === "pending" ? "#0070f3" : key === "confirmed" ? "#10b981" : "#ef4444"
          return (
            <button key={key} onClick={() => setActiveFilter(key)} style={{
              padding: isMobile ? "9px 16px" : "7px 14px", borderRadius: 20, fontSize: 13, cursor: "pointer",
              border: `1.5px solid ${isActive ? activeBorder : "#e2e8f0"}`,
              background: isActive ? activeBg : "white",
              color: isActive ? activeColor : "#64748b",
              fontWeight: isActive ? 600 : 500,
              minHeight: 38, whiteSpace: "nowrap", display: "flex", alignItems: "center", gap: 5, flexShrink: 0,
              transition: "all 0.2s ease",
            }}>
              {label}
              {count > 0 && (
                <span style={{
                  background: isActive ? "rgba(255,255,255,0.5)" : "#f1f5f9",
                  color: isActive ? activeColor : "#64748b",
                  borderRadius: 10, padding: "1px 7px", fontSize: 11, fontWeight: 600,
                }}>
                  {count}
                </span>
              )}
            </button>
          )
        })}
      </div>

      {visibleStops.length === 0 ? (
        <div style={{ textAlign: "center", padding: "60px 20px", color: "#bbb" }}>
          <Icon icon="mdi:map-marker-off" width={40} style={{ marginBottom: 10, display: "block", margin: "0 auto 10px" }} />
          <p style={{ margin: 0, fontSize: 14 }}>No {activeFilter} stops</p>
        </div>
      ) : viewMode === "card" ? (
        visibleStops.map((stop) => (
          <div key={stop.stop_id} style={{ background: "white", border: "1px solid #eee", borderRadius: 12, padding: isMobile ? "14px 16px" : "16px 20px", marginBottom: 10, boxShadow: "0 1px 4px rgba(0,0,0,0.05)" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 10 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <div style={{ width: 36, height: 36, borderRadius: 9, background: "#f0f7ff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  <Icon icon="mdi:truck" width={18} color="#0070f3" />
                </div>
                <div>
                  <p style={{ margin: 0, fontWeight: "bold", fontSize: isMobile ? 15 : 14, color: "#171717" }}>{stop.plate_number}</p>
                  <p style={{ margin: "2px 0 0", fontSize: 12, color: "#888" }}>{stop.stop_location}</p>
                </div>
              </div>
              <p style={{ margin: 0, fontSize: 11, color: "#aaa", flexShrink: 0, paddingLeft: 8 }}>
                {new Date(stop.stop_time).toLocaleDateString("en-NG", { day: "numeric", month: "short" })}
              </p>
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, padding: "10px 12px", background: "#f9f9f9", borderRadius: 8, marginBottom: 12 }}>
              <div><p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Bags</p><p style={{ margin: "2px 0 0", fontWeight: "bold", fontSize: 14, color: "#171717" }}>{stop.quantity_offloaded}</p></div>
              <div><p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Customer</p><p style={{ margin: "2px 0 0", fontSize: 13, color: "#171717", fontWeight: "500" }}>{stop.customer_name}</p></div>
              <div><p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Loading Point</p><p style={{ margin: "2px 0 0", fontSize: 12, color: "#555" }}>{stop.material_centre}</p></div>
              {stop.order_no ? (
                <>
                  <div><p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Order No</p><p style={{ margin: "2px 0 0", fontSize: 12, color: "#555" }}>{stop.order_no}</p></div>
                  {stop.child_order_no && <div><p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Child Order</p><p style={{ margin: "2px 0 0", fontSize: 12, color: "#555" }}>{stop.child_order_no}</p></div>}
                </>
              ) : stop.atc ? (
                <div><p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>ATC</p><p style={{ margin: "2px 0 0", fontSize: 12, color: "#555" }}>{stop.atc}</p></div>
              ) : null}
            </div>

            {activeFilter === "pending" && (
              <div style={{ display: "flex", gap: 8 }}>
                <button onClick={() => openConfirmModal(stop)} style={{ flex: 1, padding: "11px 0", background: "#0070f3", color: "white", border: "none", borderRadius: 8, cursor: "pointer", fontWeight: "bold", fontSize: isMobile ? 14 : 13, minHeight: 44, display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
                  <Icon icon="mdi:check-circle" width={16} />
                  Confirm
                </button>
                <button onClick={() => { setDisputingStop(stop); setDisputeReason(""); setMessage("") }} style={{ flex: 1, padding: "11px 0", background: "white", color: "#ff4444", border: "1.5px solid #ff4444", borderRadius: 8, cursor: "pointer", fontWeight: "bold", fontSize: isMobile ? 14 : 13, minHeight: 44, display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
                  <Icon icon="mdi:alert-circle" width={16} />
                  Dispute
                </button>
              </div>
            )}
            {activeFilter === "confirmed" && <div style={{ display: "flex", alignItems: "center", gap: 6, padding: "8px 10px", background: "#ecfdf5", borderRadius: 7 }}><Icon icon="mdi:check-circle" width={16} color="#10b981" /><span style={{ fontSize: 13, color: "#10b981", fontWeight: "600" }}>Confirmed</span></div>}
            {activeFilter === "disputed" && <div style={{ display: "flex", alignItems: "center", gap: 6, padding: "8px 10px", background: "#fff0f0", borderRadius: 7 }}><Icon icon="mdi:alert-circle" width={16} color="#ff4444" /><span style={{ fontSize: 13, color: "#ff4444", fontWeight: "600" }}>Disputed</span></div>}
          </div>
        ))
      ) : (
          <div style={{ background: "white", borderRadius: 12, border: "1px solid #e2e8f0", boxShadow: "0 1px 3px rgba(0,0,0,0.05)", overflowX: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", textAlign: "left" }}>
              <thead>
                <tr style={{ background: "#f8fafc", borderBottom: "1px solid #e2e8f0" }}>
                  <th style={{ padding: "12px 16px", fontWeight: 600, fontSize: 12, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px" }}>Plate</th>
                  <th style={{ padding: "12px 16px", fontWeight: 600, fontSize: 12, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px" }}>Customer</th>
                  <th style={{ padding: "12px 16px", fontWeight: 600, fontSize: 12, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px", textAlign: "right" }}>Bags</th>
                  <th style={{ padding: "12px 16px", fontWeight: 600, fontSize: 12, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px" }}>Location</th>
                  <th style={{ padding: "12px 16px", fontWeight: 600, fontSize: 12, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px" }}>Date</th>
                  <th style={{ padding: "12px 16px", fontWeight: 600, fontSize: 12, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px" }}>Status</th>
                  <th style={{ padding: "12px 16px", fontWeight: 600, fontSize: 12, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px", textAlign: "right" }}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {visibleStops.map((stop, idx) => (
                  <tr key={stop.stop_id} style={{ borderBottom: idx === visibleStops.length - 1 ? "none" : "1px solid #e2e8f0", transition: "background 0.2s" }}
                    onMouseEnter={e => e.currentTarget.style.background = "#f8fafc"}
                    onMouseLeave={e => e.currentTarget.style.background = "transparent"}
                  >
                    <td style={{ padding: "12px 16px", color: "#0f172a", fontSize: 14, fontWeight: 500 }}>{stop.plate_number}</td>
                    <td style={{ padding: "12px 16px", color: "#475569", fontSize: 13 }}>{stop.customer_name}</td>
                    <td style={{ padding: "12px 16px", textAlign: "right", color: "#0f172a", fontSize: 14, fontWeight: 600 }}>{stop.quantity_offloaded}</td>
                    <td style={{ padding: "12px 16px", color: "#64748b", fontSize: 13 }}>{stop.stop_location}</td>
                    <td style={{ padding: "12px 16px", color: "#64748b", fontSize: 13 }}>{new Date(stop.stop_time).toLocaleDateString("en-NG", { day: "numeric", month: "short" })}</td>
                    <td style={{ padding: "12px 16px" }}>
                      {stop.confirmed ? (
                        <span style={{ padding: "4px 10px", borderRadius: 6, fontSize: 12, fontWeight: 500, background: "#d1fae5", color: "#065f46", border: "1px solid #a7f3d0", display: "inline-block" }}>Confirmed</span>
                      ) : stop.disputed ? (
                        <span style={{ padding: "4px 10px", borderRadius: 6, fontSize: 12, fontWeight: 500, background: "#fee2e2", color: "#7f1d1d", border: "1px solid #fecaca", display: "inline-block" }}>Disputed</span>
                      ) : (
                        <span style={{ padding: "4px 10px", borderRadius: 6, fontSize: 12, fontWeight: 500, background: "#f0f7ff", color: "#0c4a6e", border: "1px solid #bfdbfe", display: "inline-block" }}>Pending</span>
                      )}
                    </td>
                    <td style={{ padding: "12px 16px", textAlign: "right" }}>
                      {activeFilter === "pending" ? (
                        <div style={{ display: "flex", gap: 6, justifyContent: "flex-end" }}>
                          <button onClick={() => openConfirmModal(stop)} style={{ padding: "6px 10px", cursor: "pointer", borderRadius: 6, border: "1px solid #0070f3", color: "#0070f3", background: "#f0f7ff", fontSize: 12, fontWeight: 600, transition: "all 0.2s", minHeight: 32, display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 4 }}
                            onMouseEnter={e => { e.currentTarget.style.background = "#e0efff" }} onMouseLeave={e => { e.currentTarget.style.background = "#f0f7ff" }}>
                            <Icon icon="mdi:check-circle" width={14} /> Confirm
                          </button>
                          <button onClick={() => { setDisputingStop(stop); setDisputeReason(""); setMessage("") }} style={{ padding: "6px 10px", cursor: "pointer", borderRadius: 6, border: "1px solid #fecaca", color: "#ef4444", background: "#fef2f2", fontSize: 12, fontWeight: 600, transition: "all 0.2s", minHeight: 32, display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 4 }}
                            onMouseEnter={e => { e.currentTarget.style.background = "#fee2e2" }} onMouseLeave={e => { e.currentTarget.style.background = "#fef2f2" }}>
                            <Icon icon="mdi:alert-circle" width={14} /> Dispute
                          </button>
                        </div>
                      ) : (
                        <span style={{ fontSize: 12, color: "#94a3b8" }}>ΓÇö</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
      )}

      {selectedStop && (
        <div onClick={closeModal} style={modalOverlay}>
          <div onClick={e => e.stopPropagation()} style={modalBox}>
            {isMobile && <div style={{ width: 40, height: 4, background: "#e0e0e0", borderRadius: 2, margin: "0 auto 20px" }} />}
            <h3 style={{ margin: "0 0 4px", color: "#171717", fontSize: isMobile ? 18 : 16 }}>Confirm Stop</h3>
            <p style={{ color: "#888", fontSize: 13, marginBottom: 20 }}>{selectedStop.plate_number} ┬╖ {selectedStop.stop_location}</p>

            <div style={{ padding: "12px 14px", background: "#f9f9f9", borderRadius: 10, marginBottom: 20 }}>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                <div><p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Bags</p><p style={{ margin: "2px 0 0", fontWeight: "bold", fontSize: 16, color: "#171717" }}>{selectedStop.quantity_offloaded}</p></div>
                <div><p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Loading Point</p><p style={{ margin: "2px 0 0", fontSize: 13, color: "#171717" }}>{selectedStop.material_centre}</p></div>
                {selectedStop.order_no ? (
                  <>
                    <div><p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Order No</p><p style={{ margin: "2px 0 0", fontSize: 13, color: "#171717" }}>{selectedStop.order_no}</p></div>
                    {selectedStop.child_order_no && <div><p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Child Order</p><p style={{ margin: "2px 0 0", fontSize: 13, color: "#171717" }}>{selectedStop.child_order_no}</p></div>}
                  </>
                ) : selectedStop.atc ? (
                  <div><p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>ATC</p><p style={{ margin: "2px 0 0", fontSize: 13, color: "#171717" }}>{selectedStop.atc}</p></div>
                ) : null}
                <div><p style={{ margin: 0, fontSize: 11, color: "#aaa" }}>Driver's Customer</p><p style={{ margin: "2px 0 0", fontSize: 13, color: "#171717" }}>{selectedStop.customer_name}</p></div>
              </div>
            </div>

            <div style={{ marginBottom: 16 }}>
              <label style={labelStyle}>Correct Customer (if not provided)</label>
              <CustomerSelector onSelect={(c) => setSelectedCustomer(c)} />
            </div>

            {companyPriceMap[selectedStop.product] !== undefined && (
              <div style={{ marginBottom: 12, padding: "8px 12px", background: "#ecfdf5", borderRadius: 8, border: "1px solid #10b981", display: "flex", alignItems: "center", gap: 8 }}>
                <Icon icon="mdi:information" width={16} color="#10b981" />
                <span style={{ fontSize: 13, color: "#10b981" }}>Company price: <strong>Γéª{companyPriceMap[selectedStop.product].toLocaleString()}</strong>/bag</span>
              </div>
            )}

            <div style={{ marginBottom: 12 }}>
              <label style={labelStyle}>Price Per Bag (Γéª) *</label>
              <ModernInput type="text" inputMode="numeric" placeholder="e.g. 10,500" value={pricePerBag} onChange={(e) => { setPricePerBag(formatAmount(e.target.value)); setMessage("") }} style={inputStyle} />
            </div>

            {companyPriceMap[selectedStop.product] !== undefined && (
              <>
                <div style={{ marginBottom: 16 }}>
                  <label style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer", fontWeight: 500, fontSize: 13, color: "#444" }}>
                    <input type="checkbox" checked={soldAtDifferentPrice} onChange={e => handleToggleDifferentPrice(e.target.checked)} style={{ width: 16, height: 16, cursor: "pointer" }} />
                    Sold at a different price?
                  </label>
                </div>

                {soldAtDifferentPrice && (
                  <div style={{ display: "flex", gap: 10, marginBottom: 16 }}>
                    <div style={{ flex: 1 }}>
                      <label style={labelStyle}>Discount (Γéª)</label>
                      <ModernInput type="text" inputMode="numeric" placeholder="0" value={discount} onChange={e => handleDiscountChange(e.target.value)} style={inputStyle} />
                    </div>
                    <div style={{ flex: 1 }}>
                      <label style={labelStyle}>Sale Price (Γéª)</label>
                      <ModernInput type="text" inputMode="numeric" placeholder="Sale price" value={salePrice} onChange={e => handleSalePriceChange(e.target.value)} style={inputStyle} />
                    </div>
                  </div>
                )}
              </>
            )}

            {message && <div style={{ display: "flex", alignItems: "center", gap: 6, color: "#ff4444", marginBottom: 14, fontSize: 13 }}><Icon icon="mdi:alert-circle" width={15} />{message}</div>}

            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={closeModal} style={{ flex: 1, padding: "13px 0", background: "white", border: "1.5px solid #e5e5e5", borderRadius: 10, cursor: "pointer", fontSize: 15, minHeight: 50, fontWeight: "bold" }}>Cancel</button>
              <button onClick={handleConfirm} disabled={submitting} style={{ flex: 1, padding: "13px 0", background: submitting ? "#ccc" : "#0070f3", color: "white", border: "none", borderRadius: 10, cursor: submitting ? "not-allowed" : "pointer", fontSize: 15, minHeight: 50, fontWeight: "bold", display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
                {submitting ? <><Icon icon="mdi:loading" width={16} style={{ animation: "spin 1s linear infinite" }} />ConfirmingΓÇª</> : <><Icon icon="mdi:check-circle" width={16} />Confirm Stop</>}
              </button>
            </div>
          </div>
        </div>
      )}

      {disputingStop && (
        <div onClick={() => setDisputingStop(null)} style={modalOverlay}>
          <div onClick={e => e.stopPropagation()} style={modalBox}>
            {isMobile && <div style={{ width: 40, height: 4, background: "#e0e0e0", borderRadius: 2, margin: "0 auto 20px" }} />}
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
              <div style={{ width: 38, height: 38, borderRadius: 10, background: "#fff0f0", display: "flex", alignItems: "center", justifyContent: "center" }}>
                <Icon icon="mdi:alert-circle" width={20} color="#ff4444" />
              </div>
              <h3 style={{ margin: 0, color: "#ff4444", fontSize: isMobile ? 18 : 16 }}>Dispute Stop</h3>
            </div>
            <p style={{ color: "#888", fontSize: 13, marginBottom: 20 }}>{disputingStop.plate_number} ┬╖ {disputingStop.stop_location}</p>

            <div style={{ marginBottom: 24 }}>
              <label style={labelStyle}>Reason for Dispute *</label>
              <ModernInput as="textarea" placeholder="e.g. This stop does not belong to meΓÇª" value={disputeReason} onChange={e => { setDisputeReason(e.target.value); setMessage("") }} rows={4} style={{ ...inputStyle, resize: "none", minHeight: 110 }} />
            </div>

            {message && <div style={{ display: "flex", alignItems: "center", gap: 6, color: "#ff4444", marginBottom: 14, fontSize: 13 }}><Icon icon="mdi:alert-circle" width={15} />{message}</div>}

            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={() => setDisputingStop(null)} style={{ flex: 1, padding: "13px 0", background: "white", border: "1.5px solid #e5e5e5", borderRadius: 10, cursor: "pointer", fontSize: 15, minHeight: 50, fontWeight: "bold" }}>Cancel</button>
              <button onClick={handleDispute} disabled={submitting} style={{ flex: 1, padding: "13px 0", background: submitting ? "#ccc" : "#ff4444", color: "white", border: "none", borderRadius: 10, cursor: submitting ? "not-allowed" : "pointer", fontSize: 15, minHeight: 50, fontWeight: "bold", display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
                {submitting ? <><Icon icon="mdi:loading" width={16} style={{ animation: "spin 1s linear infinite" }} />SubmittingΓÇª</> : <><Icon icon="mdi:alert-circle" width={16} />Submit Dispute</>}
              </button>
            </div>
          </div>
        </div>
      )}

      <style>{`@keyframes spin { from { transform: rotate(0deg) } to { transform: rotate(360deg) } }`}</style>
    </div>
  )
}

"use client"

import { Icon } from "@iconify/react"
import { FONT_SIZE } from "@/lib/constants"
import { formatDateTime, formatTime } from "@/lib/date-utils"

type ATF = {
  request_id: string
  atf_code: string | null
  plate_number: string
  driver_name: string
  officer_name: string
  company_name: string
  litres: number
  atf_status: string
  requested_at: string
  rate_per_litre: number | null
  total_amount: number | null
  fuel_balance: number | null
  engine_type: string | null
}

type Props = {
  atfs: ATF[]
  atfFilter: string
  setAtfFilter: (v: string) => void
  filteredATFs: ATF[]
  filteredATFsAll: ATF[]
  safeAtfPage: number
  atfTotalPages: number
  setAtfPage: (v: number | ((p: number) => number)) => void
  atfPage: number
  onAuthorise: (atf: ATF) => void
  onInvalidate: (atf: ATF) => void
  onRefresh: () => void
  PAGE_SIZE: number
}

const atfFilters = ["All", "Pending", "Authorised", "Dispensed", "Confirmed", "Invalidated"]

const atfStatusColor = (status: string) => {
  switch (status) {
    case "Pending": return { bg: "#fff8e1", color: "#f5a623", border: "#fde68a" }
    case "Authorised": return { bg: "#f0f7ff", color: "#0070f3", border: "#bfdbfe" }
    case "Dispensed": return { bg: "#f0f7ff", color: "#0070f3", border: "#bfdbfe" }
    case "Confirmed": return { bg: "#f0fff4", color: "#16a34a", border: "#86efac" }
    case "Invalidated": return { bg: "#fef2f2", color: "#ef4444", border: "#fecaca" }
    default: return { bg: "#f8fafc", color: "#64748b", border: "#e2e8f0" }
  }
}

const remainingColor = (balance: number | null) => {
  if (balance == null) return { bg: "#f8fafc", color: "#64748b", border: "#e2e8f0" }
  if (balance <= 0) return { bg: "#fef2f2", color: "#ef4444", border: "#fecaca" }
  if (balance < 100) return { bg: "#fffbeb", color: "#b45309", border: "#fde68a" }
  return { bg: "#f0fdf4", color: "#16a34a", border: "#bbf7d0" }
}

const atfFilterColor = (filter: string, activeFilter: string) => {
  if (filter === "All") return { bg: activeFilter === "All" ? "rgba(0, 112, 243, 0.1)" : "white", color: activeFilter === "All" ? "#0070f3" : "#64748b", border: activeFilter === "All" ? "#0070f3" : "#e2e8f0" }
  if (filter === "Pending") return { bg: activeFilter === "Pending" ? "rgba(245, 166, 35, 0.1)" : "white", color: activeFilter === "Pending" ? "#f5a623" : "#64748b", border: activeFilter === "Pending" ? "#f5a623" : "#e2e8f0" }
  if (filter === "Authorised" || filter === "Dispensed") return { bg: activeFilter === filter ? "rgba(0, 112, 243, 0.1)" : "white", color: activeFilter === filter ? "#0070f3" : "#64748b", border: activeFilter === filter ? "#0070f3" : "#e2e8f0" }
  if (filter === "Confirmed") return { bg: activeFilter === "Confirmed" ? "rgba(22, 163, 74, 0.1)" : "white", color: activeFilter === "Confirmed" ? "#16a34a" : "#64748b", border: activeFilter === "Confirmed" ? "#16a34a" : "#e2e8f0" }
  if (filter === "Invalidated") return { bg: activeFilter === "Invalidated" ? "rgba(239, 68, 68, 0.1)" : "white", color: activeFilter === "Invalidated" ? "#ef4444" : "#64748b", border: activeFilter === "Invalidated" ? "#ef4444" : "#e2e8f0" }
  return { bg: "white", color: "#64748b", border: "#e2e8f0" }
}

export default function ATFSection({
  atfs, atfFilter, setAtfFilter, filteredATFs, filteredATFsAll,
  safeAtfPage, atfTotalPages, setAtfPage, atfPage,
  onAuthorise, onInvalidate, onRefresh, PAGE_SIZE,
}: Props) {
  return (
    <div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 16, alignItems: "center" }}>
        {atfFilters.map(f => {
          const { bg, color, border } = atfFilterColor(f, atfFilter)
          return (
            <button key={f} onClick={() => setAtfFilter(f)} className="filter-btn" style={{ padding: "6px 14px", borderRadius: 20, fontSize: FONT_SIZE.xs, cursor: "pointer", border: `1.5px solid ${border}`, background: bg, color, fontWeight: atfFilter === f ? 600 : 500, transition: "all 0.2s", minHeight: 40 }}>
              {f}
            </button>
          )
        })}
        <div style={{ flex: 1 }} />
        <button onClick={onRefresh} className="refresh-btn" style={{ padding: "6px 12px", fontSize: FONT_SIZE.xs, cursor: "pointer", borderRadius: 8, border: "1px solid #e2e8f0", background: "white", color: "#64748b", transition: "all 0.2s", fontWeight: 600 }}>
          Γå╗
        </button>
      </div>

      {filteredATFs.length === 0 && <p style={{ color: "#64748b", fontSize: FONT_SIZE.base }}>No ATFs found.</p>}
      {filteredATFsAll.length > PAGE_SIZE && (
        <div style={{ display: "flex", justifyContent: "center", gap: 8, marginBottom: 16 }}>
          <button disabled={safeAtfPage <= 1} onClick={() => setAtfPage(p => Math.max(1, p - 1))} style={{ padding: "6px 14px", background: safeAtfPage <= 1 ? "#f0f0f0" : "white", border: "1px solid #e2e8f0", borderRadius: 8, cursor: safeAtfPage <= 1 ? "not-allowed" : "pointer", fontSize: FONT_SIZE.xs, color: safeAtfPage <= 1 ? "#ccc" : "#64748b" }}>
            ΓåÉ Previous
          </button>
          <span style={{ display: "flex", alignItems: "center", fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Page {safeAtfPage} of {atfTotalPages}</span>
          <button disabled={safeAtfPage >= atfTotalPages} onClick={() => setAtfPage(p => p + 1)} style={{ padding: "6px 14px", background: safeAtfPage >= atfTotalPages ? "#f0f0f0" : "white", border: "1px solid #e2e8f0", borderRadius: 8, cursor: safeAtfPage >= atfTotalPages ? "not-allowed" : "pointer", fontSize: FONT_SIZE.xs, color: safeAtfPage >= atfTotalPages ? "#ccc" : "#64748b" }}>
            Next ΓåÆ
          </button>
        </div>
      )}
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {filteredATFs.map(atf => {
          const { bg, color, border } = atfStatusColor(atf.atf_status)
          return (
            <div key={atf.request_id} className="card-hover" style={{ background: "white", border: `1px solid ${border}`, borderRadius: 12, padding: 16, boxShadow: "0 1px 3px rgba(0,0,0,0.05)", transition: "all 0.2s" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 12 }}>
                <div>
                  {atf.atf_code ? <p style={{ margin: 0, fontWeight: 700, fontSize: FONT_SIZE.base, fontFamily: "monospace", letterSpacing: 1, color: "#0f172a" }}>{atf.atf_code}</p> : <p style={{ margin: 0, fontSize: FONT_SIZE.sm, color: "#94a3b8" }}>Awaiting authorisation</p>}
                  <p style={{ margin: "4px 0 0", fontSize: FONT_SIZE.sm, color: "#64748b" }}>{atf.plate_number} ┬╖ {atf.driver_name}</p>
                  <p style={{ margin: "4px 0 0", fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Station: {atf.company_name}</p>
                  <p style={{ margin: "4px 0 0", fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Initiated by {atf.officer_name}</p>
                </div>
                <span style={{ padding: "4px 10px", borderRadius: 20, fontSize: FONT_SIZE.xs, background: bg, color, fontWeight: 700, whiteSpace: "nowrap", border: `1px solid ${color}33` }}>{atf.atf_status}</span>
              </div>
              <div style={{ display: "grid", gridTemplateColumns: atf.total_amount ? "1fr 1fr 1fr 1fr" : "1fr 1fr 1fr", gap: 10, marginBottom: 12 }}>
                <div style={{ background: "#f0f7ff", borderRadius: 8, padding: "10px 12px", border: "1px solid #bfdbfe" }}>
                  <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#3b82f6" }}>Requested</p>
                  <p style={{ margin: "2px 0 0", fontWeight: 700, color: "#1d4ed8", fontSize: FONT_SIZE.base }}>{atf.litres}L</p>
                </div>
                {atf.fuel_balance != null && (() => {
                  const rc = remainingColor(atf.fuel_balance)
                  return (
                    <div style={{ background: rc.bg, borderRadius: 8, padding: "10px 12px", border: `1px solid ${rc.border}` }}>
                      <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: rc.color }}>Remaining</p>
                      <p style={{ margin: "2px 0 0", fontWeight: 700, color: rc.color, fontSize: FONT_SIZE.base }}>{atf.fuel_balance}{atf.engine_type === "CNG" ? " bars" : "L"}</p>
                    </div>
                  )
                })()}
                {atf.rate_per_litre != null && (
                  <div style={{ background: "#f8fafc", borderRadius: 8, padding: "10px 12px", border: "1px solid #e2e8f0" }}>
                    <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Rate/L</p>
                    <p style={{ margin: "2px 0 0", fontWeight: 700, color: "#0f172a", fontSize: FONT_SIZE.base }}>Γéª{atf.rate_per_litre.toLocaleString()}</p>
                  </div>
                )}
                {atf.total_amount != null && (
                  <div style={{ background: "#f8fafc", borderRadius: 8, padding: "10px 12px", border: "1px solid #e2e8f0" }}>
                    <p style={{ margin: 0, fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>Total</p>
                    <p style={{ margin: "2px 0 0", fontWeight: 700, color: "#0070f3", fontSize: FONT_SIZE.base }}>Γéª{atf.total_amount.toLocaleString()}</p>
                  </div>
                )}
              </div>
              {atf.atf_status === "Pending" && (
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                  <button onClick={() => onAuthorise(atf)} className="btn-hover-opacity" style={{ padding: "10px 14px", background: "#0070f3", color: "white", border: "none", borderRadius: 8, cursor: "pointer", fontWeight: 700, fontSize: FONT_SIZE.sm, minHeight: 40, transition: "opacity 0.2s" }}>
                    Authorise ATF
                  </button>
                  <button onClick={() => onInvalidate(atf)} className="invalidate-btn" style={{ padding: "10px 14px", background: "white", color: "#ef4444", border: "1.5px solid #ef4444", borderRadius: 8, cursor: "pointer", fontWeight: 700, fontSize: FONT_SIZE.sm, minHeight: 40, transition: "all 0.2s" }}>
                    Invalidate
                  </button>
                </div>
              )}
              {atf.atf_status === "Authorised" && (
                <button onClick={() => onInvalidate(atf)} className="invalidate-btn" style={{ width: "100%", padding: "10px 14px", background: "white", color: "#ef4444", border: "1.5px solid #ef4444", borderRadius: 8, cursor: "pointer", fontWeight: 700, fontSize: FONT_SIZE.sm, minHeight: 40, transition: "all 0.2s" }}>
                  Invalidate
                </button>
              )}
              <p style={{ margin: "8px 0 0", fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>{formatDateTime(atf.requested_at)}</p>
            </div>
          )
        })}
      </div>
    </div>
  )
}

"use client"

import { Icon } from "@iconify/react"
import { FONT_SIZE } from "@/lib/constants"
import { formatDateTime, formatTime } from "@/lib/date-utils"

type MaintenanceReport = {
  report_id: string
  plate_number: string
  manager_name: string
  maintenance_type: string
  maintenance_location: string | null
  amount: number
  notes: string | null
  status: "Pending" | "Validated" | "Rejected"
  rejection_reason: string | null
  reported_at: string
}

type BulkProcurement = {
  procurement_id: string
  item_name: string
  total_amount: number
  notes: string | null
  logged_at: string
  distributions: { plate_number: string; amount_allocated: number }[]
}

type FeedItem =
  | { kind: "report"; data: MaintenanceReport; date: string }
  | { kind: "procurement"; data: BulkProcurement; date: string }

type Props = {
  reports: MaintenanceReport[]
  procurements: BulkProcurement[]
  balanceMap: Record<string, number>
  filter: string
  setFilter: (v: string) => void
  feedPage: number
  setFeedPage: (v: number | ((p: number) => number)) => void
  filteredFeed: FeedItem[]
  filteredFeedAll: FeedItem[]
  feedTotalPages: number
  safeFeedPage: number
  lastUpdated: Date | null
  onRefresh: () => void
  onValidate: (report: MaintenanceReport) => void
  onReject: (report: MaintenanceReport) => void
  PAGE_SIZE: number
}

const maintenanceFilters = ["All", "Pending", "Validated", "Rejected", "Bulk Procurement"]

const filterColor = (filter: string, activeFilter: string) => {
  if (filter === "All") return { bg: activeFilter === "All" ? "rgba(0, 112, 243, 0.1)" : "white", color: activeFilter === "All" ? "#0070f3" : "#64748b", border: activeFilter === "All" ? "#0070f3" : "#e2e8f0" }
  if (filter === "Pending") return { bg: activeFilter === "Pending" ? "rgba(245, 166, 35, 0.1)" : "white", color: activeFilter === "Pending" ? "#f5a623" : "#64748b", border: activeFilter === "Pending" ? "#f5a623" : "#e2e8f0" }
  if (filter === "Validated") return { bg: activeFilter === "Validated" ? "rgba(22, 163, 74, 0.1)" : "white", color: activeFilter === "Validated" ? "#16a34a" : "#64748b", border: activeFilter === "Validated" ? "#16a34a" : "#e2e8f0" }
  if (filter === "Rejected") return { bg: activeFilter === "Rejected" ? "rgba(239, 68, 68, 0.1)" : "white", color: activeFilter === "Rejected" ? "#ef4444" : "#64748b", border: activeFilter === "Rejected" ? "#ef4444" : "#e2e8f0" }
  if (filter === "Bulk Procurement") return { bg: activeFilter === "Bulk Procurement" ? "rgba(124, 58, 237, 0.1)" : "white", color: activeFilter === "Bulk Procurement" ? "#7c3aed" : "#64748b", border: activeFilter === "Bulk Procurement" ? "#7c3aed" : "#e2e8f0" }
  return { bg: "white", color: "#64748b", border: "#e2e8f0" }
}

const statusColor = (status: string) => {
  switch (status) {
    case "Pending": return { bg: "#fff8e1", color: "#f5a623", border: "#fde68a" }
    case "Validated": return { bg: "#f0fff4", color: "#16a34a", border: "#86efac" }
    case "Rejected": return { bg: "#fef2f2", color: "#ef4444", border: "#fecaca" }
    default: return { bg: "#f8fafc", color: "#64748b", border: "#e2e8f0" }
  }
}

