              </div>
              {r.notes && <p style={{ margin: "0 0 8px 0", fontSize: FONT_SIZE.sm, color: "#64748b" }}><strong>Notes:</strong> {r.notes}</p>}
              {r.status === "Rejected" && r.rejection_reason && (
                <div style={{ padding: "10px 12px", background: "#fef2f2", border: "1px solid #fecaca", borderRadius: 8, marginBottom: 12 }}>
                  <p style={{ margin: 0, fontSize: FONT_SIZE.sm, color: "#b91c1c", fontWeight: 600 }}>{r.rejection_reason}</p>
                </div>
              )}
              {r.status === "Pending" && (
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
                  <button onClick={() => onValidate(r)} className="btn-hover-opacity" style={{ padding: "10px 14px", background: "#16a34a", color: "white", border: "none", borderRadius: 8, cursor: "pointer", fontWeight: 700, fontSize: FONT_SIZE.sm, minHeight: 40, transition: "opacity 0.2s" }}>
                    Validate
                  </button>
                  <button onClick={() => onReject(r)} className="invalidate-btn" style={{ padding: "10px 14px", background: "white", color: "#ef4444", border: "1.5px solid #ef4444", borderRadius: 8, cursor: "pointer", fontWeight: 700, fontSize: FONT_SIZE.sm, minHeight: 40, transition: "all 0.2s" }}>
                    Reject
                  </button>
                </div>
              )}
              <p style={{ margin: "8px 0 0", fontSize: FONT_SIZE.xs, color: "#94a3b8" }}>{formatDateTime(r.reported_at)}</p>
            </div>
          )
        })}
      </div>
    </div>
  )
}

import { useEffect, useState, useCallback, useRef } from "react"
import { supabase } from "@/lib/supabase"

export interface FuelExpense {
  expense_id: string
  manager_id: string | null
  plate_number: string | null
  trip_id: string | null
  litres: number
  notes: string | null
  location: string | null
  logged_at: string
  officer_name: string
  kbnl_truck_no?: string | null
  material_centre?: string | null
  product?: string | null
}

interface FuelExpensesFilter {
  manager_id?: string
}

export function useFuelExpenses(filter?: FuelExpensesFilter) {
  const [data, setData] = useState<FuelExpense[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [queryKey, setQueryKey] = useState(0)
  const mountedRef = useRef(true)

  const refetch = useCallback(() => setQueryKey(k => k + 1), [])

  useEffect(() => {
    mountedRef.current = true
    let cancelled = false

    async function fetchData() {
      setLoading(true)
      setError(null)

      try {
        let query = supabase
          .from("truck_fuel_expenses")
          .select("expense_id, manager_id, plate_number, trip_id, litres, notes, location, logged_at")
          .order("logged_at", { ascending: false })

        if (filter?.manager_id) {
          query = query.eq("manager_id", filter.manager_id)
        }

        const { data: raw, error: rawError } = await query
        if (cancelled || !mountedRef.current) return

        if (rawError) throw rawError
        if (!raw) { setData([]); setLoading(false); return }

        const officerIds = [...new Set(raw.map(r => r.manager_id).filter(Boolean))]
        const plates = [...new Set(raw.map(r => r.plate_number).filter(Boolean))]
        const tripIds = [...new Set(raw.map(r => r.trip_id).filter(Boolean))]

        const [officersResult, trucksResult, tripsResult] = await Promise.all([
          officerIds.length ? supabase.from("truck_officers").select("manager_id, full_name").in("manager_id", officerIds) : Promise.resolve({ data: [], error: null }),
          plates.length ? supabase.from("Trucks").select("plate_number, kbnl_truck_no").in("plate_number", plates) : Promise.resolve({ data: [], error: null }),
          tripIds.length ? supabase.from("Trips").select("trip_id, material_centre, product").in("trip_id", tripIds) : Promise.resolve({ data: [], error: null }),
        ])

        if (cancelled || !mountedRef.current) return

        const enrichmentError = officersResult.error ?? trucksResult.error ?? tripsResult.error
        if (enrichmentError) throw enrichmentError

        const officerMap = Object.fromEntries((officersResult.data || []).map(o => [o.manager_id, o.full_name]))
        const truckMap = Object.fromEntries((trucksResult.data || []).map(t => [t.plate_number, t.kbnl_truck_no]))
        const tripMap = Object.fromEntries((tripsResult.data || []).map(t => [t.trip_id, t]))

        const enriched = raw.map(r => ({
          ...r,
          officer_name: officerMap[r.manager_id] ?? "Unknown",
          kbnl_truck_no: truckMap[r.plate_number] ?? null,
          material_centre: tripMap[r.trip_id]?.material_centre ?? null,
          product: tripMap[r.trip_id]?.product ?? null,
        }))

        setData(enriched)
      } catch (e) {
        if (cancelled || !mountedRef.current) return
        setError(e instanceof Error ? e.message : "Failed to fetch fuel expenses")
        setData([])
      } finally {
        if (!cancelled && mountedRef.current) setLoading(false)
      }
    }

    fetchData()

    return () => { cancelled = true; mountedRef.current = false }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [queryKey, filter?.manager_id])

  return { data, loading, error, refetch }
}

"use client"

import { useEffect, useCallback, useRef } from "react"

/**
 * A polling hook that pauses when the tab is hidden and
 * immediately refetches when the tab becomes visible again.
 *
 * This prevents:
 * - Timer accumulation when the tab is backgrounded
 * - Frozen loaders when returning to the tab
 * - Wasted network requests in hidden tabs
 */
export function usePolling(
  callback: () => void | Promise<unknown>,
  intervalMs: number,
  enabled = true,
) {
  const savedCallback = useRef(callback)
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null)
  const wasHidden = useRef(false)
  const inFlight = useRef(false)

  savedCallback.current = callback

  const clearPolling = useCallback(() => {
    if (intervalRef.current !== null) {
      clearInterval(intervalRef.current)
      intervalRef.current = null
    }
  }, [])

  const runCallback = useCallback(async () => {
    if (inFlight.current) return
    inFlight.current = true
    try {
      await savedCallback.current()
    } finally {
      inFlight.current = false
    }
  }, [])

  const startPolling = useCallback(() => {
    clearPolling()
    if (!enabled) return
    intervalRef.current = setInterval(() => {
      void runCallback()
    }, intervalMs)
  }, [intervalMs, enabled, clearPolling, runCallback])

  useEffect(() => {
    if (!enabled) return

    if (document.hidden) {
      wasHidden.current = true
    } else {
      startPolling()
    }

    function handleVisibilityChange() {
      if (document.hidden) {
        wasHidden.current = true
        clearPolling()
      } else if (wasHidden.current) {
        wasHidden.current = false
        void runCallback()
        startPolling()
      }
    }

    document.addEventListener("visibilitychange", handleVisibilityChange)

    return () => {
      clearPolling()
      document.removeEventListener("visibilitychange", handleVisibilityChange)
    }
  }, [enabled, startPolling, clearPolling])
}
